def get_user_scripts_path():
    ctx = uno.getComponentContext()
    path_sub = ctx.ServiceManager.createInstanceWithContext('com.sun.star.util.PathSubstitution', ctx)
    user_url = path_sub.getSubstituteVariableValue('user')
