def parse_sheets_undelete_list(table):
    """
    Разбор параметра «Листы_не_удалять» (колонка B) для этапа 1 (maybe_clear_sheets).

    Назначение:
        Шаблоны имён листов через запятую (text_match: ``*Отчет*``, ``Отчет*``).
        «*» / «Все» / «All» без фильтра в C — не удалять никакие листы.
        «*» / «Все» + filter в C — шаблон «*» + лямбда (True = оставить).
        Колонка C — опциональный JSON с лямбдой ``filter`` (см. parse_sheets_undelete_filter).

    Возвращает:
        list[str] — шаблоны; MERGE_SHEETS_UNDELETE_KEEP_ALL; или default.
    """
    vals = table_values(table, _cw_cfg.P_MERGE_SHEETS_UNDELETE)
    if vals is None or len(vals) == 0:
        return list(_cw_cfg.MERGE_SHEETS_UNDELETE_DEFAULT)
    # Только B (первый слот); C — фильтр JSON, не имя листа
    b_raw = str(vals[0] or "").strip()
    if b_raw == "":
        return list(_cw_cfg.MERGE_SHEETS_UNDELETE_DEFAULT)
    names = []
    keep_all = False
    for part in split_filter_specs(b_raw):
        token = str(part or "").strip()
        if token == "":
            continue
        if token.casefold() in ("*", "все", "all"):
            keep_all = True
            continue
        if token not in names:
            names.append(token)
    # Legacy: если C не JSON — дополнительные шаблоны из C,D…
    i = 1
    while i < len(vals):
        cell = str(vals[i] or "").strip()
        i = i + 1
        if cell == "":
            continue
        if cell.startswith("{") or cell.startswith("["):
            continue
        for part in split_filter_specs(cell):
            token = str(part or "").strip()
            if token == "":
                continue
            if token.casefold() in ("*", "все", "all"):
                keep_all = True
                continue
            if token not in names:
                names.append(token)
    filt = parse_sheets_undelete_filter(table)
    if keep_all and (filt is None or str(filt).strip() == ""):
        return _cw_cfg.MERGE_SHEETS_UNDELETE_KEEP_ALL
    if keep_all and "*" not in names:
        names.insert(0, "*")
    if len(names) == 0:
        return list(_cw_cfg.MERGE_SHEETS_UNDELETE_DEFAULT)
    return names


def parse_sheets_undelete_filter(table):
    """
    Текст лямбды фильтра из колонки C параметра «Листы_не_удалять».

    JSON: {"v":1,"filter":"lambda name: …"} или голая lambda.
    """
    vals = table_values(table, _cw_cfg.P_MERGE_SHEETS_UNDELETE)
    if vals is None or len(vals) < 2:
        return None
    try:
        from libre_macros_sheet_filter_lib import parse_sheet_filter_code

        code = parse_sheet_filter_code(vals[1])
    except Exception:
        cell = str(vals[1] or "").strip()
        if cell.startswith("{") or cell.startswith("["):
            return None
        code = cell if cell.lstrip().startswith("lambda") or cell.lstrip().startswith("def ") else ""
    if code is None or str(code).strip() == "":
        return None
    return str(code).strip()


def _merge_sheets_cell_is_filter_slot(cell):
    """
    True, если ячейка C параметра «Листы» — JSON/lambda фильтр, а не шаблон/карта 2-го файла.
    """
    cell_s = str(cell or "").strip()
    if cell_s == "":
        return False
    try:
        from libre_macros_param_codec import sheets_map_is_filter_payload
        return bool(sheets_map_is_filter_payload(cell_s))
    except Exception:
        pass
    if cell_s.startswith("{") or cell_s.startswith("["):
        # без кодека — только явный filter / неизвестный JSON считаем фильтром
        return True
    lead = cell_s.lstrip()
    if lead.startswith("lambda") or lead.startswith("def "):
        return True
    return False


def _merge_sheets_file_col_to_raw_index(file_col_idx, filter_slot_idx):
    """Индекс ячейки B,C,D… «Листы» для столбца файла (C может быть фильтром)."""
    if filter_slot_idx < 0:
        return file_col_idx
    if file_col_idx < filter_slot_idx:
        return file_col_idx
    return file_col_idx + 1


def parse_sheets_include_filter(table):
    """
    Текст лямбды фильтра из колонки C параметра «Листы» (если C — фильтр).

    JSON: {"v":1,"filter":"lambda name: …"} или голая lambda.
    """
    vals = table_values(table, _cw_cfg.P_MERGE_SHEETS)
    if vals is None or len(vals) < 2:
        return None
    if not _merge_sheets_cell_is_filter_slot(vals[1]):
        return None
    try:
        from libre_macros_sheet_filter_lib import parse_sheet_filter_code

        code = parse_sheet_filter_code(vals[1])
    except Exception:
        cell = str(vals[1] or "").strip()
        if cell.startswith("{") or cell.startswith("["):
            return None
        code = cell if cell.lstrip().startswith("lambda") or cell.lstrip().startswith("def ") else ""
    if code is None or str(code).strip() == "":
        return None
    return str(code).strip()


# Sentinel для filter_fn: см. _cw_cfg._MERGE_FILTER_FN_UNSET (pythonpath; AO не вырезает).

def _merge_sheet_slot_include_filter_passes(source_name, filter_fn):
    if filter_fn is None:
        return True
    try:
        return bool(filter_fn(source_name))
    except Exception:
        return False

def _merge_resolve_sheets_include_filter_fn(filter_fn):
    """Разрешить filter_fn: UNSET → global; иначе как передали (в т.ч. явный None)."""
    if filter_fn is _cw_cfg._MERGE_FILTER_FN_UNSET:
        return _cw_get('_MERGE_SHEETS_INCLUDE_FILTER_FN')
    return filter_fn


def _merge_sheets_undelete_protects_name(name, patterns, filter_fn):
    """True — лист защищён от предварительного удаления."""
    try:
        from libre_macros_lib import text_match
        from libre_macros_sheet_filter_lib import sheet_name_matches_patterns
    except Exception:
        return False
    if not sheet_name_matches_patterns(name, patterns, text_match_fn=text_match):
        return False
    if filter_fn is None:
        return True
    try:
        return bool(filter_fn(name))
    except Exception:
        return False

def _merge_param_b_is_col_c_marker(raw):
    s = str(raw or '').strip().casefold()
    return s in ('смотри в с', 'смотри в c', 'см.c', 'см. c')

def _merge_parse_delete_top_rows_entry(text):
    """
    Одно правило «ИмяЛиста» + разделитель + N.

    Разделитель: ``->`` или ``=`` или ``\\`` (пробелы вокруг допускаются).
    """
    s = str(text or '').strip()
    if s == '':
        return None
    sheet_name = ''
    n_txt = ''
    for sep in _cw_cfg._MERGE_DELETE_TOP_ROWS_SEPS:
        if sep in s:
            left, right = s.split(sep, 1)
            sheet_name = left.strip()
            n_txt = right.strip()
            break
    if sheet_name == '' or n_txt == '':
        return None
    try:
        n = int(n_txt)
    except (TypeError, ValueError):
        return None
    if n <= 0:
        return None
    return (sheet_name, n)

def _merge_parse_delete_top_rows_cell(raw, mapping, per_file, file_index):
    """
    Разбор одной ячейки B/C/D… параметра «удаление_верхних_строк».

    mapping — именованные правила; per_file[file_index] — N без имени листа.
    """
    raw = str(raw or '').strip()
    if raw == '':
        return
    if _merge_param_b_is_col_c_marker(raw) or str(raw or '').strip().casefold() in (
        'см. в c',
        'см. в с',
        'см.с',
        'см. с',
    ):
        return
    blocks = []
    try:
        from libre_macros_param_codec import param_decode
        blocks = param_decode(_cw_cfg.P_MERGE_DELETE_TOP_ROWS, raw) or []
    except Exception:
        blocks = []
    if blocks:
        pf_n = 0
        for block in blocks:
            if not isinstance(block, dict):
                continue
            sn = str(block.get('sheet') or block.get('name') or block.get('s') or '').strip()
            try:
                n = int(block.get('n', block.get('rows', block.get('count', 0))))
            except Exception:
                n = 0
            if n <= 0:
                continue
            if sn != '':
                mapping[sn] = n
            else:
                pf_n = max(pf_n, n)
        if pf_n > 0 and file_index is not None:
            while len(per_file) <= file_index:
                per_file.append(0)
            if pf_n > int(per_file[file_index] or 0):
                per_file[file_index] = pf_n
        return
    if raw.startswith('{') or raw.startswith('['):
        try:
            obj = json.loads(raw)
            if isinstance(obj, dict):
                for k, v in obj.items():
                    try:
                        n = int(v)
                    except Exception:
                        continue
                    if n > 0 and str(k or '').strip() != '':
                        mapping[str(k).strip()] = n
                return
            if isinstance(obj, list):
                pf_n = 0
                for item in obj:
                    if not isinstance(item, dict):
                        continue
                    sn = str(item.get('sheet') or item.get('name') or item.get('s') or '').strip()
                    try:
                        n = int(item.get('n', item.get('rows', item.get('count', 0))))
                    except Exception:
                        continue
                    if n <= 0:
                        continue
                    if sn != '':
                        mapping[sn] = n
                    else:
                        pf_n = max(pf_n, n)
                if pf_n > 0 and file_index is not None:
                    while len(per_file) <= file_index:
                        per_file.append(0)
                    if pf_n > int(per_file[file_index] or 0):
                        per_file[file_index] = pf_n
                return
        except Exception:
            pass
    for part in re.split('[,;]', raw):
        entry = _merge_parse_delete_top_rows_entry(part.strip())
        if entry is None:
            continue
        sheet_name, n_rows = entry
        mapping[sheet_name] = n_rows

def _merge_parse_delete_top_rows_expand_per_file(raw, mapping, per_file, file_count):
    """
    Разобрать одну ячейку и применить N без sheet ко всем file_count слотам.
    Именованные правила (sheet в JSON) попадают только в mapping.
    """
    if file_count is None or int(file_count) <= 0:
        return
    tmp_map = {}
    tmp_pf = []
    _merge_parse_delete_top_rows_cell(raw, tmp_map, tmp_pf, 0)
    for k, v in tmp_map.items():
        mapping[k] = v
    n = 0
    if tmp_pf:
        try:
            n = int(tmp_pf[0] or 0)
        except (TypeError, ValueError):
            n = 0
    if n <= 0:
        return
    fc = int(file_count)
    while len(per_file) < fc:
        per_file.append(0)
    fi = 0
    while fi < fc:
        try:
            cur = int(per_file[fi] or 0)
        except (TypeError, ValueError):
            cur = 0
        if n > cur:
            per_file[fi] = n
        fi += 1

def parse_delete_top_rows_map(table):
    """
    Карта «удаление_верхних_строк»: имя листа результата → число строк сверху.

    Значения в B,C,D…; в одной ячейке несколько правил через , или ;.
    """
    mapping, _per_file = parse_delete_top_rows_settings(table)
    return mapping

def parse_delete_top_rows_settings(table, file_count=0):
    """
    «удаление_верхних_строк»: mapping по имени листа + per_file[N] без sheet в JSON.

    B = «смотри в C» → JSON/правила из C; одна ячейка C на все файлы, иначе C,D…
    по файлам. Только B (без маркера) — то же «на все файлы».

    Возвращает (mapping, per_file).
    """
    mapping = {}
    per_file = []
    if table is None:
        return (mapping, per_file)
    raw_cells = table_values(table, _cw_cfg.P_MERGE_DELETE_TOP_ROWS)
    if not raw_cells:
        return (mapping, per_file)
    try:
        fc = int(file_count or 0)
    except (TypeError, ValueError):
        fc = 0
    cells = [str(x or '').strip() for x in raw_cells]
    if cells and _merge_param_b_is_col_c_marker(cells[0]):
        rest = cells[1:]
        if not rest:
            return (mapping, per_file)
        any_other = any((rest[j] != '' for j in range(1, len(rest))))
        if rest[0] != '' and (not any_other):
            _merge_parse_delete_top_rows_expand_per_file(rest[0], mapping, per_file, fc)
            return (mapping, per_file)
        fi = 0
        while fi < len(rest):
            if rest[fi] != '':
                _merge_parse_delete_top_rows_cell(rest[fi], mapping, per_file, fi)
            fi += 1
        return (mapping, per_file)
    any_other = any((cells[j] != '' for j in range(1, len(cells))))
    if cells[0] != '' and (not any_other) and fc > 0:
        _merge_parse_delete_top_rows_expand_per_file(cells[0], mapping, per_file, fc)
        return (mapping, per_file)
    fi = 0
    while fi < len(cells):
        if cells[fi] != '':
            _merge_parse_delete_top_rows_cell(cells[fi], mapping, per_file, fi)
        fi += 1
    return (mapping, per_file)

def _merge_copy_auto_trim_enabled(settings=None):
    """MERGE_COPY_AUTO_TRIM / «Автообрезка_листов» (по умолчанию Да)."""
    if settings is not None:
        flags = (settings or {}).get('merge_flags') or {}
        if 'MERGE_COPY_AUTO_TRIM' in flags:
            return bool(flags.get('MERGE_COPY_AUTO_TRIM'))
    try:
        return bool(_cw_get('MERGE_COPY_AUTO_TRIM', True))
    except Exception:
        return True

def _merge_copy_row_trim_parts(header_row, start_row, header_last=None):
    """
    Двухфазное удаление строк для «Копирование листов» (1-based).

    1) top — строки до заголовка (первая строка шапки - 1);
    2) after_header — строки между последней строкой шапки и данными.
    """
    try:
        hr = int(header_row)
    except (TypeError, ValueError):
        hr = 1
    try:
        sr = max(1, int(start_row))
    except (TypeError, ValueError):
        sr = max(1, hr) if hr > 0 else 1
    last = header_last
    if last in (None, ''):
        last = hr
    try:
        last = int(last)
    except (TypeError, ValueError):
        last = hr
    if hr <= 0:
        return (max(0, sr - 1), 0)
    hr = max(1, hr)
    last = max(hr, last)
    top = max(0, hr - 1)
    after = max(0, sr - last - 1) if sr > last + 1 else 0
    return (top, after)


def _merge_block_header_first_last_1(blk):
    """Первая и последняя строки шапки (1-based) из блока параметров."""
    if blk is None:
        return (1, 1)
    if blk.get('no_header'):
        return (0, 0)
    try:
        first_1 = int(blk.get('header_row_first_1') or 0)
    except (TypeError, ValueError):
        first_1 = 0
    try:
        last_1 = int(blk.get('header_row_last_1') or 0)
    except (TypeError, ValueError):
        last_1 = 0
    if first_1 > 0 and last_1 > 0:
        if last_1 < first_1:
            last_1 = first_1
        return (first_1, last_1)
    try:
        hr = int(str(blk.get('header_row_disp') or blk.get('start_row_disp') or '1'))
    except (TypeError, ValueError):
        hr = 1
    if hr <= 0:
        return (0, 0)
    return (hr, hr)

def _merge_copy_sheets_has_explicit_delete_top(sheet_name, file_index=None, settings=None):
    """
    True, если для листа задан явный «удаление_верхних_строк» (по имени или per_file).

    При явном параметре автообрезка по границам блока не выполняется.
    """
    if settings is not None:
        mapping = (settings or {}).get('delete_top_rows_map') or {}
        per_file = (settings or {}).get('delete_top_rows_per_file') or []
    else:
        mapping = _cw_get('_MERGE_DELETE_TOP_ROWS_MAP') or {}
        per_file = _cw_get('_MERGE_DELETE_TOP_ROWS_PER_FILE') or []
    resolved = _merge_resolve_delete_top_rows_count(sheet_name, mapping)
    if resolved is not None:
        try:
            if int(resolved) > 0:
                return True
        except (TypeError, ValueError):
            pass
    if file_index is None:
        file_index = (_cw_get('_MERGE_COPY_SHEETS_FILE_INDEX') or {}).get(sheet_name)
    if file_index is not None and file_index < len(per_file):
        try:
            if int(per_file[file_index] or 0) > 0:
                return True
        except (TypeError, ValueError):
            pass
    return False

def _merge_resolve_delete_top_rows_for_sheet(sheet_name, file_index=None):
    """N строк сверху: именованное правило или per_file для файла-источника."""
    mapping = _cw_get('_MERGE_DELETE_TOP_ROWS_MAP') or {}
    n = _merge_resolve_delete_top_rows_count(sheet_name, mapping)
    if n is not None and int(n) > 0:
        return int(n)
    if file_index is None:
        file_index = (_cw_get('_MERGE_COPY_SHEETS_FILE_INDEX') or {}).get(sheet_name)
    per_file = _cw_get('_MERGE_DELETE_TOP_ROWS_PER_FILE') or []
    if file_index is not None and file_index < len(per_file):
        try:
            pf_n = int(per_file[file_index] or 0)
        except (TypeError, ValueError):
            pf_n = 0
        if pf_n > 0:
            return pf_n
    return None

def _merge_build_copy_sheets_auto_trim_map(settings):
    """
    Автообрезка скопированных листов по «Строка_Заголовков» / «Начало_Строка».

    Листы с явным «удаление_верхних_строк» пропускаются.
    При MERGE_COPY_AUTO_TRIM=False — пустая карта (явное удаление отдельно).
    """
    if not _merge_copy_auto_trim_enabled(settings):
        return {}
    blocks_by_name = _cw_get('_MERGE_COPY_SHEETS_BLOCK_BY_NAME') or {}
    file_index_by_name = _cw_get('_MERGE_COPY_SHEETS_FILE_INDEX') or {}
    trim = {}
    for sheet_name, blk in blocks_by_name.items():
        fi = file_index_by_name.get(sheet_name)
        if _merge_copy_sheets_has_explicit_delete_top(sheet_name, fi, settings):
            continue
        if blk.get('no_header'):
            hr = 0
            last = 0
        else:
            hr, last = _merge_block_header_first_last_1(blk)
        sr = max(1, int(str(blk.get('start_row_disp') or '1')))
        top, after = _merge_copy_row_trim_parts(hr, sr, last)
        if top > 0 or after > 0:
            trim[sheet_name] = {'top': top, 'after_header': after}
    return trim

def _merge_build_copy_sheets_explicit_delete_map(settings):
    """
    Явное «удаление_верхних_строк»: именованные правила + per_file → листы результата.
    """
    mapping = dict((settings or {}).get('delete_top_rows_map') or {})
    per_file = (settings or {}).get('delete_top_rows_per_file') or []
    file_index_by_name = _cw_get('_MERGE_COPY_SHEETS_FILE_INDEX') or {}
    result = dict(mapping)
    for sheet_name, fi in file_index_by_name.items():
        if fi is None or fi >= len(per_file):
            continue
        try:
            pf_n = int(per_file[fi] or 0)
        except (TypeError, ValueError):
            pf_n = 0
        if pf_n <= 0:
            continue
        if _merge_resolve_delete_top_rows_count(sheet_name, mapping) is not None:
            continue
        result[sheet_name] = pf_n
    return result

def _merge_build_copy_sheets_trim_map(settings):
    """Совместимость: только автообрезка (без явного удаления)."""
    return _merge_build_copy_sheets_auto_trim_map(settings)

def _merge_sheet_scope_allows(sheet_name, scope_sheets):
    """True, если действие разрешено для листа по ограничению scope_sheets."""
    if scope_sheets is None:
        return True
    if not scope_sheets:
        return False
    key = merge_identity_key(sheet_name)
    for sn in scope_sheets:
        if merge_identity_key(sn) == key:
            return True
    return False

def _merge_resolve_delete_top_rows_count(sheet_name, mapping):
    """
    Число строк для удаления по имени листа.

    Точное / casefold / «N_Имя» ↔ «Имя» / шаблоны ``*`` (как фильтр «Листы»).
    Нужно, когда в JSON указано итоговое имя, а лист ещё с префиксом файла.
    """
    if not mapping or sheet_name is None:
        return None
    name = str(sheet_name).strip()
    if name == '':
        return None
    if name in mapping:
        return mapping[name]
    name_key = merge_identity_key(name)
    m_sheet = re.match('^(\\d+)_(.+)$', name)
    sheet_base = str(m_sheet.group(2)).strip() if m_sheet else ''
    sheet_base_key = merge_identity_key(sheet_base) if sheet_base else ''
    for k, v in mapping.items():
        mk = str(k or '').strip()
        if mk == '':
            continue
        if merge_identity_key(mk) == name_key:
            return v
        if sheet_base_key and merge_identity_key(mk) == sheet_base_key:
            return v
        m_map = re.match('^(\\d+)_(.+)$', mk)
        if m_map is not None:
            map_base = str(m_map.group(2)).strip()
            if map_base and merge_identity_key(map_base) == name_key:
                return v
        if '*' in mk or '?' in mk:
            if text_match(name, mk):
                return v
            if sheet_base and text_match(sheet_base, mk):
                return v
    return None

def _merge_apply_copy_sheets_row_trim_uno(doc, sheet, blk, sheet_name, file_index, report=None):
    """
    Автообрезка скопированного листа (UNO): top + after_header.

    Возвращает число удалённых строк (0 — пропуск).
    """
    if doc is None or sheet is None or blk is None:
        return 0
    if not _merge_copy_auto_trim_enabled():
        return 0
    if _merge_copy_sheets_has_explicit_delete_top(sheet_name, file_index):
        return 0
    if blk.get('no_header'):
        hr = 0
        last = 0
    else:
        hr, last = _merge_block_header_first_last_1(blk)
    sr = max(1, int(str(blk.get('start_row_disp') or '1')))
    top, after = _merge_copy_row_trim_parts(hr, sr, last)
    if top <= 0 and after <= 0:
        return 0
    removed = 0
    try:
        rows = sheet.getRows()
        if top > 0:
            rows.removeByIndex(0, int(top))
            removed += int(top)
        if after > 0:
            rows.removeByIndex(1, int(after))
            removed += int(after)
    except Exception as err:
        append_collect_log(doc, 'сбор данных', sheet.Name, _cw_cfg.P_MERGE_HEADER_ROW, '', 'ошибка', 'автообрезка %d+%d строк: %s' % (top, after, err))
        return 0
    append_collect_log(doc, 'сбор данных', sheet.Name, _cw_cfg.P_MERGE_HEADER_ROW, '', 'ok', 'автообрезка: сверху %d, после заголовка %d' % (top, after))
    if report is not None:
        try:
            report.stats['top_rows_deleted'] = report.stats.get('top_rows_deleted', 0) + int(removed)
        except Exception:
            pass
    return int(removed)

def _merge_copy_sheets_hdr_row_after_trim(sheet, blk, sheet_name=None, file_index=None, settings=None):
    """
    0-based строка заголовков на скопированном листе после автообрезки top/after_header.

    Координаты blk — до обрезки; после removeByIndex заголовок смещается на top строк вверх.
    """
    if blk is None:
        return 0
    if blk.get('no_header'):
        return -1
    if not _merge_copy_auto_trim_enabled(settings):
        return _merge_resolve_block_hdr_row(sheet, blk)
    if sheet_name is None and sheet is not None:
        try:
            sheet_name = str(getattr(sheet, 'Name', '') or '').strip()
        except Exception:
            sheet_name = ''
    if _merge_copy_sheets_has_explicit_delete_top(sheet_name, file_index, settings):
        return _merge_resolve_block_hdr_row(sheet, blk)
    if blk.get('no_header'):
        hr = 0
        last = 0
    else:
        hr, last = _merge_block_header_first_last_1(blk)
    sr = max(1, int(str(blk.get('start_row_disp') or '1')))
    top, after = _merge_copy_row_trim_parts(hr, sr, last)
    if top <= 0 and after <= 0:
        return _merge_resolve_block_hdr_row(sheet, blk)
    try:
        base = int(blk.get('hdr_row', 0))
    except (TypeError, ValueError):
        base = max(0, hr - 1)
    adjusted = max(0, base - top)
    return _merge_refine_header_row(
        sheet, adjusted, blk.get('start_col', 0), blk.get('header_row_explicit', False)
    )

def _merge_note_result_skipped_top(sheet_name, hdr_row_0):
    """
    Сколько строк над шапкой источника не переносились (one/many).

    hdr_row 0-based: 1 → над шапкой была 1 титульная строка. Нужно, чтобы
    «удаление_верхних_строк» не снимало ещё раз уже нескопированный титул
    (иначе с результата уходит строка заголовков).
    """
    sn = str(sheet_name or '').strip()
    if sn == '':
        return
    try:
        skipped = max(0, int(hdr_row_0))
    except (TypeError, ValueError):
        return
    if skipped <= 0:
        return
    store = _cw_get('_MERGE_RESULT_SKIPPED_TOP_ROWS')
    if store is None:
        store = {}
    prev = 0
    try:
        prev = int(store.get(sn) or 0)
    except (TypeError, ValueError):
        prev = 0
    if skipped > prev:
        store = dict(store)
        store[sn] = skipped
        _cw_cfg._MERGE_RESULT_SKIPPED_TOP_ROWS = store

def _merge_skipped_top_for_result_sheet(sheet_name):
    """Макс. число уже неперенесённых верхних строк для листа результата."""
    store = _cw_get('_MERGE_RESULT_SKIPPED_TOP_ROWS') or {}
    sn = str(sheet_name or '').strip()
    if sn == '' or not store:
        return 0
    best = 0
    for cand in _cell_to_column_sheet_name_candidates(sn) or [sn]:
        try:
            v = int(store.get(cand) or 0)
        except (TypeError, ValueError):
            v = 0
        if v > best:
            best = v
    # store может быть под именем результата; также сравнить ключи через матчер
    if best <= 0:
        for k, v in store.items():
            try:
                n = int(v or 0)
            except (TypeError, ValueError):
                n = 0
            if n <= best:
                continue
            if merge_identity_key(k) == merge_identity_key(sn):
                best = n
                continue
            for cand in _cell_to_column_sheet_name_candidates(sn) or []:
                if merge_identity_key(k) == merge_identity_key(cand):
                    best = n
                    break
    return int(best)

def _merge_apply_delete_top_rows_before_pp(doc, sheet, report=None, file_index=None):
    """
    Удалить верхние строки по параметру «удаление_верхних_строк» (до постобработки).

    Идемпотентно на лист за один прогон: в «Копирование листов» UNO вызывается
    и после копирования, и из apply_result_sheet_formatting — без метки удалялось дважды.
    В one/many: N уменьшается на число строк над «Строка_Заголовков», уже не
    перенесённых при чтении источника (иначе двойная обрезка титул+шапка).
    В xml_excel_ods не вызывается (_MERGE_DIRECT_XML_ACTIVE).

    Возвращает число удалённых строк (0 — пропуск).
    """
    if _cw_get('_MERGE_DIRECT_XML_ACTIVE'):
        return 0
    if doc is None or sheet is None:
        return 0
    sheet_name = str(getattr(sheet, 'Name', '') or '')
    done = _cw_get('_MERGE_DELETE_TOP_ROWS_DONE')
    if done is None:
        done = set()
    if sheet_name and sheet_name in done:
        return 0
    if file_index is None:
        file_index = (_cw_get('_MERGE_COPY_SHEETS_FILE_INDEX') or {}).get(sheet_name)
    n_rows = _merge_resolve_delete_top_rows_for_sheet(sheet_name, file_index)
    if n_rows is None or n_rows <= 0:
        return 0
    skipped = _merge_skipped_top_for_result_sheet(sheet_name)
    try:
        n_eff = int(n_rows) - int(skipped or 0)
    except (TypeError, ValueError):
        n_eff = int(n_rows)
    if n_eff <= 0:
        if sheet_name:
            done = set(done)
            done.add(sheet_name)
            _cw_cfg._MERGE_DELETE_TOP_ROWS_DONE = done
        if skipped > 0:
            append_collect_log(doc, 'сбор данных', sheet_name, _cw_cfg.P_MERGE_DELETE_TOP_ROWS, '', 'пропуск', 'N=%d уже учтено Строка_Заголовков (пропущено сверху %d)' % (int(n_rows), int(skipped)))
        return 0
    try:
        sheet.getRows().removeByIndex(0, int(n_eff))
    except Exception as err:
        append_collect_log(doc, 'сбор данных', sheet_name, _cw_cfg.P_MERGE_DELETE_TOP_ROWS, '', 'ошибка', 'удаление %d строк: %s' % (n_eff, err))
        return 0
    if sheet_name:
        done = set(done)
        done.add(sheet_name)
        _cw_cfg._MERGE_DELETE_TOP_ROWS_DONE = done
    note = 'удалено %d верхних строк' % n_eff
    if skipped > 0:
        note = '%s (из N=%d, −%d по Строка_Заголовков)' % (note, int(n_rows), int(skipped))
    append_collect_log(doc, 'сбор данных', sheet_name, _cw_cfg.P_MERGE_DELETE_TOP_ROWS, '', 'ok', note)
    if report is not None:
        try:
            report.stats['top_rows_deleted'] = report.stats.get('top_rows_deleted', 0) + int(n_eff)
        except Exception:
            pass
    return int(n_eff)

def parse_pp_extra_args(extra_cell):
    """
    Разбор дополнительных аргументов постобработки из колонки C листа параметров.

    Назначение:
        Преобразовать текст ячейки в список позиционных аргументов для merge_pp_*:
        целые, float (с запятой как десятичным разделителем) или строки.

    Параметры:
        extra_cell — значение ячейки C строки «Постобработка_Диапазон» / «Постобработка_Строка».

    Возвращает:
        list — элементы для *extra_args в _merge_pp_wrap_callback; пустая ячейка → [].

    Связь:
        read_postprocess_param_rows → parse_postprocess_from_sheet → _merge_pp_wrap_callback.
    """
    s = str(extra_cell).strip() if extra_cell is not None else ''
    if s == '':
        return []
    parts = []
    for part in s.split(','):
        p = part.strip()
        if p == '':
            continue
        if p.isdigit():
            parts.append(int(p))
            continue
        try:
            if '.' in p:
                parts.append(float(p.replace(',', '.')))
                continue
        except Exception:
            pass
        parts.append(p)
    return parts

def _merge_pp_pipeline_filter_extra(extra_raw, extra_args):
    """Текст C для фильтра шагов pipeline (после codec, не сырой JSON)."""
    if extra_args is not None and len(extra_args) > 0:
        s = str(extra_args[0] or '').strip()
        if s != '':
            return s
    return str(extra_raw or '').strip()

def _merge_pp_looks_like_json_payload(raw):
    """True, если C похожа на JSON (визард «Сохранить как JSON»)."""
    s = str(raw or '').strip()
    return bool(s) and s[0] in '[{'

def _merge_pp_codec_text_via_lib(fn_key, extra_raw):
    """JSON → текст C через libre_macros_lib (fallback без param_codec)."""
    try:
        import libre_macros_lib as _lm
        return _lm._lm_pp_codec_text_args(fn_key, extra_raw)
    except ImportError:
        s = str(extra_raw or '').strip()
        return [s] if s else []

def _merge_pp_codec_extra_args(extra_raw, fn_key):
    """JSON/текст через libre_macros_param_codec → одна строка C для lm_pp_*."""
    raw = str(extra_raw or '').strip() if extra_raw is not None else ''
    if raw == '':
        return None
    fn_key = _merge_pp_normalize_map_key(fn_key)
    if _merge_pp_looks_like_json_payload(raw):
        return [raw]
    try:
        from libre_macros_param_codec import is_codec_fn
    except ImportError:
        return None
    if not is_codec_fn(fn_key):
        return None
    return [raw]

def _merge_pp_resolve_extra_args(resolve_name, extra_raw, row_callback=False, final=False):
    """
    Колонка C/D → extra_args для merge_pp_* / merge_final_*.

    JSON из визарда не режется parse_pp_extra_args по запятым.
    """
    fn_key = str(resolve_name or '').strip()
    codec_args = _merge_pp_codec_extra_args(extra_raw, fn_key)
    if codec_args is not None:
        return codec_args
    if final:
        if _merge_final_is_zebra_name(fn_key):
            return _merge_final_zebra_extra_args(extra_raw)
        if _merge_final_is_sort_name(fn_key):
            return _merge_final_sort_extra_args(extra_raw)
        if _merge_final_is_colorize_name(fn_key):
            return _merge_final_colorize_extra_args(extra_raw)
        if _merge_final_is_header_plus_height_name(fn_key):
            return _merge_pp_header_plus_height_extra_args(extra_raw)
        if _merge_final_is_any_grid_name(fn_key):
            return _merge_pp_grid_extra_args(extra_raw)
    else:
        try:
            _ensure_pp_from_lib()
        except Exception:
            pass
        if _merge_pp_is_zebra_postprocess_name(fn_key):
            return _merge_pp_zebra_extra_args(extra_raw)
        if _merge_pp_is_sort_postprocess_name(fn_key):
            return _merge_pp_sort_extra_args(extra_raw)
        if _merge_pp_is_colorize_postprocess_name(fn_key):
            return _merge_pp_colorize_extra_args(extra_raw)
        if _merge_pp_is_header_plus_height_postprocess_name(fn_key):
            return _merge_pp_header_plus_height_extra_args(extra_raw)
        if _merge_pp_is_grid_postprocess_name(fn_key):
            return _merge_pp_grid_extra_args(extra_raw)
        if str(fn_key).strip().lower() == 'высота_строки':
            return _merge_pp_row_height_extra_args(extra_raw)
        if not row_callback and str(fn_key).strip().lower() == 'шрифт':
            return _merge_pp_font_extra_args(extra_raw)
        if not row_callback and _merge_pp_is_threshold_highlight_postprocess_name(fn_key):
            return _merge_pp_threshold_highlight_extra_args(extra_raw)
        if not row_callback and _merge_pp_is_color_scale_postprocess_name(fn_key):
            return _merge_pp_color_scale_extra_args(extra_raw)
        if not row_callback and _merge_pp_is_column_width_postprocess_name(fn_key):
            return _merge_pp_column_width_extra_args(extra_raw)
        if not row_callback and _merge_pp_is_pivot_table_postprocess_name(fn_key):
            return _merge_pp_pivot_table_extra_args(extra_raw)
    if _merge_pp_looks_like_json_payload(extra_raw):
        return [str(extra_raw).strip()]
    return parse_pp_extra_args(extra_raw)

