def _merge_pp_normalize_map_key(name):
    """Канонический ключ B (алиасы кодека: раскрасить → раскрасить_блоки и т.д.)."""
    try:
        from libre_macros_param_codec import normalize_fn_key
        return normalize_fn_key(name)
    except ImportError:
        return str(name or '').strip()

def _merge_pp_is_group_by_column_name(fn_name):
    try:
        return _merge_pp_normalize_map_key(fn_name) == 'группировка_по_столбцу'
    except Exception:
        return str(fn_name or '').strip().casefold() == 'группировка_по_столбцу'

def _merge_pp_group_by_extra_raw(extra_args):
    """extra_args обёртки → одна JSON/текст строка C."""
    if not extra_args:
        return ''
    if len(extra_args) == 1:
        a0 = extra_args[0]
        if isinstance(a0, dict):
            try:
                import json
                return json.dumps([a0], ensure_ascii=False, separators=(',', ':'))
            except Exception:
                return str(a0)
        return str(a0 or '').strip()
    parts = []
    for a in extra_args:
        if isinstance(a, dict):
            try:
                import json
                parts.append(json.dumps(a, ensure_ascii=False, separators=(',', ':')))
            except Exception:
                parts.append(str(a))
        else:
            parts.append(str(a))
    return ','.join(parts)

def _merge_pp_group_by_block_from_extra(extra_args):
    """Первый dict-блок группировка_по_столбцу из extra_args обёртки."""
    if not extra_args:
        return None
    try:
        from libre_macros_param_codec import param_decode, _normalize_group_by_column_block
        if len(extra_args) == 1 and isinstance(extra_args[0], dict):
            return _normalize_group_by_column_block(extra_args[0])
        # Важно: param_decode ждёт строку, не list (иначе unicode(list) ломает JSON).
        raw = _merge_pp_group_by_extra_raw(extra_args)
        blocks = param_decode('группировка_по_столбцу', raw)
        if blocks and isinstance(blocks[0], dict):
            return _normalize_group_by_column_block(blocks[0])
    except Exception:
        pass
    if len(extra_args) == 1 and isinstance(extra_args[0], dict):
        return extra_args[0]
    return None

def _merge_pp_group_by_block_from_fn(fn):
    extra = getattr(fn, '_merge_pp_extra_args', None)
    return _merge_pp_group_by_block_from_extra(extra)

def _merge_pp_group_by_coalesce_key(fn_or_block):
    """
    Ключ склейки подряд идущих группировка_по_столбцу: (marker, sheet).
    None — не группировка.
    """
    block = None
    fn_obj = None
    if isinstance(fn_or_block, dict):
        block = fn_or_block
    else:
        fn_obj = fn_or_block
        label = _merge_postprocess_fn_label(fn_or_block)
        fn_key = getattr(fn_or_block, '_merge_pp_fn_key', None) or label
        if not _merge_pp_is_group_by_column_name(fn_key) and not _merge_pp_is_group_by_column_name(label):
            return None
        block = _merge_pp_group_by_block_from_fn(fn_or_block)
    if isinstance(block, dict):
        marker = block.get('marker')
        if isinstance(marker, (list, tuple)):
            marker = marker[0] if marker else ''
        try:
            from libre_macros_param_codec import (
                unwrap_column_name_token,
                canonicalize_column_name_token_for_store,
            )
            tok = canonicalize_column_name_token_for_store(marker)
            if isinstance(tok, int):
                marker_key = '#%d' % int(tok)
            else:
                bare, _exact = unwrap_column_name_token(tok)
                marker_key = str(bare or tok or '').strip().casefold()
        except Exception:
            marker_key = str(marker or '').strip().casefold()
        sheet_key = str(block.get('sheet') or '').strip().casefold()
        return (marker_key, sheet_key)
    # Блок не разобрали — всё равно склеиваем подряд идущие группировка_по_столбцу
    # по сырому marker/sheet из JSON, иначе шаги снова пойдут порознь.
    if fn_obj is not None:
        raw = _merge_pp_group_by_extra_raw(getattr(fn_obj, '_merge_pp_extra_args', None) or [])
        mk = ''
        sk = ''
        try:
            import re
            m = re.search(r'"marker"\s*:\s*"((?:\\.|[^"\\])*)"', raw)
            if m:
                mk = str(m.group(1) or '').replace("\\'", "'").strip().casefold()
                if len(mk) >= 2 and mk[0] == "'" and mk[-1] == "'":
                    mk = mk[1:-1]
            m2 = re.search(r'"sheet"\s*:\s*"((?:\\.|[^"\\])*)"', raw)
            if m2:
                sk = str(m2.group(1) or '').strip().casefold()
        except Exception:
            pass
        return (mk or '__group_by__', sk)
    return None

def _merge_pp_run_group_by_merged(doc, sheet, data_range, header_row_range, fns):
    """Один проход группировка_по_столбцу по склеенным уровням aggs."""
    blocks = []
    for fn in fns or []:
        b = _merge_pp_group_by_block_from_fn(fn)
        if isinstance(b, dict):
            blocks.append(b)
    if not blocks:
        if fns:
            fns[0](doc, sheet, data_range, header_row_range)
        return
    try:
        from libre_macros_param_codec import merge_group_by_column_blocks
        merged = merge_group_by_column_blocks(blocks)
    except Exception:
        merged = blocks[0]
    _ensure_pp_from_lib()
    import libre_macros_lib as lm
    lm.lm_pp_range_group_by_column(doc, sheet, data_range, header_row_range, merged)

def _merge_pp_is_plugin_fn_key(fn_name):
    """Колонка B = «функция_плагин»; ссылка/код — в C, rest — в D."""
    key = str(fn_name or '').strip().casefold()
    return key in ('функция_плагин', 'plugin_function', 'plugin')

def _merge_attach_step_condition(target, fn_name, d_raw='', e_raw=''):
    """Прикрепить сырой JSON условия (D codec / E plugin) к wrapped fn или step-dict."""
    raw = ''
    try:
        from libre_macros_step_condition_lib import pick_condition_raw
        raw = pick_condition_raw(fn_name, d_raw, e_raw)
    except Exception:
        try:
            if _merge_pp_is_plugin_fn_key(fn_name):
                raw = str(e_raw or '').strip()
            else:
                raw = str(d_raw or '').strip()
        except Exception:
            raw = ''
    if target is None:
        return target
    if isinstance(target, dict):
        target['condition_raw'] = raw
        if 'condition_decision' in target:
            try:
                del target['condition_decision']
            except Exception:
                target['condition_decision'] = None
        return target
    try:
        target._merge_step_condition_raw = raw
        # Не оставлять кэш с прошлого запуска на shared map-callable.
        if hasattr(target, '_merge_step_condition_decision'):
            try:
                delattr(target, '_merge_step_condition_decision')
            except Exception:
                target._merge_step_condition_decision = None
    except Exception:
        pass
    return target

def _merge_step_condition_allows(target, doc=None, label='', scope='диапазон', sheet_name='', final=False):
    """
    Gate условия выполнения шага.

    True — выполнять; False — пропуск или ошибка условия (уже в журнале).
    Результат кэшируется на target (один раз на шаг, не на каждый лист/строку).
    """
    if target is None:
        return True
    if isinstance(target, dict):
        raw = target.get('condition_raw') or ''
        if 'condition_decision' in target and target.get('condition_decision') is not None:
            return bool(target.get('condition_decision'))
    else:
        raw = getattr(target, '_merge_step_condition_raw', None) or ''
        if hasattr(target, '_merge_step_condition_decision'):
            cached = getattr(target, '_merge_step_condition_decision', None)
            if cached is not None:
                return bool(cached)
    if str(raw or '').strip() == '':
        return True
    summary = ''
    ok = True
    err_text = ''
    try:
        from libre_macros_step_condition_lib import eval_step_condition
        ok, summary = eval_step_condition(raw)
    except Exception as err:
        ok = False
        err_text = str(err)
    if isinstance(target, dict):
        target['condition_decision'] = bool(ok) and (err_text == '')
        # при ошибке оценки — не кэшировать как «успешный skip»
        if err_text != '':
            target['condition_decision'] = False
    else:
        try:
            if err_text != '':
                target._merge_step_condition_decision = False
            else:
                target._merge_step_condition_decision = bool(ok)
        except Exception:
            pass
    status = 'пропуск'
    note = 'условие=False (%s)' % (summary or '')
    if err_text != '':
        status = 'ошибка'
        note = 'условие: %s' % err_text
        print('  ⚠ условие шага «%s»: %s' % (label or '?', err_text))
    elif not ok:
        print('  · условие шага «%s»: False — пропуск (%s)' % (label or '?', summary or ''))
    else:
        return True
    if final:
        _merge_log_final_processing(doc, str(label or ''), status, note)
    else:
        _merge_log_postprocess(doc, sheet_name, scope, label, status, note)
    return False

def _merge_pp_plugin_blocks_from_parsed(parsed):
    """Все блоки из JSON list/dict для «функция_плагин»."""
    if isinstance(parsed, list):
        out = []
        i = 0
        while i < len(parsed):
            item = parsed[i]
            if isinstance(item, dict):
                out.append(item)
            i = i + 1
        return out
    if isinstance(parsed, dict):
        return [parsed]
    return []

def _merge_pp_plugin_block_from_parsed(parsed):
    """Первый блок из JSON list/dict для «функция_плагин»."""
    blocks = _merge_pp_plugin_blocks_from_parsed(parsed)
    if len(blocks) == 0:
        return None
    return blocks[0]

def _merge_pp_try_parse_plugin_json(s):
    """Разбор JSON плагина; терпим к Calc (кавычки, переносы строк в ячейке)."""
    import json
    raw = str(s or '').strip()
    if raw == '':
        return None
    if len(raw) >= 2 and raw[0] == '"' and (raw[-1] == '"'):
        unq = raw[1:-1].strip()
        if unq.startswith('[') or unq.startswith('{'):
            raw = unq
    candidates = [raw]
    if '\n' in raw and raw.lstrip().startswith('['):
        candidates.append(raw.replace('\r\n', ' ').replace('\n', ' '))
    for cand in candidates:
        try:
            data = json.loads(cand)
            if isinstance(data, (list, dict)):
                return data
        except Exception:
            pass
    try:
        from libre_macros_param_codec import _parse_json_relaxed
        data = _parse_json_relaxed(raw)
        if isinstance(data, (list, dict)):
            return data
    except Exception:
        pass
    return None

def _merge_pp_plugin_blocks_from_c_raw(c_raw):
    """JSON-блоки «функция_плагин» из колонки C (список, может быть пустым)."""
    c_s = str(c_raw or '').strip()
    if c_s == '':
        return []
    kind, val = _merge_pp_parse_plugin_function_text(c_s)
    if kind == 'json':
        return _merge_pp_plugin_blocks_from_parsed(val)
    return []

def _merge_pp_plugin_block_from_c_raw(c_raw):
    """Первый JSON-блок «функция_плагин» из колонки C (или None)."""
    blocks = _merge_pp_plugin_blocks_from_c_raw(c_raw)
    if len(blocks) == 0:
        return None
    return blocks[0]

def _merge_pp_resolve_plugin_block(block, d_raw=''):
    """ref/code и extra из одного dict-блока плагина."""
    if not isinstance(block, dict):
        return ('', '')
    if block.get('code'):
        ref = str(block.get('code') or '').strip()
    else:
        ref = str(block.get('ref') or block.get('c') or '').strip()
    extra = str(block.get('extra') or block.get('d') or '').strip()
    if extra == '':
        extra = str(d_raw or '').strip()
    return (ref, extra)

def _merge_pp_iter_plugin_row_specs(fn_name, c_raw, d_raw=''):
    """
    Итератор (plugin_block, resolve_name, extra_raw) по строке B=функция_плагин.
    Несколько объектов в JSON C → несколько спецификаций (блок на лист).
    """
    if not _merge_pp_is_plugin_fn_key(fn_name):
        resolve_name, extra_raw = _merge_pp_resolve_row_fn_and_extra(fn_name, c_raw, d_raw)
        yield (None, resolve_name, extra_raw)
        return
    blocks = _merge_pp_plugin_blocks_from_c_raw(c_raw)
    if len(blocks) == 0:
        resolve_name, extra_raw = _merge_pp_resolve_row_fn_and_extra(fn_name, c_raw, d_raw)
        yield (None, resolve_name, extra_raw)
        return
    i = 0
    while i < len(blocks):
        block = blocks[i]
        resolve_name, extra_raw = _merge_pp_resolve_plugin_block(block, d_raw)
        extra_raw = _merge_pp_plugin_extra_text(block, extra_raw, d_raw)
        yield (block, resolve_name, extra_raw)
        i = i + 1

def _merge_pp_plugin_sheet_targets(block):
    """Имена листов из block.sheet / block.sheets; None — все листы."""
    if not isinstance(block, dict):
        return None
    sheets = block.get('sheets')
    if sheets is not None:
        names = set()
        if isinstance(sheets, (list, tuple)):
            si = 0
            while si < len(sheets):
                s = str(sheets[si] or '').strip()
                if s != '':
                    names.add(s)
                si = si + 1
        else:
            for part in str(sheets or '').replace(';', ',').split(','):
                p = part.strip()
                if p != '':
                    names.add(p)
        return names if len(names) > 0 else None
    sheet = str(block.get('sheet') or '').strip()
    if sheet == '':
        return None
    names = set()
    for part in sheet.replace(';', ',').split(','):
        p = part.strip()
        if p != '':
            names.add(p)
    return names if len(names) > 0 else None

def _merge_pp_plugin_applies_to_sheet(block, sheet_name):
    """True, если плагин нужно выполнить на этом листе."""
    targets = _merge_pp_plugin_sheet_targets(block)
    if not targets:
        return True
    try:
        import libre_macros_lib as _lm
        return _lm._lm_pp_sheet_name_matches_target(sheet_name, targets)
    except ImportError:
        nm = str(sheet_name or '').strip()
        return nm in targets

def _merge_pp_plugin_extra_text(block, extra_raw, d_raw):
    """Текст extra для плагина: JSON extra → D → d_raw."""
    if isinstance(block, dict):
        ex = str(block.get('extra') or block.get('d') or '').strip()
        if ex != '':
            return ex
    er = str(extra_raw or '').strip()
    if er != '':
        return er
    return str(d_raw or '').strip()

def _merge_pp_attach_plugin_block(wrapped, fn_name, c_raw):
    """Прикрепить JSON-блок плагина к обёртке для фильтра по листу."""
    if not _merge_pp_is_plugin_fn_key(fn_name):
        return wrapped
    block = _merge_pp_plugin_block_from_c_raw(c_raw)
    if block is not None:
        wrapped._merge_pp_plugin_block = block
    return wrapped

def _merge_pp_wrapped_applies_to_sheet(wrapped, sheet):
    """Фильтр листа для обёртки с _merge_pp_plugin_block."""
    block = getattr(wrapped, '_merge_pp_plugin_block', None)
    if block is None:
        return True
    sheet_name = ''
    if sheet is not None:
        try:
            sheet_name = str(sheet.Name)
        except Exception:
            pass
    return _merge_pp_plugin_applies_to_sheet(block, sheet_name)

def _merge_pp_resolve_plugin_c_d(c_raw, d_raw=''):
    """
    C/D при B=функция_плагин: file#func|код + D или JSON [{ref|code, extra, sheet}].
    """
    c_s = str(c_raw or '').strip()
    d_s = str(d_raw or '').strip()
    kind, val = _merge_pp_parse_plugin_function_text(c_s)
    if kind == 'json':
        block = _merge_pp_plugin_block_from_parsed(val)
        if block is not None:
            if block.get('code'):
                ref = str(block.get('code') or '').strip()
            else:
                ref = str(block.get('ref') or block.get('c') or '').strip()
            extra = str(block.get('extra') or block.get('d') or '').strip()
            if extra == '':
                extra = d_s
            if ref != '':
                return (ref, extra)
    return (c_s, d_s)

def _merge_pp_resolve_row_fn_and_extra(fn_name, c_raw, d_raw=''):
    """
    Нормализация строки постобработки/финала.

    Новый формат: B=функция_плагин, C=JSON или file#func/Python, D=rest (если не в JSON).
    C JSON: [{"v":1,"fn":"функция_плагин","ref":"…","extra":"…","sheet":"Лист"}].
    Legacy: B=ключ|file#fn|код, C=rest.
    """
    if _merge_pp_is_plugin_fn_key(fn_name):
        return _merge_pp_resolve_plugin_c_d(c_raw, d_raw)
    b_s = str(fn_name or '').strip()
    c_s = str(c_raw or '').strip()
    kind, val = _merge_pp_parse_plugin_function_text(b_s)
    if kind == 'json':
        block = _merge_pp_plugin_block_from_parsed(val)
        if block is not None and _merge_pp_is_plugin_fn_key(block.get('fn')):
            return _merge_pp_resolve_plugin_c_d(b_s, c_s or str(d_raw or '').strip())
    return (b_s, c_s)

def resolve_postprocess_function(name, function_map, namespace_getter=None, file_cache=None):
    """
    Поиск callable постобработки по имени или Python-коду из ячейки B.

    Назначение:
        1) ключ MERGE_RESULT_POSTPROCESS_*_MAP;
        2) __name__ функции merge_pp_* из карты;
        3) «путь.py#func» — def func из файла (путь относительно каталога макроса);
        4) Python-код: lambda … или def … (eval/exec, см. _merge_pp_compile_postprocess_code).

    Параметры:
        name — текст из колонки B.
        function_map — dict «короткое имя» → функция merge_pp_*.
        namespace_getter — опционально eval/exec namespace (финальная обработка).
        file_cache — опционально отдельный кэш file#func.

    Возвращает:
        callable или None.

    Связь:
        parse_postprocess_from_sheet; карты и REST_HINTS — в конце модуля.
    """
    key = str(name).strip()
    if key == '':
        return None
    if key in function_map:
        return function_map[key]
    norm = _merge_pp_normalize_map_key(key)
    if norm != key and norm in function_map:
        return function_map[norm]
    key_cf = key.casefold()
    norm_cf = str(norm).casefold()
    for map_key, fn in function_map.items():
        mk_cf = str(map_key).casefold()
        if mk_cf == key_cf or mk_cf == norm_cf:
            return fn
    for fn in function_map.values():
        if fn is not None and getattr(fn, '__name__', None) == key:
            return fn
    if _merge_pp_looks_like_file_function_ref(key):
        path_part, func_name = key.split('#', 1)
        fn = _merge_pp_load_function_from_file_ref(path_part.strip(), func_name.strip(), namespace_getter=namespace_getter, file_cache=file_cache)
        if fn is not None and callable(fn):
            return fn
    if _merge_pp_looks_like_python_code(key):
        fn = _merge_pp_compile_postprocess_code(key, namespace_getter=namespace_getter)
        if fn is not None and callable(fn):
            return fn
    return None

def resolve_final_processing_function(name, function_map):
    """Поиск callable финальной обработки (как resolve_postprocess_function)."""
    return resolve_postprocess_function(name, function_map, namespace_getter=_merge_final_eval_namespace, file_cache=_cw_cfg._MERGE_FINAL_FILE_FN_CACHE)

def _merge_pp_looks_like_python_code(text):
    """True, если B похожа на lambda/def, а не на ключ карты."""
    t = str(text).strip()
    if t == '':
        return False
    if t.startswith('lambda'):
        return True
    if t.startswith('def '):
        return True
    if '\n' in t and ('def ' in t or 'lambda ' in t):
        return True
    if t.startswith('(') and 'lambda' in t:
        return True
    return False

def _merge_pp_parse_plugin_function_text(raw_text):
    """
    Разбор текста для «функция_плагин» (колонка C).

    Правила (см. заметки ТЗ/диалог):
        1) JSON: строка начинается с '[{' и заканчивается на '}]' → parsed_json (list/dict).
        2) Python def после trim → python_def.
        3) Python lambda после trim → python_lambda.
        4) Иначе: если есть разделитель '#', то это ссылка file.py#func → file_ref.

    Возвращает tuple(kind, value):
        kind ∈ {'json', 'python_def', 'python_lambda', 'file_ref', 'text'}
        value — распарсенное значение (для json) или исходная строка (для остальных).
    """
    s = str(raw_text or '').strip()
    if s == '':
        return ('text', '')
    if s.lstrip().startswith('[') or (s.lstrip().startswith('{') and '"fn"' in s):
        parsed = _merge_pp_try_parse_plugin_json(s)
        if isinstance(parsed, (list, dict)):
            return ('json', parsed)
    if s.startswith('def '):
        return ('python_def', s)
    if s.startswith('lambda'):
        return ('python_lambda', s)
    if '#' in s:
        return ('file_ref', s)
    return ('text', s)

def _merge_macro_script_dir():
    """
    Каталог основного скрипта макроса (collect_workbooks.py).

    Сначала __file__ модуля; иначе ~/.config/libreoffice/*/user/Scripts/python; иначе cwd.
    От него разрешаются относительные пути в B вида «functions_pp.py#pp_stroka_itogo».
    """
    if _cw_cfg._MERGE_MACRO_SCRIPT_DIR_CACHE is not None:
        return _cw_cfg._MERGE_MACRO_SCRIPT_DIR_CACHE
    try:
        here = None
        mf = str(__file__ or '')
        if mf.lower().startswith('file://'):
            here = os.path.dirname(uno.fileUrlToSystemPath(__file__))
        else:
            here = os.path.dirname(os.path.abspath(__file__))
        if here and os.path.isdir(here):
            _cw_cfg._MERGE_MACRO_SCRIPT_DIR_CACHE = here
            return here
    except NameError:
        pass
    except Exception:
        pass
    home = os.environ.get('HOME') or os.path.expanduser('~')
    for rel in (os.path.join('.config', 'libreoffice', '4', 'user', 'Scripts', 'python'), os.path.join('.config', 'libreoffice', '24', 'user', 'Scripts', 'python')):
        cand = os.path.join(home, rel)
        if os.path.isdir(cand):
            _cw_cfg._MERGE_MACRO_SCRIPT_DIR_CACHE = cand
            return cand
    _cw_cfg._MERGE_MACRO_SCRIPT_DIR_CACHE = os.getcwd()
    return _cw_cfg._MERGE_MACRO_SCRIPT_DIR_CACHE

def _merge_pp_looks_like_file_function_ref(text):
    """True, если B = «путь/файл.py#имя_функции» (одна строка, одна #)."""
    t = str(text).strip()
    if t == '' or '\n' in t:
        return False
    if t.count('#') != 1:
        return False
    if t.startswith('def ') or t.startswith('lambda'):
        return False
    path_part, fn_name = t.split('#', 1)
    path_part = path_part.strip()
    fn_name = fn_name.strip()
    if path_part == '' or fn_name == '':
        return False
    if not fn_name.isidentifier():
        return False
    return True

def _merge_pp_resolve_script_path(path_part):
    """Абсолютный путь к .py: абсолютный path_part или относительно каталога макроса."""
    p = str(path_part).strip()
    if p == '':
        return None
    if os.path.isabs(p):
        return p if os.path.isfile(p) else None
    base = _merge_macro_script_dir()
    cand = os.path.normpath(os.path.join(base, p))
    if os.path.isfile(cand):
        return cand
    return None

def _merge_pp_extract_function_source(file_text, func_name):
    """Исходный текст def func_name из файла (верхний уровень модуля)."""
    try:
        tree = ast.parse(file_text)
    except SyntaxError:
        return _merge_pp_extract_function_source_lines(file_text, func_name)
    lines = file_text.splitlines()
    for node in tree.body:
        if isinstance(node, ast.FunctionDef) and node.name == func_name:
            if hasattr(ast, 'get_source_segment'):
                seg = ast.get_source_segment(file_text, node)
                if seg is not None and str(seg).strip() != '':
                    return seg
            end = getattr(node, 'end_lineno', None)
            if end is not None:
                return '\n'.join(lines[node.lineno - 1:end])
            return _merge_pp_extract_function_source_lines(file_text, func_name)
    return _merge_pp_extract_function_source_lines(file_text, func_name)

def _merge_pp_extract_function_source_lines(file_text, func_name):
    """Резерв: вырезать def func_name построчно до следующего def/class верхнего уровня."""
    lines = file_text.splitlines()
    def_prefix = 'def ' + func_name + '('
    start = None
    i = 0
    while i < len(lines):
        line = lines[i]
        if start is None:
            if line.lstrip().startswith(def_prefix):
                start = i
        else:
            stripped = line.lstrip()
            if stripped.startswith('def ') or stripped.startswith('class '):
                if line and line[0] not in (' ', '\t'):
                    break
        i = i + 1
    if start is None:
        return None
    return '\n'.join(lines[start:i])

def _merge_pp_load_function_from_file_ref(path_part, func_name, namespace_getter=None, file_cache=None):
    """
    Прочитать def func_name из .py и скомпилировать через _merge_pp_compile_postprocess_code.
    """
    abs_path = _merge_pp_resolve_script_path(path_part)
    if abs_path is None:
        print('  ⚠ Файл постобработки не найден: %s (каталог макроса: %s)' % (path_part, _merge_macro_script_dir()))
        return None
    try:
        mtime = os.path.getmtime(abs_path)
    except OSError as err:
        print('  ⚠ Не удалось прочитать mtime %s: %s' % (abs_path, err))
        return None
    cache_key = (abs_path, func_name)
    cache = file_cache if file_cache is not None else _cw_cfg._MERGE_PP_FILE_FN_CACHE
    cached = cache.get(cache_key)
    if cached is not None and cached[0] == mtime:
        return cached[1]
    try:
        f = io.open(abs_path, 'r', encoding='utf-8')
        try:
            file_text = f.read()
        finally:
            f.close()
    except OSError as err:
        print('  ⚠ Не удалось открыть %s: %s' % (abs_path, err))
        return None
    source = _merge_pp_extract_function_source(file_text, func_name)
    if source is None or str(source).strip() == '':
        print('  ⚠ В файле %s нет функции def %s' % (abs_path, func_name))
        return None
    fn = _merge_pp_compile_postprocess_code(source, namespace_getter=namespace_getter)
    if fn is not None and callable(fn):
        cache[cache_key] = (mtime, fn)
    return fn

def _merge_pp_short_label(text, max_len=120):
    """
    Короткая подпись для журнала: первая строка кода из B + «…», ключ карты без изменений.
    """
    t = str(text).strip()
    if t == '':
        return '?'
    if '\n' in t or _merge_pp_looks_like_python_code(t):
        first = t.split('\n', 1)[0].strip()
        if len(first) > max_len:
            first = first[:max_len - 1] + '…'
        return first + '…'
    if len(t) > max_len:
        return t[:max_len - 1] + '…'
    return t

def _merge_pp_format_postprocess_error(err):
    """Текст ошибки постобработки с traceback для лога и консоли."""
    tb = traceback.format_exc()
    if tb and tb.strip() not in ('NoneType: None\n', 'NoneType: None'):
        return '%s\n%s' % (err, tb)
    return str(err)

def _merge_pp_compile_postprocess_code(code_text, namespace_getter=None):
    """
    Скомпилировать Python-код из колонки B в callable постобработки.

    Поддерживает: lambda doc,sheet,…: …  и  def my_pp(doc, sheet, …): …
    Перед eval/exec — статическая санация (libre_macros_sanitize_lib).
    Fail-closed: без успешной санации код не компилируется.

    Возвращает callable или None.
    """
    code = str(code_text).strip()
    if code == '':
        return None
    try:
        from libre_macros_sanitize_lib import (
            lm_sanitize_code,
            lm_sanitize_format_issues,
            lm_sanitize_filtered_builtins,
        )
    except Exception as err:
        print('  ⚠ Санация Python-постобработки недоступна — код отклонён: %s' % err)
        return None
    try:
        san = lm_sanitize_code(code)
        if not san.ok:
            detail = lm_sanitize_format_issues(san.issues)
            print('  ⚠ Санация Python-постобработки в B: %s' % detail)
            return None
    except Exception as err:
        print('  ⚠ Санация Python-постобработки сбой — код отклонён: %s' % err)
        return None
    getter = namespace_getter if namespace_getter is not None else _merge_pp_postprocess_eval_namespace
    ns = getter()
    try:
        builtins_map = lm_sanitize_filtered_builtins(
            blocklist=_cw_cfg._MERGE_PP_EVAL_BUILTIN_BLOCKLIST
        )
    except Exception as err:
        print('  ⚠ Builtins постобработки недоступны — код отклонён: %s' % err)
        return None
    glo = {'__builtins__': builtins_map}
    glo.update(ns)
    try:
        if code.lstrip().startswith('lambda'):
            fn = eval(code, glo, {})
            if callable(fn):
                return fn
        loc = {}
        exec(code, glo, loc)
        if 'fn' in loc and callable(loc['fn']):
            return loc['fn']
        for v in loc.values():
            if callable(v):
                return v
    except Exception as err:
        detail = _merge_pp_format_postprocess_error(err)
        print('  ⚠ Ошибка Python-постобработки в B: %s' % detail)
    return None

def _merge_pp_postprocess_eval_builtins():
    """
    Builtins для eval/exec в колонке B: почти весь модуль builtins, кроме blocklist.

    Без __import__, eval, exec, open и т.п. Результат кэшируется.
    """
    if _cw_cfg._MERGE_PP_EVAL_BUILTINS_CACHE is not None:
        return _cw_cfg._MERGE_PP_EVAL_BUILTINS_CACHE
    out = {}
    for name, obj in vars(builtins).items():
        if name.startswith('_'):
            continue
        if name in _cw_cfg._MERGE_PP_EVAL_BUILTIN_BLOCKLIST:
            continue
        out[name] = obj
    _cw_cfg._MERGE_PP_EVAL_BUILTINS_CACHE = out
    return out

def _merge_pp_resolve_eval_helper(name):
    """
    Имя для exec пользовательского кода (functions_*.py / колонка B/C).
    Сначала globals() collect_workbooks (после shims), иначе libre_macros_lib.
    """
    key = str(name or '').strip()
    if key == '':
        return None
    mod = globals()
    obj = mod.get(key)
    if obj is not None:
        return obj
    if not mod.get('_PP_SHIMS_INSTALLED'):
        try:
            _install_pp_shims()
        except Exception:
            pass
        obj = mod.get(key)
        if obj is not None:
            return obj
    try:
        import libre_macros_lib as lm
    except ImportError:
        return None
    if key.startswith('_merge_pp_'):
        return getattr(lm, '_lm_pp_' + key[len('_merge_pp_'):], None)
    return getattr(lm, key, None)

def _merge_pp_postprocess_eval_namespace():
    """
    Имена, доступные в Python-коде колонки B (lambda/def).

    Карты постобработки, merge_pp_* (в т.ч. merge_pp_user_log), lo_color_rgb, cell_text,
    merge_pp_active_context, traceback.
    """
    try:
        _ensure_pp_from_lib()
    except Exception:
        pass
    ns = {}
    try:
        ns.update(_cw_cfg.MERGE_RESULT_POSTPROCESS_RANGE_MAP)
        ns.update(_cw_cfg.MERGE_RESULT_POSTPROCESS_ROW_MAP)
    except NameError:
        pass
    mod = globals()
    for name, obj in mod.items():
        if name.startswith('merge_pp_') and callable(obj):
            ns[name] = obj
    for helper_name in ('lo_color_rgb', 'cell_text', 'merge_pp_active_context', '_merge_pp_number_format_key', '_merge_pp_range_address', '_merge_pp_foreach_row', 'merge_ui_yield', 'merge_ui_status_set'):
        helper = _merge_pp_resolve_eval_helper(helper_name)
        if helper is not None:
            ns[helper_name] = helper
    ns['traceback'] = traceback
    ns['MERGE_UI_STATUS_EVERY_ROWS'] = _cw_cfg.MERGE_UI_STATUS_EVERY_ROWS
    ns['MERGE_UI_YIELD_EVERY_ROWS'] = _cw_cfg.MERGE_UI_YIELD_EVERY_ROWS
    return ns

def _merge_final_eval_namespace():
    """
    Имена для Python-кода колонки B в «Финальная_обработка».
    """
    try:
        _ensure_pp_from_lib()
    except Exception:
        pass
    ns = {}
    try:
        ns.update(_cw_cfg.MERGE_FINAL_PROCESSING_MAP)
    except NameError:
        pass
    mod = globals()
    for name, obj in mod.items():
        if name.startswith('merge_final_') and callable(obj):
            ns[name] = obj
        elif name.startswith('merge_pp_') and callable(obj):
            ns[name] = obj
    for helper in ('lo_color_rgb', 'cell_text', 'merge_pp_user_log', 'merge_pp_active_context', 'merge_ui_yield', 'merge_ui_status_set'):
        obj = _merge_pp_resolve_eval_helper(helper)
        if obj is not None:
            ns[helper] = obj
    ns['traceback'] = traceback
    return ns

def _merge_final_wrap_plugin_sheet_filter(wrapped):
    """Ограничить финальный плагин листами из JSON block.sheet / block.sheets."""
    block = getattr(wrapped, '_merge_pp_plugin_block', None)
    if block is None or _merge_pp_plugin_sheet_targets(block) is None:
        return wrapped
    inner = wrapped
    label = getattr(wrapped, '_merge_final_label', None)

    def filtered(doc, sheets, data_ranges, header_row_ranges):
        if sheets is None:
            return
        filtered_sheets = []
        filtered_data = []
        filtered_headers = []
        data = list(data_ranges or [])
        headers = list(header_row_ranges or [])
        i = 0
        while i < len(sheets):
            sheet = sheets[i]
            data_rng = data[i] if i < len(data) else None
            header_rng = headers[i] if i < len(headers) else None
            i = i + 1
            if sheet is None:
                continue
            if not _merge_pp_plugin_applies_to_sheet(block, sheet):
                continue
            filtered_sheets.append(sheet)
            filtered_data.append(data_rng)
            filtered_headers.append(header_rng)
        if len(filtered_sheets) == 0:
            return
        return inner(doc, filtered_sheets, filtered_data, filtered_headers)
    if label is not None:
        filtered._merge_final_label = label
    filtered._merge_pp_plugin_block = block
    return filtered

def _merge_final_wrap_callback(fn, extra_args, fn_name=None):
    """Обёртка финальной обработки: (doc, sheets, data_ranges, header_row_ranges, *extra_args)."""
    if fn_name is not None and str(fn_name).strip() != '':
        label = _merge_pp_short_label(fn_name)
    else:
        label = getattr(fn, '__name__', '?')
    key_cf = str(fn_name or '').strip().casefold()
    if key_cf == 'вертикаль_центр':
        sheet_names = []
        if extra_args:
            for arg in extra_args:
                if arg is None:
                    continue
                text = str(arg)
                text = text.replace(';', ',')
                for part in text.split(','):
                    s = part.strip()
                    if s != '':
                        sheet_names.append(s)
        if len(sheet_names) == 0:

            def wrapped(doc, sheets, data_ranges, header_row_ranges):
                return
            wrapped._merge_final_label = label
            return wrapped
        target_names = set(sheet_names)

        def wrapped(doc, sheets, data_ranges, header_row_ranges):
            if sheets is None:
                return
            filtered_sheets = []
            filtered_data = []
            filtered_headers = []
            data = list(data_ranges or [])
            headers = list(header_row_ranges or [])
            i = 0
            while i < len(sheets):
                sheet = sheets[i]
                data_rng = data[i] if i < len(data) else None
                header_rng = headers[i] if i < len(headers) else None
                i += 1
                if sheet is None:
                    continue
                try:
                    nm = str(getattr(sheet, 'Name', '')).strip()
                except Exception:
                    nm = ''
                if nm not in target_names:
                    continue
                filtered_sheets.append(sheet)
                filtered_data.append(data_rng)
                filtered_headers.append(header_rng)
            if not filtered_sheets:
                return
            return fn(doc, filtered_sheets, filtered_data, filtered_headers)
        wrapped._merge_final_label = label
        return wrapped
    if extra_args is None or len(extra_args) == 0:

        def wrapped(doc, sheets, data_ranges, header_row_ranges):
            return fn(doc, sheets, data_ranges, header_row_ranges)
        wrapped._merge_final_label = label
        return wrapped

    def wrapped(doc, sheets, data_ranges, header_row_ranges):
        return fn(doc, sheets, data_ranges, header_row_ranges, *extra_args)
    wrapped._merge_final_label = label
    return wrapped

def _merge_final_fn_label(fn):
    if fn is None:
        return '?'
    label = getattr(fn, '_merge_final_label', None)
    if label is not None and str(label).strip() != '':
        return str(label)
    return getattr(fn, '__name__', repr(fn))

def _merge_final_is_values_only_name(fn_name):
    key = str(fn_name or '').strip().casefold()
    return key in ('только_значения',)

def _merge_final_reorder_entries(entries):
    """
    Порядок финальной фазы: Только_значения → прочие шаги → удаление/скрытие листов.
    Порядок строк на листе параметров для этих групп не важен.
    """
    values_steps = []
    other_steps = []
    layout_steps = []
    i = 0
    while i < len(entries):
        fn = entries[i]
        label = _merge_final_fn_label(fn)
        if _merge_final_is_values_only_name(label):
            values_steps.append(fn)
        elif _merge_pp_is_delete_sheets_postprocess_name(label):
            layout_steps.append(fn)
        else:
            other_steps.append(fn)
        i = i + 1
    return values_steps + other_steps + layout_steps

def _merge_involve_extra_sheet_names(names):
    """Добавить имена листов в _MERGE_INVOLVED_SHEET_NAMES (режим «Текущие листы»)."""
    extra = []
    for nm in names or ():
        s = str(nm or '').strip()
        if s != '':
            extra.append(s)
    if not extra:
        return
    try:
        cur = set(_cw_get('_MERGE_INVOLVED_SHEET_NAMES') or ())
    except Exception:
        cur = set()
    # В режиме не-involve набор обычно пуст — не раздуваем его.
    if not cur:
        try:
            if _cw_get('_MERGE_COLLECT_MODE') != _cw_cfg.MERGE_MODE_INVOLVE:
                return
        except Exception:
            return
    before = set(cur)
    cur.update(extra)
    if cur != before:
        _cw_set('_MERGE_INVOLVED_SHEET_NAMES', frozenset(cur))
        merge_debug(
            '_merge_involve_extra_sheet_names',
            'added=%s involved=%s' % (sorted(set(extra)), sorted(cur)),
        )

def _merge_run_pending_pivot_as_values(doc, report=None):
    """Неявная материализация сводных с as_values (до удаления листов)."""
    _ensure_pp_from_lib()
    pending_fn = globals().get('merge_final_apply_pending_pivot_as_values')
    if pending_fn is None:
        try:
            import libre_macros_final_lib as fl
            pending_fn = fl.lm_final_apply_pending_pivot_as_values
        except ImportError:
            return
    pending_names = []
    list_fn = globals().get('merge_pp_pivot_list_as_values_pending')
    if list_fn is None:
        try:
            import libre_macros_pivot_lib as _pl
            list_fn = _pl.lm_pp_pivot_list_as_values_pending
        except ImportError:
            list_fn = None
    if list_fn is not None:
        try:
            pending_names = [str(x).strip() for x in (list_fn() or ()) if str(x).strip()]
            if len(pending_names) == 0:
                return
        except Exception:
            pending_names = []
    merge_ui_set_phase('Финальная обработка', 'сводные as_values', journal=False)
    merge_ui_yield(force=True)
    _merge_pp_log_fn_begin()
    try:
        pending_fn(doc)
        # После as_values DataPilot уже нет — явно вовлекаем листы сводных
        # в стек следующих финальных шагов (разделить_по_столбцам и т.п.).
        involve_names = list(pending_names)
        try:
            import libre_macros_pivot_lib as _pl
            for entry in _pl.lm_pp_pivot_list_materialized_sheets() or ():
                if isinstance(entry, dict):
                    nm = entry.get('name')
                else:
                    nm = entry
                s = str(nm or '').strip()
                if s != '':
                    involve_names.append(s)
        except Exception:
            pass
        _merge_involve_extra_sheet_names(involve_names)
        _merge_log_final_processing(doc, 'Только_значения (сводные)', 'ok', _merge_format_workbook_sheets_note(doc))
    except Exception as err:
        _merge_log_final_processing(doc, 'Только_значения (сводные)', 'ошибка', str(err))
    finally:
        _merge_pp_log_fn_end()
    _merge_undo_clear(doc, 'final:сводные as_values', defer_ok=False)

def _merge_run_final_processing_entries(doc, report, entries, sheets, data_ranges, header_row_ranges):
    i = 0
    while i < len(entries):
        fn = entries[i]
        label = _merge_final_fn_label(fn)
        if not _merge_step_condition_allows(fn, doc=doc, label=label, scope='финальная_обработка', final=True):
            i = i + 1
            continue
        merge_debug('_merge_run_final_processing_entries', 'step: %s' % label)
        merge_ui_set_phase('Финальная обработка', str(label), journal=False)
        prev_stage = _merge_pp_active_log_stage()
        _merge_pp_set_log_stage('финальная_обработка')
        _merge_pp_log_fn_begin()
        try:
            # Диапазоны заново: предыдущие шаги (применить_формулу и т.п.) меняют used area.
            sheets, data_ranges, header_row_ranges = _merge_final_collect_workbook_collections(doc, header_row=0)
            fn(doc, sheets, data_ranges, header_row_ranges)
            # Если в текущем шаге была создана сводная с as_values=true, материализуем её
            # до следующего шага финальной обработки — тогда следующий шаг увидит результат.
            _merge_run_pending_pivot_as_values(doc, report)
            _merge_log_final_processing(doc, str(label), 'ok', _merge_format_workbook_sheets_note(doc))
        except Exception as err:
            detail = _merge_pp_format_postprocess_error(err)
            _merge_log_final_processing(doc, str(label), 'ошибка', detail)
            print('  ⚠ финальная обработка «%s»: %s' % (label, detail))
        finally:
            _merge_pp_log_fn_end()
            _merge_pp_set_log_stage(prev_stage)
        merge_ui_yield(force=True)
        _merge_undo_clear(doc, 'final:%s' % label, defer_ok=False)
        i = i + 1

def _merge_pp_wrap_callback(fn, extra_args, row_callback, fn_name=None):
    """
    Обёртка колбэка постобработки с дополнительными аргументами из колонки C.

    Назначение:
        Вернуть функцию с сигнатурой merge_result_postprocess_range/row,
        дополнив вызов *extra_args после стандартных четырёх/пяти параметров.

    Параметры:
        fn — исходная merge_pp_*.
        extra_args — список из parse_pp_extra_args.
        row_callback — True для постобработки по строкам, False для диапазона.
        fn_name — имя из колонки B (для журнала «Сбор_книг_лог»).

    Возвращает:
        wrapped callable или fn без изменений, если extra_args пуст.

    Связь:
        parse_postprocess_from_sheet; вызов через _merge_run_postprocess_range/row.
    """
    if fn_name is not None and str(fn_name).strip() != '':
        label = _merge_pp_short_label(fn_name)
    else:
        label = getattr(fn, '__name__', '?')
    if extra_args is None or len(extra_args) == 0:
        fn._merge_pp_label = label
        try:
            fn._merge_pp_fn_key = _merge_pp_normalize_map_key(fn_name or label)
        except Exception:
            pass
        return fn
    if row_callback:

        def wrapped(doc, sheet, data_row_range, header_row_range, row_index):
            return fn(doc, sheet, data_row_range, header_row_range, row_index, *extra_args)
        wrapped._merge_pp_label = label
        wrapped._merge_pp_extra_args = list(extra_args)
        try:
            wrapped._merge_pp_fn_key = _merge_pp_normalize_map_key(fn_name or label)
        except Exception:
            wrapped._merge_pp_fn_key = str(fn_name or label)
        if _merge_pp_is_zebra_postprocess_name(fn_name) and len(extra_args) > 0:
            wrapped._merge_pp_zebra_rest = str(extra_args[0])
            wrapped._lm_pp_zebra_rest = str(extra_args[0])
        if _merge_pp_is_header_plus_height_postprocess_name(fn_name) and len(extra_args) > 0:
            wrapped._lm_pp_header_height_extra = str(extra_args[0])
        return wrapped

    def wrapped(doc, sheet, data_range, header_row_range):
        return fn(doc, sheet, data_range, header_row_range, *extra_args)
    wrapped._merge_pp_label = label
    wrapped._merge_pp_extra_args = list(extra_args)
    try:
        wrapped._merge_pp_fn_key = _merge_pp_normalize_map_key(fn_name or label)
    except Exception:
        wrapped._merge_pp_fn_key = str(fn_name or label)
    if _merge_pp_is_zebra_postprocess_name(fn_name) and len(extra_args) > 0:
        wrapped._merge_pp_zebra_rest = str(extra_args[0])
        wrapped._lm_pp_zebra_rest = str(extra_args[0])
    if _merge_pp_is_header_plus_height_postprocess_name(fn_name) and len(extra_args) > 0:
        wrapped._lm_pp_header_height_extra = str(extra_args[0])
    return wrapped

def _merge_postprocess_fn_label(fn):
    """Имя шага постобработки для журнала (колонка B или __name__)."""
    if fn is None:
        return '?'
    label = getattr(fn, '_merge_pp_label', None)
    if label is not None and str(label).strip() != '':
        return str(label)
    return getattr(fn, '__name__', repr(fn))

def _merge_log_final_processing(doc, fn_label, status, note=''):
    """Строка журнала финальной обработки: B=Финальная_обработка, C=функция/стадия."""
    if doc is None:
        return
    append_collect_log(doc, _cw_cfg.P_MERGE_FINAL_PROCESSING, str(fn_label), '', '', str(status), str(note) if note != '' else '')

def _merge_format_workbook_sheets_note(doc):
    """Краткая сводка листов книги для журнала финальной обработки."""
    names = []
    if doc is None:
        return '0 листов'
    try:
        sheets = doc.Sheets
        i = 0
        while i < sheets.getCount():
            names.append(str(sheets.getByIndex(i).Name))
            i = i + 1
    except Exception:
        pass
    n = len(names)
    if n == 0:
        return '0 листов'
    return '%d лист(ов): %s' % (n, ', '.join(names))

def _merge_log_postprocess(doc, target_sheet, scope, fn_label, status, note=''):
    """Строка журнала о шаге постобработки на листе «Сбор_книг_лог»."""
    if doc is None:
        return
    try:
        note = _merge_pp_format_log_note(note)
    except Exception:
        pass
    if str(scope or '').strip().casefold() == 'финальная_обработка':
        _merge_log_final_processing(doc, fn_label, status, note)
        return
    append_collect_log(doc, 'постобработка', str(target_sheet), str(scope), '', str(status), '%s: %s' % (fn_label, note) if note != '' else str(fn_label))

def merge_pp_user_log(doc, sheet, message, status='инфо', scope='python B'):
    """
    Отладочное сообщение пользовательской постобработки (код из колонки B).

    Доступно в eval/exec колонки B; пишет строку на лист «Сбор_книг_лог».
    """
    sheet_name = sheet.Name if sheet is not None else ''
    _merge_log_postprocess(doc, sheet_name, scope, 'user', status, str(message))

def read_postprocess_param_rows(doc, param_key):
    """
    Чтение всех строк постобработки с листа «Параметры_Объединения».

    Назначение:
        Найти строки, где колонка A совпадает с param_key (без учёта регистра),
        и собрать пары (имя функции, доп. аргументы).

    Параметры:
        doc — книга результата (XSpreadsheetDocument).
        param_key — P_MERGE_POSTPROCESS_RANGE или P_MERGE_POSTPROCESS_ROW.

    Возвращает:
        list[tuple(str, str, str, str)] — (fn_name из B, C, D, E); D/E могут быть пустыми.
        Пустой список, если листа параметров нет.

    Связь:
        get_sheet, cell_text, param_name_match; parse_postprocess_from_sheet.
        Обход не более MERGE_PARAM_SHEET_MAX_ROWS строк (пустые A пропускаются).
    """
    sheet = _get_param_sheet(doc)
    if sheet is None:
        return []
    rows = []
    row = 1
    while row < _cw_cfg.MERGE_PARAM_SHEET_MAX_ROWS:
        name = cell_text(sheet.getCellByPosition(0, row))
        if row == 1 and param_name_match(name, 'Параметр'):
            row = row + 1
            continue
        if name == '':
            row = row + 1
            continue
        if param_sheet_name_is_disabled(name):
            row = row + 1
            continue
        if param_name_match(name, param_key):
            fn_name = cell_text(sheet.getCellByPosition(1, row))
            c_raw = cell_text(sheet.getCellByPosition(2, row))
            d_raw = cell_text(sheet.getCellByPosition(3, row))
            e_raw = cell_text(sheet.getCellByPosition(4, row))
            if fn_name != '':
                rows.append((fn_name, c_raw, d_raw, e_raw))
        row = row + 1
    return rows

def merge_scan_param_plugins(doc):
    """
    Сканировать все листы параметров на функции плагинов (B=функция_плагин).
    Возвращает отсортированный список уникальных ссылок/меток.
    """
    refs = []
    seen = set()
    sheet_names = list_param_sheet_names(doc)
    si = 0
    while si < len(sheet_names):
        sheet = get_sheet(doc, sheet_names[si])
        si = si + 1
        if sheet is None:
            continue
        row = 1
        while row < _cw_cfg.MERGE_PARAM_SHEET_MAX_ROWS:
            name = cell_text(sheet.getCellByPosition(0, row))
            if row == 1 and param_name_match(name, 'Параметр'):
                row = row + 1
                continue
            if name == '':
                row = row + 1
                continue
            if param_sheet_name_is_disabled(name):
                row = row + 1
                continue
            fn_name = cell_text(sheet.getCellByPosition(1, row))
            c_raw = cell_text(sheet.getCellByPosition(2, row))
            d_raw = cell_text(sheet.getCellByPosition(3, row))
            if _merge_pp_is_plugin_fn_key(fn_name):
                for plugin_block, resolve_name, extra_raw in _merge_pp_iter_plugin_row_specs(fn_name, c_raw, d_raw):
                    label = _merge_pp_short_label(resolve_name or fn_name)
                    if label == '':
                        label = _cw_cfg.MERGE_PLUGIN_FUNCTION_KEY
                    key = label.casefold()
                    if key not in seen:
                        seen.add(key)
                        refs.append(label)
            row = row + 1
    refs.sort()
    return refs

def merge_ensure_consent_before_run(doc):
    """
    Условия использования + предупреждение о плагинах перед запуском.
    Возвращает True, если можно продолжать.
    """
    try:
        from libre_macros_consent_lib import lm_consent_ensure_before_run
        plugin_refs = merge_scan_param_plugins(doc)
        return lm_consent_ensure_before_run(doc, macro_version=MACRO_VERSION, plugin_refs=plugin_refs, toolkit=get_awt_toolkit(), parent_window=message_parent_window(doc), on_error=lambda text: show_message(unicode(text), doc))
    except Exception as err:
        merge_debug('merge_ensure_consent_before_run', 'error: %s' % err)
        print(traceback.format_exc())
        show_message(u'Не удалось проверить условия использования:\n%s\nЗапуск отменён.' % err, doc)
        return False

def merge_verify_plugin_allow_gates(doc):
    """
    Проверить гейт допуска для всех блоков «функция_плагин»
    (постобработка диапазон/строка/xml и финальная обработка).

    Возвращает текст ошибки или None.
    """
    try:
        from libre_macros_allow_gate_lib import verify_plugin_allow_gate
    except Exception as err:
        return u'функция_плагин запрещена: модуль допуска недоступен: %s' % err
    vm = getattr(_cw_cfg, '_MERGE_SOURCE_VARIABLES_MAP', None) or {}
    keys = (
        _cw_cfg.P_MERGE_POSTPROCESS_RANGE,
        _cw_cfg.P_MERGE_POSTPROCESS_ROW,
        _cw_cfg.P_MERGE_POSTPROCESS_XML,
        _cw_cfg.P_MERGE_FINAL_PROCESSING,
    )
    ki = 0
    while ki < len(keys):
        param_key = keys[ki]
        ki = ki + 1
        try:
            entries = read_postprocess_param_rows(doc, param_key)
        except Exception:
            entries = []
        ei = 0
        while ei < len(entries):
            fn_name, c_raw, d_raw, e_raw = entries[ei]
            ei = ei + 1
            for plugin_block, _resolve_name, _extra_raw in _merge_pp_iter_plugin_row_specs(
                fn_name, c_raw, d_raw,
            ):
                if plugin_block is None:
                    continue
                gate_err = verify_plugin_allow_gate(plugin_block, variables_map=vm)
                if gate_err:
                    return gate_err
    return None


def parse_postprocess_from_sheet(doc, param_key, function_map, row_callback=False):
    """
    Сборка цепочки колбэков постобработки с листа параметров.

    Назначение:
        Преобразовать строки read_postprocess_param_rows в tuple обёрнутых функций
        для подстановки в settings и далее в _MERGE_RESULT_POSTPROCESS_*.

    Параметры:
        doc — книга результата.
        param_key — имя параметра в колонке A.
        function_map — MERGE_RESULT_POSTPROCESS_RANGE_MAP или _ROW_MAP.
        row_callback — тип обёртки (_merge_pp_wrap_callback).

    Возвращает:
        tuple(callable, …) по порядку строк или None, если строк нет или все имена неизвестны.

    Связь:
        parse_collect_settings → run_collect_merge → _merge_build_postprocess_chain.
    """
    entries = read_postprocess_param_rows(doc, param_key)
    if len(entries) == 0:
        return None
    functions = []
    scope_label = 'диапазон' if not row_callback else 'строка'
    for fn_name, c_raw, d_raw, e_raw in entries:
        for plugin_block, resolve_name, extra_raw in _merge_pp_iter_plugin_row_specs(fn_name, c_raw, d_raw):
            fn = resolve_postprocess_function(resolve_name, function_map)
            if fn is None:
                print('  ⚠ Неизвестная функция постобработки: %s (%s); ключ карты, функция_плагин (JSON в C), файл.py#func, merge_pp_* или Python' % (_merge_pp_short_label(resolve_name or fn_name), scope_label))
                continue
            extra_args = _merge_pp_resolve_extra_args(resolve_name, extra_raw, row_callback=row_callback)
            log_name = resolve_name if not _merge_pp_is_plugin_fn_key(fn_name) else '%s: %s' % (_cw_cfg.MERGE_PLUGIN_FUNCTION_KEY, _merge_pp_short_label(resolve_name))
            wrapped = _merge_pp_wrap_callback(fn, extra_args, row_callback, log_name)
            if plugin_block is not None:
                wrapped._merge_pp_plugin_block = plugin_block
            _merge_attach_step_condition(wrapped, fn_name, d_raw, e_raw)
            functions.append(wrapped)
    if len(functions) == 0:
        return None
    return tuple(functions)

def read_final_processing_rows(doc):
    """Строки «Финальная_обработка» с листа параметров: (fn_name, C, D, E)."""
    return read_postprocess_param_rows(doc, _cw_cfg.P_MERGE_FINAL_PROCESSING)

