def parse_final_processing_from_sheet(doc, function_map):
    """Цепочка финальной обработки с листа параметров."""
    entries = read_final_processing_rows(doc)
    if len(entries) == 0:
        return None
    functions = []
    for fn_name, c_raw, d_raw, e_raw in entries:
        for plugin_block, resolve_name, extra_raw in _merge_pp_iter_plugin_row_specs(fn_name, c_raw, d_raw):
            fn = resolve_final_processing_function(resolve_name, function_map)
            if fn is None:
                print('  ⚠ Неизвестная функция финальной обработки: %s; ключ карты, функция_плагин (JSON в C), файл.py#func, merge_final_* или Python' % _merge_pp_short_label(resolve_name or fn_name))
                continue
            extra_args = _merge_pp_resolve_extra_args(resolve_name, extra_raw, final=True)
            log_name = resolve_name if not _merge_pp_is_plugin_fn_key(fn_name) else '%s: %s' % (_cw_cfg.MERGE_PLUGIN_FUNCTION_KEY, _merge_pp_short_label(resolve_name))
            wrapped = _merge_final_wrap_callback(fn, extra_args, log_name)
            if plugin_block is not None:
                wrapped._merge_pp_plugin_block = plugin_block
                wrapped = _merge_final_wrap_plugin_sheet_filter(wrapped)
            _merge_attach_step_condition(wrapped, fn_name, d_raw, e_raw)
            functions.append(wrapped)
    if len(functions) == 0:
        return None
    return tuple(functions)

def _merge_final_collect_workbook_collections(doc, header_row=0):
    """Коллекции листов книги и диапазонов данных/заголовков для финальной обработки.

    В режиме «Текущие листы» — только имена из _MERGE_INVOLVED_SHEET_NAMES;
    строка заголовков — из «Строка_Заголовков» (пусто → 0 / первая строка).
    """
    sheets = []
    data_ranges = []
    header_row_ranges = []
    if doc is None:
        return (sheets, data_ranges, header_row_ranges)
    try:
        involved = _cw_get('_MERGE_INVOLVED_SHEET_NAMES') or frozenset()
    except Exception:
        involved = frozenset()
    try:
        if _merge_is_involve_mode(doc):
            header_row = _merge_involve_header_row_0(doc)
    except Exception:
        pass
    try:
        doc_sheets = doc.Sheets
        count = int(doc_sheets.getCount())
    except Exception:
        return (sheets, data_ranges, header_row_ranges)

    # Материализованные/ожидающие сводные могут не быть в involve-наборе
    # (лист создан в финале), а после as_values у них уже нет DataPilot.
    pivot_extra_names = set()
    try:
        import libre_macros_pivot_lib as _pl
        for entry in _pl.lm_pp_pivot_list_materialized_sheets() or ():
            if isinstance(entry, dict):
                nm = entry.get('name')
            else:
                nm = entry
            s = str(nm or '').strip()
            if s != '':
                pivot_extra_names.add(s)
        for nm in _pl.lm_pp_pivot_list_as_values_pending() or ():
            s = str(nm or '').strip()
            if s != '':
                pivot_extra_names.add(s)
    except Exception:
        pivot_extra_names = set()

    def _sheet_has_datapilot(sheet_):
        """Лист содержит DataPilot (сводную) — включаем в финал даже в involve-режиме."""
        try:
            dps = sheet_.getDataPilotTables()
            if dps is None:
                return False
            try:
                return int(dps.getCount()) > 0
            except Exception:
                # fallback: если это не коллекция с getCount
                return bool(dps)
        except Exception:
            return False

    i = 0
    while i < count:
        try:
            sh = doc_sheets.getByIndex(i)
            if involved:
                try:
                    nm = str(getattr(sh, 'Name', '') or '').strip()
                except Exception:
                    nm = ''
                if nm not in involved:
                    # Сводная, созданная в финале / материализованная as_values,
                    # должна оставаться в стеке для следующих шагов (split и т.п.).
                    if nm not in pivot_extra_names and not _sheet_has_datapilot(sh):
                        i = i + 1
                        continue
            ctx = _merge_pp_context_new(sh, header_row)
            dr, hr = _merge_pp_context_ranges(ctx)
            sheets.append(sh)
            data_ranges.append(dr)
            header_row_ranges.append(hr)
        except Exception:
            pass
        i = i + 1
    return (sheets, data_ranges, header_row_ranges)

def _is_vlookup_param_name(name):
    """Проверка, является ли имя параметра ВПР (без учета регистра)."""
    if name is None:
        return False
    name_lower = str(name).strip().lower()
    return name_lower in ('впр', 'vlookup')

def _is_merge_sheets_param_name(name):
    """Параметр A = объединить_листы_в_один (без учета регистра)."""
    if name is None:
        return False
    return str(name).strip().casefold() == 'объединить_листы_в_один'

def _is_split_sheets_param_name(name):
    """Параметр A = разделить_листы (без учета регистра)."""
    if name is None:
        return False
    return str(name).strip().casefold() == 'разделить_листы'

def _is_pipeline_splitter_kind(kind):
    """Сегмент-разрезатель фазы диапазона: vlookup | merge_sheets | split_sheets."""
    return kind in ('vlookup', 'merge_sheets', 'split_sheets')

def _pipeline_c_looks_like_json(text):
    s = str(text or '').strip()
    return s.startswith('[') or s.startswith('{')

def read_processing_pipeline_rows(doc):
    """
    Чтение всех строк pipeline с листа «Параметры_Объединения».

    Назначение:
        Собрать строки ВПР / объединить / разделить, Постобработка_Диапазон,
        Постобработка_Строка в порядке их следования на листе.

    Возвращает:
        list[dict] — словари с ключами:
            - 'kind': 'range' | 'row' | 'vlookup' | 'merge_sheets' | 'split_sheets'
            - 'row_num': номер строки на листе (0-based)
            - 'raw': кортеж (A, B, C, ...) значений ячеек строки
    """
    sheet = _get_param_sheet(doc)
    if sheet is None:
        return []
    rows = []
    row = 1
    while row < _cw_cfg.MERGE_PARAM_SHEET_MAX_ROWS:
        name = cell_text(sheet.getCellByPosition(0, row))
        if row == 1 and param_name_match(name, 'Параметр'):
            row = row + 1
            continue
        if name == '':
            row = row + 1
            continue
        kind = None
        if param_name_match(name, _cw_cfg.P_MERGE_POSTPROCESS_RANGE):
            kind = 'range'
        elif param_name_match(name, _cw_cfg.P_MERGE_POSTPROCESS_ROW):
            kind = 'row'
        elif _is_vlookup_param_name(name):
            kind = 'vlookup'
        elif _is_merge_sheets_param_name(name):
            kind = 'merge_sheets'
        elif _is_split_sheets_param_name(name):
            kind = 'split_sheets'
        if kind is not None:
            raw_values = []
            for col in range(1, 6):
                val = cell_text(sheet.getCellByPosition(col, row))
                raw_values.append(val)
            if kind == 'vlookup':
                c_val = str(raw_values[1]).strip() if len(raw_values) > 1 else ''
                if str(raw_values[0]).strip() == '' and (not vlookup_is_json_cell(c_val)):
                    row = row + 1
                    continue
            elif kind in ('merge_sheets', 'split_sheets'):
                c_val = str(raw_values[1]).strip() if len(raw_values) > 1 else ''
                if str(raw_values[0]).strip() == '' and (not _pipeline_c_looks_like_json(c_val)):
                    if kind == 'split_sheets':
                        pass
                    else:
                        row = row + 1
                        continue
            if kind in ('range', 'row') and str(raw_values[0]).strip() == '':
                row = row + 1
                continue
            rows.append({'kind': kind, 'row_num': row, 'raw': tuple(raw_values)})
        row = row + 1
    return rows

def validate_processing_pipeline_order(pipeline_rows):
    """
    Валидация порядка строк pipeline.

    Правила (см. TZ_VLOOKUP2.md §4):
        - Сначала идут 'range' / splitter'ы (фаза 1 — диапазон)
        - Затем только 'row' (фаза 2 — строки)
        - После перехода к 'row' нельзя возвращаться к range/splitter

    Возвращает:
        (None, pipeline_rows) — валидация успешна
        (str, None) — строка с описанием ошибки
    """
    phase = 'RANGE'
    for entry in pipeline_rows:
        kind = entry['kind']
        row_num = entry['row_num'] + 1
        if kind == 'row':
            phase = 'ROW'
        elif kind == 'range' or _is_pipeline_splitter_kind(kind):
            if phase == 'ROW':
                return ("Ошибка в строке %d: '%s' не может идти после 'Постобработка_Строка'. Сначала должны идти все операции диапазона и ВПР, затем строки." % (row_num, kind.upper()), None)
            if kind == 'vlookup':
                raw = entry.get('raw') or ()
                c_raw = str(raw[1]).strip() if len(raw) > 1 else ''
                if vlookup_is_json_cell(c_raw):
                    continue
                left_raw = str(raw[0]).strip() if len(raw) > 0 else ''
                right_raw = str(raw[1]).strip() if len(raw) > 1 else ''
                if left_raw == '' and right_raw == '':
                    return ('Ошибка в строке %d: для ВПР нужны параметры левой и/или правой таблицы (B, C).' % row_num, None)
    return (None, pipeline_rows)

def vlookup_not_found_fill_text(value, default=None):
    """Текст заполнителя «не найдено»; «0» и 0 сохраняются (не через or)."""
    if default is None:
        default = _cw_cfg.VLOOKUP_DEFAULT_NOT_FOUND_FILL
    if value is None:
        return default
    if isinstance(value, bool):
        return default
    if isinstance(value, (int, float)):
        return str(value).strip()
    s = str(value).strip()
    if s == '':
        return default
    return s

def vlookup_not_found_fill_is_empty_cell(fill_text):
    """Заполнитель «не найдено» = пустая ячейка (_ПУСТО_, _EMPTY_, __ПУСТО__)."""
    s = str(fill_text or '').strip()
    if s == '':
        return False
    key = s.casefold().replace(' ', '')
    return key in tuple((a.casefold().replace(' ', '') for a in _cw_cfg.VLOOKUP_NOT_FOUND_EMPTY_ALIASES))

def vlookup_parse_bool_option(raw, default=True):
    """Разбор Да/Нет для полей F (регистр не важен; 0/1, true/false, yes/no, …)."""
    if raw is None:
        return default
    if isinstance(raw, bool):
        return raw
    if isinstance(raw, (int, float)):
        try:
            if float(raw) == 0.0:
                return False
            if float(raw) == 1.0:
                return True
        except Exception:
            pass
    try:
        return _merge_parse_bool_param(raw, default=default)
    except ValueError:
        return default

def vlookup_highlight_color_is_disabled(color_text):
    """Цвет подсветки отключён: пусто или явное «Нет» в F."""
    s = str(color_text or '').strip()
    if s == '':
        return True
    if s.casefold() == _cw_cfg.VLOOKUP_HIGHLIGHT_COLOR_NONE.casefold():
        return True
    try:
        parsed = _merge_parse_bool_param(s, default=None)
    except ValueError:
        return False
    return parsed is False

def _vlookup_cell_label_key(label):
    return str(label or '').strip().casefold().replace(' ', '_')

def strip_vlookup_cell_value(text):
    """
    Убрать подпись «Метка: значение» из ячейки B–F строки ВПР.

    Текст слева от «:» — подсказка для пользователя, при выполнении отбрасывается.
    Повторяющиеся метки (после пересохранения визарда) снимаются циклом.
    """
    s = str(text).strip() if text is not None else ''
    while s != '' and ':' in s:
        label, _sep, rest = s.partition(':')
        rest = rest.strip()
        if _vlookup_cell_label_key(label) in _cw_cfg._VLOOKUP_KNOWN_CELL_LABELS and rest != '':
            s = rest
            continue
        break
    return s

def _split_vlookup_key_tokens(text):
    """Разбор ключей ВПР: «,»/«;» с учётом '…'; без кавычек — как раньше."""
    s = str(text or '').strip()
    if s == '':
        return []
    try:
        from libre_macros_param_codec import split_column_name_tokens, unwrap_column_name_token
        parts = split_column_name_tokens(s)
        out = []
        for p in parts or []:
            bare, _exact = unwrap_column_name_token(p)
            bare = str(bare or '').strip()
            if bare != '':
                out.append(bare)
        if out:
            return out
    except Exception:
        pass
    return [k.strip() for k in s.replace(';', ',').split(',') if k.strip()]

def parse_vlookup_keys_cell(text):
    """
    Колонка D: общий ключ или раздельные для левой/правой таблицы.

    Форматы:
        Ключ_сравнения: Код_позиции
        Ключ_сравнения_левый: A,B # Ключ_сравнения_правый: X,Y

    Возвращает (left_keys, right_keys).
    """
    raw = str(text or '').strip()
    if raw == '':
        return ([], [])
    left_m = re.search('Ключ_сравнения_левый\\s*:\\s*([^#]+)', raw, re.IGNORECASE | re.UNICODE)
    right_m = re.search('Ключ_сравнения_правый\\s*:\\s*(.+?)(?:\\s*#|\\s*$)', raw, re.IGNORECASE | re.UNICODE)
    if left_m is not None and right_m is not None:
        left = _split_vlookup_key_tokens(left_m.group(1))
        right = _split_vlookup_key_tokens(right_m.group(1))
        return (left, right)
    unified = strip_vlookup_cell_value(raw)
    keys = _split_vlookup_key_tokens(unified)
    return (keys, list(keys))

def format_vlookup_labeled_value(label, value):
    """Запись в ячейку параметров: «Метка: значение»."""
    label_s = str(label or '').strip()
    value_s = str(value or '').strip()
    if value_s == '':
        return ''
    if label_s == '':
        return value_s
    return '%s: %s' % (label_s, value_s)

def _join_vlookup_key_tokens(tokens):
    """Склеить ключи/столбцы для UI; имена с «,» — в '…'."""
    try:
        from libre_macros_param_codec import join_column_name_tokens
        return join_column_name_tokens(tokens)
    except Exception:
        parts = []
        for t in tokens or []:
            s = str(t or '').strip()
            if s != '':
                parts.append(s)
        return ','.join(parts)

def format_vlookup_keys_cell(left_keys, right_keys):
    lk = _join_vlookup_key_tokens(left_keys or [])
    rk = _join_vlookup_key_tokens(right_keys or [])
    if lk == '':
        return ''
    if lk == rk or rk == '':
        return format_vlookup_labeled_value(u'Ключ_сравнения', lk)
    return format_vlookup_labeled_value(u'Ключ_сравнения_левый', lk) + u' # ' + format_vlookup_labeled_value(u'Ключ_сравнения_правый', rk)

def parse_vlookup_options_cell(text):
    """
    Колонка F: один или несколько параметров через «,» или «;».

    Поддерживаемые метки (регистр не важен):
        Цвет_добавленных_данных — hex, имя или заливка/шрифт (как у зебры);
            «Нет» — без подсветки
        Заполнять_дубли — Да/Нет (по умолчанию Да): копировать левую строку
            при нескольких совпадениях справа
        Мульти_совпадение_в_одну_ячейку — Да/Нет (по умолчанию Нет): все
            совпадения справа в одну ячейку через перенос строки (без дублирования строк)
        Суффикс_столбцов — Да/Нет (по умолчанию Да): к именам добавляемых
            столбцов дописывается _R1, _R2, … (номер запуска ВПР на листе)
        Заполнитель_для_не_найдено — значение столбцов E при отсутствии ключа
            (по умолчанию #Н/Д; #N/A, =NA(); _ПУСТО_ или _EMPTY_ — пустая ячейка)

    Если меток нет — вся ячейка трактуется как цвет (обратная совместимость).
    Без цвета подсветка не применяется (жёлтый по умолчанию не подставляется).
    """
    result = {'highlight_color': None, 'fill_duplicates': True, 'multi_match_one_cell': False, 'trim_keys': False, 'column_suffix': True, 'not_found_fill': _cw_cfg.VLOOKUP_DEFAULT_NOT_FOUND_FILL}
    raw = str(text or '').strip()
    if raw == '':
        return result
    color_m = re.search('Цвет_добавленных_данных\\s*:\\s*([^;,]+)', raw, re.IGNORECASE | re.UNICODE)
    fill_m = re.search('Заполнять_дубли\\s*:\\s*([^;,]+)', raw, re.IGNORECASE | re.UNICODE)
    multi_m = re.search('Мульти_совпадение_в_одну_ячейку\\s*:\\s*([^;,]+)', raw, re.IGNORECASE | re.UNICODE)
    not_found_m = re.search('Заполнитель_для_не_найдено\\s*:\\s*([^;,]+)', raw, re.IGNORECASE | re.UNICODE)
    trim_m = re.search('(?:Сж_пробелы|СЖ_ПРОБЕЛЫ|trim_keys)\\s*:\\s*([^;,]+)', raw, re.IGNORECASE | re.UNICODE)
    suffix_m = re.search('Суффикс_столбцов\\s*:\\s*([^;,]+)', raw, re.IGNORECASE | re.UNICODE)
    if color_m is not None:
        cval = color_m.group(1).strip()
        if vlookup_highlight_color_is_disabled(cval):
            result['highlight_color'] = None
        else:
            result['highlight_color'] = cval
    if fill_m is not None:
        result['fill_duplicates'] = vlookup_parse_bool_option(fill_m.group(1).strip(), default=True)
    if multi_m is not None:
        result['multi_match_one_cell'] = vlookup_parse_bool_option(multi_m.group(1).strip(), default=False)
    if not_found_m is not None:
        nf = not_found_m.group(1).strip()
        if nf != '':
            result['not_found_fill'] = nf
    if trim_m is not None:
        result['trim_keys'] = vlookup_parse_bool_option(trim_m.group(1).strip(), default=False)
    if suffix_m is not None:
        result['column_suffix'] = vlookup_parse_bool_option(suffix_m.group(1).strip(), default=True)
    if result['highlight_color'] is None:
        if fill_m is None and not_found_m is None and (suffix_m is None) and (not re.search('заполнять_дубли\\s*:', raw, re.IGNORECASE | re.UNICODE)) and (not re.search('мульти_совпадение_в_одну_ячейку\\s*:', raw, re.IGNORECASE | re.UNICODE)) and (not re.search('заполнитель_для_не_найдено\\s*:', raw, re.IGNORECASE | re.UNICODE)):
            legacy = strip_vlookup_cell_value(raw)
            if vlookup_highlight_color_is_disabled(legacy):
                result['highlight_color'] = None
            else:
                result['highlight_color'] = legacy
        elif fill_m is not None:
            before_fill = raw[:fill_m.start()].strip().rstrip(',;').strip()
            if before_fill != '' and (not re.search('заполнять_дубли\\s*:', before_fill, re.IGNORECASE | re.UNICODE)):
                legacy = strip_vlookup_cell_value(before_fill)
                if vlookup_highlight_color_is_disabled(legacy):
                    result['highlight_color'] = None
                else:
                    result['highlight_color'] = legacy
    return result

def format_vlookup_options_cell(highlight_color=None, fill_duplicates=True, not_found_fill=None, multi_match_one_cell=False, trim_keys=False, column_suffix=True):
    """Собрать значение колонки F: цвет, дубли, мульти, сж. пробелы, суффикс, заполнитель."""
    parts = []
    color = str(highlight_color or '').strip()
    if color == '' or vlookup_highlight_color_is_disabled(color):
        color = _cw_cfg.VLOOKUP_HIGHLIGHT_COLOR_NONE
    parts.append(format_vlookup_labeled_value(u'Цвет_добавленных_данных', color))
    try:
        fill_duplicates = bool(fill_duplicates)
    except Exception:
        fill_duplicates = True
    fill_text = u'Да' if fill_duplicates else u'Нет'
    nf = str(not_found_fill if not_found_fill is not None else _cw_cfg.VLOOKUP_DEFAULT_NOT_FOUND_FILL).strip()
    if nf == '':
        nf = _cw_cfg.VLOOKUP_DEFAULT_NOT_FOUND_FILL
    if vlookup_not_found_fill_is_empty_cell(nf):
        nf = _cw_cfg.VLOOKUP_NOT_FOUND_EMPTY
    parts.append(format_vlookup_labeled_value(u'Заполнять_дубли', fill_text))
    try:
        multi_match_one_cell = bool(multi_match_one_cell)
    except Exception:
        multi_match_one_cell = False
    multi_text = u'Да' if multi_match_one_cell else u'Нет'
    parts.append(format_vlookup_labeled_value(u'Мульти_совпадение_в_одну_ячейку', multi_text))
    try:
        trim_keys = bool(trim_keys)
    except Exception:
        trim_keys = False
    trim_text = u'Да' if trim_keys else u'Нет'
    parts.append(format_vlookup_labeled_value(u'Сж_пробелы', trim_text))
    try:
        column_suffix = bool(column_suffix)
    except Exception:
        column_suffix = True
    suffix_text = u'Да' if column_suffix else u'Нет'
    parts.append(format_vlookup_labeled_value(u'Суффикс_столбцов', suffix_text))
    parts.append(format_vlookup_labeled_value(u'Заполнитель_для_не_найдено', nf))
    return '; '.join(parts)

def strip_vlookup_sheet_token(sheet_token):
    """Убрать «Левая_Таблица:» / «Правая_Таблица:» с имени листа (цикл при дублях)."""
    s = str(sheet_token or '').strip()
    table_labels = (u'левая_таблица', u'правая_таблица')
    while s != '' and ':' in s:
        label, _sep, rest = s.partition(':')
        rest = rest.strip()
        if _vlookup_cell_label_key(label) in table_labels and rest != '':
            s = rest
            continue
        break
    return s

def parse_vlookup_table_params(param_text):
    """
    Парсинг объединенных параметров таблицы из формата "Лист|Строка|Столбец|Заголовок".

    Назначение:
        Разобрать значения колонок B или C ВПР-строки, где параметры разделены |.

    Формат:
        Левый_лист | Начало_Строка | Начало_Столбец | Строка_Заголовков
        Правый_лист | Правый_Начало_Строка | Правый_Начало_Столбец | Правый_Строка_Заголовков

    Параметры:
        param_text — строка из ячейки (B или C)

    Возвращает:
        dict с ключами: sheet, start_row, start_col, header_row
        Пустые значения — None
    """
    result = {'sheet': None, 'start_row': None, 'start_col': None, 'header_row': None}
    if param_text is None or str(param_text).strip() == '':
        return result
    param_text = strip_vlookup_cell_value(param_text)
    parts = [p.strip() for p in str(param_text).split('|')]
    if len(parts) >= 1 and parts[0]:
        result['sheet'] = strip_vlookup_sheet_token(parts[0]) or None
    if len(parts) >= 2 and parts[1]:
        try:
            result['start_row'] = int(parts[1])
        except ValueError:
            result['start_row'] = None
    if len(parts) >= 3 and parts[2]:
        try:
            result['start_col'] = int(parts[2])
        except ValueError:
            result['start_col'] = None
    if len(parts) >= 4 and parts[3]:
        try:
            result['header_row'] = int(parts[3])
        except ValueError:
            result['header_row'] = None
    return result

def vlookup_is_json_cell(text):
    """Колонка C содержит JSON-массив ВПР (§5.2 ТЗ)."""
    blocks, err = parse_vlookup_json_cell(text)
    return err is None and blocks is not None and (len(blocks) > 0)

def parse_vlookup_json_cell(text):
    """
    Разбор JSON ВПР из колонки C.

    Возвращает (list[dict], None) или (None, str).
    """
    s = str(text or '').strip()
    if s == '':
        return (None, u'пустой JSON')
    if not (s.startswith('[') or s.startswith('{')):
        return (None, u'не JSON')
    try:
        data = json.loads(s)
    except Exception as exc:
        return (None, u'некорректный JSON: %s' % exc)
    if isinstance(data, dict):
        items = [data]
    elif isinstance(data, list):
        items = data
    else:
        return (None, u'ожидается массив или объект')
    blocks = []
    for item in items:
        if not isinstance(item, dict):
            return (None, u'элемент JSON должен быть объектом')
        fn = str(item.get('fn') or '').strip().casefold()
        if fn not in (u'впр', u'vlookup'):
            return (None, u'поле fn должно быть «впр»')
        blocks.append(item)
    if len(blocks) == 0:
        return (None, u'пустой массив JSON')
    return (blocks, None)

def _vlookup_json_int_or_none(val):
    if val is None:
        return None
    s = str(val).strip()
    if s == '':
        return None
    try:
        return int(s)
    except (ValueError, TypeError):
        return None

def _vlookup_json_key_tokens_store(raw):
    """
    Токены для записи в JSON / UI: одинарные кавычки сохраняются
    (как columns_pick: \"'Фамилия, Имя','Колонка 2'\").
    """
    if raw is None:
        return []
    if isinstance(raw, (list, tuple)):
        out = []
        for k in raw:
            s = str(k).strip()
            if s != '':
                out.append(s)
        return out
    s = str(raw).strip()
    if s == '':
        return []
    try:
        from libre_macros_param_codec import split_column_name_tokens
        parts = split_column_name_tokens(s)
        out = [str(p).strip() for p in (parts or []) if str(p).strip()]
        if out:
            return out
    except Exception:
        pass
    return [k.strip() for k in s.replace(';', ',').split(',') if k.strip()]

def _vlookup_json_key_tokens(raw):
    """Ключи из JSON для исполнения: '…' снимаются, без кавычек — ок."""
    if raw is None:
        return []
    if isinstance(raw, (list, tuple)):
        out = []
        try:
            from libre_macros_param_codec import unwrap_column_name_token
            unwrap = unwrap_column_name_token
        except Exception:
            unwrap = None
        for k in raw:
            s = str(k).strip()
            if s == '':
                continue
            if unwrap is not None:
                bare, _e = unwrap(s)
                s = str(bare or '').strip()
            if s != '':
                out.append(s)
        return out
    s = str(raw).strip()
    if s == '':
        return []
    return _split_vlookup_key_tokens(s)

def _vlookup_json_extract_columns(raw):
    """Extract для исполнения: '…' и «Кол -> Новое» сохраняются (разбор alias позже)."""
    return _vlookup_json_key_tokens_store(raw)

def _vlookup_json_extract_columns_store(raw):
    return _vlookup_json_key_tokens_store(raw)

def _vlookup_normalize_join_type(raw, default='left'):
    s = str(raw or '').strip()
    if s == '':
        return default
    low = s.casefold()
    aliases = {
        'left': 'left',
        'левое': 'left',
        'left_join': 'left',
        'left outer': 'left',
        'left_outer': 'left',
        'inner': 'inner',
        'внутреннее': 'inner',
        'inner_join': 'inner',
        'inner join': 'inner',
        'внутреннее_соединение': 'inner',
        'внутреннее соединение': 'inner',
        'full': 'full',
        'полное': 'full',
        'full_outer': 'full',
        'full outer': 'full',
        'полное_соединение': 'full',
        'полное соединение': 'full',
    }
    return aliases.get(low, default if low not in ('left', 'inner', 'full') else low)

def _vlookup_normalize_multi_match(raw, default='all'):
    s = str(raw or '').strip()
    if s == '':
        return default
    low = s.casefold()
    aliases = {
        'all': 'all',
        'все': 'all',
        '*': 'all',
        'all_rows': 'all',
        'все_совпадения': 'all',
        'first': 'first',
        'первый': 'first',
        'первая': 'first',
        'первое': 'first',
        'first_row': 'first',
        'last': 'last',
        'последний': 'last',
        'последняя': 'last',
        'последнее': 'last',
        'last_row': 'last',
    }
    return aliases.get(low, default)

def _vlookup_normalize_extract_mode(raw, default='new'):
    s = str(raw or '').strip()
    if s == '':
        return default
    low = s.casefold()
    aliases = {
        'new': 'new',
        'новые': 'new',
        'новые колонки': 'new',
        'новые_колонки': 'new',
        'new_columns': 'new',
        'создать': 'new',
        'replace': 'replace',
        'заменить': 'replace',
        'заменить значения': 'replace',
        'замена': 'replace',
        'replace_values': 'replace',
        'overwrite': 'replace',
        'merge': 'merge',
        'объединить': 'merge',
        'объединить значения': 'merge',
        'merge_values': 'merge',
        'append': 'merge',
        'склеить': 'merge',
    }
    return aliases.get(low, default if low not in ('new', 'replace', 'merge') else low)

def _vlookup_normalize_value_delimiter(raw):
    """Экранированный разделитель склейки для JSON; пусто → '' (runtime = \\n)."""
    s = unicode(raw if raw is not None else u'').strip()
    if s == u'':
        return u''
    try:
        from libre_macros_param_wizard_cfg import VALUE_JOIN_DELIMITER_CODE

        code = VALUE_JOIN_DELIMITER_CODE.get(s.casefold())
        if code is not None:
            s = code
    except Exception:
        pass
    try:
        from libre_macros_value_join_lib import normalize_value_join_delimiter_for_store

        return normalize_value_join_delimiter_for_store(s)
    except Exception:
        return s

def _vlookup_derive_fields_from_range_a1(text):
    """A1 → derived 1-based поля стороны (без листа)."""
    import re
    s = str(text or '').strip().replace('$', '').replace(' ', '')
    if s == '':
        return {}
    try:
        from libre_macros_lib import col_letters_to_index
    except Exception:
        return {}
    out = {}
    m = re.match(r'^([A-Za-z]+)(\d+):([A-Za-z]+)(\d+)$', s)
    if m is not None:
        sc = col_letters_to_index(m.group(1))
        sr = int(m.group(2))
        ec = col_letters_to_index(m.group(3))
        er = int(m.group(4))
        if sc < 0 or ec < 0 or sr < 1 or er < 1:
            return {}
        if ec < sc:
            sc, ec = ec, sc
        if er < sr:
            sr, er = er, sr
        out['start_row'] = sr
        out['start_col'] = sc + 1
        out['header_row'] = sr
        out['end_row'] = er
        out['end_col'] = ec + 1
        return out
    m = re.match(r'^([A-Za-z]+)(\d+)$', s)
    if m is not None:
        sc = col_letters_to_index(m.group(1))
        sr = int(m.group(2))
        if sc < 0 or sr < 1:
            return {}
        out['start_row'] = sr
        out['start_col'] = sc + 1
        out['header_row'] = sr
        out['end_row'] = sr
        out['end_col'] = sc + 1
        return out
    m = re.match(r'^([A-Za-z]+):([A-Za-z]+)$', s)
    if m is not None:
        sc = col_letters_to_index(m.group(1))
        ec = col_letters_to_index(m.group(2))
        if sc < 0 or ec < 0:
            return {}
        if ec < sc:
            sc, ec = ec, sc
        out['start_col'] = sc + 1
        out['end_col'] = ec + 1
        return out
    m = re.match(r'^(\d+):(\d+)$', s)
    if m is not None:
        sr = int(m.group(1))
        er = int(m.group(2))
        if sr < 1 or er < 1:
            return {}
        if er < sr:
            sr, er = er, sr
        out['start_row'] = sr
        out['header_row'] = sr
        out['end_row'] = er
        return out
    return {}

def _vlookup_json_table_side(side, label):
    if not isinstance(side, dict):
        return (None, u'%s: ожидается объект' % label)
    sheet = str(side.get('sheet') or '').strip()
    if sheet == '':
        return (None, u'%s: не указан лист' % label)
    range_txt = str(side.get('range') or '').strip()
    start_row = _vlookup_json_int_or_none(side.get('start_row'))
    start_col = _vlookup_json_int_or_none(side.get('start_col'))
    header_row = _vlookup_json_int_or_none(side.get('header_row'))
    end_row = _vlookup_json_int_or_none(side.get('end_row'))
    end_col = _vlookup_json_int_or_none(side.get('end_col'))
    if range_txt != '':
        derived = _vlookup_derive_fields_from_range_a1(range_txt)
        if 'start_row' in derived:
            start_row = derived['start_row']
        if 'start_col' in derived:
            start_col = derived['start_col']
        if 'header_row' in derived:
            header_row = derived['header_row']
        if 'end_row' in derived:
            end_row = derived['end_row']
        if 'end_col' in derived:
            end_col = derived['end_col']
    out = {
        'sheet': sheet,
        'range': range_txt if range_txt != '' else None,
        'start_row': start_row,
        'start_col': start_col,
        'header_row': header_row,
        'end_row': end_row,
        'end_col': end_col,
    }
    return (out, None)

def vlookup_json_block_to_spec(block):
    """JSON-блок §5.2 → spec dict (как у parse_vlookup_spec)."""
    if not isinstance(block, dict):
        return (None, u'блок JSON должен быть объектом')
    left, err = _vlookup_json_table_side(block.get('left'), u'left')
    if err:
        return (None, err)
    right, err = _vlookup_json_table_side(block.get('right'), u'right')
    if err:
        return (None, err)
    if str(left['sheet']).strip() == str(right['sheet']).strip():
        return (None, u'Левый и правый листы не могут быть одинаковыми')
    keys_same = vlookup_parse_bool_option(block.get('keys_same'), default=True)
    left_keys = _vlookup_json_key_tokens(block.get('keys_left'))
    right_keys = _vlookup_json_key_tokens(block.get('keys_right'))
    if keys_same or len(right_keys) == 0:
        right_keys = list(left_keys)
    if len(left_keys) == 0:
        return (None, u'Не указаны ключи левой таблицы')
    if len(right_keys) == 0:
        return (None, u'Не указаны ключи правой таблицы')
    cols = _vlookup_json_extract_columns(block.get('extract_columns') or block.get('extract_cols'))
    if len(cols) == 0:
        return (None, u'Не указаны столбцы для извлечения')
    join_type = _vlookup_normalize_join_type(block.get('join_type'), default='left')
    cols_right = _vlookup_json_extract_columns(
        block.get('extract_columns_right') or block.get('extract_cols_right')
    )
    if join_type == 'full' and len(cols_right) == 0:
        return (None, u'Для полного соединения укажите колонки в Прав. из Лев.')
    color = block.get('highlight_color')
    if color is not None and str(color).strip() == '':
        color = None
    elif color is not None and vlookup_highlight_color_is_disabled(color):
        color = None
    not_found_fill = block.get('not_found_fill')
    if not_found_fill is None:
        not_found_fill = _cw_cfg.VLOOKUP_DEFAULT_NOT_FOUND_FILL
    else:
        not_found_fill = str(not_found_fill)
        if not_found_fill.strip() == '':
            not_found_fill = _cw_cfg.VLOOKUP_DEFAULT_NOT_FOUND_FILL
        elif vlookup_not_found_fill_is_empty_cell(not_found_fill):
            not_found_fill = _cw_cfg.VLOOKUP_NOT_FOUND_EMPTY
    spec = {
        'left_sheet': left['sheet'],
        'left_range': left.get('range'),
        'left_start_row': left['start_row'],
        'left_start_col': left['start_col'],
        'left_header_row': left['header_row'],
        'left_end_row': left.get('end_row'),
        'left_end_col': left.get('end_col'),
        'right_sheet': right['sheet'],
        'right_range': right.get('range'),
        'right_start_row': right['start_row'],
        'right_start_col': right['start_col'],
        'right_header_row': right['header_row'],
        'right_end_row': right.get('end_row'),
        'right_end_col': right.get('end_col'),
        'join_keys': left_keys,
        'join_keys_left': left_keys,
        'join_keys_right': right_keys,
        'extract_cols': cols,
        'extract_cols_right': cols_right,
        'join_type': join_type,
        'highlight_color': color,
        'fill_duplicates': vlookup_parse_bool_option(block.get('fill_duplicates'), default=True),
        'multi_match_one_cell': vlookup_parse_bool_option(block.get('multi_match_one_cell'), default=False),
        'multi_match': _vlookup_normalize_multi_match(block.get('multi_match'), default='all'),
        'value_delimiter': _vlookup_normalize_value_delimiter(
            block.get('value_delimiter') or block.get('join_delimiter')
        ),
        'not_found_fill': not_found_fill,
        'trim_keys': vlookup_parse_bool_option(block.get('trim_keys'), default=False),
        'column_suffix': vlookup_parse_bool_option(block.get('column_suffix'), default=True),
        'match_count': vlookup_parse_bool_option(block.get('match_count'), default=False),
        'extract_mode': _vlookup_normalize_extract_mode(block.get('extract_mode'), default='new'),
    }
    return (spec, None)

def vlookup_fields_to_json_block(fields):
    """Поля диалога ВПР → один JSON-блок §5.2."""
    keys_same = bool(fields.get('keys_same', True))
    # В JSON — как в визарде: '…' сохраняются (имена с запятыми / exact).
    keys_left = _vlookup_json_key_tokens_store(fields.get('keys_left') or fields.get('keys_d'))
    keys_right = _vlookup_json_key_tokens_store(fields.get('keys_right'))
    if keys_same or len(keys_right) == 0:
        keys_right = list(keys_left)
    extract_cols = _vlookup_json_extract_columns_store(fields.get('extract_e'))
    join_type = _vlookup_normalize_join_type(fields.get('join_type'), default='left')

    def _side(prefix):
        side = {
            'sheet': str(fields.get(prefix + '_sheet') or '').strip(),
            'start_row': _vlookup_json_int_or_none(fields.get(prefix + '_start_row')),
            'start_col': _vlookup_json_int_or_none(fields.get(prefix + '_start_col')),
            'header_row': _vlookup_json_int_or_none(fields.get(prefix + '_header_row')),
        }
        range_txt = str(fields.get(prefix + '_range') or '').strip()
        if range_txt != '':
            side['range'] = range_txt
            derived = _vlookup_derive_fields_from_range_a1(range_txt)
            for key in ('start_row', 'start_col', 'header_row', 'end_row', 'end_col'):
                if key in derived and derived[key] is not None:
                    side[key] = derived[key]
        return side
    color = fields.get('highlight_color')
    if color is None:
        color = fields.get('vlookup_color')
    if color is not None:
        color = str(color).strip()
        if color == '' or color == _cw_cfg.VLOOKUP_HIGHLIGHT_COLOR_NONE:
            color = None
    not_found_fill = fields.get('not_found_fill')
    if not_found_fill is None:
        not_found_fill = _cw_cfg.VLOOKUP_DEFAULT_NOT_FOUND_FILL
    else:
        not_found_fill = str(not_found_fill)
        if not_found_fill.strip() == '':
            not_found_fill = ''
    block = {
        'v': 1,
        'fn': u'впр',
        'left': _side('left'),
        'right': _side('right'),
        'keys_same': keys_same,
        'keys_left': list(keys_left),
        'keys_right': list(keys_right),
        'extract_columns': extract_cols,
        'join_type': join_type,
        'highlight_color': color,
        'fill_duplicates': vlookup_parse_bool_option(fields.get('fill_duplicates'), default=True),
        'not_found_fill': not_found_fill,
        'multi_match_one_cell': vlookup_parse_bool_option(fields.get('multi_match_one_cell'), default=False),
        'multi_match': _vlookup_normalize_multi_match(fields.get('multi_match'), default='all'),
        'trim_keys': vlookup_parse_bool_option(fields.get('trim_keys'), default=False),
    }
    vd = _vlookup_normalize_value_delimiter(
        fields.get('value_delimiter') or fields.get('join_delimiter')
    )
    if vd:
        block['value_delimiter'] = vd
    if join_type == 'full':
        block['extract_columns_right'] = _vlookup_json_extract_columns_store(
            fields.get('extract_e_right') or fields.get('extract_columns_right')
        )
    if not vlookup_parse_bool_option(fields.get('column_suffix'), default=True):
        block['column_suffix'] = False
    extract_mode = _vlookup_normalize_extract_mode(fields.get('extract_mode'), default='new')
    if extract_mode != 'new':
        block['extract_mode'] = extract_mode
    if vlookup_parse_bool_option(fields.get('match_count'), default=False):
        block['match_count'] = True
    return block

def encode_vlookup_json(block_or_blocks):
    """Компактный JSON-массив для колонки C."""
    if isinstance(block_or_blocks, dict):
        blocks = [block_or_blocks]
    else:
        blocks = list(block_or_blocks or [])
    return json.dumps(blocks, ensure_ascii=False, separators=(',', ':'))

def vlookup_json_block_to_dialog_fields(block):
    """JSON-блок → начальные значения диалога ВПР."""
    spec, err = vlookup_json_block_to_spec(block)
    if err:
        return {}
    keys_same = vlookup_parse_bool_option(block.get('keys_same'), default=True)
    # UI: кавычки из JSON как есть (не снимать при открытии визарда).
    keys_left = _vlookup_json_key_tokens_store(block.get('keys_left'))
    keys_right = _vlookup_json_key_tokens_store(block.get('keys_right'))
    if keys_same or len(keys_right) == 0:
        keys_right = list(keys_left)
    extract_cols = _vlookup_json_extract_columns_store(
        block.get('extract_columns') or block.get('extract_cols')
    )
    extract_right = _vlookup_json_extract_columns_store(
        block.get('extract_columns_right') or block.get('extract_cols_right')
    )
    nf_raw = block.get('not_found_fill')
    if nf_raw is None:
        nf = _cw_cfg.VLOOKUP_DEFAULT_NOT_FOUND_FILL
    else:
        nf = str(nf_raw)
        if nf.strip() == u'':
            nf = _cw_cfg.VLOOKUP_DEFAULT_NOT_FOUND_FILL
        elif vlookup_not_found_fill_is_empty_cell(nf):
            nf = '_ПУСТО_'
    hc = spec.get('highlight_color')
    if hc is None and block.get('highlight_color') not in (None, u''):
        hc = block.get('highlight_color')
    left_side = block.get('left') or {}
    right_side = block.get('right') or {}
    return {
        'save_as_json': True,
        'left_sheet': spec.get('left_sheet') or u'',
        'left_range': str(left_side.get('range') or spec.get('left_range') or u'').strip(),
        'left_start_row': u'' if spec.get('left_start_row') is None else str(spec['left_start_row']),
        'left_start_col': u'' if spec.get('left_start_col') is None else str(spec['left_start_col']),
        'left_header_row': u'' if spec.get('left_header_row') is None else str(spec['left_header_row']),
        'right_sheet': spec.get('right_sheet') or u'',
        'right_range': str(right_side.get('range') or spec.get('right_range') or u'').strip(),
        'right_start_row': u'' if spec.get('right_start_row') is None else str(spec['right_start_row']),
        'right_start_col': u'' if spec.get('right_start_col') is None else str(spec['right_start_col']),
        'right_header_row': u'' if spec.get('right_header_row') is None else str(spec['right_header_row']),
        'keys_same': keys_same,
        'keys_left': _join_vlookup_key_tokens(keys_left),
        'keys_right': _join_vlookup_key_tokens(keys_right),
        'extract_e': _join_vlookup_key_tokens(extract_cols),
        'extract_e_right': _join_vlookup_key_tokens(extract_right),
        'join_type': spec.get('join_type') or 'left',
        'vlookup_color': hc or u'',
        'fill_duplicates': spec.get('fill_duplicates', True),
        'multi_match_one_cell': spec.get('multi_match_one_cell', False),
        'multi_match': spec.get('multi_match') or 'all',
        'value_delimiter': spec.get('value_delimiter') or u'',
        'not_found_fill': nf,
        'trim_keys': spec.get('trim_keys', False),
        'column_suffix': spec.get('column_suffix', True),
        'match_count': spec.get('match_count', False),
        'extract_mode': spec.get('extract_mode') or 'new',
        'json_c': encode_vlookup_json(block),
    }

def parse_vlookup_spec(raw_values, doc=None):
    """
    Парсинг спецификации ВПР из raw-значений строки.

    Параметры:
        raw_values — кортеж (B, C, D, E, F) значений из read_processing_pipeline_rows
        doc — опционально, документ для проверки существования листов

    Возвращает:
        (spec_dict, None) — успех, spec_dict содержит все поля ВПР
        (None, str) — ошибка парсинга

    Структура raw_values:
        B — Параметры_левой_таблицы (Лист|Строка|Столбец|Заголовок)
        C — Параметры_правой_таблицы (Лист|Строка|Столбец|Заголовок)
        D — Ключи_соединения (столбцы через , или ;)
        E — Столбцы_для_извлечения (столбцы через , или ;)
        F — Цвет_подсветки (hex или имя, опционально)
    """
    if len(raw_values) >= 2 and vlookup_is_json_cell(raw_values[1]):
        blocks, err = parse_vlookup_json_cell(raw_values[1])
        if err:
            return (None, err)
        if len(blocks) != 1:
            return (None, u'JSON ВПР: ожидается один элемент массива')
        return vlookup_json_block_to_spec(blocks[0])
    if len(raw_values) < 4:
        return (None, 'Недостаточно значений (требуется минимум B, C, D)')
    left_raw, right_raw, keys_raw, cols_raw, color_raw = (raw_values[0], raw_values[1], raw_values[2], raw_values[3], raw_values[4] if len(raw_values) > 4 else '')
    left = parse_vlookup_table_params(left_raw)
    if left['sheet'] is None:
        return (None, 'Не указан левый лист (колонка B)')
    right = parse_vlookup_table_params(right_raw)
    if right['sheet'] is None:
        return (None, 'Не указан правый лист (колонка C)')
    if str(left['sheet']).strip() == str(right['sheet']).strip():
        return (None, 'Левый и правый листы не могут быть одинаковыми')
    left_keys, right_keys = parse_vlookup_keys_cell(keys_raw)
    if len(left_keys) == 0:
        return (None, 'Не указаны ключи соединения (колонка D)')
    if len(right_keys) == 0:
        return (None, 'Не указаны ключи правой таблицы (колонка D)')
    cols_raw = strip_vlookup_cell_value(cols_raw)
    if not cols_raw or str(cols_raw).strip() == '':
        return (None, 'Не указаны столбцы для извлечения (колонка E)')
    cols = _vlookup_json_extract_columns_store(cols_raw)
    if len(cols) == 0:
        return (None, 'Не указаны столбцы для извлечения (колонка E)')
    color_raw = raw_values[4] if len(raw_values) > 4 else ''
    options = parse_vlookup_options_cell(color_raw)
    color = options['highlight_color']
    if color is not None and str(color).strip() == '':
        color = None
    fill_duplicates = options['fill_duplicates']
    not_found_fill = vlookup_not_found_fill_text(options.get('not_found_fill'))
    if vlookup_not_found_fill_is_empty_cell(not_found_fill):
        not_found_fill = _cw_cfg.VLOOKUP_NOT_FOUND_EMPTY
    spec = {'left_sheet': left['sheet'], 'left_start_row': left['start_row'], 'left_start_col': left['start_col'], 'left_header_row': left['header_row'], 'right_sheet': right['sheet'], 'right_start_row': right['start_row'], 'right_start_col': right['start_col'], 'right_header_row': right['header_row'], 'join_keys': left_keys, 'join_keys_left': left_keys, 'join_keys_right': right_keys, 'extract_cols': cols, 'highlight_color': color, 'fill_duplicates': fill_duplicates, 'multi_match_one_cell': options.get('multi_match_one_cell', False), 'multi_match': _vlookup_normalize_multi_match(options.get('multi_match'), default='all'), 'not_found_fill': not_found_fill, 'trim_keys': options.get('trim_keys', False), 'column_suffix': options.get('column_suffix', True), 'match_count': False, 'extract_mode': 'new'}
    return (spec, None)

def parse_merge_sheets_spec(raw_values, doc=None):
    """
    Спецификация «объединить_листы_в_один» из строки параметра.

    Prefer JSON в C (raw[1]); иначе legacy: B=sheets, C=dest_sheet,
    D=header_row, E=with_formatting.
    """
    _unused = doc
    raw = list(raw_values or ())
    c_raw = str(raw[1]).strip() if len(raw) > 1 else ''
    if _pipeline_c_looks_like_json(c_raw):
        blocks = None
        err = None
        try:
            from libre_macros_param_codec import param_decode
            blocks = param_decode('объединить_листы_в_один', [c_raw]) or []
        except Exception:
            try:
                import libre_macros_lib as _lm
                blocks = _lm._lm_pp_param_decode('объединить_листы_в_один', [c_raw]) or []
            except Exception as exc:
                err = str(exc)
        if err:
            return (None, err)
        if not blocks:
            return (None, 'пустой JSON объединить_листы_в_один')
        block = blocks[0] if isinstance(blocks[0], dict) else {}
        sheets = block.get('sheets') or block.get('source_sheets') or block.get('sheet_list') or []
        if isinstance(sheets, str):
            sheets = [x.strip() for x in sheets.replace(';', ',').split(',') if x.strip()]
        elif not isinstance(sheets, (list, tuple)):
            sheets = []
        else:
            sheets = [str(x).strip() for x in sheets if str(x or '').strip()]
        dest = str(block.get('dest_sheet') or block.get('result_sheet') or block.get('target_sheet') or block.get('dest') or '').strip()
        if dest == '':
            return (None, 'нужен dest_sheet')
        if len(sheets) == 0:
            return (None, 'нужен sheets')
        with_formatting = False
        try:
            with_formatting = bool(_merge_parse_bool_param(block.get('with_formatting'), default=False))
        except Exception:
            with_formatting = bool(block.get('with_formatting'))
        auto_format = True
        try:
            auto_format = bool(_merge_parse_bool_param(block.get('auto_format'), default=True))
        except Exception:
            if 'auto_format' in block:
                auto_format = bool(block.get('auto_format'))
        columns = list(block.get('columns') or [])
        return ({'sheets': list(sheets), 'dest_sheet': dest, 'header_row': block.get('header_row'), 'with_formatting': with_formatting, 'auto_format': auto_format, 'columns': columns}, None)
    b_raw = str(raw[0]).strip() if len(raw) > 0 else ''
    dest = str(raw[1]).strip() if len(raw) > 1 else ''
    hdr_raw = str(raw[2]).strip() if len(raw) > 2 else ''
    fmt_raw = str(raw[3]).strip() if len(raw) > 3 else ''
    if b_raw == '' or dest == '':
        return (None, 'нужны sheets (B) и dest_sheet (C)')
    sheets = [x.strip() for x in b_raw.replace(';', ',').split(',') if x.strip()]
    if len(sheets) == 0:
        return (None, 'нужен sheets')
    header_row = None
    if hdr_raw != '':
        header_row = hdr_raw
    with_formatting = False
    if fmt_raw != '':
        try:
            with_formatting = bool(_merge_parse_bool_param(fmt_raw, default=False))
        except Exception:
            with_formatting = False
    return ({'sheets': sheets, 'dest_sheet': dest, 'header_row': header_row, 'with_formatting': with_formatting}, None)

def parse_split_sheets_spec(raw_values, doc=None):
    """
    Спецификация «разделить_листы» из строки параметра (JSON в C).
    """
    _unused = doc
    raw = list(raw_values or ())
    c_raw = str(raw[1]).strip() if len(raw) > 1 else ''
    if not _pipeline_c_looks_like_json(c_raw):
        return (None, 'нужен JSON в колонке C')
    blocks = None
    err = None
    try:
        from libre_macros_param_codec import param_decode
        blocks = param_decode('разделить_листы', [c_raw]) or []
    except Exception:
        try:
            import libre_macros_lib as _lm
            blocks = _lm._lm_pp_param_decode('разделить_листы', [c_raw]) or []
        except Exception as exc:
            err = str(exc)
    if err:
        return (None, err)
    if not blocks:
        return (None, 'пустой JSON разделить_листы')
    if len(blocks) > 1:
        return (None, 'разделить_листы: один блок JSON на строку')
    block = blocks[0] if isinstance(blocks[0], dict) else {}
    src = block.get('source') or {}
    sheet_name = str(src.get('sheet') or block.get('source_sheet') or block.get('sheet') or '').strip()
    if sheet_name == '':
        return (None, 'нужен source.sheet')
    phase = str(block.get('run_phase') or 'after_postprocess').strip().casefold()
    if phase not in ('after_collect', 'after_postprocess', 'after_final'):
        phase = 'after_postprocess'
    spec = {'v': 1, 'fn': 'разделить_листы', 'run_phase': phase, 'source': {'book': 'эта_книга', 'sheet': sheet_name}, 'split_books': list(block.get('split_books') or []), 'split_sheets': list(block.get('split_sheets') or []), 'header_row': block.get('header_row'), 'pre_sort': block.get('pre_sort', True), 'book_template': str(block.get('book_template') or 'эта_книга').strip(), 'sheet_template': str(block.get('sheet_template') or '[Split]').strip(), 'split_mode': str(block.get('split_mode') or 'copy_range').strip(), 'paste_formats': block.get('paste_formats', False), 'copy_header': block.get('copy_header', True), 'create_folders': block.get('create_folders', True), 'overwrite_sheets': block.get('overwrite_sheets', True), 'append_if_exists': block.get('append_if_exists', False), 'save_immediately': block.get('save_immediately', False)}
    return (spec, None)

def collect_split_sheets_deferred_steps(doc):
    """Строки разделить_листы с run_phase after_collect / after_final (не в pipeline)."""
    out = []
    for entry in read_processing_pipeline_rows(doc):
        if entry.get('kind') != 'split_sheets':
            continue
        spec, err = parse_split_sheets_spec(entry.get('raw'), doc)
        if err or spec is None:
            continue
        phase = str(spec.get('run_phase') or 'after_postprocess').strip().casefold()
        if phase in ('after_collect', 'after_final'):
            out.append({'kind': 'split_sheets', 'spec': spec, 'row_num': entry.get('row_num'), 'run_phase': phase, 'name': _cw_cfg.P_SPLIT_SHEETS})
    return out

def _validate_split_sheets_xml_run_phase(doc, data_transfer_mode):
    """
    При xml_excel_ods «разделить_листы» только с run_phase=after_final.
    Иначе — текст ошибки (fatal до сбора).
    """
    if data_transfer_mode != _cw_cfg.MERGE_TRANSFER_XML_EXCEL_ODS:
        return None
    bad = []
    for entry in read_processing_pipeline_rows(doc):
        if entry.get('kind') != 'split_sheets':
            continue
        spec, err = parse_split_sheets_spec(entry.get('raw'), doc)
        if err or spec is None:
            continue
        phase = str(spec.get('run_phase') or 'after_postprocess').strip().casefold()
        if phase == 'after_final':
            continue
        row_num = entry.get('row_num')
        try:
            row_label = 'стр. %d' % (int(row_num) + 1)
        except (TypeError, ValueError):
            row_label = 'стр. ?'
        bad.append('%s (run_phase=%s)' % (row_label, phase or 'after_postprocess'))
    if not bad:
        return None
    return (
        'При «Способ_переноса» = xml_excel_ods параметр «разделить_листы» '
        'поддерживается только с точкой запуска after_final '
        '(после финальной обработки).\n'
        'Исправьте: %s' % '; '.join(bad)
    )

def _merge_pp_pipeline_plugin_specs(b_raw, c_raw, d_raw, raw=None):
    """Спецификации плагина для pipeline (с fallback сдвига C→D)."""
    specs = list(_merge_pp_iter_plugin_row_specs(b_raw, c_raw, d_raw))
    if _merge_pp_is_plugin_fn_key(b_raw) and len(specs) == 1 and (specs[0][0] is None) and (str(specs[0][1] or '').strip() == '') and (str(d_raw or '').strip() != ''):
        shifted_ref = str(d_raw or '').strip()
        shifted_rest = ''
        if raw is not None and len(raw) > 3:
            shifted_rest = str(raw[3] or '').strip()
        if _merge_pp_looks_like_file_function_ref(shifted_ref) or _merge_pp_looks_like_python_code(shifted_ref):
            return [(None, shifted_ref, shifted_rest)]
    return specs

def build_processing_pipeline(doc, function_map_range, function_map_row):
    """
    Сборка pipeline обработки из строк листа параметров.

    Назначение:
        Объединить Постобработка_Диапазон, ВПР, Постобработка_Строка в единый pipeline.

    Возвращает:
        (None, str) — ошибка
        (pipeline, None) — успех, pipeline — список dict с kind, spec и т.д.
    """
    _ensure_pp_from_lib()
    rows = read_processing_pipeline_rows(doc)
    if len(rows) == 0:
        return ([], None)
    err, _ = validate_processing_pipeline_order(rows)
    if err:
        return (None, err)
    pipeline = []
    for entry in rows:
        kind = entry['kind']
        raw = entry['raw']
        row_num = entry['row_num']
        if kind == 'range':
            b_raw = raw[0] if len(raw) > 0 else ''
            c_raw = raw[1] if len(raw) > 1 else ''
            d_raw = raw[2] if len(raw) > 2 else ''
            for plugin_block, resolve_name, extra_raw in _merge_pp_pipeline_plugin_specs(b_raw, c_raw, d_raw, raw):
                fn = resolve_postprocess_function(resolve_name, function_map_range)
                if fn is None:
                    if _merge_pp_looks_like_python_code(resolve_name or ''):
                        return (None, 'Ошибка в Python-коде постобработки/диапазон в строке %d: %s\nОжидается ключ (например, «тонкая_сетка») или ссылка «functions_*.py#fn».\nЕсли вы вставляете код, проверьте синтаксис/отступы.' % (row_num + 1, _merge_pp_short_label(resolve_name or '')))
                    return (None, "Неизвестная функция диапазона '%s' в строке %d" % (resolve_name or b_raw, row_num + 1))
                extra_args = _merge_pp_resolve_extra_args(resolve_name, extra_raw, row_callback=False)
                log_name = resolve_name if not _merge_pp_is_plugin_fn_key(b_raw) else '%s: %s' % (_cw_cfg.MERGE_PLUGIN_FUNCTION_KEY, _merge_pp_short_label(resolve_name))
                filter_extra = _merge_pp_pipeline_filter_extra(extra_raw, extra_args)
                wrapped = _merge_pp_wrap_callback(fn, extra_args, False, log_name)
                if plugin_block is not None:
                    wrapped._merge_pp_plugin_block = plugin_block
                e_raw = raw[3] if len(raw) > 3 else ''
                _merge_attach_step_condition(wrapped, b_raw, d_raw, e_raw)
                pipeline.append({'kind': 'range', 'name': log_name, 'fn': wrapped, 'row_num': row_num, 'pivot_extra': filter_extra if _merge_pp_is_pivot_table_postprocess_name(resolve_name) else None, 'sort_extra': filter_extra if _merge_pp_is_sort_postprocess_name(resolve_name) else None, 'colorize_extra': filter_extra if _merge_pp_is_colorize_postprocess_name(resolve_name) else None, 'header_height_extra': filter_extra if _merge_pp_is_header_plus_height_postprocess_name(resolve_name) else None, 'grid_extra': filter_extra if _merge_pp_is_any_grid_postprocess_name(resolve_name) else None, 'formula_extra': filter_extra if _merge_pp_is_apply_formula_postprocess_name(resolve_name) else None, 'color_scale_extra': filter_extra if _merge_pp_is_color_scale_postprocess_name(resolve_name) else None, 'format_extra': filter_extra if _merge_pp_is_format_postprocess_name(resolve_name) else None})
        elif kind == 'row':
            b_raw = raw[0] if len(raw) > 0 else ''
            c_raw = raw[1] if len(raw) > 1 else ''
            d_raw = raw[2] if len(raw) > 2 else ''
            for plugin_block, resolve_name, extra_raw in _merge_pp_pipeline_plugin_specs(b_raw, c_raw, d_raw, raw):
                fn = resolve_postprocess_function(resolve_name, function_map_row)
                if fn is None:
                    if _merge_pp_looks_like_python_code(resolve_name or ''):
                        return (None, 'Ошибка в Python-коде постобработки/строка в строке %d: %s\nОжидается ключ или ссылка «functions_*.py#fn». Если вы вставляете код — проверьте синтаксис/отступы.' % (row_num + 1, _merge_pp_short_label(resolve_name or '')))
                    return (None, "Неизвестная функция строки '%s' в строке %d" % (resolve_name or b_raw, row_num + 1))
                extra_args = _merge_pp_resolve_extra_args(resolve_name, extra_raw, row_callback=True)
                log_name = resolve_name if not _merge_pp_is_plugin_fn_key(b_raw) else '%s: %s' % (_cw_cfg.MERGE_PLUGIN_FUNCTION_KEY, _merge_pp_short_label(resolve_name))
                wrapped = _merge_pp_wrap_callback(fn, extra_args, True, log_name)
                if plugin_block is not None:
                    wrapped._merge_pp_plugin_block = plugin_block
                e_raw = raw[3] if len(raw) > 3 else ''
                _merge_attach_step_condition(wrapped, b_raw, d_raw, e_raw)
                pipeline.append({'kind': 'row', 'name': log_name, 'fn': wrapped, 'row_num': row_num})
        elif kind == 'vlookup':
            spec, err = parse_vlookup_spec(raw, doc)
            if err:
                return (None, 'Ошибка ВПР в строке %d: %s' % (row_num + 1, err))
            pipeline.append({'kind': 'vlookup', 'spec': spec, 'row_num': row_num})
        elif kind == 'merge_sheets':
            spec, err = parse_merge_sheets_spec(raw, doc)
            if err:
                return (None, 'Ошибка объединить_листы_в_один в строке %d: %s' % (row_num + 1, err))
            pipeline.append({'kind': 'merge_sheets', 'spec': spec, 'row_num': row_num, 'name': _cw_cfg.P_MERGE_SHEETS_INTO_ONE})
        elif kind == 'split_sheets':
            spec, err = parse_split_sheets_spec(raw, doc)
            if err:
                return (None, 'Ошибка разделить_листы в строке %d: %s' % (row_num + 1, err))
            phase = str((spec or {}).get('run_phase') or 'after_postprocess').strip().casefold()
            if phase == 'after_postprocess':
                pipeline.append({'kind': 'split_sheets', 'spec': spec, 'row_num': row_num, 'name': _cw_cfg.P_SPLIT_SHEETS})
    return (pipeline, None)

def build_xml_postprocess_pipeline(doc, function_map=None):
    """
    Цепочка postprocess_xml + ВПР с листа параметров (только для xml_excel_ods).

    Возвращает список шагов direct-пайплайна в порядке строк листа параметров:
      - kind='range'  -> шаг Постобработка_xml
      - kind='vlookup' -> ВПР_XML
    """
    _ensure_pp_from_lib()
    if function_map is None:
        function_map = _cw_cfg.MERGE_RESULT_POSTPROCESS_XML_MAP
    sheet = _get_param_sheet(doc)
    if sheet is None:
        return []
    pipeline = []
    row = 1
    while row < _cw_cfg.MERGE_PARAM_SHEET_MAX_ROWS:
        pname = cell_text(sheet.getCellByPosition(0, row))
        if row == 1 and param_name_match(pname, 'Параметр'):
            row = row + 1
            continue
        if pname == '':
            row = row + 1
            continue
        if param_name_match(pname, _cw_cfg.P_MERGE_POSTPROCESS_XML):
            b_raw = cell_text(sheet.getCellByPosition(1, row))
            c_raw = cell_text(sheet.getCellByPosition(2, row))
            d_raw = cell_text(sheet.getCellByPosition(3, row))
            e_raw = cell_text(sheet.getCellByPosition(4, row))
            if str(b_raw).strip() == '':
                row = row + 1
                continue
            raw = (b_raw, c_raw, d_raw, e_raw)
            for plugin_block, resolve_name, extra_raw in _merge_pp_pipeline_plugin_specs(b_raw, c_raw, d_raw, raw):
                fn = resolve_postprocess_function(resolve_name, function_map)
                if fn is None:
                    print('  ⚠ Постобработка_xml: неизвестная функция: %s' % _merge_pp_short_label(resolve_name or b_raw))
                    continue
                extra_args = _merge_pp_resolve_extra_args(resolve_name, extra_raw, row_callback=False)
                log_name = resolve_name if not _merge_pp_is_plugin_fn_key(b_raw) else '%s: %s' % (_cw_cfg.MERGE_PLUGIN_FUNCTION_KEY, _merge_pp_short_label(resolve_name))
                filter_extra = _merge_pp_pipeline_filter_extra(extra_raw, extra_args)
                step = {'kind': 'range', 'name': log_name, 'fn': None, 'row_num': row, 'extra': filter_extra}
                _merge_attach_step_condition(step, b_raw, d_raw, e_raw)
                if _merge_pp_is_pivot_table_postprocess_name(resolve_name):
                    step['pivot_extra'] = filter_extra
                if _merge_pp_is_sort_postprocess_name(resolve_name):
                    step['sort_extra'] = filter_extra
                if _merge_pp_is_colorize_postprocess_name(resolve_name):
                    step['colorize_extra'] = filter_extra
                if _merge_pp_is_header_plus_height_postprocess_name(resolve_name):
                    step['header_height_extra'] = filter_extra
                if _merge_pp_is_any_grid_postprocess_name(resolve_name):
                    step['grid_extra'] = filter_extra
                if _merge_pp_is_apply_formula_postprocess_name(resolve_name):
                    step['formula_extra'] = filter_extra
                if _merge_pp_is_color_scale_postprocess_name(resolve_name):
                    step['color_scale_extra'] = filter_extra
                if _merge_pp_is_format_postprocess_name(resolve_name):
                    step['format_extra'] = filter_extra
                pipeline.append(step)
        elif _is_vlookup_param_name(pname):
            raw = []
            for col in range(1, 6):
                raw.append(cell_text(sheet.getCellByPosition(col, row)))
            c_val = str(raw[1]).strip() if len(raw) > 1 else ''
            if str(raw[0]).strip() != '' or vlookup_is_json_cell(c_val):
                spec, err = parse_vlookup_spec(tuple(raw), doc)
                if err:
                    print('  ⚠ ВПР_XML: %s' % err)
                else:
                    pipeline.append({'kind': 'vlookup', 'spec': spec, 'row_num': row})
        elif _is_merge_sheets_param_name(pname):
            raw = []
            for col in range(1, 6):
                raw.append(cell_text(sheet.getCellByPosition(col, row)))
            c_val = str(raw[1]).strip() if len(raw) > 1 else ''
            if str(raw[0]).strip() != '' or _pipeline_c_looks_like_json(c_val):
                spec, err = parse_merge_sheets_spec(tuple(raw), doc)
                if err:
                    print('  ⚠ объединить_листы_в_один (xml): %s' % err)
                else:
                    pipeline.append({'kind': 'merge_sheets', 'spec': spec, 'row_num': row, 'name': _cw_cfg.P_MERGE_SHEETS_INTO_ONE})
        elif _is_split_sheets_param_name(pname):
            raw = []
            for col in range(1, 6):
                raw.append(cell_text(sheet.getCellByPosition(col, row)))
            spec, err = parse_split_sheets_spec(tuple(raw), doc)
            if err:
                print('  ⚠ разделить_листы (xml): %s' % err)
            else:
                pipeline.append({'kind': 'split_sheets', 'spec': spec, 'row_num': row, 'name': _cw_cfg.P_SPLIT_SHEETS})
        row = row + 1
    return pipeline

def _merge_log_postprocess_setup(doc, param_key, function_map, scope_label):
    """
    Запись в «Сбор_книг_лог» шагов постобработки из листа параметров.

    Вызывается в run_collect_merge после reset_collect_log (этап 2).
    """
    if doc is None:
        return
    entries = read_postprocess_param_rows(doc, param_key)
    if len(entries) == 0:
        _merge_log_postprocess(doc, '', 'настройка', param_key, 'пропуск', 'строк на листе параметров нет (%s)' % scope_label)
        return
    resolve_fn = resolve_postprocess_function
    if param_key == _cw_cfg.P_MERGE_FINAL_PROCESSING:
        resolve_fn = resolve_final_processing_function
    for fn_name, c_raw, d_raw, e_raw in entries:
        resolve_name, extra_raw = _merge_pp_resolve_row_fn_and_extra(fn_name, c_raw, d_raw)
        fn = resolve_fn(resolve_name, function_map)
        if _merge_pp_is_plugin_fn_key(fn_name):
            label = '%s: %s' % (_cw_cfg.MERGE_PLUGIN_FUNCTION_KEY, _merge_pp_short_label(resolve_name))
        else:
            label = _merge_pp_short_label(fn_name)
        if fn is None:
            _merge_log_postprocess(doc, '', 'настройка', label, 'ошибка', 'неизвестная функция (%s)' % scope_label)
            continue
        if _merge_pp_is_plugin_fn_key(fn_name):
            c_note = c_raw if c_raw != '' else '(пусто)'
            d_note = extra_raw if extra_raw != '' else '(пусто)'
            e_note = e_raw if e_raw != '' else '(пусто)'
            extra_note = 'C=%s, D=%s, E=%s' % (c_note, d_note, e_note)
        else:
            cond_note = d_raw if d_raw != '' else '(без условия)'
            extra_note = '%s; условие D=%s' % (extra_raw if extra_raw != '' else '(без C)', cond_note)
        _merge_log_postprocess(doc, '', 'настройка', label, 'в очереди', '%s, %s' % (scope_label, extra_note))

def _merge_build_postprocess_chain(param_tuple, code_tuple):
    """
    Объединение цепочек постобработки: лист параметров + константы в коде.

    Назначение:
        Сформировать единый tuple колбэков: сначала с листа (param_tuple),
        затем из _MERGE_CODE_POSTPROCESS_RANGE / _ROW в конце файла.

    Параметры:
        param_tuple — результат parse_postprocess_from_sheet или None.
        code_tuple — _MERGE_CODE_POSTPROCESS_RANGE или _MERGE_CODE_POSTPROCESS_ROW.

    Возвращает:
        tuple(callable, …) или None, если после фильтрации список пуст.

    Связь:
        run_collect_merge задаёт глобальные _MERGE_RESULT_POSTPROCESS_*;
        apply_result_sheet_postprocessing читает эти глобальные переменные.
    """
    fns = []
    for spec in (param_tuple, code_tuple):
        for fn in _merge_postprocess_callbacks(spec):
            fns.append(fn)
    if len(fns) == 0:
        return None
    return tuple(fns)

class ProgressReport:
    """
    Счётчик прогресса и итоговая статистика сбора для этапа 2.

    Назначение:
        Вести шаги (step), детальный статус (status), нефатальные проблемы (problem),
        счётчики files_done / sheets_done / rows_copied и формировать текст
        build_final_message для show_message в collect_workbooks_run.

    Не использует StatusIndicator в ProgressReport — для UI см. merge_ui_yield /
    merge_ui_status_* (вызываются из циклов копирования).
    Проблемы дублируются в problems и на лист «Сбор_книг_лог» через append_collect_log.

    Связь:
        Создаётся в collect_workbooks_run; передаётся в merge_on_one_sheet /
        merge_on_many_sheets и run_collect_merge.
    """

    def __init__(self, total_steps, doc=None):
        """
        Инициализация отчёта перед run_collect_merge.

        Параметры:
            total_steps — оценка из estimate_work_steps (минимум 1).
            doc — книга результата для append_collect_log в problem/log_stat.
        """
        import time
        self.total_steps = total_steps
        if self.total_steps < 1:
            self.total_steps = 1
        self.current_step = 0
        self.last_status = ''
        self.doc = doc
        self.problems = []
        self.stats = {'files_done': 0, 'sheets_done': 0, 'rows_copied': 0, 'rows_skipped': 0, 'sheets_skipped': 0}
        self.timings = {'data_collection': 0.0, 'formatting': 0.0, 'postprocess_range': 0.0, 'postprocess_row': 0.0, 'postprocess_delete': 0.0, 'postprocess_pivot': 0.0, 'final_processing': 0.0, 'total': 0.0}
        self._time_start = time.time()
        self._stage_start = None
        self._current_stage = None

    def _log(self, text):
        """Внутренний вывод в консоль Python и поле last_status (step/status)."""
        self.last_status = text
        print(text)

    def step(self, text):
        """Крупный шаг: увеличивает current_step, пишет в консоль (обычно новый файл)."""
        self.current_step = self.current_step + 1
        self._log(text)
        try:
            merge_ui_sync_progress(self, file_frac=0.0)
        except Exception:
            pass

    def status(self, text):
        """Детальный статус (лист/строка/столбец) без инкремента current_step."""
        self._log(text)

    def problem(self, text):
        """Нефатальная проблема: в problems и лог «проблема»; сбор не прерывается."""
        self.problems.append(text)
        if self.doc is not None:
            append_collect_log(self.doc, '', '', '', '', 'проблема', text)

    def log_stat(self, source, sheet, column, rows_n, status, note=''):
        """Строка детального журнала на лист «Сбор_книг_лог» (append_collect_log)."""
        if self.doc is not None:
            append_collect_log(self.doc, source, sheet, column, rows_n, status, note)

    def start_stage(self, stage_name):
        """Начать замер времени для этапа."""
        import time
        if self._current_stage is not None and self._stage_start is not None:
            elapsed = time.time() - self._stage_start
            if self._current_stage in self.timings:
                self.timings[self._current_stage] += elapsed
        self._current_stage = stage_name
        self._stage_start = time.time()

    def end_stage(self, stage_name=None):
        """Завершить замер времени для этапа."""
        import time
        if stage_name is None:
            stage_name = self._current_stage
        if stage_name is not None and self._stage_start is not None:
            elapsed = time.time() - self._stage_start
            if stage_name in self.timings:
                self.timings[stage_name] += elapsed
        self._current_stage = None
        self._stage_start = None

    def finalize_timings(self):
        """Завершить все замеры и подсчитать общее время."""
        import time
        if self._current_stage is not None and self._stage_start is not None:
            elapsed = time.time() - self._stage_start
            if self._current_stage in self.timings:
                self.timings[self._current_stage] += elapsed
        self.timings['total'] = time.time() - self._time_start

    def format_timings(self):
        """Форматированная строка с временем выполнения."""

        def fmt(sec):
            if sec < 0.01:
                return '<0.01с'
            if sec < 1:
                return '%.2fс' % sec
            if sec < 60:
                return '%.1fс' % sec
            m = int(sec // 60)
            s = sec % 60
            return '%dм%.1fс' % (m, s)
        lines = ['Время выполнения:', '  • Сбор данных: %s' % fmt(self.timings['data_collection']), '  • Форматирование: %s' % fmt(self.timings['formatting']), '  • Постобработка (диапазон): %s' % fmt(self.timings['postprocess_range']), '  • Постобработка (строки): %s' % fmt(self.timings['postprocess_row']), '  • Финальная обработка: %s' % fmt(self.timings['final_processing']), '  • Общее: %s' % fmt(self.timings['total'])]
        return '\n'.join(lines)

    def close(self):
        """Заглушка совместимости; вызывается в finally collect_workbooks_run."""
        pass

    def build_final_message(self, mode_text, file_count, success=True):
        """
        Текст итогового диалога: режим, счётчики stats, время выполнения, до 25 проблем.

        Параметры:
            mode_text — settings["mode"].
            file_count — len(settings["files"]).
            success — заголовок «Готово» vs «Отчёт».
        """
        if success:
            msg = 'Готово.\n\n'
        else:
            msg = 'Отчёт.\n\n'
        msg = msg + 'Режим: %s\n' % mode_text
        msg = msg + 'Файлов в задании: %d\n' % file_count
        msg = msg + 'Обработано файлов: %d\n' % self.stats['files_done']
        msg = msg + 'Листов обработано: %d\n' % self.stats['sheets_done']
        msg = msg + 'Строк скопировано: %d\n' % self.stats['rows_copied']
        msg = msg + 'Строк пропущено: %d\n' % self.stats.get('rows_skipped', 0)
        msg = msg + 'Пропусков листов: %d\n' % self.stats['sheets_skipped']
        msg = msg + '\n' + self.format_timings() + '\n'
        if len(self.problems) > 0:
            msg = msg + '\nПредупреждения и проблемы (%d):\n' % len(self.problems)
            i = 0
            while i < len(self.problems) and i < 25:
                msg = msg + '  • ' + self.problems[i] + '\n'
                i = i + 1
            if len(self.problems) > 25:
                msg = msg + '  … и ещё %d\n' % (len(self.problems) - 25)
        return msg

def estimate_work_steps(file_count, mode):
    """
    Грубая оценка числа шагов для ProgressReport.total_steps.

    Параметры:
        file_count — количество развёрнутых файлов после expand_source_files.
        mode — MERGE_MODE_ONE, MERGE_MODE_MANY или MERGE_MODE_COPY (нормализованный «Режим»).

    Возвращает:
        int — «копирование листов»: file_count*6+5;
              «на разные листы»: file_count*8+5; «на один лист»: file_count*12+10.

    Связь:
        collect_workbooks_run → ProgressReport(...).
    """
    if mode == _cw_cfg.MERGE_MODE_COPY:
        return file_count * 6 + 5
    if mode == _cw_cfg.MERGE_MODE_MANY:
        return file_count * 8 + 5
    if mode == _cw_cfg.MERGE_MODE_INVOLVE:
        return max(8, int(file_count) * 2 + 6)
    return file_count * 12 + 10

def short_name(path):
    """
    Имя файла без каталога для сообщений report.step/status.

    Параметры:
        path — путь к файлу-источнику.

    Возвращает:
        str — os.path.basename(path).
    """
    return os.path.basename(path)

def _parse_service_column_mode(raw, default='none'):
    """
    Разбор режима служебной колонки: none | short | long.

    none — не выводить; short/long — формат значения.
    """
    text = str(raw).strip().lower()
    if text in ('', 'не_выводить', 'не выводить', 'невыводить', 'none', 'нет', 'скрыть', 'скрыто', '-', 'off'):
        return 'none'
    if text in ('коротко', 'short', 'кратко', 'краткий', 'имя файла'):
        return 'short'
    if text in ('длинно', 'long', 'полный', 'полный путь'):
        return 'long'
    if text.startswith('не_') or text.startswith('не '):
        return 'none'
    if text.startswith('корот') or text.startswith('крат'):
        return 'short'
    if text.startswith('длин') or text.startswith('полн'):
        return 'long'
    return default

def parse_path_display_mode(table):
    """
    Режим колонки «#Путь» (параметр «Источник_в_первой_колонке»).

    Возвращает: "none" | "short" | "long" (по умолчанию "none").
    """
    raw = first_value(table, _cw_cfg.P_MERGE_PATH_DISPLAY, 'Не_выводить')
    return _parse_service_column_mode(raw, default='none')

def parse_datetime_display_mode(table):
    """
    Режим колонки «#ДатаВремяФайла» (параметр «Дата_источника_во_второй_колонке»).

    Возвращает: "none" | "short" (только дата) | "long" (дата и время); по умолчанию "none".
    """
    raw = first_value(table, _cw_cfg.P_MERGE_DATETIME_DISPLAY, None)
    if raw is None:
        raw = first_value(table, _cw_cfg.P_MERGE_DATETIME_DISPLAY_LEGACY, 'Не_выводить')
    return _parse_service_column_mode(raw, default='none')

def _parse_data_transfer_raw(raw):
    """
    Разбор одной ячейки способа переноса (B отдельной строки или C «Режим»).

    Возвращает MERGE_TRANSFER_API | MERGE_TRANSFER_CLIPBOARD_HEADERS |
    MERGE_TRANSFER_CLIPBOARD_POSITION | MERGE_TRANSFER_XML_EXCEL_ODS.
    Пустое raw — MERGE_TRANSFER_DEFAULT (По_API).
    """
    token = str(raw).strip().lower().replace(' ', '_').replace('-', '_')
    if token == '':
        return _cw_cfg.MERGE_TRANSFER_DEFAULT
    if token in ('по_api', 'api', 'uno', 'по_uno', 'uno_api', 'как_сейчас', 'сейчас', 'default'):
        return _cw_cfg.MERGE_TRANSFER_API
    if token in ('буфер_по_заголовкам', 'буфер_матчинг', 'буфер_заголовки', 'clipboard_headers', 'clipboard_match', 'буфер_с_матчингом'):
        return _cw_cfg.MERGE_TRANSFER_CLIPBOARD_HEADERS
    if token in ('буфер_по_позиции', 'буфер_без_матчинга', 'буфер_позиция', 'clipboard_position', 'clipboard_pos', 'буфер_без_заголовков'):
        return _cw_cfg.MERGE_TRANSFER_CLIPBOARD_POSITION
    if token in ('xml_excel_ods', 'excel_ods', 'xlsx_ods', 'direct', 'direct_files', 'по_файлам', 'прямой', 'прямой_перенос'):
        return _cw_cfg.MERGE_TRANSFER_XML_EXCEL_ODS
    raise ValueError('неизвестный «%s»: «%s» (ожидается По_API, Буфер_по_заголовкам, Буфер_по_позиции или xml_excel_ods)' % (_cw_cfg.P_MERGE_DATA_TRANSFER, token))

def parse_data_transfer_mode(table):
    """
    Способ переноса данных.

    Приоритет: отдельная строка «Способ_переноса» (B) → колонка C строки «Режим»
    → По_API. Для «На один лист», «На разные листы» и «Копирование листов»
    (при xml_excel_ods книга результата должна быть сохранена на диск).
    """
    separate = table_values(table, _cw_cfg.P_MERGE_DATA_TRANSFER)
    if separate is not None and len(separate) > 0:
        sep_raw = str(separate[0]).strip()
        if sep_raw != '':
            return _parse_data_transfer_raw(sep_raw)
    mode_vals = table_values(table, _cw_cfg.P_MERGE_MODE)
    if mode_vals is not None and len(mode_vals) > 1:
        inline = str(mode_vals[1]).strip()
        if inline != '':
            return _parse_data_transfer_raw(inline)
    return _cw_cfg.MERGE_TRANSFER_DEFAULT

def _merge_data_transfer_mode_label(mode):
    if mode == _cw_cfg.MERGE_TRANSFER_CLIPBOARD_HEADERS:
        return 'Буфер по заголовкам'
    if mode == _cw_cfg.MERGE_TRANSFER_CLIPBOARD_POSITION:
        return 'Буфер по позиции'
    if mode == _cw_cfg.MERGE_TRANSFER_XML_EXCEL_ODS:
        return 'Прямой перенос (xml_excel_ods)'
    return 'По API'

def merge_service_columns_layout(path_mode, datetime_mode):
    """Расположение служебных колонок: индексы 0-based и first_data_col."""
    path_col = -1
    datetime_col = -1
    col = 0
    if path_mode != 'none':
        path_col = col
        col = col + 1
    if datetime_mode != 'none':
        datetime_col = col
        col = col + 1
    return {'path_mode': path_mode, 'datetime_mode': datetime_mode, 'path_col': path_col, 'datetime_col': datetime_col, 'first_data_col': col}

def _merge_service_row_context(fpath, is_current_book, sheet_name, layout, path_display):
    """Метки служебных колонок и file_key для копирования строк."""
    row_label = ''
    if layout['path_mode'] != 'none':
        row_label = format_source_label(fpath if not is_current_book else '', layout['path_mode'], sheet_name)
    mtime_val = None
    if layout['datetime_mode'] != 'none' and (not is_current_book):
        mtime_val = file_mtime_datetime(fpath)
    log_fpath = fpath if not is_current_book else get_current_book_path() or ''
    file_key = cell_to_column_file_key(log_fpath, path_display)
    return (row_label, mtime_val, file_key)

def _merge_effective_service_layout(settings):
    """
    Раскладка служебных колонок с учётом режима сбора.

    «Копирование листов» (UNO и xml_excel_ods) — служебные колонки не выводятся.
    """
    path_display = settings.get('path_display', 'none')
    datetime_display = settings.get('datetime_display', 'none')
    mode = str(settings.get('mode') or '').strip().lower()
    if mode in (_cw_cfg.MERGE_MODE_COPY, _cw_cfg.MERGE_MODE_INVOLVE):
        return merge_service_columns_layout('none', 'none')
    return merge_service_columns_layout(path_display, datetime_display)

def merge_run_context_begin(settings):
    """Сброс контекста запуска: раскладка служебных колонок и метаданные строк."""
    layout = settings.get('service_layout')
    if layout is None:
        layout = _merge_effective_service_layout(settings)
    _cw_cfg._MERGE_ACTIVE_SERVICE_LAYOUT = layout
    transfer = settings.get('data_transfer_mode', _cw_cfg.MERGE_TRANSFER_DEFAULT)
    if transfer not in (_cw_cfg.MERGE_TRANSFER_API, _cw_cfg.MERGE_TRANSFER_CLIPBOARD_HEADERS, _cw_cfg.MERGE_TRANSFER_CLIPBOARD_POSITION, _cw_cfg.MERGE_TRANSFER_XML_EXCEL_ODS):
        transfer = _cw_cfg.MERGE_TRANSFER_DEFAULT
    _cw_cfg._MERGE_ACTIVE_DATA_TRANSFER_MODE = transfer
    _cw_cfg._MERGE_FILE_TRANSFER_OVERRIDE = None
    _cw_cfg._MERGE_ROW_SOURCE_BY_SHEET = {}
    _cw_cfg._MERGE_SOURCE_VARIABLES_MAP = {}
    _cw_cfg._MERGE_SOURCE_VARIABLES_ORDER = []
    try:
        from libre_macros_global_settings_lib import GLOBAL_VARIABLES_FILE_KEY, GLOBAL_VARIABLES_SHEET_KEY, resolved_global_variables

        for item in resolved_global_variables() or []:
            nm = str(item.get('name') or '').strip()
            if nm == '':
                continue
            val = item.get('value')
            if val is None:
                val = ''
            _merge_source_variables_put(
                nm,
                GLOBAL_VARIABLES_SHEET_KEY,
                GLOBAL_VARIABLES_FILE_KEY,
                (str(val), 'text'),
                report=None,
                cell_ref='global',
            )
    except Exception:
        pass
    # Ручной ввод: переложить значения, собранные в parse_collect_settings
    # (карта очищается выше; без reinject плейсхолдеры в постобработке пропадут).
    try:
        manual_entries = (settings or {}).get('manual_variables') or []
        sheet_key = getattr(_cw_cfg, 'MANUAL_VARIABLE_SHEET_KEY', 'ручной_ввод')
        file_key = getattr(_cw_cfg, 'MANUAL_VARIABLE_FILE_KEY', 'ручной_ввод')
        mi = 0
        while mi < len(manual_entries):
            ent = manual_entries[mi]
            mi = mi + 1
            if not isinstance(ent, (list, tuple)) or len(ent) < 2:
                continue
            nm = str(ent[0] or '').strip()
            text = str(ent[1] if len(ent) > 1 else '')
            token = str(ent[2] if len(ent) > 2 else 'text') or 'text'
            if nm == '':
                continue
            _merge_source_variables_put(
                nm, sheet_key, file_key, (text, token), report=None, cell_ref='ручной_ввод',
            )
    except Exception:
        pass
    plan = (settings or {}).get('add_to_variables_map_plan', [])
    files_n = len((settings or {}).get('files') or [])
    _cw_cfg._MERGE_ADD_TO_VARIABLES_PER_FILE = build_add_to_variables_map_per_file_specs(plan, files_n)
    extras = (settings or {}).get('per_file_source_extra')
    if extras is None:
        extras = []
    _cw_cfg._MERGE_PER_FILE_SOURCE_EXTRA = list(extras)
    _cw_set('_MERGE_SHEETS_INCLUDE_FILTER_FN', (settings or {}).get('sheets_include_filter_fn'))


def _merge_source_extra_for_fi(fi):
    """Доп. параметры источника для индекса развёрнутого файла (или None)."""
    extras = getattr(_cw_cfg, '_MERGE_PER_FILE_SOURCE_EXTRA', None) or []
    try:
        idx = int(fi)
    except (TypeError, ValueError):
        return None
    if idx < 0 or idx >= len(extras):
        return None
    return extras[idx]


def _merge_open_source_for_file(fpath, fi, writable=False, sheet_specs=None):
    """open_source с доп. параметрами столбца источника (CSV delimiter и т.п.)."""
    return open_source(
        fpath,
        writable=writable,
        sheet_specs=sheet_specs,
        source_extra=_merge_source_extra_for_fi(fi),
    )

def _merge_clear_file_transfer_override():
    """Сбросить подмену способа переноса после книги-источника."""
    _cw_cfg._MERGE_FILE_TRANSFER_OVERRIDE = None

def _merge_hidden_source_slot_names(src, sheet_specs, sheet_kind):
    """Имена листов сбора, которые скрыты (hidden / very_hidden)."""
    names = []
    if src is None:
        return names
    try:
        slots = list(iter_sheet_slots(src, sheet_specs, sheet_kind))
    except Exception:
        return names
    seen = set()
    for slot in slots:
        n = slot.get('source_name') or u''
        if n == u'' or n in seen:
            continue
        seen.add(n)
        sh = get_sheet(src, n)
        if sh is None:
            continue
        if not _merge_sheet_is_visible(sh):
            names.append(n)
    return names

def _merge_maybe_force_api_for_hidden_source(src, sheet_specs, sheet_kind, report=None, src_label=''):
    """
    Если среди листов сбора книги есть скрытый — для этой книги буфер → По_API.

    xml_excel_ods и уже выбранный По_API не трогаем. Вызывать после открытия
    источника (или для текущей книги) до копирования строк.
    """
    _merge_clear_file_transfer_override()
    if src is None:
        return
    configured = _cw_cfg._MERGE_ACTIVE_DATA_TRANSFER_MODE or _cw_cfg.MERGE_TRANSFER_DEFAULT
    if configured not in (
        _cw_cfg.MERGE_TRANSFER_CLIPBOARD_HEADERS,
        _cw_cfg.MERGE_TRANSFER_CLIPBOARD_POSITION,
    ):
        return
    kind = sheet_kind
    if kind is None or kind == '':
        try:
            kind = classify_sheet_specs(sheet_specs or [])
        except Exception:
            kind = 'ALL'
    hidden = _merge_hidden_source_slot_names(src, sheet_specs or [], kind)
    if not hidden:
        return
    _cw_cfg._MERGE_FILE_TRANSFER_OVERRIDE = _cw_cfg.MERGE_TRANSFER_API
    shown = u', '.join(hidden[:8])
    if len(hidden) > 8:
        shown = shown + u'…'
    note = u'скрытый лист источника (%s) — перенос По_API вместо буфера' % shown
    try:
        merge_debug('transfer_override', note)
    except Exception:
        pass
    if report is not None:
        try:
            report.log_stat(src_label or u'', hidden[0], u'', u'', u'способ_переноса', note)
            return
        except Exception:
            pass
    try:
        doc = get_run_target_doc()
        if doc is not None:
            append_collect_log(doc, src_label or u'', hidden[0], u'', u'', u'способ_переноса', note)
    except Exception:
        pass

def _merge_configured_data_transfer_mode():
    """Способ переноса из параметров запуска (без подмены для скрытых листов)."""
    return _cw_cfg._MERGE_ACTIVE_DATA_TRANSFER_MODE or _cw_cfg.MERGE_TRANSFER_DEFAULT

def _merge_active_data_transfer_mode():
    ov = getattr(_cw_cfg, '_MERGE_FILE_TRANSFER_OVERRIDE', None)
    if ov:
        return ov
    return _merge_configured_data_transfer_mode()

def _merge_uses_header_column_matching():
    """Матчинг столбцов по заголовкам (не «буфер по позиции», в т.ч. API-fallback)."""
    if _merge_configured_data_transfer_mode() == _cw_cfg.MERGE_TRANSFER_CLIPBOARD_POSITION:
        return False
    return _merge_active_data_transfer_mode() != _cw_cfg.MERGE_TRANSFER_CLIPBOARD_POSITION

def _merge_api_copy_chunk():
    """Строк за один getDataArray/setDataArray в режиме По_API (диалог не режет до 50)."""
    try:
        n = int(getattr(_cw_cfg, 'MERGE_COPY_ROW_CHUNK', 1000) or 1000)
    except Exception:
        n = 1000
    if n < 1:
        return 1000
    return n

def merge_active_service_layout():
    if _cw_cfg._MERGE_ACTIVE_SERVICE_LAYOUT is None:
        return merge_service_columns_layout('none', 'none')
    return _cw_cfg._MERGE_ACTIVE_SERVICE_LAYOUT

def merge_get_first_data_col():
    return merge_active_service_layout()['first_data_col']

def merge_get_path_col():
    return merge_active_service_layout()['path_col']

def merge_get_datetime_col():
    return merge_active_service_layout()['datetime_col']

def path_display_for_file_key(path_display):
    """Ключ файла для «Ячейка_В_Столбец», если колонка #Путь скрыта — короткое имя."""
    if path_display == 'none':
        return 'short'
    return path_display

def merge_row_source_track(sheet_name, row_index, file_key, source_sheet):
    bucket = _cw_cfg._MERGE_ROW_SOURCE_BY_SHEET.get(sheet_name)
    if bucket is None:
        bucket = {}
        _cw_cfg._MERGE_ROW_SOURCE_BY_SHEET[sheet_name] = bucket
    bucket[row_index] = (file_key, source_sheet)

def merge_cell_path_value(sheet, row_index):
    """Значение «#Путь» из ячейки или из метаданных строки (если колонка скрыта)."""
    layout = merge_active_service_layout()
    pc = layout['path_col']
    if pc >= 0:
        return cell_text(sheet.getCellByPosition(pc, row_index))
    try:
        sheet_name = sheet.Name
    except Exception:
        sheet_name = ''
    meta = _cw_cfg._MERGE_ROW_SOURCE_BY_SHEET.get(sheet_name, {}).get(row_index)
    if meta is None:
        return ''
    file_key, source_sheet = meta
    if source_sheet != '':
        return '%s#%s' % (file_key, source_sheet)
    return file_key

def format_source_path(path, path_display):
    """
    Идентификатор файла-источника для колонки «#Путь» и лога.

    Параметры:
        path — путь к файлу на диске.
        path_display — "short" | "long" (не "none").

    Возвращает:
        str — stem без расширения (short) или os.path.abspath (long).
    """
    if path_display == 'none':
        path_display = 'short'
    abspath = os.path.abspath(path)
    if path_display == 'short':
        base = os.path.basename(abspath)
        stem, _ext = os.path.splitext(base)
        if stem != '':
            return stem
        return base
    return abspath

def format_file_mtime(path, datetime_mode='long'):
    """
    Строка mtime файла-источника для колонки «#ДатаВремяФайла».

    datetime_mode: "short" — только дата; "long" — дата и время; "none" — "".
    """
    dt = file_mtime_datetime(path)
    if dt is None:
        return ''
    if datetime_mode == 'short':
        return dt.strftime('%Y-%m-%d')
    return dt.strftime('%Y-%m-%d %H:%M:%S')

def file_mtime_datetime(path):
    """datetime mtime файла-источника или None."""
    if path is None or str(path).strip() == '':
        return None
    try:
        ts = os.path.getmtime(os.path.abspath(path))
        return datetime.fromtimestamp(ts).replace(microsecond=0)
    except Exception:
        return None

def _merge_datetime_to_calc_serial(dt):
    """Python datetime → серийное число Calc (дни с 1899-12-30)."""
    if dt is None:
        return None
    if isinstance(dt, (int, float)):
        return float(dt)
    try:
        if not isinstance(dt, datetime):
            return None
    except Exception:
        return None
    base = datetime(1899, 12, 30)
    delta = dt - base
    return float(delta.days) + float(delta.seconds) / 86400.0

def _merge_service_datetime_format_string(datetime_mode):
    if datetime_mode == 'short':
        return _cw_cfg.MERGE_SERVICE_DATETIME_FMT_SHORT
    return _cw_cfg.MERGE_SERVICE_DATETIME_FMT_LONG

def _merge_service_datetime_nf_key(doc, datetime_mode):
    if doc is None or datetime_mode == 'none':
        return None
    fmt = _merge_service_datetime_format_string(datetime_mode)
    cache_key = (id(doc), fmt)
    cached = _cw_cfg._MERGE_SERVICE_DT_NF_KEYS.get(cache_key)
    if cached is not None:
        return cached
    lang, country = ('ru', 'RU')
    cl = _merge_doc_char_locale(doc)
    if cl is not None:
        try:
            if cl.Language:
                lang = cl.Language
            if cl.Country:
                country = cl.Country
        except Exception:
            pass
    ol = _merge_office_setup_locale()
    if ol is not None:
        lang, country = ol
    key = None
    fn = _merge_pp_resolve_eval_helper('_merge_pp_number_format_key')
    if fn is not None:
        try:
            key = fn(doc, fmt, lang, country)
        except Exception:
            key = None
    if key is None or int(key) < 0:
        key = _merge_number_format_key_cross_doc(doc, fmt, lang, country)
    _cw_cfg._MERGE_SERVICE_DT_NF_KEYS[cache_key] = key
    return key

def _merge_apply_service_datetime_column_format(sheet, doc, header_row, end_row):
    """Числовой формат DD.MM.YYYY HH:MM:SS на колонку #ДатаВремяФайла."""
    if sheet is None or doc is None:
        return
    layout = merge_active_service_layout()
    dt_col = int(layout.get('datetime_col', -1))
    datetime_mode = layout.get('datetime_mode', 'long')
    if dt_col < 0 or datetime_mode == 'none':
        return
    if not _merge_service_header_at_col(sheet, dt_col, int(header_row), _cw_cfg.MERGE_DATETIME_HEADER):
        return
    if int(end_row) <= int(header_row):
        return
    nf_key = _merge_service_datetime_nf_key(doc, datetime_mode)
    if nf_key is None:
        return
    try:
        svc_range = sheet.getCellRangeByPosition(dt_col, int(header_row) + 1, dt_col, int(end_row))
        if svc_range is not None:
            svc_range.NumberFormat = int(nf_key)
    except Exception:
        pass

def _merge_write_service_datetime_cell(cell, dt_val, doc, datetime_mode):
    """Записать #ДатаВремяФайла как число + формат отображения."""
    if cell is None or datetime_mode == 'none':
        return
    serial = None
    if isinstance(dt_val, datetime):
        serial = _merge_datetime_to_calc_serial(dt_val)
    elif isinstance(dt_val, (int, float)):
        serial = float(dt_val)
    elif isinstance(dt_val, str) and str(dt_val).strip() != '':
        try:
            import libre_macros_lib as _lm
            serial = _lm._lm_pp_try_parse_date_string(dt_val)
        except Exception:
            serial = None
        if serial is None:
            try:
                cell.String = str(dt_val)
            except Exception:
                pass
            return
    if serial is None:
        return
    try:
        cell.Value = serial
        nf_key = _merge_service_datetime_nf_key(doc, datetime_mode)
        if nf_key is not None:
            cell.NumberFormat = int(nf_key)
    except Exception:
        try:
            if isinstance(dt_val, datetime):
                cell.String = dt_val.strftime('%Y-%m-%d %H:%M:%S')
            else:
                cell.String = str(dt_val)
        except Exception:
            pass

def _merge_read_service_datetime_from_cell(src_cell, fallback_val, datetime_mode):
    """Считать дату/время из ячейки источника (число или текст) для копирования."""
    if src_cell is None:
        return fallback_val
    try:
        if _merge_cell_value_looks_like_serial_date(src_cell):
            return float(src_cell.Value)
    except Exception:
        pass
    txt = cell_text(src_cell)
    if txt != '':
        try:
            import libre_macros_lib as _lm
            ser = _lm._lm_pp_try_parse_date_string(txt)
            if ser is not None:
                return ser
        except Exception:
            pass
    return fallback_val

def format_source_label(path, path_display, sheet_name=None):
    """
    Полное значение служебной колонки «#Путь» для одной строки данных.

    Параметры:
        path — файл-источник.
        path_display — short/long.
        sheet_name — имя листа источника; если задано, добавляется через «#».

    Возвращает:
        str — например «source_01#Отчёт» или абсолютный путь#лист.

    Связь:
        format_source_path; merge_on_one_sheet при копировании строк.
    """
    label = format_source_path(path, path_display)
    if sheet_name is not None and str(sheet_name).strip() != '':
        return '%s#%s' % (label, str(sheet_name).strip())
    return label

def path_looks_like_glob(path):
    """
    Проверка, задан ли путь как маска glob для expand_source_files.

    Параметры:
        path — строка из «Файлы-Источники».

    Возвращает:
        bool — True, если есть *, ? или [.
    """
    p = str(path)
    return '*' in p or '?' in p or '[' in p

def _merge_source_exclude_masks(source_extra=None):
    """
    Список масок исключения: лист MERGE_SOURCE_EXCLUDE_MASK + доп. из source_extra.

    Маски складываются (union, без дублей, порядок: сначала лист, потом extra).
    Пустой параметр листа → только маски из source_extra (если есть).
    """
    parts = []
    seen = set()

    def _add_one(mask):
        t = str(mask or '').strip()
        if t == '':
            return
        try:
            key = t.casefold()
        except Exception:
            key = t.lower()
        if key in seen:
            return
        seen.add(key)
        parts.append(t)

    raw = str(_cw_get('MERGE_SOURCE_EXCLUDE_MASK', '--*') or '').strip()
    if raw != '':
        for chunk in raw.replace(';', ',').split(','):
            _add_one(chunk)
    if source_extra is not None:
        try:
            from libre_macros_source_extra_lib import source_extra_exclude_masks

            for m in source_extra_exclude_masks(source_extra):
                _add_one(m)
        except Exception:
            pass
    return parts

def _merge_source_basename_excluded(basename, exclude_masks=None):
    """True — файл не брать: имя ~* или совпало с exclude-маской (регистронезависимо)."""
    name = str(basename or '')
    if name == '':
        return True
    try:
        name_cf = name.casefold()
    except Exception:
        name_cf = name.lower()
    if name_cf.startswith('~') or name.startswith('~'):
        return True
    masks = exclude_masks if exclude_masks is not None else _merge_source_exclude_masks()
    for mask in masks or []:
        m = str(mask or '').strip()
        if m == '':
            continue
        try:
            m_cf = m.casefold()
        except Exception:
            m_cf = m.lower()
        try:
            if fnmatch.fnmatch(name_cf, m_cf):
                return True
        except Exception:
            pass
    return False

def _merge_glob_split_dir_mask(resolved_path):
    """
    Разделить путь-маску на (стартовая_директория, маска).

    Сегменты «**» пропускаются. Маска может включать подпути (*/*source_*).
    Если каталог из пути не существует (glob в середине пути) — поднимаемся вверх.
    """
    p = os.path.normpath(str(resolved_path or ''))
    drive, tail = os.path.splitdrive(p)
    is_abs = tail.startswith(os.sep)
    parts = [x for x in tail.split(os.sep) if x and x != '**']
    walk_parts = []
    mask_parts = []
    for part in parts:
        has_glob = any(c in part for c in '*?[')
        if has_glob or mask_parts:
            mask_parts.append(part)
        else:
            walk_parts.append(part)

    directory = os.sep.join(walk_parts)
    if is_abs:
        directory = (os.sep + directory) if directory else os.sep
    elif directory == '':
        directory = '.'

    if drive:
        if directory in ('', '.'):
            directory = drive + (os.sep if is_abs else '')
        elif directory.startswith(os.sep):
            directory = drive + directory
        else:
            directory = drive + os.sep + directory

    mask = os.sep.join(mask_parts) if mask_parts else '*'

    root_stop = drive + os.sep if drive else os.sep
    while not os.path.isdir(directory):
        if directory in ('', '.', root_stop, drive):
            break
        parent = os.path.dirname(directory)
        tail_name = os.path.basename(directory)
        if parent == directory:
            break
        mask = tail_name + (os.sep + mask if mask else '')
        directory = parent

    if directory == '':
        directory = '.'
    return (directory, mask)

def _merge_glob_casefold_path(path):
    try:
        return str(path or '').replace('\\', '/').casefold()
    except Exception:
        return str(path or '').replace('\\', '/').lower()

def _merge_glob_entry_matches(full_path, directory, mask_cf, recursive):
    """Файл подходит под маску: по имени или по относительному пути от directory."""
    try:
        base_cf = _merge_glob_casefold_path(os.path.basename(full_path))
        if fnmatch.fnmatch(base_cf, mask_cf):
            return True
    except Exception:
        pass
    if recursive and ('/' in mask_cf):
        try:
            rel_cf = _merge_glob_casefold_path(os.path.relpath(full_path, directory))
            if fnmatch.fnmatch(rel_cf, mask_cf):
                return True
        except Exception:
            pass
    return False

def _merge_expand_glob_files(resolved_path, source_extra=None):
    """
    Развернуть маску в список существующих файлов.

    MERGE_SOURCE_VIEW_SUBFOLDERS=Да — рекурсия по подпапкам.
    Совпадение имён регистронезависимое (fnmatch на casefold).
    Исключения: ~* всегда; MERGE_SOURCE_EXCLUDE_MASK (по умолчанию --*)
    плюс маски из Доп_Параметры_Источника столбца (если заданы).
    """
    directory, file_mask = _merge_glob_split_dir_mask(resolved_path)
    exclude_masks = _merge_source_exclude_masks(source_extra=source_extra)
    recursive = bool(_cw_get('MERGE_SOURCE_VIEW_SUBFOLDERS', True))
    mask_cf = _merge_glob_casefold_path(file_mask)
    out = []
    if not os.path.isdir(directory):
        merge_debug('expand_glob', 'not a directory: %s (from %s)' % (directory, resolved_path))
        return out
    if recursive:
        for dirpath, _dirnames, filenames in os.walk(directory):
            for fn in filenames:
                if _merge_source_basename_excluded(fn, exclude_masks):
                    continue
                full = os.path.join(dirpath, fn)
                if not os.path.isfile(full):
                    continue
                if not _merge_glob_entry_matches(full, directory, mask_cf, True):
                    continue
                out.append(os.path.abspath(full))
    else:
        try:
            names = os.listdir(directory)
        except Exception:
            names = []
        for fn in names:
            full = os.path.join(directory, fn)
            if not os.path.isfile(full):
                continue
            if _merge_source_basename_excluded(fn, exclude_masks):
                continue
            if not _merge_glob_entry_matches(full, directory, mask_cf, False):
                continue
            out.append(os.path.abspath(full))
    out.sort()
    try:
        from libre_macros_source_extra_lib import apply_source_extra_file_pick

        before_n = len(out)
        out = apply_source_extra_file_pick(
            out, source_extra, log_fn=lambda m: merge_debug('file_pick', m)
        )
        if len(out) != before_n:
            merge_debug(
                'expand_glob',
                'file_pick %d -> %d' % (before_n, len(out)),
            )
    except Exception as err:
        merge_debug('expand_glob', 'file_pick skip: %s' % err)
    merge_debug(
        'expand_glob',
        'mask=%s dir=%s file_mask=%s recursive=%s exclude=%s -> %d' % (
            resolved_path, directory, file_mask, recursive,
            u','.join(unicode(m) for m in (exclude_masks or []))[:120],
            len(out),
        ),
    )
    return out

def is_current_book_marker(path):
    """
    Проверяет, является ли путь маркером текущей книги.

    Гибкая нормализация (регистр, пробелы, «_», «-», «.»): эта_книга / Эта-книга /
    этакнига / ThisWorkbook / This_Workbook / current и т.п.
    См. libre_macros_collect_cfg.merge_normalize_current_book_marker_key.

    Параметры:
        path — строка из «Файлы-Источники».

    Возвращает:
        bool — True, если это маркер текущей книги.
    """
    try:
        return bool(_cw_cfg.is_current_book_marker_key(path))
    except Exception:
        p = str(path).strip().lower()
        return p in _cw_cfg._MERGE_CURRENT_BOOK_MARKERS


def _normalize_collect_merge_mode(raw):
    """
    Нормализация параметра «Режим» → MERGE_MODE_*.

    «Текущие листы» (legacy «Вовлечь листы»): involve_sheets, passthrough, …
    """
    mode = str(raw or '').strip().lower()
    compact = mode.replace('_', ' ').replace('-', ' ')
    while '  ' in compact:
        compact = compact.replace('  ', ' ')
    key = compact.replace(' ', '')
    if compact in ('копирование листов', 'copy sheets') or key in ('копированиелистов', 'copysheets'):
        return _cw_cfg.MERGE_MODE_COPY
    if key in getattr(_cw_cfg, '_MERGE_MODE_INVOLVE_KEYS', ()) or compact in (
        'текущие листы',
        'current sheets',
        'вовлечь листы',
        'involve sheets',
        'passthrough',
        'без копирования',
        'только обработка',
    ):
        return _cw_cfg.MERGE_MODE_INVOLVE
    if compact in ('на разные листы',) or key == 'наразныелисты':
        return _cw_cfg.MERGE_MODE_MANY
    if compact in ('на один лист',) or key == 'наодинлист':
        return _cw_cfg.MERGE_MODE_ONE
    return compact


def _merge_involve_missing_sheet_specs(doc, sheet_specs, sheet_kind):
    """Имена/индексы из «Листы», которым нет соответствия в книге (strict)."""
    missing = []
    if doc is None:
        return missing
    if sheet_kind == 'NAME':
        names = sheet_names(doc)
        for spec in sheet_specs or []:
            any_match = False
            for n in names:
                if text_match(n, spec):
                    any_match = True
                    break
            if not any_match:
                missing.append(str(spec))
    elif sheet_kind == 'INDEX':
        for spec in sheet_specs or []:
            try:
                idx = int(str(spec).strip()) - 1
            except Exception:
                missing.append(str(spec))
                continue
            if idx < 0 or idx >= doc.Sheets.getCount():
                missing.append(str(spec))
    return missing

def get_current_book_path():
    """
    Получает путь к текущей книге (книге с листом параметров).

    Возвращает:
        str — абсолютный путь к файлу или пустая строка, если не удалось определить.
    """
    try:
        doc = get_run_target_doc()
        if doc is None:
            return ''
        url = doc.getURL()
        if not url:
            return ''
        return uno.fileUrlToSystemPath(url)
    except Exception:
        return ''

def _merge_doc_system_path(doc):
    """
    Абсолютный путь к текущему документу Calc (книга результата) или "".

    Важно: не зависит от get_run_target_doc(); используем в parse_collect_settings,
    чтобы корректно резолвить относительные пути даже до установки глобального состояния.
    """
    if doc is None:
        return ''
    try:
        url = doc.getURL()
        if not url:
            return ''
        return uno.fileUrlToSystemPath(url)
    except Exception:
        return ''

def _merge_doc_is_unsaved(doc):
    """True — документ без пути на диске (новый / private: URL)."""
    if doc is None:
        return True
    try:
        url = str(doc.getURL() or '').strip()
    except Exception:
        return True
    if url == '':
        return True
    if url.lower().startswith('private:'):
        return True
    return False

def _merge_xml_excel_ods_require_saved_book(doc):
    """
    Проверка книги результата для xml_excel_ods.
    Возвращает текст ошибки или None.
    """
    if _merge_doc_is_unsaved(doc):
        return u'Режим «xml_excel_ods» работает с файлом книги на диске.\n\nКнига результата ещё не сохранена.\nСначала сохраните её (Файл → Сохранить или Сохранить как…, рекомендуется .ods), затем запустите сбор снова.'
    path = str(_merge_doc_system_path(doc) or '').strip()
    if path == '':
        return u'Режим «xml_excel_ods» не удалось определить путь к файлу книги результата.\nСохраните книгу на диск и повторите запуск.'
    if not os.path.isfile(path):
        return u'Режим «xml_excel_ods»: файл книги результата не найден на диске:\n%s\n\nСохраните книгу и повторите запуск.' % path
    ext = os.path.splitext(path)[1].lower()
    if ext not in ('.ods', '.xlsx', '.xlsm'):
        return u'Режим «xml_excel_ods»: книга результата должна быть сохранена как .ods или .xlsx.\nТекущий файл: %s' % path
    return None

def _merge_normalize_path_for_compare(path):
    """Абсолютный путь для сравнения (normcase на Windows)."""
    try:
        p = os.path.normpath(os.path.abspath(str(path or '').strip()))
        if p == '':
            return ''
        if hasattr(os.path, 'normcase'):
            p = os.path.normcase(p)
        return p
    except Exception:
        return str(path or '').strip()

def _merge_paths_same(path_a, path_b):
    """True, если пути указывают на один файл."""
    a = _merge_normalize_path_for_compare(path_a)
    b = _merge_normalize_path_for_compare(path_b)
    if a == '' or b == '':
        return False
    if a == b:
        return True
    try:
        return os.path.samefile(path_a, path_b)
    except Exception:
        return False

def _merge_iter_open_calc_documents():
    """Все открытые книги Calc (XSpreadsheetDocument)."""
    try:
        parts = XSCRIPTCONTEXT.getDesktop().getComponents().createEnumeration()
    except Exception:
        return
    while parts.hasMoreElements():
        part = parts.nextElement()
        try:
            if part is not None and hasattr(part, 'Sheets'):
                yield part
        except Exception:
            pass

def _merge_doc_has_unsaved_changes(doc):
    """True — документ изменён и не сохранён на диск."""
    if doc is None:
        return False
    if _merge_doc_is_unsaved(doc):
        return True
    try:
        if getattr(doc, 'isModified', None) is not None:
            return bool(doc.isModified())
    except Exception:
        pass
    return False

def _merge_find_open_doc_for_path(path):
    """Открытый документ Calc с тем же файлом на диске, или None."""
    target = str(path or '').strip()
    if target == '' or not os.path.isfile(target):
        return None
    for doc in _merge_iter_open_calc_documents():
        doc_path = _merge_open_doc_system_path(doc)
        if doc_path == '':
            continue
        if _merge_paths_same(target, doc_path):
            return doc
    return None

def _merge_open_doc_system_path(doc):
    """Абсолютный путь открытого документа или ""."""
    return _merge_doc_system_path(doc)

def _merge_check_open_sources_unsaved(files, is_current_book_flags):
    """
    Перед переносом: файлы-источники (кроме «эта_книга») не должны быть открыты
    с несохранёнными изменениями.

    Возвращает текст ошибки или None.
    """
    problems = []
    seen_norm = set()
    fi = 0
    while fi < len(files):
        is_curr = is_current_book_flags[fi] if fi < len(is_current_book_flags) else False
        if is_curr:
            fi += 1
            continue
        fpath = str(files[fi] or '').strip()
        fi += 1
        if fpath == '' or not os.path.isfile(fpath):
            continue
        norm = _merge_normalize_path_for_compare(fpath)
        if norm in seen_norm:
            continue
        seen_norm.add(norm)
        open_doc = _merge_find_open_doc_for_path(fpath)
        if open_doc is None:
            continue
        if not _merge_doc_has_unsaved_changes(open_doc):
            continue
        label = fpath
        try:
            title = str(getattr(open_doc, 'Title', '') or '').strip()
        except Exception:
            title = ''
        if title != '' and merge_identity_key(title) != merge_identity_key(short_name(fpath)):
            label = '%s — «%s»' % (fpath, title)
        problems.append(label)
    if not problems:
        return None
    lines = ['Перед переносом данных сохраните открытые файлы-источники с несохранёнными изменениями:']
    pi = 0
    while pi < len(problems):
        lines.append('  • %s' % problems[pi])
        pi += 1
    lines.append('')
    lines.append('Закройте файл или выполните «Файл → Сохранить», затем запустите сбор снова.')
    return '\n'.join(lines)

def _merge_is_windows_os():
    """True, если макрос выполняется в Windows (нативный Calc)."""
    return os.name == 'nt' or str(sys.platform).lower().startswith('win')

def _merge_is_remote_url_path(path):
    """True для smb://, http://, …; file:// — False (нормализуется в локальный путь)."""
    try:
        from libre_macros_bundle_paths import is_remote_url

        return bool(is_remote_url(path))
    except Exception:
        p = str(path or '').strip()
        if p == '' or p.lower().startswith('file://'):
            return False
        return '://' in p

def _merge_normalize_source_path_input(path):
    """file:// → /…; smb:// и пр. без изменений."""
    try:
        from libre_macros_bundle_paths import normalize_source_path

        return str(normalize_source_path(path))
    except Exception:
        p = str(path or '').strip()
        if p.lower().startswith('file://'):
            try:
                return os.path.normpath(uno.fileUrlToSystemPath(p))
            except Exception:
                rest = p[7:]
                if rest.startswith('//'):
                    rest = rest[1:]
                return os.path.normpath(rest)
        return p

def _merge_path_notation_kind(path):
    """
    Класс нотации пути: marker, windows, unix, relative.

    unix — абсолютный путь в стиле /home/... (на Windows os.path.isabs часто False).
    """
    p = str(path).strip()
    if is_current_book_marker(p):
        return 'marker'
    if re.match('^[A-Za-z]:[/\\\\]', p) or p.startswith('\\\\'):
        return 'windows'
    if p.startswith('/'):
        return 'unix'
    return 'relative'

def _merge_wsl_unc_from_unix_path(unix_path):
    """
    /home/user/... → \\\\wsl.localhost\\<distro>\\home\\user\\... (Windows + WSL).

    Имя дистрибутива: WSL_DISTRO_NAME или Ubuntu по умолчанию.
    """
    p = str(unix_path).strip()
    if not p.startswith('/'):
        return p
    body = p.replace('/', '\\')
    distro = os.environ.get('WSL_DISTRO_NAME', '').strip()
    if distro == '':
        distro = 'Ubuntu'
    return '\\\\wsl.localhost\\%s%s' % (distro, body)

def _merge_transform_path_for_current_os(path):
    """
    Преобразовать путь из «чужой» ОС-нотации в нативную для текущей системы.

    Возвращает (new_path, changed).
    """
    p = str(path).strip()
    if p == '' or is_current_book_marker(p):
        return (p, False)
    p = _merge_normalize_source_path_input(p)
    kind = _merge_path_notation_kind(p)
    on_windows = _merge_is_windows_os()
    if on_windows and kind == 'unix':
        m = re.match('^/mnt/([a-zA-Z])(?:/(.*))?$', p)
        if m:
            drive = m.group(1).upper()
            rest = (m.group(2) or '').replace('/', '\\')
            new_p = '%s:\\%s' % (drive, rest)
            return (os.path.normpath(new_p), True)
        m = re.match('^/cygdrive/([a-zA-Z])/(.*)$', p)
        if m:
            drive = m.group(1).upper()
            rest = m.group(2).replace('/', '\\')
            new_p = '%s:\\%s' % (drive, rest)
            return (os.path.normpath(new_p), True)
        if p.startswith('//wsl') or p.lower().startswith('\\\\wsl'):
            new_p = p.replace('/', '\\')
            return (os.path.normpath(new_p), True)
        new_p = _merge_wsl_unc_from_unix_path(p)
        return (os.path.normpath(new_p), True)
    if not on_windows and kind == 'windows':
        p_slash = p.replace('\\', '/')
        m = re.match('^([A-Za-z]):/Users/([^/]+)/(.*)$', p_slash)
        if m:
            user = m.group(2)
            rest = m.group(3)
            new_p = os.path.normpath('/home/%s/%s' % (user, rest))
            return (new_p, True)
        m = re.match('^([A-Za-z]):/(.*)$', p_slash)
        if m:
            drive = m.group(1).lower()
            rest = m.group(2)
            new_p = '/mnt/%s/%s' % (drive, rest)
            return (os.path.normpath(new_p), True)
    if kind == 'relative':
        new_p = os.path.normpath(p)
        return (new_p, new_p != p)
    if kind == 'windows' and on_windows:
        new_p = os.path.normpath(p)
        return (new_p, new_p != p)
    if kind == 'unix' and (not on_windows):
        new_p = os.path.normpath(p)
        return (new_p, new_p != p)
    return (p, False)

def _merge_param_row_index(sheet, param_name):
    """Номер строки (0-based) параметра на листе или -1."""
    if sheet is None:
        return -1
    row = 1
    while row < _cw_cfg.MERGE_PARAM_SHEET_MAX_ROWS:
        name = cell_text(sheet.getCellByPosition(0, row))
        if row == 1 and param_name_match(name, 'Параметр'):
            row = row + 1
            continue
        if name == '':
            break
        if param_name_match(name, param_name):
            return row
        row = row + 1
    return -1

def _merge_fixup_source_paths_in_param_sheet(doc):
    """
    Кросс-ОС: переписать ячейки «Файлы-Источники» и остановить сбор для проверки.

    Возвращает (stop_run, message): stop_run=True — не продолжать этап 1/2.
    """
    sheet = _get_param_sheet(doc)
    if sheet is None:
        return (False, None)
    row = _merge_param_row_index(sheet, _cw_cfg.P_MERGE_FILES)
    if row < 0:
        return (False, None)
    changes = []
    doc_path = _merge_doc_system_path(doc)
    col = 1
    while col < 50:
        original = cell_text(sheet.getCellByPosition(col, row))
        if original == '':
            break
        if is_current_book_marker(original):
            col = col + 1
            continue
        if _merge_is_remote_url_path(original):
            col = col + 1
            continue
        # Не трогать пути с плейсхолдерами карты — подстановка позже в parse.
        if _merge_path_has_variable_placeholder(original):
            col = col + 1
            continue
        if str(original or '').strip().lower().startswith('file://'):
            new_local = _merge_normalize_source_path_input(original)
            if new_local != original:
                sheet.getCellByPosition(col, row).String = new_local
                changes.append((col_label(col), original, new_local))
            col = col + 1
            continue
        if source_path_refers_to_current_book(original, doc_path):
            if original != _cw_cfg.MERGE_CURRENT_BOOK_MARKER:
                sheet.getCellByPosition(col, row).String = _cw_cfg.MERGE_CURRENT_BOOK_MARKER
                changes.append((col_label(col), original, _cw_cfg.MERGE_CURRENT_BOOK_MARKER))
            col = col + 1
            continue
        new_path, changed = _merge_transform_path_for_current_os(original)
        if changed and new_path != original:
            sheet.getCellByPosition(col, row).String = new_path
            changes.append((col_label(col), original, new_path))
        col = col + 1
    if len(changes) == 0:
        return (False, None)
    lines = []
    ci = 0
    while ci < len(changes):
        letter, old, new = changes[ci]
        lines.append('  %s: %s' % (letter, old))
        lines.append('    → %s' % new)
        ci = ci + 1
    msg = 'Пути источников скорректированы (текущая книга / ОС).\nПроверьте корректность в параметрах и запустите макрос снова для сбора данных.\n\n' + '\n'.join(lines)
    return (True, msg)

def _merge_same_file_path(path_a, path_b):
    """True, если оба пути указывают на один и тот же файл."""
    if path_a is None or path_b is None:
        return False
    a = str(path_a).strip()
    b = str(path_b).strip()
    if a == '' or b == '':
        return False
    try:
        na = os.path.normcase(os.path.normpath(os.path.abspath(a)))
        nb = os.path.normcase(os.path.normpath(os.path.abspath(b)))
        if na == nb:
            return True
        return os.path.normcase(os.path.realpath(a)) == os.path.normcase(os.path.realpath(b))
    except Exception:
        return False

def source_path_refers_to_current_book(path, current_book_path=None):
    """
    True, если путь источника — маркер или тот же файл, что книга параметров.
    """
    if is_current_book_marker(path):
        return True
    if current_book_path is None or str(current_book_path).strip() == '':
        current_book_path = get_current_book_path()
    if not current_book_path:
        return False
    resolved, is_marker = resolve_source_path(path, current_book_path)
    if is_marker:
        return True
    return _merge_same_file_path(resolved, current_book_path)

def normalize_source_path_cell_value(path, current_book_path=None):
    """
    Значение для ячейки «Файлы-Источники»: «Эта_книга», если путь — текущая книга.
    """
    p = str(path).strip()
    if p == '':
        return p
    if is_current_book_marker(p):
        return _cw_cfg.MERGE_CURRENT_BOOK_MARKER
    p = _merge_normalize_source_path_input(p)
    if _merge_is_remote_url_path(p):
        return p
    if source_path_refers_to_current_book(p, current_book_path):
        return _cw_cfg.MERGE_CURRENT_BOOK_MARKER
    new_p, _changed = _merge_transform_path_for_current_os(p)
    return new_p

def merge_current_book_source_sheet_names(doc, per_file_sheet_specs, is_current_book_flags, filter_fn=_cw_cfg._MERGE_FILTER_FN_UNSET):
    """
    Имена листов текущей книги, которые будут источниками при «Эта_книга».

    Для этапа 1: не предлагать их к удалению вместе со служебными листами.
    """
    names = []
    seen = set()
    if doc is None or not is_current_book_flags:
        return names
    filter_fn = _merge_resolve_sheets_include_filter_fn(filter_fn)
    has_current = False
    fi = 0
    while fi < len(is_current_book_flags):
        if is_current_book_flags[fi]:
            has_current = True
            break
        fi = fi + 1
    if not has_current:
        return names
    doc_sheet_names = sheet_names(doc)
    fi = 0
    while fi < len(is_current_book_flags):
        if not (fi < len(is_current_book_flags) and is_current_book_flags[fi]):
            fi = fi + 1
            continue
        specs = per_file_sheet_specs[fi] if fi < len(per_file_sheet_specs) else ['Все']
        kind = classify_sheet_specs(specs)
        if kind == 'MIXED':
            fi = fi + 1
            continue
        if kind == 'ALL':
            for n in doc_sheet_names:
                if _is_service_sheet(n):
                    continue
                if not _merge_sheet_slot_include_filter_passes(n, filter_fn):
                    continue
                key = merge_identity_key(n)
                if key not in seen:
                    seen.add(key)
                    names.append(n)
        elif kind == 'INDEX':
            for spec in specs:
                try:
                    idx = int(str(spec).strip()) - 1
                except Exception:
                    continue
                if idx >= 0 and idx < doc.Sheets.getCount():
                    n = doc.Sheets.getByIndex(idx).Name
                    if _is_service_sheet(n):
                        continue
                    if not _merge_sheet_slot_include_filter_passes(n, filter_fn):
                        continue
                    key = merge_identity_key(n)
                    if key not in seen:
                        seen.add(key)
                        names.append(n)
        else:
            for n in doc_sheet_names:
                if _is_service_sheet(n):
                    continue
                matched = False
                for spec in specs:
                    if text_match(n, spec):
                        matched = True
                        break
                if matched:
                    if not _merge_sheet_slot_include_filter_passes(n, filter_fn):
                        continue
                    key = merge_identity_key(n)
                    if key not in seen:
                        seen.add(key)
                        names.append(n)
        fi = fi + 1
    return names

def resolve_source_path(path, current_book_path=None):
    """
    Преобразует путь источника в абсолютный.

    Обрабатывает:
        - Абсолютные пути (как есть)
        - Относительные пути (относительно каталога текущей книги)
        - Маркер текущей книги ("эта_книга" и т.п.)
        - Кросс-ОС нотацию (/mnt/c/…, C:\\…, WSL UNC)
        - Нормализацию разделителей Windows/Linux

    Параметры:
        path — строка из «Файлы-Источники».
        current_book_path — путь к текущей книге (кэш, опционально).

    Возвращает:
        tuple (resolved_path, is_current_book):
            resolved_path — абсолютный путь или оригинальный маркер.
            is_current_book — True, если это маркер текущей книги.
    """
    p = str(path).strip()
    if is_current_book_marker(p):
        return (p, True)
    p = _merge_normalize_source_path_input(p)
    if _merge_is_remote_url_path(p):
        return (p, False)
    p, _changed = _merge_transform_path_for_current_os(p)
    if os.path.isabs(p):
        return (os.path.normpath(p), False)
    if _merge_path_notation_kind(p) == 'unix' and _merge_is_windows_os():
        return (os.path.normpath(p), False)
    if current_book_path is None:
        current_book_path = get_current_book_path()
    if current_book_path:
        base_dir = os.path.dirname(current_book_path)
        if base_dir:
            full_path = os.path.normpath(os.path.join(base_dir, p))
            return (full_path, False)
    return (p, False)

def expand_source_files(raw_paths, current_book_path=None, per_col_source_extra=None):
    """
    Разворот параметра «Файлы-Источники»: маски glob → список файлов.

    Назначение:
        Каждая ячейка B,C,D… может быть одним путём, маской (*.xlsx)
        или маркером текущей книги ("эта_книга").
        Маска заменяется отсортированным списком существующих файлов;
        дубликаты путей не удаляются (повтор ячейки = повторный сбор).
        Относительные пути разрешаются относительно каталога текущей книги.
        per_col_source_extra[i] — dict Доп_Параметры_Источника столбца i
        (маски exclude складываются с MERGE_SOURCE_EXCLUDE_MASK листа и
        применяются и к glob, и к явно указанным путям).

    Параметры:
        raw_paths — list значений из read_param_table(P_MERGE_FILES).

    Возвращает:
        tuple (files, param_col_for_file, empty_glob_patterns, is_current_book_flags):
          files — абсолютные пути или маркеры ("эта_книга");
          param_col_for_file[i] — индекс исходной ячейки (0=B, 1=C…) для файла i;
          empty_glob_patterns — маски без совпадений (ошибка в parse_collect_settings);
          is_current_book_flags[i] — True, если files[i] — маркер текущей книги.

    Связь:
        parse_collect_settings → build_per_file_* через param_col_for_file.
    """
    files = []
    param_col_for_file = []
    empty_globs = []
    is_current_book_flags = []
    try:
        _cw_cfg._MERGE_SOURCE_ROOTS_EXPAND_ERRORS = []
    except Exception:
        pass
    if current_book_path is None or str(current_book_path).strip() == '':
        current_book_path = get_current_book_path()
    extras = per_col_source_extra if isinstance(per_col_source_extra, (list, tuple)) else None
    variables_map = getattr(_cw_cfg, '_MERGE_SOURCE_VARIABLES_MAP', None) or {}
    i = 0
    while i < len(raw_paths):
        pattern = str(raw_paths[i]).strip()
        if pattern == '':
            i = i + 1
            continue
        resolved_path, is_current_book = resolve_source_path(pattern, current_book_path)
        if not is_current_book and current_book_path and _merge_same_file_path(resolved_path, current_book_path):
            resolved_path = _cw_cfg.MERGE_CURRENT_BOOK_MARKER
            is_current_book = True
        if is_current_book:
            files.append(resolved_path)
            param_col_for_file.append(i)
            is_current_book_flags.append(True)
            i = i + 1
            continue
        col_extra = None
        if extras is not None and i < len(extras):
            col_extra = extras[i]
        if path_looks_like_glob(resolved_path):
            try:
                from libre_macros_source_roots_lib import guard_glob_or_path

                ok_roots, err_roots = guard_glob_or_path(
                    resolved_path,
                    True,
                    book_path=current_book_path,
                    variables_map=variables_map,
                )
            except Exception as err:
                ok_roots, err_roots = True, u''
                merge_debug('source_roots', 'guard glob skip: %s' % err)
            if not ok_roots:
                try:
                    _cw_cfg._MERGE_SOURCE_ROOTS_EXPAND_ERRORS.append(err_roots or resolved_path)
                except Exception:
                    pass
                i = i + 1
                continue
            matched = _merge_expand_glob_files(resolved_path, source_extra=col_extra)
            found = 0
            j = 0
            while j < len(matched):
                p = matched[j]
                if os.path.isfile(p):
                    abs_p = os.path.abspath(p)
                    try:
                        from libre_macros_source_roots_lib import guard_glob_or_path as _guard_file

                        ok_f, err_f = _guard_file(
                            abs_p, False, book_path=current_book_path, variables_map=variables_map,
                        )
                    except Exception:
                        ok_f, err_f = True, u''
                    if not ok_f:
                        try:
                            _cw_cfg._MERGE_SOURCE_ROOTS_EXPAND_ERRORS.append(err_f or abs_p)
                        except Exception:
                            pass
                        j = j + 1
                        continue
                    files.append(abs_p)
                    param_col_for_file.append(i)
                    is_current_book_flags.append(False)
                    found = found + 1
                j = j + 1
            if found == 0:
                empty_globs.append(resolved_path)
        else:
            # Явный путь тоже фильтруем exclude_mask / MERGE_SOURCE_EXCLUDE_MASK
            # (раньше маски работали только при развороте glob).
            if not _merge_is_remote_url_path(resolved_path):
                try:
                    from libre_macros_source_roots_lib import guard_glob_or_path

                    ok_roots, err_roots = guard_glob_or_path(
                        resolved_path,
                        False,
                        book_path=current_book_path,
                        variables_map=variables_map,
                    )
                except Exception as err:
                    ok_roots, err_roots = True, u''
                    merge_debug('source_roots', 'guard path skip: %s' % err)
                if not ok_roots:
                    try:
                        _cw_cfg._MERGE_SOURCE_ROOTS_EXPAND_ERRORS.append(err_roots or resolved_path)
                    except Exception:
                        pass
                    i = i + 1
                    continue
                excl = _merge_source_exclude_masks(source_extra=col_extra)
                base = os.path.basename(resolved_path)
                if _merge_source_basename_excluded(base, excl):
                    merge_debug(
                        'expand_source',
                        'excluded explicit file=%s masks=%s'
                        % (
                            base,
                            u','.join(unicode(m) for m in (excl or []))[:120],
                        ),
                    )
                    i = i + 1
                    continue
                try:
                    from libre_macros_source_extra_lib import apply_source_extra_file_pick

                    picked = apply_source_extra_file_pick(
                        [os.path.abspath(resolved_path)],
                        col_extra,
                        log_fn=lambda m: merge_debug('file_pick', m),
                    )
                    if not picked:
                        merge_debug(
                            'expand_source',
                            'file_pick excluded explicit file=%s' % base,
                        )
                        i = i + 1
                        continue
                    resolved_path = picked[0]
                except Exception as err:
                    merge_debug('expand_source', 'file_pick skip: %s' % err)
            else:
                try:
                    from libre_macros_source_roots_lib import guard_glob_or_path

                    ok_roots, err_roots = guard_glob_or_path(
                        resolved_path,
                        False,
                        book_path=current_book_path,
                        variables_map=variables_map,
                    )
                except Exception as err:
                    ok_roots, err_roots = True, u''
                    merge_debug('source_roots', 'guard remote skip: %s' % err)
                if not ok_roots:
                    try:
                        _cw_cfg._MERGE_SOURCE_ROOTS_EXPAND_ERRORS.append(err_roots or resolved_path)
                    except Exception:
                        pass
                    i = i + 1
                    continue
            if _merge_is_remote_url_path(resolved_path):
                files.append(resolved_path)
            else:
                files.append(os.path.abspath(resolved_path))
            param_col_for_file.append(i)
            is_current_book_flags.append(False)
        i = i + 1
    return (files, param_col_for_file, empty_globs, is_current_book_flags)

def pad_param_cols(raw_vals, n_cols):
    """
    Дополнение списка значений параметра пустыми строками до n_cols.

    Параметры:
        raw_vals — значения из B,C,D… одной строки таблицы параметров.
        n_cols — число ячеек «Файлы-Источники» (до разворота масок).

    Возвращает:
        list[str] — длина n_cols; недостающие — "".

    Связь:
        resolve_param_per_expanded_files, resolve_per_file_strings.
    """
    vals = []
    i = 0
    while i < n_cols:
        if i < len(raw_vals):
            vals.append(str(raw_vals[i]).strip())
        else:
            vals.append('')
        i = i + 1
    return vals

def resolve_param_per_expanded_files(raw_vals, param_col_for_file, n_source_cols, default_str):
    """
    Значение параметра для каждого развёрнутого файла после expand_source_files.

    Назначение:
        Сначала resolve_per_file_strings по ячейкам B,C,D… (логика «одно на всех /
        индивидуально»), затем для файла i берётся столбец param_col_for_file[i]
        (файлы из одной маски наследуют настройки той ячейки).

    Параметры:
        raw_vals — список из list_value(table, ключ).
        param_col_for_file — из expand_source_files.
        n_source_cols — len(raw_files) до разворота.
        default_str — подстановка для пустых ячеек.

    Возвращает:
        list[str] — длина len(param_col_for_file).

    Связь:
        build_per_file_sheet_specs, build_per_file_col_specs, build_per_file_block_settings.
    """
    col_vals = resolve_per_file_strings(pad_param_cols(raw_vals, n_source_cols), n_source_cols, default_str)
    result = []
    fi = 0
    while fi < len(param_col_for_file):
        col = param_col_for_file[fi]
        if col < len(col_vals):
            result.append(col_vals[col])
        else:
            result.append(default_str)
        fi = fi + 1
    return result

def col_label(col_index):
    """
    Буквенное обозначение столбца Calc для сообщений и лога.

    Параметры:
        col_index — 0-based индекс (0 → A, 25 → Z, 26 → AA).

    Возвращает:
        str — буквы столбца Excel/Calc.

    Связь:
        header_at («Колонка_%s»), report.status, append_collect_log.
    """
    n = col_index + 1
    letters = ''
    while n > 0:
        n, rem = divmod(n - 1, 26)
        letters = chr(65 + rem) + letters
    return letters

def message_parent_window(doc=None):
    """
    Окно-родитель для AWT MessageBox / QueryBox.

    Параметры:
        doc — книга результата; если None — getDocument() или текущий frame Desktop.

    Возвращает:
        XWindow или None.

    Связь:
        _message_box_execute, show_message, ask_yes_no.
    """
    if doc is None:
        try:
            doc = XSCRIPTCONTEXT.getDocument()
        except Exception:
            doc = None
    if doc is not None:
        try:
            return doc.getCurrentController().getFrame().getContainerWindow()
        except Exception:
            pass
    try:
        return XSCRIPTCONTEXT.getDesktop().getCurrentFrame().getContainerWindow()
    except Exception:
        return None

def get_awt_toolkit():
    """
    Получение com.sun.star.awt.Toolkit для создания диалогов.

    Возвращает:
        Toolkit или None — Desktop.getToolkit() или createInstanceWithContext.

    Связь:
        _message_box_execute; merge_ui_yield.
    """
    try:
        return XSCRIPTCONTEXT.getDesktop().getToolkit()
    except Exception:
        pass
    try:
        ctx = XSCRIPTCONTEXT.getComponentContext()
        return ctx.ServiceManager.createInstanceWithContext('com.sun.star.awt.Toolkit', ctx)
    except Exception:
        return None

def merge_ui_abort_reset():
    """Сброс флага «Прервать» перед новым запуском."""
    _cw_cfg._merge_ui_abort_requested = False
    _cw_cfg._merge_ui_phase = ''
    _cw_cfg._merge_ui_phase_detail = ''
    _cw_cfg._merge_ui_file_index = 0
    _cw_cfg._merge_ui_file_total = 0
    _cw_cfg._merge_ui_fname = ''
    _cw_cfg._merge_ui_sheet_name = ''
    merge_ui_log_reset()

def merge_ui_log_reset():
    """Очистить накопительный журнал строк диалога прогресса."""
    _cw_cfg._merge_ui_log_lines = []

def merge_ui_log_text():
    """Текст журнала диалога (все строки с начала запуска)."""
    return '\n'.join(_cw_cfg._merge_ui_log_lines)

def merge_ui_log_refresh():
    """Перерисовать поле журнала в диалоге и прокрутить к последней строке."""
    if not _merge_ui_is_dialog_mode():
        return
    _merge_ui_dialog_set_log(merge_ui_log_text())

def merge_ui_log_append(line, replace_prefix=None):
    """
    Добавить строку в накопительный журнал диалога (этапы, события).

    Частые обновления счётчиков (50/1500…) — в merge_ui_detail_set, не сюда.
    """
    if not _merge_ui_is_dialog_mode():
        return
    s = str(line or '').rstrip()
    if s == '':
        return
    _cw_cfg._merge_ui_log_lines.append(s)
    if len(_cw_cfg._merge_ui_log_lines) > _cw_cfg._MERGE_UI_LOG_MAX_LINES:
        _cw_cfg._merge_ui_log_lines = _cw_cfg._merge_ui_log_lines[-_cw_cfg._MERGE_UI_LOG_MAX_LINES:]
    merge_ui_log_refresh()

def merge_ui_detail_set(text):
    """Перезаписать поле текущего прогресса (счётчики, строка N/M)."""
    if not _merge_ui_is_dialog_mode():
        return
    s = str(text or '')
    try:
        if _cw_cfg._merge_ui_progress_detail_label is not None:
            try:
                _cw_cfg._merge_ui_progress_detail_label.setText(s)
            except Exception:
                try:
                    _cw_cfg._merge_ui_progress_detail_label.setLabel(s)
                except Exception:
                    pass
    except Exception:
        pass
    merge_ui_yield(force=True)
    _merge_ui_dialog_pulse()

def _merge_ui_dialog_scroll_log_to_end():
    """Прокрутить журнал событий к последней строке."""
    try:
        ctl = _cw_cfg._merge_ui_progress_label
        if ctl is None:
            return
        text = ''
        try:
            text = ctl.getText()
        except Exception:
            try:
                text = ctl.Model.Text
            except Exception:
                pass
        n = len(str(text))
        if n > 0:
            sel = uno.createUnoStruct('com.sun.star.awt.Selection')
            sel.Min = n
            sel.Max = n
            ctl.setSelection(sel)
    except Exception:
        pass
    try:
        sb = _cw_cfg._merge_ui_progress_label.getVerticalScrollBar()
        if sb is not None:
            sb.setValue(sb.getMaximum())
    except Exception:
        pass

def _merge_ui_dialog_set_log(text):
    """Обновить накопительный журнал в диалоге."""
    try:
        if _cw_cfg._merge_ui_progress_label is not None:
            try:
                _cw_cfg._merge_ui_progress_label.setText(str(text))
            except Exception:
                try:
                    _cw_cfg._merge_ui_progress_label.setLabel(str(text))
                except Exception:
                    pass
            _merge_ui_dialog_scroll_log_to_end()
    except Exception:
        pass
    if _merge_ui_is_dialog_mode():
        _merge_ui_dialog_pulse()

def merge_ui_bind_settings(settings):
    """Запомнить settings для режима UI (диалог / строка состояния)."""
    _cw_cfg._merge_ui_active_settings = settings

def merge_ui_bind_report(report):
    """Запомнить ProgressReport для шкалы прогресса в диалоге."""
    _cw_cfg._merge_ui_active_report = report

def merge_ui_sync_progress(report=None, file_frac=0.0, extra_frac=0.0):
    """
    Обновить полосу прогресса (0…_merge_ui_progress_scale) по шагам report.

    file_frac — доля текущего файла (0…1); extra_frac — доп. сдвиг внутри шага.
    """
    if not _merge_ui_is_dialog_mode():
        return
    r = report if report is not None else _cw_cfg._merge_ui_active_report
    if r is None:
        return
    try:
        ff = float(file_frac)
    except Exception:
        ff = 0.0
    if ff < 0.0:
        ff = 0.0
    if ff > 1.0:
        ff = 1.0
    try:
        ef = float(extra_frac)
    except Exception:
        ef = 0.0
    step_idx = int(r.current_step) - 1 + ff + ef
    if step_idx < 0:
        step_idx = 0
    total = int(r.total_steps)
    if total < 1:
        total = 1
    val = int(round(step_idx / float(total) * _cw_cfg._merge_ui_progress_scale))
    if val < 0:
        val = 0
    if val > _cw_cfg._merge_ui_progress_scale:
        val = _cw_cfg._merge_ui_progress_scale
    _merge_ui_dialog_set(val, None)

def _merge_ui_is_dialog_mode(settings=None):
    if _cw_cfg._merge_ui_progress_dialog is not None:
        return True
    return _merge_progress_ui_mode(settings or _cw_cfg._merge_ui_active_settings) == _cw_cfg.MERGE_PROGRESS_UI_DIALOG

def _merge_ui_yield_every():
    if _merge_ui_is_dialog_mode():
        return _cw_cfg._MERGE_UI_DIALOG_YIELD_EVERY_ROWS
    return _cw_cfg.MERGE_UI_YIELD_EVERY_ROWS

def _merge_ui_status_every():
    if _merge_ui_is_dialog_mode():
        return _cw_cfg._MERGE_UI_DIALOG_STATUS_EVERY_ROWS
    return _cw_cfg.MERGE_UI_STATUS_EVERY_ROWS

def merge_ui_set_sheet(sheet_name):
    _cw_cfg._merge_ui_sheet_name = str(sheet_name or '')

def merge_ui_set_phase(phase, detail='', journal=True):
    """
    Текущий этап для диалога / строки состояния.

    journal=False — только перезаписываемое поле прогресса (постобработка, счётчики).
    """
    _cw_cfg._merge_ui_phase = str(phase or '')
    _cw_cfg._merge_ui_phase_detail = str(detail or '')
    if _merge_ui_is_dialog_mode():
        if journal:
            merge_ui_log_append('— %s —' % _cw_cfg._merge_ui_phase)
            if _cw_cfg._merge_ui_phase_detail != '':
                merge_ui_log_append('  %s' % _cw_cfg._merge_ui_phase_detail)
        if _cw_cfg._merge_ui_phase_detail != '':
            merge_ui_detail_set(_cw_cfg._merge_ui_phase_detail)
        else:
            merge_ui_detail_set(_cw_cfg._merge_ui_phase)
        merge_ui_sync_progress()
        _merge_ui_dialog_pulse()
    else:
        merge_ui_status_set(None, _merge_ui_build_status_text())
    merge_debug('merge_ui_set_phase', '%s%s' % (_cw_cfg._merge_ui_phase, ' / ' + _cw_cfg._merge_ui_phase_detail if _cw_cfg._merge_ui_phase_detail else ''))

def _merge_ui_build_status_text(fname=None, sheet_name=None, source_row_1based=None, rows_copied=None, extra_line=''):
    lines = []
    phase = _cw_cfg._merge_ui_phase if _cw_cfg._merge_ui_phase != '' else 'Сбор данных'
    lines.append('Этап: %s' % phase)
    if _cw_cfg._merge_ui_phase_detail != '':
        lines.append(_cw_cfg._merge_ui_phase_detail)
    fi = _cw_cfg._merge_ui_file_index
    ft = _cw_cfg._merge_ui_file_total
    fn = _cw_cfg._merge_ui_fname if fname is None else fname
    if ft > 0:
        lines.append('Файл %d/%d: %s' % (int(fi), int(ft), fn))
    elif fn not in (None, ''):
        lines.append('Файл: %s' % fn)
    sn = _cw_cfg._merge_ui_sheet_name if sheet_name is None else sheet_name
    if sn is not None and str(sn).strip() != '':
        lines.append('Лист: «%s»' % sn)
    if source_row_1based is not None:
        lines.append('Строка источника: %d' % int(source_row_1based))
    if rows_copied is not None:
        lines.append('Скопировано строк: %d' % int(rows_copied))
    if extra_line not in (None, ''):
        lines.append(str(extra_line))
    return '\n'.join(lines)

def _merge_ui_dialog_pulse():
    """Отдать события UI и перерисовать диалог прогресса."""
    if _cw_cfg._merge_ui_progress_dialog is None:
        return
    ms = int(_cw_cfg._MERGE_UI_DIALOG_EVENT_MS)
    try:
        toolkit = get_awt_toolkit()
        if toolkit is not None:
            if hasattr(toolkit, 'processEventsToIdle'):
                toolkit.processEventsToIdle(ms)
            elif hasattr(toolkit, 'processEventsToIdleWithMode'):
                toolkit.processEventsToIdleWithMode(ms, 0)
    except Exception:
        pass
    try:
        peer = _cw_cfg._merge_ui_progress_dialog.getPeer()
        if peer is not None:
            peer.setVisible(True)
    except Exception:
        pass

def merge_ui_abort_requested():
    """True, если пользователь нажал «Прервать» в диалоге прогресса."""
    return bool(_cw_cfg._merge_ui_abort_requested)

def merge_ui_abort_raise():
    """Запросить прерывание сбора (кнопка «Прервать»)."""
    _cw_cfg._merge_ui_abort_requested = True

def merge_ui_poll_abort():
    """Отдать события UI и вернуть True, если запрошено прерывание."""
    merge_ui_yield(force=True)
    return merge_ui_abort_requested()

def _merge_stop_if_aborted(report):
    """Если нажато «Прервать» — записать в report и вернуть True."""
    if not merge_ui_abort_requested():
        return False
    if report is not None:
        report.problem('Прервано пользователем.')
    return True

def _merge_ui_dialog_parent():
    if _cw_cfg._merge_ui_anchor_doc is not None:
        try:
            return _cw_cfg._merge_ui_anchor_doc.getCurrentController().getFrame().getContainerWindow()
        except Exception:
            pass
    try:
        frame = XSCRIPTCONTEXT.getDesktop().getCurrentFrame()
        if frame is not None:
            return frame.getContainerWindow()
    except Exception:
        pass
    return None

def _merge_document_frame(doc):
    """XFrame книги или None."""
    if doc is None:
        return None
    try:
        ctrl = doc.getCurrentController()
        if ctrl is not None:
            return ctrl.getFrame()
    except Exception:
        pass
    return None

def _merge_find_frame_by_name(name):
    """Найти frame по имени среди открытых окон Desktop."""
    nm = str(name or '').strip()
    if nm == '':
        return None
    try:
        desktop = XSCRIPTCONTEXT.getDesktop()
        frames = desktop.getFrames()
        if frames is None or not hasattr(frames, 'createEnumeration'):
            return None
        enum = frames.createEnumeration()
        while enum.hasMoreElements():
            fr = enum.nextElement()
            try:
                if fr.getName() == nm:
                    return fr
            except Exception:
                pass
    except Exception:
        pass
    return None

def _merge_activate_frame(frame):
    """Активировать frame и вывести его окно на передний план."""
    if frame is None:
        return False
    ok = False
    try:
        frame.activate()
        ok = True
    except Exception:
        pass
    try:
        win = frame.getContainerWindow()
        if win is not None:
            try:
                win.setVisible(True)
            except Exception:
                pass
            if hasattr(win, 'toFront'):
                try:
                    win.toFront()
                    ok = True
                except Exception:
                    pass
    except Exception:
        pass
    return ok

def _merge_keep_document_hidden(doc):
    """
    Усилить Hidden после loadComponentFromURL(Hidden=True).

    Не вызывать setVisible(True)/toFront — иначе книга мелькает во время
    UNO-добивки (freeze, заголовок_плюс_высота). Показ — только в финале
    через _merge_activate_document / _merge_ui_anchor_end.
    """
    if doc is None:
        return False
    try:
        ctrl = doc.getCurrentController()
    except Exception:
        ctrl = None
    if ctrl is None:
        return False
    try:
        frame = ctrl.getFrame()
    except Exception:
        frame = None
    if frame is None:
        try:
            frame = _merge_document_frame(doc)
        except Exception:
            frame = None
    if frame is None:
        return True
    try:
        win = frame.getContainerWindow()
        if win is not None:
            try:
                win.setVisible(False)
            except Exception:
                pass
            for attr, val in (('IsMinimized', True), ('Minimized', True)):
                if hasattr(win, attr):
                    try:
                        setattr(win, attr, val)
                    except Exception:
                        try:
                            win.setPropertyValue(attr, val)
                        except Exception:
                            pass
    except Exception:
        pass
    return True

def _merge_activate_document(doc):
    """Сделать книгу активной в UI LibreOffice."""
    if doc is None:
        return False
    frame = _merge_document_frame(doc)
    if frame is None and doc is _cw_cfg._merge_ui_anchor_doc:
        frame = _cw_cfg._merge_ui_anchor_frame
        if frame is None:
            frame = _merge_find_frame_by_name(_cw_cfg._merge_ui_anchor_frame_name)
    ok = _merge_activate_frame(frame)
    merge_ui_yield(force=True)
    try:
        _merge_flush_xml_freeze_pending(doc)
    except Exception:
        pass
    return ok


def _merge_create_silent_interaction_handler():
    """SilentInteractionHandler AO/LO для подавления системных инфо-окон."""
    try:
        try:
            ctx = XSCRIPTCONTEXT.getComponentContext()
        except NameError:
            ctx = uno.getComponentContext()
        if ctx is None:
            return None
        sm = ctx.ServiceManager
        return sm.createInstanceWithContext(
            'com.sun.star.comp.framework.SilentInteractionHandler', ctx
        )
    except Exception:
        return None


def _merge_collect_ui_target_docs(primary_doc=None):
    """Документы, на чьих frame стоит временно подавить системные диалоги."""
    docs = []
    seen = set()

    def _add(doc):
        if doc is None:
            return
        key = id(doc)
        if key in seen:
            return
        seen.add(key)
        docs.append(doc)

    _add(primary_doc)
    try:
        _add(get_run_target_doc())
    except Exception:
        pass
    try:
        _add(_cw_cfg._merge_ui_anchor_doc)
    except Exception:
        pass
    try:
        desktop = XSCRIPTCONTEXT.getDesktop()
        cur = desktop.getCurrentComponent()
        _add(cur)
    except Exception:
        pass
    return docs


def _merge_run_with_suppressed_office_info(callback, primary_doc=None):
    """Выполнить callback с SilentInteractionHandler на текущих frame."""
    if not callable(callback):
        return None
    handler = _merge_create_silent_interaction_handler()
    if handler is None:
        return callback()
    restores = []
    try:
        for doc in _merge_collect_ui_target_docs(primary_doc):
            frame = _merge_document_frame(doc)
            if frame is None:
                continue
            old_handler = None
            try:
                old_handler = frame.getPropertyValue('InteractionHandler')
            except Exception:
                old_handler = None
            try:
                frame.setPropertyValue('InteractionHandler', handler)
                restores.append((frame, old_handler))
            except Exception:
                pass
        return callback()
    finally:
        for frame, old_handler in restores:
            try:
                frame.setPropertyValue('InteractionHandler', old_handler)
            except Exception:
                pass


def _merge_force_result_interactive(doc):
    """После прогресс-диалога/anchor вернуть фокус и отзывчивость книге результата."""
    if doc is None:
        return False
    try:
        if _cw_cfg._merge_ui_progress_dialog is not None:
            try:
                _cw_cfg._merge_ui_progress_dialog.setVisible(False)
            except Exception:
                pass
            try:
                peer = _cw_cfg._merge_ui_progress_dialog.getPeer()
                if peer is not None:
                    peer.setVisible(False)
            except Exception:
                pass
    except Exception:
        pass
    ok = False
    try:
        ok = _merge_activate_document(doc)
    except Exception:
        ok = False
    merge_ui_yield(force=True)
    try:
        refresh_document(doc)
    except Exception:
        pass
    try:
        ok = _merge_activate_document(doc) or ok
    except Exception:
        pass
    try:
        import libre_macros_split_lib as _split

        if hasattr(_split, '_split_maximize_document'):
            _split._split_maximize_document(doc)
        if hasattr(_split, '_split_flush_maximize_pending'):
            _split._split_flush_maximize_pending()
        try:
            ctrl = doc.getCurrentController()
            frame = ctrl.getFrame() if ctrl is not None else None
            win = frame.getContainerWindow() if frame is not None else None
        except Exception:
            win = None
        if win is not None and hasattr(_split, '_split_window_set_bool'):
            _split._split_window_set_bool(win, ('IsMaximized', 'Maximized'), False)
            merge_ui_yield(force=True)
            if hasattr(_split, '_split_maximize_document'):
                _split._split_maximize_document(doc)
    except Exception:
        pass
    try:
        ok = _merge_activate_document(doc) or ok
    except Exception:
        pass
    return ok

def _merge_document_window_hidden(doc):
    """True, если окно книги скрыто (freezeAtPosition не срабатывает)."""
    if doc is None:
        return True
    try:
        ctrl = doc.getCurrentController()
        if ctrl is None:
            return True
        frame = ctrl.getFrame()
        if frame is None:
            return False
        win = frame.getContainerWindow()
        if win is None:
            return False
        for attr in ('isVisible', 'IsVisible'):
            if hasattr(win, attr):
                try:
                    if not bool(getattr(win, attr)):
                        return True
                except Exception:
                    pass
    except Exception:
        pass
    return False

def _merge_pending_freeze_normalize(items):
    """Список {name, header_row} без дубликатов (последний header_row побеждает)."""
    out = []
    seen = {}
    ii = 0
    while ii < len(items or []):
        entry = items[ii]
        ii += 1
        if isinstance(entry, dict):
            nm = str(entry.get('name') or '').strip()
            try:
                hr = int(entry.get('header_row') or 0)
            except (TypeError, ValueError):
                hr = 0
        else:
            nm = str(entry or '').strip()
            hr = 0
        if nm == '':
            continue
        key = nm.casefold()
        item = {'name': nm, 'header_row': hr}
        if key in seen:
            seen[key]['header_row'] = hr
        else:
            seen[key] = item
            out.append(item)
    return out

def _merge_queue_freeze_items(doc, items, report=None):
    """Добавить листы в очередь freeze до показа окна книги."""
    new_items = _merge_pending_freeze_normalize(items)
    if doc is None or not new_items:
        return
    pending = _cw_cfg._merge_xml_freeze_pending
    if pending is not None and pending.get('doc') is doc:
        old = pending.get('items') or pending.get('sheets') or []
        combined = _merge_pending_freeze_normalize(list(old) + new_items)
        rep = report if report is not None else pending.get('report')
    else:
        combined = new_items
        rep = report
    _cw_cfg._merge_xml_freeze_pending = {'doc': doc, 'items': combined, 'report': rep}
    merge_debug('xml_freeze', 'queued=%d (после показа окна)' % len(combined))

def _merge_queue_freeze_sheet(doc, sheet_name, header_row_0=0, report=None):
    _merge_queue_freeze_items(doc, [{'name': str(sheet_name or '').strip(), 'header_row': int(header_row_0)}], report=report)

def _merge_freeze_defer_hook(doc, sheet, header_row_0):
    """Хук libre_macros_lib: отложить freeze, пока книга Hidden."""
    if not _merge_document_window_hidden(doc):
        return False
    try:
        nm = str(getattr(sheet, 'Name', '') or '').strip()
    except Exception:
        nm = ''
    if nm == '':
        return False
    _merge_queue_freeze_sheet(doc, nm, header_row_0)
    merge_debug('freeze_defer', 'sheet=%s header_row=%d' % (nm, int(header_row_0)))
    return True

def _merge_install_lib_hooks():
    """Хуки collect_workbooks → libre_macros_lib (лог на лист, отложенный freeze)."""
    if _merge_debug_enabled() or _merge_debug_log_to_worksheet():
        _merge_install_debug_log_hooks()
    try:
        import libre_macros_lib as _lm
        if hasattr(_lm, 'lm_set_freeze_defer_hook'):
            _lm.lm_set_freeze_defer_hook(_merge_freeze_defer_hook)
    except Exception:
        pass

def _merge_queue_xml_freeze(doc, sheet_names, report=None):
    """Отложить «закрепить_заголовок» до первого показа книги результата."""
    items = []
    si = 0
    while si < len(sheet_names or []):
        nm = str(sheet_names[si] or '').strip()
        si += 1
        if nm != '':
            items.append({'name': nm, 'header_row': 0})
    _merge_queue_freeze_items(doc, items, report=report)

def _merge_flush_xml_freeze_pending(doc):
    """
    Применить отложенный freeze, если активируется нужная книга.

    Вызывать только когда окно уже видимо (после _merge_activate_frame).
    """
    pending = _cw_cfg._merge_xml_freeze_pending
    if pending is None or doc is None:
        return
    if pending.get('doc') is not doc:
        return
    items = _merge_pending_freeze_normalize(pending.get('items') or pending.get('sheets') or [])
    report = pending.get('report')
    _cw_cfg._merge_xml_freeze_pending = None
    if not items:
        return
    _merge_apply_xml_freeze_pending(doc, items, report)

def _merge_ui_anchor_close(save=False):
    """Закрыть книгу-якорь диалога (без сохранения по умолчанию)."""
    anchor = _cw_cfg._merge_ui_anchor_doc
    _cw_cfg._merge_ui_anchor_doc = None
    _cw_cfg._merge_ui_anchor_frame = None
    if anchor is None:
        return
    try:
        anchor.close(bool(save))
    except Exception:
        try:
            anchor.dispose()
        except Exception:
            pass

def _merge_ui_anchor_begin(settings=None, anchor_doc=None):
    """
    xml_excel_ods + диалог: якорь = уже открытая книга результата.

    Книга остаётся открытой; работа direct/UNO идёт во временной OS-копии.
    Не создаём private:factory/scalc и не трогаем Hidden/Minimized.
    """
    if anchor_doc is None:
        merge_debug('merge_ui_anchor', 'begin: no anchor_doc')
        return False
    prev = _cw_cfg._merge_ui_anchor_doc
    if prev is not None and prev is not anchor_doc:
        # Старый factory-якорь — закрыть; книгу результата не трогаем.
        try:
            if prev is not anchor_doc:
                _cw_cfg._merge_ui_anchor_doc = prev
                _merge_ui_anchor_close(save=False)
        except Exception:
            pass
    _cw_cfg._merge_ui_anchor_doc = anchor_doc
    try:
        frame = _merge_document_frame(anchor_doc)
        if frame is not None:
            try:
                frame.setName(_cw_cfg._merge_ui_anchor_frame_name)
            except Exception:
                pass
            _cw_cfg._merge_ui_anchor_frame = frame
        else:
            _cw_cfg._merge_ui_anchor_frame = None
        merge_debug('merge_ui_anchor', 'begin: bound to result doc')
        return True
    except Exception as err:
        merge_debug('merge_ui_anchor', 'begin failed: %s' % err)
        _cw_cfg._merge_ui_anchor_doc = None
        _cw_cfg._merge_ui_anchor_frame = None
        return False

def _merge_ui_anchor_activate():
    """Активировать окно книги-якоря (диалог прогресса)."""
    frame = _cw_cfg._merge_ui_anchor_frame
    if frame is None and _cw_cfg._merge_ui_anchor_doc is not None:
        frame = _merge_document_frame(_cw_cfg._merge_ui_anchor_doc)
        _cw_cfg._merge_ui_anchor_frame = frame
    if frame is None:
        frame = _merge_find_frame_by_name(_cw_cfg._merge_ui_anchor_frame_name)
        _cw_cfg._merge_ui_anchor_frame = frame
    if frame is not None:
        _merge_activate_frame(frame)
    elif _cw_cfg._merge_ui_anchor_doc is not None:
        _merge_activate_document(_cw_cfg._merge_ui_anchor_doc)
    try:
        if _cw_cfg._merge_ui_progress_dialog is not None:
            _cw_cfg._merge_ui_progress_dialog.setVisible(True)
            peer = _cw_cfg._merge_ui_progress_dialog.getPeer()
            if peer is not None:
                peer.setVisible(True)
                if hasattr(peer, 'toFront'):
                    peer.toFront()
    except Exception:
        pass
    merge_ui_yield(force=True)
    _merge_ui_dialog_pulse()
    merge_debug('merge_ui_anchor', 'activate: frame=%s dialog=%s' % (frame is not None, _cw_cfg._merge_ui_progress_dialog is not None))

def _merge_ui_anchor_end(activate_doc=None, close_anchor=True):
    """
    Снять привязку якоря.

    close_anchor=True — закрыть якорь без сохранения (финал xml_excel_ods).
    close_anchor=False — только отвязать ссылки (книга остаётся открытой).
    """
    anchor = _cw_cfg._merge_ui_anchor_doc
    _cw_cfg._merge_ui_anchor_doc = None
    _cw_cfg._merge_ui_anchor_frame = None
    if close_anchor and anchor is not None:
        if activate_doc is not None and anchor is activate_doc:
            # Не закрывать тот же документ, который сейчас показываем.
            pass
        else:
            try:
                anchor.close(False)
            except Exception:
                try:
                    anchor.dispose()
                except Exception:
                    pass
            merge_debug('merge_ui_anchor', 'end: closed anchor without save')
    if activate_doc is not None:
        _merge_force_result_interactive(activate_doc)
        merge_debug('merge_ui_anchor', 'end: activated result')

def _merge_ui_dialog_ctl(dialog, name):
    try:
        return dialog.getControl(name)
    except Exception:
        return None

def _merge_mode_label(mode):
    m = str(mode or '').strip().lower()
    if m == _cw_cfg.MERGE_MODE_COPY:
        return 'Копирование листов'
    if m == _cw_cfg.MERGE_MODE_MANY:
        return 'На разные листы'
    if m == _cw_cfg.MERGE_MODE_INVOLVE:
        return 'Текущие листы'
    return 'На один лист'

def _merge_path_mode_label(mode):
    if mode == 'short':
        return 'Коротко'
    if mode == 'long':
        return 'Длинно'
    return 'Не выводить'

def _merge_param_comment_from_table(table):
    """Текст строки «Комментарий» (B и следующие непустые ячейки)."""
    vals = table_values(table, _cw_cfg.P_MERGE_COMMENT)
    if vals is None:
        return ''
    parts = []
    i = 0
    while i < len(vals):
        t = str(vals[i]).strip() if vals[i] is not None else ''
        if t != '':
            parts.append(t)
        i = i + 1
    return '\n'.join(parts)

def _merge_param_comment_for_named_sheet(doc, sheet_name):
    """Комментарий с указанного листа параметров (для оркестратора)."""
    name = str(sheet_name or '').strip()
    if name == '' or doc is None:
        return ''
    prev = get_run_param_sheet(doc)
    try:
        if name not in doc.Sheets:
            return ''
        set_run_param_sheet(name)
        table = read_param_table(doc)
        return _merge_param_comment_from_table(table)
    except Exception:
        return ''
    finally:
        try:
            set_run_param_sheet(prev)
        except Exception:
            pass

def _merge_param_comments_for_sheets(doc, sheet_names):
    """Имя листа параметров → полный текст комментария."""
    out = {}
    for nm in sheet_names or []:
        name = str(nm or '').strip()
        if name == '':
            continue
        out[name] = _merge_param_comment_for_named_sheet(doc, name)
    return out

def _merge_build_run_summary(settings):
    """Текст сводки для диалога подтверждения перед этапом 2."""
    files = settings.get('files') or []
    flags = settings.get('is_current_book_flags') or []
    lines = ['Будет выполнен сбор данных из книг-источников в текущую книгу.', '', 'РЕКОМЕНДУЕТСЯ ЗАКРЫТЬ ВСЕ КНИГИ, КРОМЕ ТОЙ, В КОТОРУЮ', 'БУДЕТ ПРОВЕДЁН СБОР ДАННЫХ И ОБРАБОТКА РЕЗУЛЬТАТА.']
    comment = str(settings.get('param_comment') or '').strip()
    if comment != '':
        lines.append('')
        lines.append('Комментарий к параметрам:')
        for line in comment.splitlines():
            lines.append('  %s' % line.rstrip())
    lines.append('')
    lines.extend(['Режим: %s' % _merge_mode_label(settings.get('mode')), 'Файлов-источников: %d' % len(files)])
    transfer = settings.get('data_transfer_mode', _cw_cfg.MERGE_TRANSFER_DEFAULT)
    if settings.get('mode') in (_cw_cfg.MERGE_MODE_ONE, _cw_cfg.MERGE_MODE_MANY):
        lines.append('Способ переноса: %s' % _merge_data_transfer_mode_label(transfer))
        if transfer == _cw_cfg.MERGE_TRANSFER_XML_EXCEL_ODS:
            lines.append('')
            lines.append('Внимание: в режиме «xml_excel_ods» книга результата должна быть')
            lines.append('  сохранена на диск (.ods или .xlsx) до запуска сбора.')
            lines.append('  Во время переноса книга будет закрыта и открыта снова.')
            xml_flags = settings.get('merge_flags') or {}
            if 'MERGE_XML_CONVERT_TO_NUMBERS' in xml_flags:
                lines.append('  MERGE_XML_CONVERT_TO_NUMBERS: %s' % xml_flags.get('MERGE_XML_CONVERT_TO_NUMBERS'))
            if str(xml_flags.get('MERGE_XML_DATETIME_FORMATS', '') or '').strip() != '':
                lines.append('  MERGE_XML_DATETIME_FORMATS: %s' % xml_flags.get('MERGE_XML_DATETIME_FORMATS'))
    pd = settings.get('path_display')
    dt = settings.get('datetime_display')
    if pd and pd != 'none':
        lines.append('Колонка «#Путь»: %s' % _merge_path_mode_label(pd))
    if dt and dt != 'none':
        lines.append('Колонка «#ДатаВремяФайла»: %s' % _merge_path_mode_label(dt))
    lines.append('')
    lines.append('Источники:')
    # Лимит строк/имён — иначе QueryBox/диалог раздувается при десятках файлов.
    max_show = 8
    name_max = 64
    fi = 0
    while fi < len(files) and fi < max_show:
        is_curr = flags[fi] if fi < len(flags) else False
        if is_curr:
            lines.append('  %d. (текущая книга)' % (fi + 1))
        else:
            name = short_name(files[fi])
            if len(name) > name_max:
                name = name[: max(1, name_max - 1)] + '…'
            lines.append('  %d. %s' % (fi + 1, name))
        fi = fi + 1
    if len(files) > max_show:
        lines.append('  … и ещё %d' % (len(files) - max_show))
    pp_range = settings.get('postprocess_range') or []
    pp_row = settings.get('postprocess_row') or []
    ctc = settings.get('cell_to_column_plan') or []
    dtr = settings.get('delete_top_rows_map') or {}
    extras = []
    if len(pp_range) > 0:
        extras.append('постобработка диапазона (%d шаг.)' % len(pp_range))
    if len(pp_row) > 0:
        extras.append('постобработка строк (%d шаг.)' % len(pp_row))
    if len(ctc) > 0:
        extras.append('«Ячейка_В_Столбец»')
    if len(dtr) > 0:
        extras.append('«удаление_верхних_строк» (%d лист.)' % len(dtr))
    xml_pp = settings.get('xml_postprocess_pipeline') or []
    if len(xml_pp) > 0:
        extras.append('Постобработка_xml (%d шаг.)' % len(xml_pp))
    if len(extras) > 0:
        lines.append('')
        lines.append('Дополнительно: ' + ', '.join(extras))
    lines.append('')
    lines.append('Нажмите «Запуск» для начала или «Отмена» для выхода.')
    return '\n'.join(lines)

def _merge_ui_dlg_create_peer(dlg, toolkit, doc=None, parent_win=None):
    """
    createPeer с перебором родителей (как consent_lib / param_wizard MessageBox).
    parent_win=None — пробуем doc frame, desktop, None.
    """
    if dlg is None or toolkit is None:
        return False
    parents = []
    if parent_win is not None:
        parents.append(parent_win)
        try:
            peer = parent_win.getPeer()
            if peer is not None:
                parents.append(peer)
        except Exception:
            pass
    if doc is not None:
        try:
            w = doc.getCurrentController().getFrame().getContainerWindow()
            if w is not None and w not in parents:
                parents.append(w)
        except Exception:
            pass
    if _cw_cfg._merge_ui_progress_dialog is not None:
        try:
            peer = _cw_cfg._merge_ui_progress_dialog.getPeer()
            if peer is not None and peer not in parents:
                parents.append(peer)
        except Exception:
            pass
    try:
        frame = XSCRIPTCONTEXT.getDesktop().getCurrentFrame()
        if frame is not None:
            w = frame.getContainerWindow()
            if w is not None and w not in parents:
                parents.append(w)
    except Exception:
        pass
    parents.append(None)
    i = 0
    while i < len(parents):
        try:
            dlg.createPeer(toolkit, parents[i])
            return True
        except Exception:
            pass
        i = i + 1
    return False

def _merge_ui_dlg_modal_execute(dialog, toolkit, doc=None):
    """
    Модальный диалог: createPeer (цепочка родителей, как consent) → execute().
    execute() без peer в AlterOffice возвращается сразу (confirmed=False).
    """
    if dialog is None:
        return None
    peer_ok = _merge_ui_dlg_create_peer(dialog, toolkit, doc=doc, parent_win=_merge_ui_dialog_parent())
    merge_debug('merge_ui_dialog', 'modal createPeer=%s' % peer_ok)
    if not peer_ok:
        return None
    try:
        rc = dialog.execute()
        merge_debug('merge_ui_dialog', 'modal execute rc=%s' % rc)
        return rc
    except Exception as err:
        merge_debug('merge_ui_dialog', 'modal execute failed: %s' % err)
        return None

def _merge_ui_dlg_center(dm, toolkit, parent_win=None):
    """Позиционирование как param_wizard: фиксированный отступ 80×60 от parent."""
    ui = _merge_ui_dlg_use_macro_ui()
    if ui is not None and hasattr(ui, 'dlg_center_model'):
        try:
            ui.dlg_center_model(dm, toolkit, parent_win)
            return
        except Exception:
            pass
    dm.PositionX = 80
    dm.PositionY = 60

def _merge_ui_dlg_model(ctx):
    sm = ctx.getServiceManager()
    return sm.createInstanceWithContext('com.sun.star.awt.UnoControlDialogModel', ctx)

def _merge_ui_dlg_use_macro_ui():
    try:
        import macro_ui
        return macro_ui
    except Exception:
        return None

def _merge_ui_dlg_add_edit(dm, name, x, y, w, h, multiline=False, readonly=False):
    ui = _merge_ui_dlg_use_macro_ui()
    if ui is not None:
        return ui.dlg_add_edit(dm, name, x, y, w, h, multiline=multiline, readonly=readonly)
    m = dm.createInstance('com.sun.star.awt.UnoControlEditModel')
    m.PositionX = int(x)
    m.PositionY = int(y)
    m.Width = int(w)
    m.Height = int(h)
    if multiline:
        m.MultiLine = True
    if readonly:
        m.ReadOnly = True
    try:
        if multiline:
            m.VScroll = True
    except Exception:
        pass
    m.Name = str(name)
    dm.insertByName(str(name), m)
    return m

def _merge_ui_dlg_edit_height_for_text(text, content_w, min_h=180, max_h=520, line_h=16):
    """Высота многострочного поля: вмещает текст; при переполнении остаётся VScroll."""
    body = str(text or '')
    if body == '':
        return int(min_h)
    try:
        cw = max(200, int(content_w))
    except (TypeError, ValueError):
        cw = 480
    chars_per_line = max(20, cw // 7)
    visual_lines = 0
    for raw_ln in body.split('\n'):
        ln = str(raw_ln)
        if ln == '':
            visual_lines = visual_lines + 1
        else:
            visual_lines = visual_lines + max(1, (len(ln) + chars_per_line - 1) // chars_per_line)
    visual_lines = max(1, visual_lines)
    h = visual_lines * int(line_h) + 20
    if h < int(min_h):
        h = int(min_h)
    if h > int(max_h):
        h = int(max_h)
    return int(h)

