def _merge_csv_included_by_sheet_specs(src_title, sheet_specs, sheet_kind):
    """Фильтр «Листы» для единственного логического листа CSV."""
    kind = sheet_kind or classify_sheet_specs(sheet_specs or [])
    if kind == 'ALL' or kind == 'MIXED':
        return True
    if kind == 'INDEX':
        i = 0
        while i < len(sheet_specs or []):
            sel = _sheet_spec_select_token(sheet_specs[i])
            if sel == u'':
                i = i + 1
                continue
            try:
                if int(unicode(sel).strip()) == 1:
                    return True
            except (TypeError, ValueError):
                pass
            i = i + 1
        return False
    # NAME: «*» / «Отчет*» / точное имя; CSV всегда индекс 1
    title = unicode(src_title or u'')
    i = 0
    while i < len(sheet_specs or []):
        left = _sheet_spec_select_token(sheet_specs[i])
        if left == u'':
            i = i + 1
            continue
        if left.isdigit():
            try:
                if int(left) == 1:
                    return True
            except (TypeError, ValueError):
                pass
            i = i + 1
            continue
        if text_match(title, left) or text_match(u'CSV', left):
            return True
        i = i + 1
    return False


def _merge_csv_build_matrix(headers, data_rows):
    """Список строк (list[list]) одинаковой ширины для setDataArray (пока строки)."""
    rows = []
    if headers:
        rows.append([unicode(h) if h is not None else u'' for h in headers])
    ri = 0
    while ri < len(data_rows or []):
        row = data_rows[ri]
        out = []
        ci = 0
        while ci < len(row or []):
            c = row[ci]
            out.append(unicode(c) if c is not None else u'')
            ci = ci + 1
        rows.append(out)
        ri = ri + 1
    if not rows:
        return []
    max_c = 1
    for r in rows:
        if len(r) > max_c:
            max_c = len(r)
    padded = []
    for r in rows:
        if len(r) < max_c:
            padded.append(list(r) + [u''] * (max_c - len(r)))
        else:
            padded.append(list(r))
    return padded


def _merge_csv_parsed_to_array_value(parsed):
    """date/datetime/int/float → значение для setDataArray (даты — серийный float Calc)."""
    import datetime as _dt_mod
    if parsed is None:
        return u''
    if isinstance(parsed, bool):
        return unicode(parsed)
    if isinstance(parsed, _dt_mod.datetime):
        serial = _merge_datetime_to_calc_serial(parsed)
        return float(serial) if serial is not None else u''
    if isinstance(parsed, _dt_mod.date):
        serial = _merge_datetime_to_calc_serial(
            _dt_mod.datetime(parsed.year, parsed.month, parsed.day)
        )
        return float(serial) if serial is not None else u''
    if isinstance(parsed, _dt_mod.time):
        return (
            float(parsed.hour) / 24.0
            + float(parsed.minute) / 1440.0
            + float(parsed.second) / 86400.0
            + float(getattr(parsed, 'microsecond', 0) or 0) / 86400000000.0
        )
    if isinstance(parsed, int):
        return parsed
    if isinstance(parsed, float):
        return float(parsed)
    try:
        from decimal import Decimal
        if isinstance(parsed, Decimal):
            return float(parsed)
    except Exception:
        pass
    if isinstance(parsed, (unicode, str)):
        return unicode(parsed)
    return unicode(parsed)


def _merge_csv_is_native_datetime(v):
    import datetime as _dt_mod
    if v is None or isinstance(v, bool):
        return False
    return isinstance(v, (_dt_mod.datetime, _dt_mod.date, _dt_mod.time))


def _merge_csv_convert_matrix_numbers_dates(doc, matrix, hdr_row0=0, col_map_items=None, col_headers_rel=None):
    """
    В памяти: текст → число/дата (та же логика столбцов, что UNO/direct).
    Уже готовые datetime/date из openpyxl/odf → серийный float Calc.

    col_map_items — блоки JSON «Столбцы» (convert_to_numbers=false, format).
    col_headers_rel — заголовки столбцов чанка (если hdr_row0 < 0).

    Возвращает (matrix, meta), meta: date_cols, num_cols, counts, timings, date_fmt_by_col.
    """
    import time
    import datetime as _dt_mod
    meta = {
        'date_cols': set(),
        'num_cols': set(),
        'date_fmt_by_col': {},
        'explicit_fmt_by_col': {},
        'converted_dt': 0,
        'converted_num': 0,
        'ms_detect': 0.0,
        'ms_convert': 0.0,
        'skipped': False,
        'reason': '',
    }
    if not matrix:
        meta['skipped'] = True
        meta['reason'] = 'empty'
        return (matrix, meta)
    map_items = col_map_items
    if map_items is None:
        map_items = _cw_get('_MERGE_COL_MAP_ITEMS_FLAT') or []
    if not _merge_wants_number_date_convert(map_items):
        meta['skipped'] = True
        meta['reason'] = 'convert_to_numbers=off'
        return (matrix, meta)
    try:
        _merge_bind_direct_convert_options(doc)
        import libre_macros_direct_lib as direct
    except Exception as err:
        meta['skipped'] = True
        meta['reason'] = 'direct_lib: %s' % err
        return (matrix, meta)
    if not direct._direct_wants_convert_to_numbers():
        meta['skipped'] = True
        meta['reason'] = 'convert_to_numbers=False'
        return (matrix, meta)
    hdr = int(hdr_row0) if hdr_row0 is not None else 0
    end_row = len(matrix) - 1
    end_col = len(matrix[0]) - 1 if matrix else -1
    if end_col < 0 or end_row <= hdr:
        meta['skipped'] = True
        meta['reason'] = 'no data rows'
        return (matrix, meta)

    def get_row_map(row0):
        row = matrix[int(row0)]
        out = {}
        c = 0
        while c <= end_col:
            out[c] = row[c]
            c = c + 1
        return out

    t_det = time.time()
    if _merge_convert_global_auto_probe():
        date_cols = set(direct._direct_build_datetime_column_set(get_row_map, hdr, end_col, end_row))
    else:
        date_cols = set()
    native_date_cols = set()
    rr = hdr + 1
    while rr <= end_row:
        row = matrix[rr]
        c = 0
        while c <= end_col:
            if _merge_csv_is_native_datetime(row[c] if c < len(row) else None):
                native_date_cols.add(c)
            c = c + 1
        rr = rr + 1
    date_cols = date_cols | native_date_cols
    if _merge_convert_global_auto_probe():
        num_cols = set(direct._direct_build_number_column_set(
            get_row_map, hdr, end_col, end_row, exclude_cols=date_cols
        ))
    else:
        num_cols = set()
    try:
        from libre_macros_param_codec import (
            columns_map_apply_convert_policies,
            columns_map_headers_by_index_from_matrix,
            columns_map_merge_headers,
        )
        if hdr < 0:
            headers_by_col = dict(col_headers_rel or {})
        else:
            headers_by_col = columns_map_headers_by_index_from_matrix(matrix, hdr)
            if col_headers_rel:
                headers_by_col = columns_map_merge_headers(headers_by_col, col_headers_rel)
        items = map_items
        date_cols, num_cols, explicit_fmt = columns_map_apply_convert_policies(
            date_cols, num_cols, headers_by_col, items, output_headers=False
        )
        meta['explicit_fmt_by_col'] = dict(explicit_fmt or {})
    except Exception:
        pass
    meta['ms_detect'] = (time.time() - t_det) * 1000.0
    meta['date_cols'] = set(date_cols)
    meta['num_cols'] = set(num_cols)
    if not date_cols and not num_cols:
        meta['reason'] = 'no columns matched'
        return (matrix, meta)

    t_cv = time.time()
    date_fmt_by_col = {}
    rr = hdr + 1
    while rr <= end_row:
        row = matrix[rr]
        for col in date_cols:
            if col >= len(row):
                continue
            val = row[col]
            parsed = None
            if _merge_csv_is_native_datetime(val):
                parsed = val
            elif direct._direct_is_plain_string_for_datetime(val):
                parsed = direct._direct_try_parse_datetime_text(val)
            if parsed is None:
                continue
            row[col] = _merge_csv_parsed_to_array_value(parsed)
            meta['converted_dt'] = meta['converted_dt'] + 1
            if col not in date_fmt_by_col:
                try:
                    if isinstance(parsed, _dt_mod.time) and not isinstance(parsed, _dt_mod.datetime):
                        date_fmt_by_col[col] = u'HH:MM:SS'
                    else:
                        date_fmt_by_col[col] = direct._direct_date_format_for_parsed(
                            parsed, for_ods=True
                        )
                except Exception:
                    date_fmt_by_col[col] = direct._direct_default_date_format()
        for col in num_cols:
            if col >= len(row):
                continue
            txt = row[col]
            if not direct._direct_is_plain_string_for_datetime(txt):
                continue
            parsed = direct._direct_try_parse_number_text(txt)
            if parsed is None:
                continue
            row[col] = _merge_csv_parsed_to_array_value(parsed)
            meta['converted_num'] = meta['converted_num'] + 1
        rr = rr + 1
    meta['ms_convert'] = (time.time() - t_cv) * 1000.0
    explicit_fmt = meta.get('explicit_fmt_by_col') or {}
    for col, fmt in explicit_fmt.items():
        if fmt and col in date_cols:
            date_fmt_by_col[col] = fmt
    meta['date_fmt_by_col'] = date_fmt_by_col
    return (matrix, meta)


def _merge_csv_apply_converted_number_formats(doc, sheet, n_rows, convert_meta):
    """NumberFormat на столбцы дат/чисел после setDataArray (без поклеточной конвертации)."""
    if doc is None or sheet is None or not convert_meta or n_rows < 2:
        return 0.0
    import time
    t0 = time.time()
    try:
        import libre_macros_direct_lib as direct
    except Exception:
        return 0.0
    date_cols = convert_meta.get('date_cols') or set()
    num_cols = convert_meta.get('num_cols') or set()
    date_fmt_by_col = convert_meta.get('date_fmt_by_col') or {}
    explicit_fmt = convert_meta.get('explicit_fmt_by_col') or {}
    data_r0 = 1
    end_row = n_rows - 1
    for col in sorted(date_cols):
        fmt = explicit_fmt.get(col) or date_fmt_by_col.get(col) or direct._direct_default_date_format()
        nf_key = _merge_uno_nf_key_for_format(doc, fmt)
        if nf_key is None:
            continue
        try:
            rng = sheet.getCellRangeByPosition(int(col), data_r0, int(col), end_row)
            rng.NumberFormat = int(nf_key)
        except Exception:
            pass
    num_fmt = direct._direct_default_number_format()
    if num_cols:
        for col in sorted(num_cols):
            fmt = explicit_fmt.get(col) or num_fmt
            if not fmt:
                continue
            nf_key = _merge_uno_nf_key_for_format(doc, fmt)
            if nf_key is None:
                continue
            try:
                rng = sheet.getCellRangeByPosition(int(col), data_r0, int(col), end_row)
                rng.NumberFormat = int(nf_key)
            except Exception:
                pass
    return (time.time() - t0) * 1000.0


def _merge_csv_mark_skip_number_date_convert(sheet_name, reason=u''):
    """Пометить лист результата: не конвертировать текст→число/дата (UNO и xml)."""
    sn = str(sheet_name or '').strip()
    if sn == '':
        return
    try:
        pre = getattr(_cw_cfg, '_MERGE_CSV_PRECONVERTED_SHEETS', None)
        if pre is None:
            _cw_cfg._MERGE_CSV_PRECONVERTED_SHEETS = set()
            pre = _cw_cfg._MERGE_CSV_PRECONVERTED_SHEETS
        pre.add(sn)
    except Exception:
        return
    if reason:
        try:
            _merge_csv_console_log(u'%s: без отдельной конвертации чисел/дат — %s' % (sn, reason))
        except Exception:
            pass


def _merge_csv_filter_sheets_for_number_date_convert(sheet_names):
    """Убрать из списка листы CSV, где Calc/матрица уже дали числа и даты."""
    if not sheet_names:
        return []
    pre = getattr(_cw_cfg, '_MERGE_CSV_PRECONVERTED_SHEETS', None) or set()
    if not pre:
        return list(sheet_names)
    out = []
    for nm in sheet_names:
        if str(nm or '') in pre:
            continue
        out.append(nm)
    return out


