def _merge_write_matrix_set_data_array(sheet, matrix, report=None, status_label=u''):
    """
    Записать матрицу на лист через setDataArray (чанками MERGE_COPY_ROW_CHUNK).

    Значения: unicode / int / float (даты — серийный float).
    Возвращает dict статистики таймингов.
    """
    import time
    stats = {
        'chunk': 0,
        'chunks_n': 0,
        'ms_total': 0.0,
        'chunk_ms': [],
        'n_rows': 0,
        'n_cols': 0,
    }
    if sheet is None or not matrix:
        return stats
    n_rows = len(matrix)
    n_cols = len(matrix[0]) if matrix else 0
    stats['n_rows'] = n_rows
    stats['n_cols'] = n_cols
    if n_cols < 1:
        return stats
    try:
        chunk = int(_merge_ui_dialog_copy_chunk())
    except Exception:
        chunk = int(getattr(_cw_cfg, 'MERGE_COPY_ROW_CHUNK', 1000) or 1000)
    if chunk < 1:
        chunk = 1000
    stats['chunk'] = chunk
    chunks_n = (n_rows + chunk - 1) // chunk
    stats['chunks_n'] = chunks_n
    t_all = time.time()
    off = 0
    chunk_i = 0
    while off < n_rows:
        end = off + chunk
        if end > n_rows:
            end = n_rows
        chunk_i = chunk_i + 1
        block_rows = []
        ri = off
        while ri < end:
            row_vals = []
            for v in matrix[ri]:
                row_vals.append(_merge_csv_parsed_to_array_value(v))
            block_rows.append(tuple(row_vals))
            ri = ri + 1
        block = tuple(block_rows)
        t_ch = time.time()
        try:
            rng = sheet.getCellRangeByPosition(0, off, n_cols - 1, end - 1)
            rng.setDataArray(block)
        except Exception as err:
            if report is not None:
                report.problem('матрица setDataArray (строки %d–%d): %s' % (off + 1, end, err))
            raise
        ch_ms = (time.time() - t_ch) * 1000.0
        stats['chunk_ms'].append(ch_ms)
        _merge_csv_console_log(
            u'setDataArray chunk %d/%d rows %d–%d (n=%d): %.1f ms'
            % (chunk_i, chunks_n, off + 1, end, end - off, ch_ms)
        )
        if status_label and report is not None:
            try:
                report.status(u'  %s: строк %d / %d' % (status_label, end, n_rows))
            except Exception:
                pass
        merge_ui_yield(force=(end >= n_rows or (end % (chunk * 5) == 0)))
        off = end
    stats['ms_total'] = (time.time() - t_all) * 1000.0
    return stats


