def _merge_book_memory_path_active(fpath, fi, mode, is_current_book):
    """
    Проверка условий §4 ТЗ prepare_source_in_memory.

    Возвращает (active: bool, skip_reason: unicode).
    """
    try:
        from libre_macros_source_extra_lib import source_extra_prepare_in_memory
        from libre_macros_book_source_lib import is_book_source_path
    except Exception:
        return (False, u'нет модулей source/book')
    if is_current_book:
        return (False, u'эта_книга')
    extra = _merge_source_extra_for_fi(fi)
    if not source_extra_prepare_in_memory(extra):
        return (False, u'')
    if not is_book_source_path(fpath):
        return (False, u'не книга')
    if _merge_is_remote_url_path(fpath):
        return (False, u'URL/smb — только UNO')
    transfer = _merge_active_data_transfer_mode()
    if transfer not in (
        _cw_cfg.MERGE_TRANSFER_CLIPBOARD_HEADERS,
        _cw_cfg.MERGE_TRANSFER_CLIPBOARD_POSITION,
    ):
        return (False, u'transfer=%s' % (transfer or u'—'))
    if mode not in (_cw_cfg.MERGE_MODE_ONE, _cw_cfg.MERGE_MODE_MANY):
        return (False, u'режим=%s' % (mode or u'—'))
    return (True, u'')


def _merge_mem_log_tag_for_path(fpath):
    ext = os.path.splitext(unicode(fpath or u''))[1].lower()
    if ext == u'.ods':
        return u'ODS-MEM'
    if ext in (u'.xls', u'.xlsx', u'.xlsm'):
        return u'XLS-MEM'
    return u'MEM'


def _merge_resolve_book_read_path(fpath, tmp_paths):
    """
    Локальный путь для бандл-чтения; .xls → temp .xlsx (UNO один раз).

    Возвращает (read_path, kind) или (None, u'').
    """
    try:
        from libre_macros_book_source_lib import book_source_file_kind, book_source_normalize_local_path
    except Exception:
        return (None, u'')
    p = book_source_normalize_local_path(fpath)
    if p == u'' or not os.path.isfile(p):
        return (None, u'')
    kind = book_source_file_kind(p)
    if kind == u'xls':
        import tempfile
        fd, tmp_xlsx = tempfile.mkstemp(prefix=u'libre_macros_book_mem_', suffix=u'.xlsx')
        try:
            os.close(fd)
        except Exception:
            pass
        ok = _merge_convert_xls_to_xlsx_via_uno(p, tmp_xlsx)
        if not ok:
            try:
                os.unlink(tmp_xlsx)
            except Exception:
                pass
            return (None, u'')
        if tmp_paths is not None:
            tmp_paths.append(tmp_xlsx)
        return (tmp_xlsx, u'xlsx')
    if kind in (u'xlsx', u'xlsm'):
        return (p, kind)
    if kind == u'ods':
        return (p, u'ods')
    return (None, u'')


def _merge_iter_book_sheet_slots(fpath, sheet_specs, sheet_kind, filter_fn=_cw_cfg._MERGE_FILTER_FN_UNSET):
    """iter_sheet_slots без UNO — по именам листов файла."""
    try:
        from libre_macros_book_source_lib import book_source_sheet_names
    except Exception:
        return
    filter_fn = _merge_resolve_sheets_include_filter_fn(filter_fn)
    names = book_source_sheet_names(fpath)

    # Поддержка `!hidden` (нет инфы о видимости без UNO) и переименования `Старое->Новое`.
    IGNORE_HIDDEN_TOKENS = set([u'!hidden', u'ignore_hidden', u'игнорировать_скрытые'])
    ARROW_SEP = u'->'
    rename_entries = []  # [(match_spec, target_name or None)]
    for spec in sheet_specs or []:
        try:
            s = unicode(spec or u'').strip()
        except Exception:
            s = str(spec or u'').strip()
        if s == u'':
            continue
        if unicode(s).casefold() in IGNORE_HIDDEN_TOKENS:
            continue
        if ARROW_SEP in s:
            left, right = s.split(ARROW_SEP, 1)
            left = unicode(left or u'').strip()
            right = unicode(right or u'').strip()
            if left != u'':
                rename_entries.append((left, right if right != u'' else None))
            continue
        rename_entries.append((s, None))

    if sheet_kind == 'ALL':
        used_tgt = set()
        i = 0
        while i < len(names):
            n = names[i]
            if _merge_sheet_slot_include_filter_passes(n, filter_fn):
                desired = n
                for match_spec, tgt in rename_entries:
                    if tgt is None or unicode(tgt).strip() == u'':
                        continue
                    if _sheet_spec_is_all_select(match_spec) or text_match(n, match_spec):
                        desired = unicode(tgt).strip()
                        break
                tkey = _merge_unique_slot_target_name(desired, used_tgt)
                yield {u'target_key': tkey, u'source_name': n, u'source_index': i}
            i = i + 1
        return
    if sheet_kind == 'INDEX':
        used_tgt = set()
        for spec, _tgt in rename_entries:
            try:
                idx = int(unicode(spec).strip()) - 1
            except (TypeError, ValueError):
                continue
            if idx >= 0 and idx < len(names):
                n = names[idx]
                if _merge_sheet_slot_include_filter_passes(n, filter_fn):
                    if _tgt is not None and unicode(_tgt).strip() != u'':
                        desired = unicode(_tgt).strip()
                    else:
                        desired = n
                    tkey = _merge_unique_slot_target_name(desired, used_tgt)
                    yield {
                        u'target_key': tkey,
                        u'source_name': n,
                        u'source_index': idx,
                    }
        return
    picked = []
    used_tgt = set()
    for n in names:
        for match_spec, tgt in rename_entries:
            if text_match(n, match_spec):
                desired = tgt if tgt is not None and unicode(tgt).strip() != u'' else n
                target_name = _merge_unique_slot_target_name(desired, used_tgt)
                picked.append((n, target_name))
                break
    i = 0
    while i < len(picked):
        n, target_name = picked[i]
        if _merge_sheet_slot_include_filter_passes(n, filter_fn):
            yield {u'target_key': target_name, u'source_name': n, u'source_index': -1}
        i = i + 1


def _merge_book_matrix_keep_text(chunk_rows):
    out = []
    for row in chunk_rows or []:
        nr = []
        for v in row:
            if v is None:
                nr.append(u'')
            elif isinstance(v, bool):
                nr.append(unicode(v))
            elif isinstance(v, (int, float)):
                nr.append(unicode(v))
            else:
                nr.append(unicode(v))
        out.append(nr)
    return out


def _merge_book_append_chunk( target_doc, ts, chunk_rows, session, out_row, report, fname, tname, src_label, fpath, path_display, fi, blk):
    """Слить один chunk данных на лист результата."""
    import time
    if not chunk_rows:
        return out_row
    tag = session.get(u'log_tag') or u'MEM'
    convert_types = session.get(u'convert_types') or u'in_memory'
    chunk_rows_work = [list(r) for r in chunk_rows]
    if convert_types == u'keep_text':
        chunk_rows_work = _merge_book_matrix_keep_text(chunk_rows_work)
    conv_meta = session.get(u'conv_meta') or {}
    hdr_row = int(session.get(u'hdr_row') or 0)
    probe = [list(r) for r in (session.get(u'probe_matrix') or [])]
    base = len(probe)
    temp_matrix = probe + chunk_rows_work
    if convert_types == u'in_memory':
        t_conv = time.time()
        temp_matrix, chunk_conv = _merge_csv_convert_matrix_numbers_dates(
            target_doc, temp_matrix, hdr_row0=hdr_row,
            col_map_items=session.get(u'col_map_items'),
        )
        ms_conv = (time.time() - t_conv) * 1000.0
        for key in (u'date_cols', u'num_cols'):
            base_set = conv_meta.get(key) or set()
            add_set = chunk_conv.get(key) or set()
            conv_meta[key] = set(base_set) | set(add_set)
        conv_meta[u'converted_dt'] = int(conv_meta.get(u'converted_dt') or 0) + int(chunk_conv.get(u'converted_dt') or 0)
        conv_meta[u'converted_num'] = int(conv_meta.get(u'converted_num') or 0) + int(chunk_conv.get(u'converted_num') or 0)
        df = dict(conv_meta.get(u'date_fmt_by_col') or {})
        df.update(chunk_conv.get(u'date_fmt_by_col') or {})
        conv_meta[u'date_fmt_by_col'] = df
        ef = dict(conv_meta.get(u'explicit_fmt_by_col') or {})
        ef.update(chunk_conv.get(u'explicit_fmt_by_col') or {})
        conv_meta[u'explicit_fmt_by_col'] = ef
        session[u'conv_meta'] = conv_meta
    cols = session.get(u'cols') or []
    skip_spec = session.get(u'skip_spec') or u''
    data_rows, _skip_n, _allow = _merge_csv_prepare_data_rows_with_skip(
        temp_matrix, hdr_row, blk.get(u'start_col', 0), blk.get(u'row_count'), blk.get(u'col_count'),
        skip_spec, report, fname, tname, first_data_row_0=base,
    )
    if not data_rows:
        return out_row
    session[u'chunk_num'] = int(session.get(u'chunk_num') or 0) + 1
    if convert_types == u'in_memory':
        _merge_mem_console_log(
            tag,
            u'chunk %d | rows=%d | convert_types=in_memory'
            % (session[u'chunk_num'], len(chunk_rows_work)),
        )
    t_wr = time.time()
    write_start = out_row
    rows_n = len(data_rows)
    layout = merge_active_service_layout()
    row_label, mtime_str, file_key = _merge_service_row_context(fpath, False, tname, layout, path_display)
    if rows_n > 0:
        _merge_fill_service_columns(
            ts, out_row, rows_n, row_label, mtime_str,
            file_key=file_key, source_sheet_name=tname,
        )
    transfer = _merge_active_data_transfer_mode()
    if transfer == _cw_cfg.MERGE_TRANSFER_CLIPBOARD_POSITION or (not _merge_uses_header_column_matching()):
        out_row = _merge_csv_write_matrix_by_position(
            ts, temp_matrix, cols, data_rows, out_row, hdr_row, report, fname, tname,
        )
    else:
        out_row = _merge_csv_write_matrix_by_headers(
            ts, temp_matrix, cols, data_rows, out_row, report, fname, tname,
        )
    ms_wr = (time.time() - t_wr) * 1000.0
    _merge_mem_console_log(
        tag,
        u'chunk %d write | rows=%d | ms=%.1f | mode=%s'
        % (
            session[u'chunk_num'],
            rows_n,
            ms_wr,
            u'position' if transfer == _cw_cfg.MERGE_TRANSFER_CLIPBOARD_POSITION else u'headers',
        ),
    )
    if rows_n > 0 and convert_types == u'in_memory':
        _merge_csv_apply_formats_on_target_cols(target_doc, ts, write_start, rows_n, cols, conv_meta)
    if report is not None:
        report.stats[u'rows_copied'] = report.stats.get(u'rows_copied', 0) + rows_n
    return out_row


def _merge_process_book_sheet_in_memory( target_doc, ts, read_path, kind, sheet_index, sheet_name, blk, col_specs, col_kind, skip_spec, out_row, report, fname, tname, src_label, fpath, path_display, fi, extra, col_rename_items=None):
    """Один лист книги → chunked матрица → setDataArray."""
    import time
    try:
        from libre_macros_source_extra_lib import (
            source_extra_chunk_rows,
            source_extra_convert_types,
            source_extra_last_row_column,
            source_extra_merged_cells,
            source_extra_trim_empty,
            source_extra_values_mode,
        )
        from libre_macros_book_source_lib import (
            book_source_iter_data_rows,
            book_source_read_probe_rows,
            book_source_resolve_bounds,
        )
    except Exception as err:
        _merge_mem_console_log(u'MEM', u'модули: %s' % err)
        return out_row
    tag = _merge_mem_log_tag_for_path(fpath)
    values_mode = source_extra_values_mode(extra)
    merged_cells = source_extra_merged_cells(extra)
    trim_empty = source_extra_trim_empty(extra, prepare_active=True)
    convert_types = source_extra_convert_types(extra)
    chunk_limit = source_extra_chunk_rows(extra)
    last_row_col_spec = source_extra_last_row_column(extra)
    hdr_row, start_row_0, no_header, skipped_top_0 = _merge_block_matrix_collect_params(blk)
    start_col = (blk or {}).get(u'start_col', 0)
    col_count = (blk or {}).get(u'col_count')
    _merge_mem_console_log(
        tag,
        u'%s | лист=%s idx=%s chunk_rows=%d values=%s merge=%s trim=%s convert=%s'
        % (fpath, tname, sheet_index, chunk_limit, values_mode, merged_cells, trim_empty, convert_types),
    )
    t0 = time.time()
    t_bounds = time.time()
    try:
        end_col0, end_row0 = book_source_resolve_bounds(
            read_path, kind, int(sheet_index), hdr_row, start_col, trim_empty,
            last_row_col_spec=last_row_col_spec,
        )
    except Exception as err:
        if report is not None:
            report.problem(u'[%s] границы листа «%s»: %s' % (tag, tname, err))
        return out_row
    if end_col0 < int(start_col or 0) or end_row0 < hdr_row:
        if report is not None:
            report.log_stat(src_label, tname, u'', 0, u'пропуск', u'пустой лист')
        return out_row
    probe_end = max(int(hdr_row), int(start_row_0), 0)
    if probe_end > end_row0:
        probe_end = end_row0
    probe_matrix = book_source_read_probe_rows(
        read_path, kind, int(sheet_index), end_col0, probe_end,
        values_mode, merged_cells,
    )
    if not probe_matrix:
        if report is not None:
            report.problem(u'[%s] «%s» / «%s»: пустая проба' % (tag, fname, tname))
        return out_row
    hdr_titles = None
    spec = _merge_block_header_spec(blk)
    if spec is not None:
        try:
            from libre_macros_header_lib import flatten_headers_path, titles_map_from_pairs
            src_kind = u'xlsx' if str(kind or u'') in (u'xlsx', u'xlsm', u'xls') else u'ods'
            pairs = flatten_headers_path(
                read_path, src_kind, int(sheet_index), spec,
                start_col=int(start_col or 0), col_count=col_count,
            )
            hdr_titles = titles_map_from_pairs(pairs)
        except Exception:
            hdr_titles = _merge_header_titles_for_matrix(probe_matrix, blk, start_col, col_count)
    cols = _merge_csv_build_column_list(
        probe_matrix, col_specs, col_kind, hdr_row, start_col, col_count,
        no_header=no_header, probe_row_0=start_row_0, header_titles=hdr_titles,
    )
    cols = _merge_apply_col_rename_items(cols, col_rename_items)
    if len(cols) == 0:
        if report is not None:
            report.problem(u'[%s] «%s» / «%s»: нет столбцов' % (tag, fname, tname))
            report.log_stat(src_label, tname, u'', 0, u'пропуск', u'нет столбцов')
        return out_row
    _merge_note_result_skipped_top(ts.Name, skipped_top_0)
    if _merge_uses_header_column_matching():
        ensure_target_headers(ts, cols)
    session = {
        u'probe_matrix': probe_matrix,
        u'hdr_row': hdr_row,
        u'cols': cols,
        u'conv_meta': {},
        u'convert_types': convert_types,
        u'skip_spec': skip_spec,
        u'log_tag': tag,
        u'chunk_num': 0,
        u'col_map_items': list(col_rename_items or []),
    }
    first_data = int(start_row_0)
    if first_data < 0:
        first_data = 0
    if hdr_row >= 0 and first_data <= hdr_row:
        first_data = hdr_row + 1
    _merge_log_last_row_column_usage(
        report, src_label, tname, last_row_col_spec,
        max(0, int(end_row0) - int(first_data) + 1),
        first_row_0=first_data, last_row_0=end_row0,
        elapsed_ms=(time.time() - t_bounds) * 1000.0,
    )
    chunk = []
    chunk_i = 0
    for row in book_source_iter_data_rows(
        read_path, kind, int(sheet_index), first_data, end_row0, end_col0,
        values_mode, merged_cells,
        yield_callback=lambda: merge_ui_yield(force=False),
    ):
        chunk.append(row)
        if len(chunk) >= chunk_limit:
            chunk_i = chunk_i + 1
            out_row = _merge_book_append_chunk(
                target_doc, ts, chunk, session, out_row, report, fname, tname,
                src_label, fpath, path_display, fi, blk,
            )
            chunk = []
    if chunk:
        out_row = _merge_book_append_chunk(
            target_doc, ts, chunk, session, out_row, report, fname, tname,
            src_label, fpath, path_display, fi, blk,
        )
    if convert_types in (u'in_memory', u'no', u'keep_text'):
        reason = u'convert_types=%s' % convert_types
        _merge_csv_mark_skip_number_date_convert(getattr(ts, u'Name', u'') or u'', reason=reason)
    if report is not None:
        report.stats[u'sheets_done'] = report.stats.get(u'sheets_done', 0) + 1
        ci = 0
        while ci < len(cols):
            sc = cols[ci][0]
            hname = cols[ci][1]
            report.log_stat(
                src_label, tname, u'%s (%s)' % (col_label(sc), hname), 0,
                u'%s→matrix' % tag, block_settings_note(blk),
            )
            ci = ci + 1
    _merge_mem_console_log(tag, u'лист «%s» готово за %.1f ms' % (tname, (time.time() - t0) * 1000.0))
    return out_row


def _merge_process_book_file_in_memory( target_doc, ts_or_targets, fpath, fi, blk, col_specs, col_kind, skip_spec, out_row_or_none, report, fname, src_label, path_display, sheet_specs, sheet_kind, many_mode=False, cell_to_column_cache=None, ctc_per_file_specs=None, col_rename_items=None):
    """
    Все листы одного файла через бандл-матрицу.

    ts_or_targets: лист Merge (one) или dict name_targets (many).
    """
    tmp_paths = []
    read_path, kind = _merge_resolve_book_read_path(fpath, tmp_paths)
    tag = _merge_mem_log_tag_for_path(fpath)
    if read_path is None or kind == u'':
        if report is not None:
            report.problem(u'[%s] не удалось подготовить чтение: %s' % (tag, fpath))
        return out_row_or_none
    extra = _merge_source_extra_for_fi(fi) or {}
    try:
        from libre_macros_source_extra_lib import source_extra_values_mode
        values_mode = source_extra_values_mode(extra)
    except Exception:
        values_mode = u'cached'
    any_sheet = False
    try:
        for slot in _merge_iter_book_sheet_slots(read_path, sheet_specs, sheet_kind):
            if _merge_stop_if_aborted(report):
                break
            tname = slot[u'source_name']
            sidx = slot[u'source_index']
            if sidx < 0:
                try:
                    from libre_macros_book_source_lib import book_source_sheet_names
                    names = book_source_sheet_names(read_path)
                    sidx = names.index(tname)
                except Exception:
                    sidx = 0
            if many_mode:
                ikey = merge_identity_key(tname)
                if isinstance(ts_or_targets, dict):
                    if ikey not in ts_or_targets:
                        continue
                    target_info = ts_or_targets[ikey]
                    ts = target_info[u'sheet']
                    out_row = target_info[u'out_row']
                else:
                    continue
            else:
                ts = ts_or_targets
                out_row = out_row_or_none
            report.status(u'  → [%s] «%s»' % (tag, tname))
            if _merge_ui_is_dialog_mode():
                merge_ui_yield(force=True)
            _merge_book_prefetch_sheet_meta(
                read_path, kind, sidx, tname, fpath, path_display, fi,
                cell_to_column_cache, ctc_per_file_specs, values_mode=values_mode, report=report,
            )
            new_out = _merge_process_book_sheet_in_memory(
                target_doc, ts, read_path, kind, sidx, tname, blk, col_specs, col_kind,
                skip_spec, out_row, report, fname, tname, src_label, fpath, path_display, fi, extra,
                col_rename_items=col_rename_items,
            )
            if many_mode and isinstance(ts_or_targets, dict):
                ts_or_targets[ikey][u'out_row'] = new_out
                ts_or_targets[ikey][u'sources'].append(fname)
            else:
                out_row_or_none = new_out
            any_sheet = True
            _merge_undo_clear(target_doc, u'source:%s|%s' % (src_label, tname), defer_ok=False)
    finally:
        for p in tmp_paths:
            try:
                os.unlink(p)
            except Exception:
                pass
    if many_mode:
        return any_sheet
    return out_row_or_none


def _merge_load_csv_source_matrix(doc, fpath, fi, col_map_items=None):
    """
    CSV → текст → матрица → числа/даты в памяти.

    Возвращает (matrix, conv_meta) или (None, None).
    """
    import time
    try:
        from libre_macros_csv_source_lib import (
            csv_source_read_rows,
            source_extra_delimiter,
            source_extra_encoding,
        )
    except Exception as err:
        _merge_csv_console_log(u'нет libre_macros_csv_source_lib: %s' % err)
        return (None, None)
    extra = _merge_source_extra_for_fi(fi)
    delim = source_extra_delimiter(extra)
    encoding = source_extra_encoding(extra)
    _merge_csv_console_log(u'файл=%s delim=%r encoding=%r' % (fpath, delim, encoding))
    t_read = time.time()
    try:
        headers, data_rows = csv_source_read_rows(fpath, delimiter=delim, encoding=encoding)
    except Exception as err:
        _merge_csv_console_log(u'ошибка чтения: %s' % err)
        return (None, None)
    ms_read = (time.time() - t_read) * 1000.0
    _merge_csv_console_log(
        u'чтение текста: %.1f ms | заголовков=%d строк_данных=%d'
        % (ms_read, len(headers or []), len(data_rows or []))
    )
    t_build = time.time()
    matrix = _merge_csv_build_matrix(headers, data_rows)
    ms_build = (time.time() - t_build) * 1000.0
    if not matrix:
        _merge_csv_console_log(u'пустой CSV')
        return (None, None)
    n_rows = len(matrix)
    n_cols = len(matrix[0])
    _merge_csv_console_log(
        u'матрица в памяти (строки): %.1f ms | %d×%d' % (ms_build, n_rows, n_cols)
    )
    t_conv = time.time()
    matrix, conv_meta = _merge_csv_convert_matrix_numbers_dates(
        doc, matrix, hdr_row0=0, col_map_items=col_map_items
    )
    ms_conv = (time.time() - t_conv) * 1000.0
    if conv_meta.get('skipped'):
        _merge_csv_console_log(
            u'конвертация чисел/дат: пропуск (%s) | wall=%.1f ms'
            % (conv_meta.get('reason') or u'—', ms_conv)
        )
    else:
        _merge_csv_console_log(
            u'конвертация в памяти: dates=%d numbers=%d | detect=%.1f ms convert=%.1f ms wall=%.1f ms | date_cols=%s num_cols=%s'
            % (
                int(conv_meta.get('converted_dt') or 0),
                int(conv_meta.get('converted_num') or 0),
                float(conv_meta.get('ms_detect') or 0.0),
                float(conv_meta.get('ms_convert') or 0.0),
                ms_conv,
                sorted(conv_meta.get('date_cols') or []),
                sorted(conv_meta.get('num_cols') or []),
            )
        )
    conv_meta = dict(conv_meta or {})
    conv_meta['ms_read'] = ms_read
    conv_meta['ms_build'] = ms_build
    conv_meta['ms_convert_wall'] = ms_conv
    return (matrix, conv_meta)


def _merge_block_matrix_collect_params(blk):
    """hdr_row, start_row_0, no_header, skipped_top_0 для CSV-матрицы (без UNO-листа)."""
    no_header = bool(blk and blk.get('no_header'))
    start_row_0 = _merge_block_first_data_row_0(blk)
    if no_header:
        hdr_row = -1
    else:
        try:
            hdr_row = int((blk or {}).get('hdr_row', 0))
        except (TypeError, ValueError):
            hdr_row = 0
        if hdr_row < 0:
            hdr_row = 0
    skipped_top_0 = _merge_block_skipped_top_0(blk, hdr_row)
    return (hdr_row, start_row_0, no_header, skipped_top_0)


def _merge_csv_matrix_cell_text(matrix, row, col):
    if matrix is None or row < 0 or row >= len(matrix):
        return u''
    row_vals = matrix[row]
    if col < 0 or col >= len(row_vals):
        return u''
    v = row_vals[col]
    if v is None:
        return u''
    if isinstance(v, bool):
        return unicode(v)
    if isinstance(v, (int, float)):
        return unicode(v)
    return unicode(v).strip()


def _merge_csv_matrix_header_at(matrix, hdr_row, col):
    if hdr_row is None or int(hdr_row) < 0:
        return _merge_synthetic_column_header(col)
    t = _merge_csv_matrix_cell_text(matrix, int(hdr_row), col)
    try:
        from libre_macros_header_lib import clean_header_name
        t = clean_header_name(t)
    except Exception:
        pass
    return t


def _merge_csv_build_column_list(matrix, col_specs, col_kind, hdr_row, start_col, col_count, no_header=False, probe_row_0=None, header_titles=None):
    """Как build_column_list, но по матрице CSV."""
    if not matrix:
        return []
    n_cols = len(matrix[0])
    result = []
    seen = []
    probe_row = int(probe_row_0) if probe_row_0 is not None else int(hdr_row if hdr_row is not None and int(hdr_row) >= 0 else 0)

    def _title_at(c):
        if header_titles is not None:
            t = header_titles.get(c)
            if t:
                return t
            return _merge_synthetic_column_header(c)
        return _merge_csv_matrix_header_at(matrix, hdr_row, c)

    if col_kind == 'ALL':
        if header_titles is not None:
            for c in sorted(header_titles.keys()):
                h = header_titles.get(c) or _merge_synthetic_column_header(c)
                if _is_service_header(h):
                    continue
                result.append((c, h))
            return result
        c = int(start_col or 0)
        limit = c + col_count if col_count else c + 500
        if limit > n_cols:
            limit = n_cols
        while c < limit:
            if no_header:
                if col_count is None and _merge_csv_matrix_cell_text(matrix, probe_row, c) == u'':
                    break
                h = _merge_synthetic_column_header(c)
            else:
                h = _title_at(c)
                if h == u'' and col_count is None:
                    break
            if _is_service_header(h):
                c = c + 1
                continue
            result.append((c, h if h != u'' else _merge_synthetic_column_header(c)))
            c = c + 1
        return result
    for spec in col_specs or []:
        st = unicode(spec or u'').strip()
        if st == u'':
            continue
        if col_kind == 'INDEX':
            try:
                c = int(st) - 1
            except (TypeError, ValueError):
                continue
            if c < 0 or c >= n_cols or c in seen:
                continue
            if no_header:
                h = _merge_synthetic_column_header(c)
            else:
                h = _title_at(c)
            if _is_service_header(h):
                continue
            seen.append(c)
            result.append((c, h if h != u'' else _merge_synthetic_column_header(c)))
            continue
        elif col_kind == 'LETTER':
            c = col_letters_to_index(st)
            if c < 0 or c >= n_cols or c in seen:
                continue
            if no_header:
                h = _merge_synthetic_column_header(c)
            else:
                h = _title_at(c)
            if _is_service_header(h):
                continue
            seen.append(c)
            result.append((c, h if h != u'' else _merge_synthetic_column_header(c)))
            continue
        else:
            if no_header:
                continue
            match_fn = None
            try:
                from libre_macros_param_codec import column_header_matches_token
                match_fn = column_header_matches_token
            except Exception:
                match_fn = None
            if header_titles is not None:
                for hc, ht in sorted(header_titles.items()):
                    if hc in seen or hc < 0 or hc >= n_cols:
                        continue
                    ok = match_fn(ht, st) if match_fn is not None else text_match(ht, st)
                    if not ok:
                        continue
                    h = ht or _merge_synthetic_column_header(hc)
                    if _is_service_header(h):
                        continue
                    seen.append(hc)
                    result.append((hc, h if h != u'' else _merge_synthetic_column_header(hc)))
            else:
                scan = int(start_col or 0)
                scan_end = scan + 300
                if scan_end > n_cols:
                    scan_end = n_cols
                while scan < scan_end:
                    if scan in seen:
                        scan = scan + 1
                        continue
                    ht = _merge_csv_matrix_header_at(matrix, hdr_row, scan)
                    ok = match_fn(ht, st) if match_fn is not None else text_match(ht, st)
                    if ok:
                        h = _title_at(scan)
                        if not _is_service_header(h):
                            seen.append(scan)
                            result.append((scan, h if h != u'' else _merge_synthetic_column_header(scan)))
                    scan = scan + 1
    return result


def _merge_csv_data_row_indices(matrix, first_data_row_0, row_count, hdr_row=None, start_col=0, col_count=None, last_row_col_spec=''):
    """Индексы строк данных матрицы (аналог data_rows_from_sheet)."""
    if not matrix:
        return []
    try:
        first = int(first_data_row_0)
    except (TypeError, ValueError):
        first = 0
    if first < 0:
        first = 0
    last = len(matrix) - 1
    spec = unicode(last_row_col_spec or u'').strip()
    if spec != u'' and matrix:
        resolved, _missing = _merge_csv_resolve_skip_column_indices(
            matrix, hdr_row, start_col, col_count, [spec]
        )
        if resolved:
            scan_col = int(resolved[0])
            def _suffix_has_value(lo_row, hi_row):
                rr = int(lo_row)
                hi = int(hi_row)
                while rr <= hi:
                    row_vals = matrix[rr] if rr < len(matrix) else []
                    val = row_vals[scan_col] if scan_col < len(row_vals) else u''
                    if not _merge_csv_matrix_value_empty(val):
                        return True
                    rr = rr + 1
                return False

            lo = int(first)
            hi = int(last)
            best = first - 1
            while lo <= hi:
                mid = (lo + hi) // 2
                if _suffix_has_value(mid, last):
                    best = mid
                    lo = mid + 1
                else:
                    hi = mid - 1
            if best >= first:
                last = int(best)
            else:
                return []
    if last < first:
        return []
    available = last - first + 1
    if row_count is None:
        n = available
    else:
        try:
            n = int(row_count)
        except (TypeError, ValueError):
            n = available
        if n > available:
            n = available
        if n < 0:
            n = 0
    out = []
    i = 0
    while i < n:
        out.append(first + i)
        i = i + 1
    return out


def _merge_csv_matrix_value_empty(v):
    if v is None:
        return True
    if isinstance(v, (int, float)) and (not isinstance(v, bool)):
        return False
    return unicode(v).strip() == u''


def _merge_csv_resolve_skip_column_indices(matrix, hdr_row, start_col, col_count, parts):
    indices = []
    missing = []
    n_cols = len(matrix[0]) if matrix else 0
    match_fn = None
    unwrap = None
    try:
        from libre_macros_param_codec import column_header_matches_token, unwrap_column_name_token
        match_fn = column_header_matches_token
        unwrap = unwrap_column_name_token
    except Exception:
        match_fn = None
        unwrap = None
    for part in parts or []:
        st_raw = unicode(part or u'').strip()
        if st_raw == u'':
            continue
        st = st_raw
        quoted = False
        if unwrap is not None:
            try:
                st, quoted = unwrap(st_raw)
                st = unicode(st or u'').strip()
            except Exception:
                st = st_raw
                quoted = False
        c = -1
        if (not quoted) and st.isdigit():
            try:
                c = int(st) - 1
            except (TypeError, ValueError):
                c = -1
        elif (not quoted) and is_col_letters(st):
            c = col_letters_to_index(st)
        else:
            scan = int(start_col or 0)
            limit = scan + (int(col_count) if col_count else 300)
            if limit > n_cols:
                limit = n_cols
            while scan < limit:
                ht = _merge_csv_matrix_header_at(matrix, hdr_row, scan)
                ok = match_fn(ht, st_raw) if match_fn is not None else text_match(ht, st)
                if ok:
                    c = scan
                    break
                scan = scan + 1
        if c >= 0 and c < n_cols:
            if c not in indices:
                indices.append(c)
        else:
            missing.append(st_raw)
    return (indices, missing)


def _merge_csv_prepare_data_rows_with_skip(matrix, hdr_row, start_col, row_count, col_count, skip_spec_text, report, fname, sheet_label, first_data_row_0=None, last_row_col_spec=''):
    """Строки данных CSV-матрицы + пропуск по столбцам (формула — не для CSV)."""
    if first_data_row_0 is None:
        first_data_row_0 = int(hdr_row) + 1 if hdr_row is not None and int(hdr_row) >= 0 else 0
    data_rows = _merge_csv_data_row_indices(
        matrix,
        first_data_row_0,
        row_count,
        hdr_row=hdr_row,
        start_col=start_col,
        col_count=col_count,
        last_row_col_spec=last_row_col_spec,
    )
    parsed = parse_skip_row_spec(skip_spec_text, source_sheet_name=sheet_label)
    if parsed.get('mode') == 'none':
        return (data_rows, 0, True)
    if parsed.get('mode') == 'formula':
        if report is not None:
            report.problem(
                u'«%s» / «%s»: пропуск по формуле для CSV не поддерживается (нужен UNO-лист) — игнор'
                % (fname, sheet_label)
            )
        return (data_rows, 0, True)
    if parsed.get('mode') == 'columns':
        col_indices, missing_parts = _merge_csv_resolve_skip_column_indices(
            matrix, hdr_row, start_col, col_count, parsed.get('parts') or []
        )
        if len(col_indices) == 0:
            if report is not None:
                report.problem(
                    u'«%s» / «%s»: «%s» — не найдены столбцы «%s»'
                    % (
                        fname,
                        sheet_label,
                        _cw_cfg.P_MERGE_SKIP_SOURCE_ROWS,
                        u', '.join(missing_parts) if missing_parts else unicode(skip_spec_text or u''),
                    )
                )
            return (data_rows, 0, True)
        out = []
        skipped = 0
        for sr in data_rows:
            empty_all = True
            for c in col_indices:
                if not _merge_csv_matrix_value_empty(matrix[sr][c] if c < len(matrix[sr]) else u''):
                    empty_all = False
                    break
            if empty_all:
                skipped = skipped + 1
            else:
                out.append(sr)
        if skipped > 0 and report is not None:
            report.stats['rows_skipped'] = report.stats.get('rows_skipped', 0) + skipped
        return (out, skipped, True)
    return (data_rows, 0, True)


def _merge_csv_apply_formats_on_target_cols(doc, ts, out_row0, rows_n, cols, conv_meta):
    """NumberFormat целевых столбцов после записи CSV-матрицы."""
    if doc is None or ts is None or rows_n < 1 or not conv_meta:
        return
    date_cols = conv_meta.get('date_cols') or set()
    num_cols = conv_meta.get('num_cols') or set()
    explicit_fmt = conv_meta.get('explicit_fmt_by_col') or {}
    if not date_cols and not num_cols and not explicit_fmt:
        return
    try:
        import libre_macros_direct_lib as direct
    except Exception:
        return
    date_fmt_by_col = conv_meta.get('date_fmt_by_col') or {}
    end_row = out_row0 + rows_n - 1
    ci = 0
    while ci < len(cols):
        sc = cols[ci][0]
        hname = cols[ci][1]
        if _merge_uses_header_column_matching():
            tc = find_or_create_header_column(ts, hname)
        else:
            tc = merge_get_first_data_col() + ci
        if tc < 0:
            ci = ci + 1
            continue
        nf_key = None
        if sc in explicit_fmt:
            nf_key = _merge_uno_nf_key_for_format(doc, explicit_fmt.get(sc))
        elif sc in date_cols:
            fmt = date_fmt_by_col.get(sc) or direct._direct_default_date_format()
            nf_key = _merge_uno_nf_key_for_format(doc, fmt)
        elif sc in num_cols:
            num_fmt = direct._direct_default_number_format()
            if num_fmt:
                nf_key = _merge_uno_nf_key_for_format(doc, num_fmt)
        if nf_key is not None:
            try:
                rng = ts.getCellRangeByPosition(int(tc), int(out_row0), int(tc), int(end_row))
                rng.NumberFormat = int(nf_key)
            except Exception:
                pass
        ci = ci + 1


def _merge_csv_write_matrix_by_headers(ts, matrix, cols, data_rows, out_row, report, fname, tname):
    """Запись матрицы на результат: матчинг заголовков, setDataArray по столбцам (CSV / книга в памяти)."""
    import time
    rows_n = len(data_rows)
    if rows_n == 0 or not cols:
        return out_row
    chunk = _merge_ui_dialog_copy_chunk()
    if chunk < 1:
        chunk = 1000
    t0 = time.time()
    di = 0
    while di < rows_n:
        end = di + chunk
        if end > rows_n:
            end = rows_n
        chunk_rows = data_rows[di:end]
        tr0 = out_row + di
        tr1 = tr0 + len(chunk_rows) - 1
        t_ch = time.time()
        ci = 0
        while ci < len(cols):
            sc = cols[ci][0]
            hname = cols[ci][1]
            tc = find_or_create_header_column(ts, hname)
            if tc >= 0:
                block = []
                for sr in chunk_rows:
                    v = matrix[sr][sc] if sc < len(matrix[sr]) else u''
                    block.append((_merge_csv_parsed_to_array_value(v),))
                try:
                    rng = ts.getCellRangeByPosition(tc, tr0, tc, tr1)
                    rng.setDataArray(tuple(block))
                except Exception as err:
                    if report is not None:
                        report.problem(
                            u'матрица setDataArray «%s»/«%s» col «%s»: %s' % (fname, tname, hname, err)
                        )
            ci = ci + 1
        _merge_matrix_write_console_log(
            u'write headers chunk rows %d–%d (n=%d cols=%d): %.1f ms'
            % (di + 1, end, end - di, len(cols), (time.time() - t_ch) * 1000.0)
        )
        if report is not None:
            report.stats['rows_copied'] = report.stats.get('rows_copied', 0) + len(chunk_rows)
        merge_ui_yield(force=True)
        if merge_ui_poll_abort():
            return out_row + end
        di = end
    _merge_matrix_write_console_log(
        u'write by headers total: %.1f ms | rows=%d cols=%d chunk=%d'
        % ((time.time() - t0) * 1000.0, rows_n, len(cols), chunk)
    )
    return out_row + rows_n


def _merge_csv_write_matrix_by_position(ts, matrix, cols, data_rows, out_row, hdr_row, report, fname, tname):
    """Запись матрицы на результат: буфер по позиции (прямоугольник setDataArray; CSV / книга в памяти)."""
    import time
    rows_n = len(data_rows)
    if rows_n == 0 or not cols:
        return out_row
    tc0 = merge_get_first_data_col()
    # Заголовки один раз (как _merge_copy_positional_header_row)
    if out_row == 1:
        try:
            if cell_text(ts.getCellByPosition(tc0, 0)) == '':
                hi = 0
                while hi < len(cols):
                    try:
                        ts.getCellByPosition(tc0 + hi, 0).String = cols[hi][1]
                    except Exception:
                        pass
                    hi = hi + 1
        except Exception:
            pass
    chunk = _merge_ui_dialog_copy_chunk()
    if chunk < 1:
        chunk = 1000
    t0 = time.time()
    n_cols = len(cols)
    di = 0
    while di < rows_n:
        end = di + chunk
        if end > rows_n:
            end = rows_n
        chunk_rows = data_rows[di:end]
        tr0 = out_row + di
        tr1 = tr0 + len(chunk_rows) - 1
        t_ch = time.time()
        block = []
        for sr in chunk_rows:
            row_out = []
            ci = 0
            while ci < n_cols:
                sc = cols[ci][0]
                v = matrix[sr][sc] if sc < len(matrix[sr]) else u''
                row_out.append(_merge_csv_parsed_to_array_value(v))
                ci = ci + 1
            block.append(tuple(row_out))
        try:
            rng = ts.getCellRangeByPosition(tc0, tr0, tc0 + n_cols - 1, tr1)
            rng.setDataArray(tuple(block))
        except Exception as err:
            if report is not None:
                report.problem(u'матрица setDataArray позиция «%s»/«%s»: %s' % (fname, tname, err))
        _merge_matrix_write_console_log(
            u'write position chunk rows %d–%d (n=%d × %d): %.1f ms'
            % (di + 1, end, end - di, n_cols, (time.time() - t_ch) * 1000.0)
        )
        if report is not None:
            report.stats['rows_copied'] = report.stats.get('rows_copied', 0) + len(chunk_rows)
        merge_ui_yield(force=True)
        if merge_ui_poll_abort():
            return out_row + end
        di = end
    _unused = hdr_row
    _merge_matrix_write_console_log(
        u'write by position total: %.1f ms | rows=%d cols=%d chunk=%d'
        % ((time.time() - t0) * 1000.0, rows_n, n_cols, chunk)
    )
    return out_row + rows_n


def _merge_append_csv_matrix_to_target(target_doc, ts, matrix, conv_meta, blk, col_specs, col_kind, skip_spec, out_row, report, fname, tname, src_label, fpath, path_display, fi, col_rename_items=None):
    """
    CSV-матрица → лист результата (one/many).

    По заголовкам: По_API и буфер_по_заголовкам.
    По позиции: буфер_по_позиции (прямоугольник, как копирование листов по колонкам).
    """
    if ts is None or not matrix:
        return out_row
    start_col = (blk or {}).get('start_col', 0)
    row_count = (blk or {}).get('row_count')
    col_count = (blk or {}).get('col_count')
    hdr_row, start_row_0, no_header, skipped_top_0 = _merge_block_matrix_collect_params(blk)
    hdr_titles = _merge_header_titles_for_matrix(matrix, blk, start_col, col_count)
    cols = _merge_csv_build_column_list(
        matrix, col_specs, col_kind, hdr_row, start_col, col_count,
        no_header=no_header, probe_row_0=start_row_0, header_titles=hdr_titles,
    )
    cols = _merge_apply_col_rename_items(cols, col_rename_items)
    if len(cols) == 0:
        if report is not None:
            report.problem(u'CSV «%s»: нет столбцов по фильтру — пропуск.' % fname)
            report.log_stat(src_label, tname, '', 0, 'пропуск', 'нет столбцов')
            report.stats['sheets_skipped'] = report.stats.get('sheets_skipped', 0) + 1
        return out_row
    _merge_note_result_skipped_top(ts.Name, skipped_top_0)
    if _merge_uses_header_column_matching():
        ensure_target_headers(ts, cols)
    last_row_col_spec = u''
    try:
        from libre_macros_source_extra_lib import source_extra_last_row_column

        last_row_col_spec = source_extra_last_row_column(_merge_source_extra_for_fi(fi))
    except Exception:
        last_row_col_spec = u''
    t_rows = time.time()
    data_rows, _skip_n, _allow = _merge_csv_prepare_data_rows_with_skip(
        matrix, hdr_row, start_col, row_count, col_count, skip_spec, report, fname, tname,
        first_data_row_0=start_row_0,
        last_row_col_spec=last_row_col_spec,
    )
    rows_elapsed_ms = (time.time() - t_rows) * 1000.0
    rows_n = len(data_rows)
    first_row_0 = data_rows[0] if rows_n > 0 else None
    last_row_0 = data_rows[-1] if rows_n > 0 else None
    _merge_log_last_row_column_usage(
        report, src_label, tname, last_row_col_spec, rows_n,
        first_row_0=first_row_0, last_row_0=last_row_0, elapsed_ms=rows_elapsed_ms,
    )
    layout = merge_active_service_layout()
    row_label, mtime_str, file_key = _merge_service_row_context(fpath, False, tname, layout, path_display)
    write_start = out_row
    if rows_n > 0:
        _merge_fill_service_columns(
            ts, out_row, rows_n, row_label, mtime_str,
            file_key=file_key, source_sheet_name=tname,
        )
    transfer = _merge_active_data_transfer_mode()
    mode_label = u'headers'
    if transfer == _cw_cfg.MERGE_TRANSFER_CLIPBOARD_POSITION or (not _merge_uses_header_column_matching()):
        mode_label = u'position'
        _merge_csv_console_log(u'режим записи: буфер по позиции → «%s»' % (getattr(ts, 'Name', '') or u''))
        out_row = _merge_csv_write_matrix_by_position(
            ts, matrix, cols, data_rows, out_row, hdr_row, report, fname, tname
        )
    else:
        _merge_csv_console_log(
            u'режим записи: по заголовкам (%s) → «%s»'
            % (transfer or u'По_API', getattr(ts, 'Name', '') or u'')
        )
        out_row = _merge_csv_write_matrix_by_headers(
            ts, matrix, cols, data_rows, out_row, report, fname, tname
        )
    if rows_n > 0:
        _merge_csv_apply_formats_on_target_cols(target_doc, ts, write_start, rows_n, cols, conv_meta or {})
    if report is not None:
        report.stats['sheets_done'] = report.stats.get('sheets_done', 0) + 1
        ci = 0
        while ci < len(cols):
            sc = cols[ci][0]
            hname = cols[ci][1]
            report.log_stat(
                src_label, tname, '%s (%s)' % (col_label(sc), hname), rows_n,
                u'CSV→%s' % mode_label, block_settings_note(blk),
            )
            ci = ci + 1
    _unused_fi = fi
    return out_row


def _merge_create_sheet_from_csv_file(target_doc, fpath, fi, sheet_specs, target_name, report=None, col_map_items=None):
    """
    CSV → текст → матрица (числа/даты в памяти) → новый лист + setDataArray + NumberFormat.

    Возвращает XSpreadsheet или None.
    """
    import time
    t_total = time.time()
    _unused_specs = sheet_specs
    matrix, conv_meta = _merge_load_csv_source_matrix(
        target_doc, fpath, fi, col_map_items=col_map_items
    )
    if not matrix:
        if report is not None:
            report.problem(u'Не удалось прочитать CSV «%s»' % fpath)
        return None
    n_rows = len(matrix)
    n_cols = len(matrix[0])
    _merge_csv_console_log(u'→ лист «%s» (copy sheets)' % target_name)
    try:
        pos = target_doc.Sheets.getCount()
        t_ins = time.time()
        target_doc.Sheets.insertNewByName(target_name, pos)
        ms_ins = (time.time() - t_ins) * 1000.0
        _merge_csv_console_log(u'insertNewByName «%s»: %.1f ms' % (target_name, ms_ins))
    except Exception as err:
        if report is not None:
            report.problem(u'Не удалось создать лист «%s»: %s' % (target_name, err))
        return None
    sheet = get_sheet(target_doc, target_name)
    if sheet is None:
        return None
    try:
        write_stats = _merge_write_matrix_set_data_array(
            sheet, matrix, report=report, status_label=short_name(fpath) or target_name
        )
    except Exception:
        return None
    _merge_csv_console_log(
        u'setDataArray итог: %.1f ms | chunk=%d chunks=%d rows=%d cols=%d'
        % (
            float(write_stats.get('ms_total') or 0.0),
            int(write_stats.get('chunk') or 0),
            int(write_stats.get('chunks_n') or 0),
            int(write_stats.get('n_rows') or 0),
            int(write_stats.get('n_cols') or 0),
        )
    )
    ms_fmt = 0.0
    if conv_meta and (not conv_meta.get('skipped')) and (
        conv_meta.get('date_cols') or conv_meta.get('num_cols')
    ):
        ms_fmt = _merge_csv_apply_converted_number_formats(
            target_doc, sheet, n_rows, conv_meta
        )
        _merge_csv_console_log(u'NumberFormat столбцов: %.1f ms' % ms_fmt)
        _merge_csv_mark_skip_number_date_convert(
            target_name, reason=u'числа/даты уже в матрице'
        )
    ms_total = (time.time() - t_total) * 1000.0
    _merge_csv_console_log(
        u'ГОТОВО лист «%s»: total=%.1f ms (read=%.1f build=%.1f convert=%.1f write=%.1f fmt=%.1f)'
        % (
            target_name,
            ms_total,
            float((conv_meta or {}).get('ms_read') or 0.0),
            float((conv_meta or {}).get('ms_build') or 0.0),
            float((conv_meta or {}).get('ms_convert_wall') or 0.0),
            float(write_stats.get('ms_total') or 0.0),
            ms_fmt,
        )
    )
    merge_debug(
        'merge_on_copy_sheets.csv',
        'sheet=%s rows=%d cols=%d dt=%d num=%d total_ms=%.1f'
        % (
            target_name,
            n_rows,
            n_cols,
            int((conv_meta or {}).get('converted_dt') or 0),
            int((conv_meta or {}).get('converted_num') or 0),
            ms_total,
        ),
    )
    return sheet


def _merge_copy_sheets_pp_bounds(sheet, blk):
    """
    Границы постобработки на уже скопированном листе (0-based): header_row, end_col, end_row, rows_n.

    Вызывается только ПОСЛЕ importSheet/copyByName — на листе в книге результата.
    К источнику и его ячейкам до копирования не обращается.

    Если в блоке не заданы «Число_Строк»/«Число_Столбцов»/«Строка_Заголовков» и границы по умолчанию
    (строка 1, столбец 1) — значащая область скопированного листа, первая её строка = заголовок.
    Иначе — по параметрам блока (как в режимах слияния по ячейкам).
    """
    used_sc, used_sr, used_ec, used_er = get_sheet_used_area(sheet)
    if used_er < used_sr:
        used_ec, used_er = get_sheet_used_bounds(sheet)
        used_sc, used_sr = (0, 0)
    auto_extent = blk.get('row_count') is None and blk.get('col_count') is None and (not blk.get('header_row_explicit', False)) and (not blk.get('no_header', False)) and (str(blk.get('start_row_disp', '1')).strip() in ('', '1')) and (str(blk.get('start_col_disp', '1')).strip() in ('', '1'))
    if auto_extent:
        if used_er < used_sr:
            return (0, max(0, used_ec), max(0, used_er), 0)
        header_row = used_sr
        end_col = used_ec
        end_row = used_er
        rows_n = max(0, end_row - header_row)
        return (header_row, end_col, end_row, rows_n)
    if blk.get('no_header'):
        first_data = int(blk.get('start_row_0', 0))
        start_col = int(blk.get('start_col', 0))
        row_count = blk.get('row_count')
        col_count = blk.get('col_count')
        if col_count is not None and int(col_count) > 0:
            end_col = start_col + int(col_count) - 1
        else:
            end_col = max(start_col, used_ec)
        if row_count is not None and int(row_count) > 0:
            end_row = first_data + int(row_count) - 1
        else:
            end_row = max(first_data, used_er)
        rows_n = max(0, end_row - first_data + 1)
        return (-1, end_col, end_row, rows_n)
    hdr_row = _merge_copy_sheets_hdr_row_after_trim(sheet, blk)
    start_col = int(blk.get('start_col', 0))
    row_count = blk.get('row_count')
    col_count = blk.get('col_count')
    first_data = _merge_block_first_data_row_0(blk)
    if col_count is not None and int(col_count) > 0:
        end_col = start_col + int(col_count) - 1
    else:
        end_col = max(start_col, used_ec)
    if row_count is not None and int(row_count) > 0:
        end_row = first_data + int(row_count) - 1
    else:
        end_row = max(first_data, used_er)
    rows_n = max(0, end_row - hdr_row)
    return (hdr_row, end_col, end_row, rows_n)

def merge_involve_sheets(target_doc, per_file_sheet_specs, per_file_blocks, report):
    """
    Режим «Текущие листы»: без копирования/слияния — существующие вкладки
    текущей книги сразу в sheets_info → оформление (preexisting-skip) →
    pipeline постобработки. Финальная_обработка — в finally run_collect_merge.
    """
    merge_debug('merge_involve_sheets', 'begin')
    if target_doc is None:
        if report is not None:
            report.problem('Нет книги результата для вовлечения листов.')
        return False
    sheet_specs = per_file_sheet_specs[0] if per_file_sheet_specs else []
    sheet_kind = classify_sheet_specs(sheet_specs)
    if sheet_kind == 'MIXED':
        if report is not None:
            report.problem('В «Листы» один тип в списке: только номера или только имена/шаблоны.')
        return False
    if per_file_blocks and len(per_file_blocks) > 0:
        blk = per_file_blocks[0]
    else:
        blk = parse_block_from_strings('1', '1', '', '', '')
    sheets = []
    involved_names = []
    for slot in _iter_sheet_slots_current_book(target_doc, sheet_specs, sheet_kind):
        if report is not None and _merge_stop_if_aborted(report):
            break
        sname = slot.get('source_name') or ''
        try:
            sh = target_doc.Sheets.getByName(sname)
        except Exception:
            sh = None
        if sh is None:
            if report is not None:
                report.problem('Лист для вовлечения не найден: %s' % sname)
            return False
        sheets.append(sh)
        involved_names.append(sname)
        if report is not None:
            report.log_stat('(текущая книга)', sname, sname, '', 'вовлечение', 'без копирования | %s' % block_settings_note(blk))
            report.stats['sheets_done'] = report.stats.get('sheets_done', 0) + 1
    if not sheets:
        if report is not None:
            report.problem('Нет листов для вовлечения.')
        return False
    _cw_set('_MERGE_INVOLVED_SHEET_NAMES', frozenset(involved_names))
    merge_debug(
        'merge_involve_sheets',
        'involved n=%d names=%s' % (len(involved_names), involved_names[:40]),
    )
    if report is not None:
        report.step('Вовлечение листов: %d' % len(sheets))
        report.status('Вовлечено: %s' % ', '.join(involved_names[:12]))
        append_collect_log(
            target_doc,
            '',
            '',
            '',
            '',
            'вовлечение',
            'листов=%d: %s' % (len(involved_names), ', '.join(involved_names)),
        )
    all_sheets_info = _merge_build_sheets_info_from_sheets(target_doc, sheets, blk)
    if report is not None and report._current_stage == 'data_collection':
        try:
            report.end_stage('data_collection')
        except Exception:
            pass
    if _merge_stop_if_aborted(report):
        return False
    # Снять унаследованные/старые именованные DatabaseRange до оформления.
    try:
        from libre_macros_split_lib import _split_clear_database_ranges
        dropped = _split_clear_database_ranges(target_doc, keep_anonymous=False)
        if dropped:
            merge_debug(
                'merge_involve_sheets',
                'cleared DatabaseRanges n=%d' % len(dropped),
            )
    except Exception as err:
        merge_debug('merge_involve_sheets', 'clear DatabaseRanges: %s' % err)
    _merge_run_split_sheets_deferred_phase(target_doc, 'after_collect', report=report, sheets_info=all_sheets_info)
    _merge_apply_builtin_then_book_pipeline(target_doc, all_sheets_info, report=report)
    merge_debug('merge_involve_sheets', 'done n=%d' % len(sheets))
    return True


def merge_on_copy_sheets(target_doc, files, is_current_book_flags, per_file_sheet_specs, per_file_col_specs, per_file_blocks, per_file_skip_row_specs, path_display, cell_to_column_plan, report, skip_phase2=False, per_file_col_rename_items=None):
    """
    Режим «Копирование листов»: целые листы-источники как вкладки результата.

    Две фазы на файл:
      1) xlsx/ods/… → importSheet; .csv → текст (encoding/delimiter) → матрица с
         числами/датами в памяти → insertNewByName + setDataArray + NumberFormat →
         (для CSV открытия Calc нет; UNO-конвертация текста пропускается);
      2) на листе в результате — обрезка строк, встроенное оформление, постобработка.

    «Ячейка_В_Столбец»: снимок с источника при открытии, столбец на копии до обрезки/удаления
    (заголовок — Строка_Заголовков). Для CSV без UNO-источника — не применяется.
    """
    merge_debug('merge_on_copy_sheets', 'files=%d' % len(files))
    _cw_cfg._MERGE_COPY_SHEETS_BLOCK_BY_NAME = {}
    _cw_cfg._MERGE_COPY_SHEETS_FILE_INDEX = {}
    _cw_cfg._MERGE_CSV_PRECONVERTED_SHEETS = set()
    _unused = per_file_skip_row_specs
    ctc_per_file_specs = build_cell_to_column_per_file_specs(cell_to_column_plan, len(files))
    cell_to_column_cache = {}
    try:
        _ensure_pp_from_lib()
    except Exception:
        pass
    used_names = set()
    for svc_name in _cw_cfg.MERGE_SHEETS_UNDELETE_DEFAULT:
        used_names.add(svc_name)
    si = 0
    while si < target_doc.Sheets.getCount():
        try:
            used_names.add(target_doc.Sheets.getByIndex(si).Name)
        except Exception:
            pass
        si = si + 1
    any_sheet = False
    last_copied_sheet = None
    all_sheets_info = []
    fi = 0
    while fi < len(files):
        if _merge_stop_if_aborted(report):
            break
        merge_debug('merge_on_copy_sheets.file', 'fi=%d/%d' % (fi + 1, len(files)))
        is_current_book = is_current_book_flags[fi] if fi < len(is_current_book_flags) else False
        is_csv_source = False
        csv_use_memory = False
        csv_shadow_xlsx = False
        col_rename_items_loop = []
        if per_file_col_rename_items and fi < len(per_file_col_rename_items):
            col_rename_items_loop = per_file_col_rename_items[fi] or []
        if is_current_book:
            fpath = get_current_book_path()
            fname = short_name(fpath) if fpath else '(текущая книга)'
            src_label = '(текущая книга)'
            src = target_doc
        else:
            fpath = os.path.abspath(files[fi])
            fname = short_name(fpath)
            src_label = format_source_path(fpath, path_display_for_file_key(path_display))
            sheet_specs = per_file_sheet_specs[fi] if fi < len(per_file_sheet_specs) else []
            is_csv_source = _merge_path_is_csv(fpath)
            csv_whole_sheet = False
            csv_shadow_xlsx = False
            if is_csv_source:
                try:
                    from libre_macros_csv_source_lib import (
                        source_extra_copy_whole_sheet,
                        source_extra_open_as_xlsx,
                    )
                    extra = _merge_source_extra_for_fi(fi)
                    csv_whole_sheet = bool(
                        source_extra_copy_whole_sheet(extra)
                    )
                    csv_shadow_xlsx = bool(source_extra_open_as_xlsx(extra))
                except Exception:
                    csv_whole_sheet = False
                    csv_shadow_xlsx = False
            # По умолчанию CSV → temp xlsx (open_as_xlsx=true); матрица только при явном false.
            # copy_whole_sheet=true → Calc + importSheet (без теневого xlsx, если open_as_xlsx=false).
            csv_use_memory = bool(is_csv_source) and (not csv_whole_sheet) and (not csv_shadow_xlsx)
            if csv_use_memory:
                src = None
                _merge_csv_console_log(
                    u'копирование листов: %s → матрица/setDataArray (copy_whole_sheet=нет)'
                    % fname
                )
            else:
                if is_csv_source and csv_whole_sheet:
                    _merge_csv_console_log(
                        u'копирование листов: %s → открытие в Calc + лист целиком (copy_whole_sheet=да)'
                        % fname
                    )
                elif is_csv_source and csv_shadow_xlsx:
                    _merge_csv_console_log(
                        u'копирование листов: %s → теневая схема csv->xlsx (open_as_xlsx=да)'
                        % fname
                    )
                src = _merge_open_source_for_file(fpath, fi, writable=False, sheet_specs=sheet_specs)
        if not is_current_book and (not csv_use_memory) and src is None:
            report.problem('Не удалось открыть файл: %s' % fpath)
            fi = fi + 1
            continue
        sheet_specs = per_file_sheet_specs[fi] if fi < len(per_file_sheet_specs) else []
        sheet_kind = classify_sheet_specs(sheet_specs)
        if fi < len(per_file_blocks):
            blk = per_file_blocks[fi]
        elif len(per_file_blocks) > 0:
            blk = per_file_blocks[0]
        else:
            blk = parse_block_from_strings('1', '1', '', '', '')
        report.step('Файл %d/%d: %s' % (fi + 1, len(files), fname))
        _merge_ui_collect_file_start(report, fi + 1, len(files), fname)
        report.log_stat(src_label, '', '', '', 'файл', 'копирование листов | %s' % block_settings_note(blk))
        log_fpath = fpath if not is_current_book else get_current_book_path() or ''
        file_key = cell_to_column_file_key(log_fpath, path_display)
        ctc_specs = ctc_per_file_specs[fi] if fi < len(ctc_per_file_specs) else []
        try:
            if blk and blk.get('no_header'):
                header_row_0 = max(0, int(blk.get('start_row_0', 0)))
            else:
                _hr, last_1 = _merge_block_header_first_last_1(blk)
                header_row_0 = max(0, int(last_1) - 1) if last_1 else 0
        except (TypeError, ValueError):
            header_row_0 = 0
        copied_jobs = []
        try:
            if csv_use_memory:
                tname = _merge_csv_logical_sheet_title(fpath)
                if not _merge_csv_included_by_sheet_specs(tname, sheet_specs, sheet_kind):
                    report.stats['sheets_skipped'] = report.stats.get('sheets_skipped', 0) + 1
                    report.log_stat(src_label, '', tname, '', 'пропуск', 'CSV не входит в фильтр «Листы»')
                else:
                    desired = _merge_csv_resolve_target_name(tname, sheet_specs)
                    target_name = _merge_copy_sheets_resolve_name(target_doc, desired, used_names)
                    report.status(u'  → CSV «%s» ← %s (setDataArray)' % (target_name, fname))
                    if _merge_ui_is_dialog_mode():
                        merge_ui_yield(force=True)
                    copied = _merge_create_sheet_from_csv_file(
                        target_doc, fpath, fi, sheet_specs, target_name, report=report,
                        col_map_items=col_rename_items_loop,
                    )
                    if copied is None:
                        report.stats['sheets_skipped'] = report.stats.get('sheets_skipped', 0) + 1
                    else:
                        any_sheet = True
                        last_copied_sheet = copied
                        report.stats['sheets_done'] = report.stats.get('sheets_done', 0) + 1
                        _cw_cfg._MERGE_COPY_SHEETS_BLOCK_BY_NAME[target_name] = blk
                        _cw_cfg._MERGE_COPY_SHEETS_FILE_INDEX[target_name] = fi
                        if ctc_specs:
                            report.log_stat(
                                src_label, target_name, tname, '', 'инфо',
                                u'Ячейка_В_Столбец для CSV пропущена (нет UNO-источника)',
                            )
                        copied_jobs.append((copied, target_name, tname, True))
                        report.log_stat(src_label, target_name, tname, '', 'CSV→лист', block_settings_note(blk))
                        _merge_undo_clear(target_doc, 'source:%s|%s' % (src_label, target_name), defer_ok=False)
            else:
                if is_current_book:
                    slots = _iter_sheet_slots_current_book(src, sheet_specs, sheet_kind)
                else:
                    slots = iter_sheet_slots(src, sheet_specs, sheet_kind)
                    if is_csv_source:
                        slots = _merge_csv_name_slots_for_shadow(src, fpath, list(slots))
                for slot in slots:
                    if _merge_stop_if_aborted(report):
                        break
                    src_sheet_name = slot['source_name']
                    tname = src_sheet_name
                    if is_csv_source:
                        logical = _merge_csv_logical_sheet_title(fpath)
                        if merge_identity_key(tname) == merge_identity_key(u'CSV'):
                            tname = logical
                    # rename target из слота (JSON/«Старое->Новое»), иначе имя источника
                    desired = slot.get('target_key') or tname
                    if is_csv_source and merge_identity_key(unicode(desired or u'')) == merge_identity_key(u'CSV'):
                        desired = tname
                    target_name = _merge_copy_sheets_resolve_name(target_doc, desired, used_names)
                    if is_csv_source and (not csv_shadow_xlsx):
                        report.status(u'  → CSV «%s» ← %s (importSheet)' % (target_name, tname))
                    else:
                        report.status('  → копия «%s» ← %s' % (target_name, tname))
                    if _merge_ui_is_dialog_mode():
                        merge_ui_yield(force=True)
                    maybe_prefetch_cell_to_column(cell_to_column_cache, ctc_per_file_specs, fi, fpath if not is_current_book else '', is_current_book, path_display, src_sheet_name, src)
                    maybe_prefetch_add_to_variables_map(_cw_cfg._MERGE_ADD_TO_VARIABLES_PER_FILE, fi, fpath if not is_current_book else '', is_current_book, path_display, src_sheet_name, src, report=report)
                    copied = _merge_copy_sheet_between_docs(src, src_sheet_name, target_doc, target_name, report)
                    if copied is None:
                        report.stats['sheets_skipped'] = report.stats.get('sheets_skipped', 0) + 1
                        continue
                    any_sheet = True
                    last_copied_sheet = copied
                    report.stats['sheets_done'] = report.stats.get('sheets_done', 0) + 1
                    _cw_cfg._MERGE_COPY_SHEETS_BLOCK_BY_NAME[target_name] = blk
                    _cw_cfg._MERGE_COPY_SHEETS_FILE_INDEX[target_name] = fi
                    if ctc_specs:
                        _apply_cell_to_column_on_copied_sheet(copied, tname, ctc_specs, cell_to_column_cache, file_key, header_row_0, report, src_label=src_label)
                    if is_csv_source and (not csv_shadow_xlsx):
                        # Calc уже распознал числа/даты при открытии CSV — не гонять
                        # UNO/xml конвертацию (даже при MERGE_XML_CONVERT_TO_NUMBERS=Да).
                        _merge_csv_mark_skip_number_date_convert(
                            target_name,
                            reason=u'copy_whole_sheet: Calc при открытии',
                        )
                    copied_jobs.append((copied, target_name, tname, False))
                    report.log_stat(
                        src_label, target_name, tname, '',
                        u'CSV importSheet' if is_csv_source else 'скопирован лист',
                        block_settings_note(blk),
                    )
                    _merge_undo_clear(target_doc, 'source:%s|%s' % (src_label, target_name), defer_ok=False)
        finally:
            if not is_current_book and src is not None:
                close_source(src)
        if report is not None and report._current_stage == 'data_collection':
            report.end_stage('data_collection')
        ji = 0
        while ji < len(copied_jobs):
            if _merge_stop_if_aborted(report):
                break
            copied, target_name, tname, from_csv = copied_jobs[ji]
            fi_job = _cw_cfg._MERGE_COPY_SHEETS_FILE_INDEX.get(target_name, fi)
            if not skip_phase2:
                _merge_apply_flattened_header_on_result(
                    copied, blk, start_col=(blk or {}).get('start_col', 0),
                    col_count=(blk or {}).get('col_count'),
                )
                trimmed_n = _merge_apply_copy_sheets_row_trim_uno(target_doc, copied, blk, target_name, fi_job, report)
                _merge_apply_delete_top_rows_before_pp(target_doc, copied, report, file_index=fi_job)
            else:
                trimmed_n = 0
            col_rename_items = []
            if per_file_col_rename_items and fi_job < len(per_file_col_rename_items):
                col_rename_items = per_file_col_rename_items[fi_job] or []
            if col_rename_items and (not skip_phase2):
                _merge_apply_col_rename_on_copied_sheet(
                    copied, blk, col_rename_items,
                    sheet_name=target_name, file_index=fi_job, report=report,
                )
            header_row, end_col, end_row, rows_n = _merge_copy_sheets_pp_bounds(copied, blk)
            if end_row >= header_row:
                info = {
                    'sheet': copied,
                    'header_row': header_row,
                    'end_col': end_col,
                    'end_row': end_row,
                    'pp_ctx': None,
                }
                if from_csv:
                    # Нет оформления источника — встроенный стиль шапки/листа.
                    info['from_copy'] = True
                    info['format_from_source'] = False
                all_sheets_info.append(info)
            report.stats['rows_copied'] = report.stats.get('rows_copied', 0) + rows_n
            merge_ui_status_set(report.stats['rows_copied'], 'Строк: %d' % report.stats['rows_copied'])
            ji = ji + 1
        if _merge_stop_if_aborted(report):
            break
        merge_ui_yield(force=True)
        fi = fi + 1
    if not skip_phase2 and (not _merge_stop_if_aborted(report)) and all_sheets_info:
        blk = per_file_blocks[0] if len(per_file_blocks) > 0 else parse_block_from_strings('1', '1', '', '', '')
        si = 0
        while si < len(all_sheets_info):
            info = all_sheets_info[si]
            si = si + 1
            sh = info.get('sheet')
            if sh is None:
                continue
            sheet_name = str(getattr(sh, 'Name', '') or '').strip()
            sheet_blk = (_cw_get('_MERGE_COPY_SHEETS_BLOCK_BY_NAME') or {}).get(sheet_name) or blk
            fi_job = (_cw_get('_MERGE_COPY_SHEETS_FILE_INDEX') or {}).get(sheet_name)
            if sheet_blk is not None:
                info['header_row'] = _merge_copy_sheets_hdr_row_after_trim(
                    sh, sheet_blk, sheet_name=sheet_name, file_index=fi_job
                )
            try:
                ec, er = get_sheet_used_bounds(sh)
                info['end_col'] = int(ec)
                info['end_row'] = int(er)
            except Exception:
                pass
        _merge_run_split_sheets_deferred_phase(target_doc, 'after_collect', report=report, sheets_info=all_sheets_info)
        # importSheet мог принести smart-table / именованные DatabaseRange — снять до оформления.
        try:
            from libre_macros_split_lib import _split_clear_database_ranges
            dropped = _split_clear_database_ranges(target_doc, keep_anonymous=False)
            if dropped:
                merge_debug(
                    'merge_on_copy_sheets',
                    'cleared DatabaseRanges n=%d' % len(dropped),
                )
        except Exception as err:
            merge_debug('merge_on_copy_sheets', 'clear DatabaseRanges: %s' % err)
        _merge_apply_builtin_formatting_all(target_doc, [info.get('sheet') for info in all_sheets_info], report)
        pipeline = _cw_cfg._MERGE_PROCESSING_PIPELINE
        if pipeline is not None and len(pipeline) > 0:
            _merge_log_postprocess(target_doc, '', 'постобработка', 'pipeline', 'инфо', 'книжный проход: range по всем листам → ВПР → … (листы=%d)' % len(all_sheets_info))
            apply_result_book_postprocessing_pipeline(target_doc, all_sheets_info, report=report)
        else:
            for info in all_sheets_info:
                sh = info.get('sheet')
                if sh is None:
                    continue
                apply_result_sheet_postprocessing(target_doc, sh, int(info.get('end_col', 0)), int(info.get('end_row', 0)), int(info.get('header_row', 0)), report)
        for info in all_sheets_info:
            copied = info.get('sheet')
            header_row = int(info.get('header_row', 0))
            if copied is None:
                continue
            skip_default = _merge_sheet_skip_default_formatting(copied)
            try:
                header_style = _merge_pp_resolve_zebra_header_style_from_specs(_cw_cfg._MERGE_RESULT_POSTPROCESS_RANGE, _cw_cfg._MERGE_RESULT_POSTPROCESS_ROW)
            except Exception:
                header_style = None
            if _cw_get('MERGE_FINALIZE_HEADER', True):
                ec2, _er2 = get_sheet_used_bounds(copied)
                if header_style is not None:
                    _merge_finalize_header_row_appearance(copied, ec2, header_row, target_doc, _cw_cfg._MERGE_RESULT_POSTPROCESS_RANGE, _cw_cfg._MERGE_RESULT_POSTPROCESS_ROW)
                elif (not skip_default) and info.get('from_copy') and not info.get('format_from_source'):
                    apply_hdr = globals().get('merge_pp_apply_merge_dest_header_default')
                    if apply_hdr is None:
                        apply_hdr = _cw_get('_merge_pp_apply_merge_dest_header_default')
                    if apply_hdr is None:
                        try:
                            import libre_macros_lib as _lm
                            apply_hdr = getattr(_lm, '_lm_pp_apply_merge_dest_header_default', None)
                        except Exception:
                            apply_hdr = None
                    if apply_hdr is not None:
                        try:
                            apply_hdr(copied, header_row)
                        except Exception:
                            _apply_header_row_appearance(copied, ec2, header_row)
                    else:
                        _apply_header_row_appearance(copied, ec2, header_row)
            if not skip_default:
                _merge_apply_result_sheet_user_flags(target_doc, copied, header_row)
    report.stats['files_done'] = fi if merge_ui_abort_requested() else len(files)
    if last_copied_sheet is not None:
        activate_sheet(target_doc, last_copied_sheet)
    if not any_sheet:
        report.problem('Нет листов по фильтрам — ничего не скопировано.')
        return False
    return True

def merge_on_one_sheet(target_doc, files, is_current_book_flags, per_file_sheet_specs, per_file_col_specs, per_file_blocks, per_file_skip_row_specs, path_display, cell_to_column_plan, report, per_file_col_rename_items=None):
    """
    Ядро режима «На один лист»: слияние всех данных в ЕДИНСТВЕННЫЙ лист «Merge».

    Назначение (новая логика):
        Всегда один лист результата («Merge»), независимо от фильтров листов.
        Фильтры применяются для выбора листов источников, но все данные
        попадают в один общий лист. Столбцы сливаются по имени заголовка.

    Параметры:
        target_doc — книга результата.
        files — абсолютные пути или маркеры «эта_книга».
        is_current_book_flags — список флагов (True = текущая книга).
        per_file_sheet_specs, per_file_col_specs, per_file_blocks — на каждый файл.
        path_display — "short" | "long".
        report — ProgressReport.

    Возвращает:
        bool — True, если хотя бы один лист обработан.
    """
    merge_debug('merge_on_one_sheet', 'files=%d' % len(files))
    target_key = _cw_cfg.MERGE_ONE_SHEET_TARGET_NAME
    cleared_names = set()
    ts, out_row = prepare_target_sheet(target_doc, target_key, cleared_names)
    if ts is None:
        report.problem('Не удалось создать лист «%s» в книге результата.' % target_key)
        return False
    ensure_service_headers(ts)
    any_sheet = False
    ctc_per_file_specs = build_cell_to_column_per_file_specs(cell_to_column_plan, len(files))
    cell_to_column_cache = {}
    fi = 0
    while fi < len(files):
        if _merge_stop_if_aborted(report):
            break
        merge_debug('merge_on_one_sheet.file', 'fi=%d/%d' % (fi + 1, len(files)))
        is_current_book = is_current_book_flags[fi] if fi < len(is_current_book_flags) else False
        is_csv_source = False
        csv_shadow_xlsx = False
        is_book_memory = False
        csv_matrix = None
        csv_conv_meta = None
        col_rename_items_loop = []
        if per_file_col_rename_items and fi < len(per_file_col_rename_items):
            col_rename_items_loop = per_file_col_rename_items[fi] or []
        if is_current_book:
            fpath = get_current_book_path()
            fname = short_name(fpath) if fpath else '(текущая книга)'
            src_label = '(текущая книга)'
            src = target_doc
        else:
            fpath = os.path.abspath(files[fi])
            fname = short_name(fpath)
            src_label = format_source_path(fpath, path_display_for_file_key(path_display))
            sheet_specs = per_file_sheet_specs[fi] if fi < len(per_file_sheet_specs) else []
            book_mem_active, book_skip = _merge_book_memory_path_active(
                fpath, fi, _cw_cfg.MERGE_MODE_ONE, is_current_book,
            )
            if book_mem_active:
                is_book_memory = True
                src = None
            elif book_skip:
                _merge_mem_console_log(
                    _merge_mem_log_tag_for_path(fpath),
                    u'prepare_source_in_memory не применимо: %s' % book_skip,
                )
            is_csv_source = _merge_path_is_csv(fpath)
            csv_shadow_xlsx = False
            if is_csv_source:
                try:
                    from libre_macros_csv_source_lib import source_extra_open_as_xlsx
                    csv_shadow_xlsx = bool(source_extra_open_as_xlsx(_merge_source_extra_for_fi(fi)))
                except Exception:
                    csv_shadow_xlsx = False
            if is_csv_source and (not csv_shadow_xlsx):
                src = None
                csv_matrix, csv_conv_meta = _merge_load_csv_source_matrix(
                    target_doc, fpath, fi, col_map_items=col_rename_items_loop
                )
                if not csv_matrix:
                    report.problem('Не удалось прочитать CSV: %s' % fpath)
                    fi = fi + 1
                    continue
            elif not is_book_memory:
                skip_spec_open = ''
                if fi < len(per_file_skip_row_specs):
                    skip_spec_open = per_file_skip_row_specs[fi]
                src = _merge_open_source_for_file(fpath, fi, writable=_merge_skip_spec_needs_writable(skip_spec_open), sheet_specs=sheet_specs)
        if fi < len(per_file_blocks):
            blk = per_file_blocks[fi]
        elif len(per_file_blocks) > 0:
            blk = per_file_blocks[0]
        else:
            blk = parse_block_from_strings('1', '1', '', '', '')
        start_col = blk['start_col']
        row_count = blk['row_count']
        col_count = blk['col_count']
        report.step('Файл %d/%d: %s' % (fi + 1, len(files), fname))
        _merge_ui_collect_file_start(report, fi + 1, len(files), fname)
        sheet_specs = per_file_sheet_specs[fi]
        col_specs = per_file_col_specs[fi]
        col_rename_items = list(col_rename_items_loop)
        sheet_kind = classify_sheet_specs(sheet_specs)
        col_kind = classify_column_specs(col_specs)
        report.log_stat(src_label, '', '', '', 'файл', file_params_note(blk, sheet_specs, col_specs))
        if not is_current_book and (not is_csv_source) and (not is_book_memory) and src is None:
            report.problem('Не удалось открыть файл: %s' % fpath)
            fi = fi + 1
            continue
        try:
            if is_book_memory:
                skip_spec = ''
                if fi < len(per_file_skip_row_specs):
                    skip_spec = per_file_skip_row_specs[fi]
                sheets_before = report.stats.get('sheets_done', 0)
                out_row = _merge_process_book_file_in_memory(
                    target_doc, ts, fpath, fi, blk, col_specs, col_kind, skip_spec,
                    out_row, report, fname, src_label, path_display, sheet_specs, sheet_kind,
                    many_mode=False,
                    cell_to_column_cache=cell_to_column_cache,
                    ctc_per_file_specs=ctc_per_file_specs,
                    col_rename_items=col_rename_items,
                )
                if report.stats.get('sheets_done', 0) > sheets_before:
                    any_sheet = True
            elif is_csv_source and (not csv_shadow_xlsx):
                tname = _merge_csv_logical_sheet_title(fpath)
                if not _merge_csv_included_by_sheet_specs(tname, sheet_specs, sheet_kind):
                    report.stats['sheets_skipped'] = report.stats.get('sheets_skipped', 0) + 1
                    report.log_stat(src_label, '', tname, '', 'пропуск', 'CSV не входит в фильтр «Листы»')
                else:
                    report.status(u'  → CSV «%s» в Merge' % tname)
                    if _merge_ui_is_dialog_mode():
                        merge_ui_yield(force=True)
                    skip_spec = ''
                    if fi < len(per_file_skip_row_specs):
                        skip_spec = per_file_skip_row_specs[fi]
                    sheets_before = report.stats.get('sheets_done', 0)
                    out_row = _merge_append_csv_matrix_to_target(
                        target_doc, ts, csv_matrix, csv_conv_meta, blk, col_specs, col_kind,
                        skip_spec, out_row, report, fname, tname, src_label, fpath, path_display, fi,
                        col_rename_items=col_rename_items,
                    )
                    if report.stats.get('sheets_done', 0) > sheets_before:
                        any_sheet = True
                    _merge_undo_clear(target_doc, 'source:%s|%s' % (src_label, tname), defer_ok=False)
            else:
                _merge_maybe_force_api_for_hidden_source(
                    src, sheet_specs, sheet_kind, report=report, src_label=src_label,
                )
                if is_current_book:
                    slots = _iter_sheet_slots_current_book(src, sheet_specs, sheet_kind)
                else:
                    slots = iter_sheet_slots(src, sheet_specs, sheet_kind)
                for slot in slots:
                    if _merge_stop_if_aborted(report):
                        break
                    tname = slot['source_name']
                    ss = get_sheet(src, tname)
                    if ss is None:
                        if is_current_book:
                            report.problem('В текущей книге нет листа «%s» — пропуск.' % tname)
                        else:
                            report.problem('В файле «%s» нет листа «%s» — пропуск.' % (fname, tname))
                        report.stats['sheets_skipped'] = report.stats['sheets_skipped'] + 1
                        continue
                    hdr_row, start_row_0, no_header, skipped_top_0 = _merge_block_sheet_collect_params(ss, blk)
                    hdr_titles = _merge_header_titles_for_sheet(ss, blk, start_col, col_count)
                    cols = build_column_list(ss, col_specs, col_kind, hdr_row, start_col, col_count, no_header=no_header, probe_row_0=start_row_0, header_titles=hdr_titles)
                    cols = _merge_apply_col_rename_items(cols, col_rename_items)
                    if len(cols) == 0:
                        if is_current_book:
                            report.problem('Лист «%s» в текущей книге: нет столбцов — пропуск.' % tname)
                        else:
                            report.problem('Лист «%s» в «%s»: нет столбцов по фильтру — пропуск.' % (tname, fname))
                        report.log_stat(src_label, tname, '', 0, 'пропуск', 'нет столбцов')
                        report.stats['sheets_skipped'] = report.stats['sheets_skipped'] + 1
                        continue
                    any_sheet = True
                    report.stats['sheets_done'] = report.stats['sheets_done'] + 1
                    _merge_note_result_skipped_top(ts.Name, skipped_top_0)
                    report.status('  → лист «%s» в Merge' % tname)
                    if _merge_ui_is_dialog_mode():
                        merge_ui_yield(force=True)
                    maybe_prefetch_cell_to_column(cell_to_column_cache, ctc_per_file_specs, fi, fpath if not is_current_book else '', is_current_book, path_display, tname, src)
                    maybe_prefetch_add_to_variables_map(_cw_cfg._MERGE_ADD_TO_VARIABLES_PER_FILE, fi, fpath if not is_current_book else '', is_current_book, path_display, tname, src, report=report)
                    if _merge_uses_header_column_matching():
                        ensure_target_headers(ts, cols)
                    skip_spec = ''
                    if fi < len(per_file_skip_row_specs):
                        skip_spec = per_file_skip_row_specs[fi]
                    last_row_col_spec = ''
                    try:
                        from libre_macros_source_extra_lib import source_extra_last_row_column

                        last_row_col_spec = source_extra_last_row_column(
                            _merge_source_extra_for_fi(fi)
                        )
                    except Exception:
                        last_row_col_spec = ''
                    t_rows = time.time()
                    data_rows, _skip_n, allow_batch = _merge_prepare_data_rows_with_skip(ss, hdr_row, start_col, row_count, col_count, skip_spec, report, fname, tname, src_doc=src, is_current_book=is_current_book, first_data_row_0=start_row_0, last_row_col_spec=last_row_col_spec)
                    rows_elapsed_ms = (time.time() - t_rows) * 1000.0
                    rows_n = len(data_rows)
                    first_row_0 = data_rows[0] if rows_n > 0 else None
                    last_row_0 = data_rows[-1] if rows_n > 0 else None
                    _merge_log_last_row_column_usage(
                        report, src_label, tname, last_row_col_spec, rows_n,
                        first_row_0=first_row_0, last_row_0=last_row_0, elapsed_ms=rows_elapsed_ms,
                    )
                    layout = merge_active_service_layout()
                    log_fpath = fpath if not is_current_book else get_current_book_path() or ''
                    row_label, mtime_str, file_key = _merge_service_row_context(log_fpath, is_current_book, tname, layout, path_display)
                    out_row = _merge_copy_data_rows_to_target(ts, ss, cols, data_rows, out_row, src if not is_current_book else None, target_doc, row_label, mtime_str, report, fname, tname, file_key=file_key, source_sheet_name=tname, allow_batch_copy=allow_batch, hdr_row=hdr_row)
                    ci = 0
                    while ci < len(cols):
                        sc = cols[ci][0]
                        hname = cols[ci][1]
                        report.log_stat(src_label, tname, '%s (%s)' % (col_label(sc), hname), rows_n, 'скопировано', block_settings_note(blk))
                        ci = ci + 1
                    _merge_undo_clear(target_doc, 'source:%s|%s' % (src_label, tname), defer_ok=False)
        finally:
            _merge_clear_file_transfer_override()
            if not is_current_book and src is not None:
                close_source(src)
        if _merge_stop_if_aborted(report):
            break
        merge_ui_yield(force=True)
        fi = fi + 1
    if merge_ui_abort_requested():
        if any_sheet:
            apply_cell_to_column_mappings([ts], files, is_current_book_flags, cell_to_column_plan, cell_to_column_cache, path_display, report)
            _merge_run_split_sheets_deferred_phase(target_doc, 'after_collect', report=report)
            apply_result_sheet_formatting(target_doc, ts, report)
            activate_sheet(target_doc, ts)
            report.stats['files_done'] = fi
            refresh_document(target_doc)
        return any_sheet
    if not any_sheet:
        report.problem('Нет листов/столбцов по фильтрам — данные не собраны.')
        return False
    apply_cell_to_column_mappings([ts], files, is_current_book_flags, cell_to_column_plan, cell_to_column_cache, path_display, report)
    _merge_run_split_sheets_deferred_phase(target_doc, 'after_collect', report=report)
    apply_result_sheet_formatting(target_doc, ts, report)
    activate_sheet(target_doc, ts)
    report.stats['files_done'] = len(files)
    refresh_document(target_doc)
    return True

def merge_on_many_sheets(target_doc, files, is_current_book_flags, per_file_sheet_specs, per_file_col_specs, per_file_blocks, per_file_skip_row_specs, path_display, cell_to_column_plan, report, per_file_col_rename_items=None):
    """
    Ядро режима «На разные листы».

    INDEX / NAME / ALL: листы результата по target_key из iter_sheet_slots
    (имя листа источника или rename). Одноимённые target из разных файлов
    объединяются. INDEX больше не создаёт Merge_1…N.

    Параметры:
        target_doc, files, is_current_book_flags, per_file_*, path_display, report.

    Возвращает:
        bool — True (даже при частичных пропусках).
    """
    merge_debug('merge_on_many_sheets', 'files=%d' % len(files))
    sheet_kind = 'ALL'
    if len(per_file_sheet_specs) > 0:
        sheet_kind = classify_sheet_specs(per_file_sheet_specs[0])
    used_names = set()
    for svc_name in _cw_cfg.MERGE_SHEETS_UNDELETE_DEFAULT:
        used_names.add(svc_name)
    # Бывший INDEX→Merge_N отключён: INDEX обрабатывается веткой NAME ниже.
    if False and sheet_kind == 'INDEX':
        all_indices = set()
        idx = 0
        while idx < len(per_file_sheet_specs):
            specs = per_file_sheet_specs[idx]
            for spec in specs:
                try:
                    i = int(spec.strip())
                    if i > 0:
                        all_indices.add(i)
                except Exception:
                    pass
            idx = idx + 1
        merge_targets = {}
        for idx in sorted(all_indices):
            target_key = _cw_cfg.MERGE_SHEET_INDEX_TARGET_PREFIX + str(idx)
            if target_key not in target_doc.Sheets:
                try:
                    target_doc.Sheets.insertNewByName(target_key, target_doc.Sheets.getCount())
                except Exception:
                    pass
            ts = get_sheet(target_doc, target_key)
            if ts is None:
                report.problem('Не удалось создать лист «%s»' % target_key)
                continue
            ensure_service_headers(ts)
            merge_targets[idx] = {'sheet': ts, 'out_row': 1, 'sources': []}
        ctc_per_file_specs = build_cell_to_column_per_file_specs(cell_to_column_plan, len(files))
        cell_to_column_cache = {}
        fi = 0
        while fi < len(files):
            if _merge_stop_if_aborted(report):
                break
            merge_debug('merge_on_many_sheets.index.file', 'fi=%d/%d' % (fi + 1, len(files)))
            is_current_book = is_current_book_flags[fi] if fi < len(is_current_book_flags) else False
            is_csv_source = False
            csv_shadow_xlsx = False
            is_book_memory = False
            csv_matrix = None
            csv_conv_meta = None
            col_rename_items_loop = []
            if per_file_col_rename_items and fi < len(per_file_col_rename_items):
                col_rename_items_loop = per_file_col_rename_items[fi] or []
            if is_current_book:
                fpath = get_current_book_path()
                fname = short_name(fpath) if fpath else '(текущая книга)'
                src_label = '(текущая книга)'
                src = target_doc
            else:
                fpath = os.path.abspath(files[fi])
                fname = short_name(fpath)
                src_label = format_source_path(fpath, path_display_for_file_key(path_display))
                sheet_specs = per_file_sheet_specs[fi] if fi < len(per_file_sheet_specs) else []
                book_mem_active, book_skip = _merge_book_memory_path_active(
                    fpath, fi, _cw_cfg.MERGE_MODE_MANY, is_current_book,
                )
                if book_mem_active:
                    is_book_memory = True
                    src = None
                elif book_skip:
                    _merge_mem_console_log(
                        _merge_mem_log_tag_for_path(fpath),
                        u'prepare_source_in_memory не применимо: %s' % book_skip,
                    )
                is_csv_source = _merge_path_is_csv(fpath)
                csv_shadow_xlsx = False
                if is_csv_source:
                    try:
                        from libre_macros_csv_source_lib import source_extra_open_as_xlsx
                        csv_shadow_xlsx = bool(source_extra_open_as_xlsx(_merge_source_extra_for_fi(fi)))
                    except Exception:
                        csv_shadow_xlsx = False
                if is_csv_source and (not csv_shadow_xlsx):
                    src = None
                    csv_matrix, csv_conv_meta = _merge_load_csv_source_matrix(
                        target_doc, fpath, fi, col_map_items=col_rename_items_loop
                    )
                    if not csv_matrix:
                        report.problem('Не удалось прочитать CSV: %s' % fpath)
                        fi = fi + 1
                        continue
                elif not is_book_memory:
                    skip_spec_open = ''
                    if fi < len(per_file_skip_row_specs):
                        skip_spec_open = per_file_skip_row_specs[fi]
                    src = _merge_open_source_for_file(fpath, fi, writable=_merge_skip_spec_needs_writable(skip_spec_open), sheet_specs=sheet_specs)
            if not is_current_book and (not is_csv_source) and (not is_book_memory) and src is None:
                report.problem('Не удалось открыть: %s' % fpath)
                fi = fi + 1
                continue
            if fi < len(per_file_blocks):
                blk = per_file_blocks[fi]
            elif len(per_file_blocks) > 0:
                blk = per_file_blocks[0]
            else:
                blk = parse_block_from_strings('1', '1', '', '', '')
            start_col = blk['start_col']
            row_count = blk['row_count']
            col_count = blk['col_count']
            col_specs = per_file_col_specs[fi] if fi < len(per_file_col_specs) else []
            col_rename_items = list(col_rename_items_loop)
            col_kind = classify_column_specs(col_specs)
            report.step('Файл %d/%d: %s' % (fi + 1, len(files), fname))
            _merge_ui_collect_file_start(report, fi + 1, len(files), fname)
            try:
                if is_csv_source and (not csv_shadow_xlsx):
                    # CSV = один логический лист → индекс 1
                    if 1 in merge_targets:
                        tname = _merge_csv_logical_sheet_title(fpath)
                        target_info = merge_targets[1]
                        ts = target_info['sheet']
                        out_row = target_info['out_row']
                        report.status(u'  → Merge_1 ← CSV %s' % tname)
                        skip_spec = ''
                        if fi < len(per_file_skip_row_specs):
                            skip_spec = per_file_skip_row_specs[fi]
                        out_row = _merge_append_csv_matrix_to_target(
                            target_doc, ts, csv_matrix, csv_conv_meta, blk, col_specs, col_kind,
                            skip_spec, out_row, report, fname, tname, src_label, fpath, path_display, fi,
                            col_rename_items=col_rename_items,
                        )
                        target_info['out_row'] = out_row
                        target_info['sources'].append(fname)
                        _merge_undo_clear(target_doc, 'source:%s|Merge_1' % src_label, defer_ok=False)
                elif is_book_memory:
                    tmp_paths = []
                    read_path, kind = _merge_resolve_book_read_path(fpath, tmp_paths)
                    extra = _merge_source_extra_for_fi(fi) or {}
                    skip_spec = ''
                    if fi < len(per_file_skip_row_specs):
                        skip_spec = per_file_skip_row_specs[fi]
                    try:
                        if read_path is None:
                            report.problem(u'[%s] не удалось прочитать: %s' % (_merge_mem_log_tag_for_path(fpath), fpath))
                        else:
                            try:
                                from libre_macros_book_source_lib import book_source_sheet_names
                                bnames = book_source_sheet_names(read_path)
                            except Exception:
                                bnames = []
                            for idx in sorted(all_indices):
                                if _merge_stop_if_aborted(report):
                                    break
                                if idx not in merge_targets:
                                    continue
                                si = int(idx) - 1
                                if si < 0 or si >= len(bnames):
                                    continue
                                tname = bnames[si]
                                target_info = merge_targets[idx]
                                ts = target_info['sheet']
                                out_row = target_info['out_row']
                                report.status(u'  → Merge_%d ← [%s] %s' % (idx, _merge_mem_log_tag_for_path(fpath), tname))
                                try:
                                    from libre_macros_source_extra_lib import source_extra_values_mode
                                    _vm = source_extra_values_mode(extra)
                                except Exception:
                                    _vm = u'cached'
                                _merge_book_prefetch_sheet_meta(
                                    read_path, kind, si, tname, fpath, path_display, fi,
                                    cell_to_column_cache, ctc_per_file_specs,
                                    values_mode=_vm, report=report,
                                )
                                out_row = _merge_process_book_sheet_in_memory(
                                    target_doc, ts, read_path, kind, si, tname, blk, col_specs, col_kind,
                                    skip_spec, out_row, report, fname, tname, src_label, fpath, path_display, fi, extra,
                                    col_rename_items=col_rename_items,
                                )
                                target_info['out_row'] = out_row
                                target_info['sources'].append(fname)
                                _merge_undo_clear(target_doc, 'source:%s|Merge_%d' % (src_label, idx), defer_ok=False)
                    finally:
                        for p in tmp_paths:
                            try:
                                os.unlink(p)
                            except Exception:
                                pass
                else:
                    _merge_maybe_force_api_for_hidden_source(
                        src, sheet_specs, sheet_kind, report=report, src_label=src_label,
                    )
                    for idx in sorted(all_indices):
                        if _merge_stop_if_aborted(report):
                            break
                        if idx - 1 >= src.Sheets.getCount():
                            continue
                        ss = src.Sheets.getByIndex(idx - 1)
                        if ss is None:
                            continue
                        tname = ss.Name
                        hdr_row, start_row_0, no_header, skipped_top_0 = _merge_block_sheet_collect_params(ss, blk)
                        hdr_titles = _merge_header_titles_for_sheet(ss, blk, start_col, col_count)
                        cols = build_column_list(ss, col_specs, col_kind, hdr_row, start_col, col_count, no_header=no_header, probe_row_0=start_row_0, header_titles=hdr_titles)
                        cols = _merge_apply_col_rename_items(cols, col_rename_items)
                        if len(cols) == 0:
                            continue
                        if idx not in merge_targets:
                            continue
                        target_info = merge_targets[idx]
                        ts = target_info['sheet']
                        out_row = target_info['out_row']
                        _merge_note_result_skipped_top(ts.Name, skipped_top_0)
                        report.status('  → Merge_%d ← %s' % (idx, tname))
                        maybe_prefetch_cell_to_column(cell_to_column_cache, ctc_per_file_specs, fi, fpath if not is_current_book else '', is_current_book, path_display, tname, src)
                        maybe_prefetch_add_to_variables_map(_cw_cfg._MERGE_ADD_TO_VARIABLES_PER_FILE, fi, fpath if not is_current_book else '', is_current_book, path_display, tname, src, report=report)
                        if _merge_uses_header_column_matching():
                            ensure_target_headers(ts, cols)
                        skip_spec = ''
                        if fi < len(per_file_skip_row_specs):
                            skip_spec = per_file_skip_row_specs[fi]
                        last_row_col_spec = ''
                        try:
                            from libre_macros_source_extra_lib import source_extra_last_row_column

                            last_row_col_spec = source_extra_last_row_column(
                                _merge_source_extra_for_fi(fi)
                            )
                        except Exception:
                            last_row_col_spec = ''
                        t_rows = time.time()
                        data_rows, _skip_n, allow_batch = _merge_prepare_data_rows_with_skip(ss, hdr_row, start_col, row_count, col_count, skip_spec, report, fname, tname, src_doc=src, is_current_book=is_current_book, first_data_row_0=start_row_0, last_row_col_spec=last_row_col_spec)
                        rows_elapsed_ms = (time.time() - t_rows) * 1000.0
                        rows_n = len(data_rows)
                        first_row_0 = data_rows[0] if rows_n > 0 else None
                        last_row_0 = data_rows[-1] if rows_n > 0 else None
                        _merge_log_last_row_column_usage(
                            report, src_label, tname, last_row_col_spec, rows_n,
                            first_row_0=first_row_0, last_row_0=last_row_0, elapsed_ms=rows_elapsed_ms,
                        )
                        layout = merge_active_service_layout()
                        log_fpath = fpath if not is_current_book else get_current_book_path() or ''
                        row_label, mtime_str, file_key = _merge_service_row_context(log_fpath, is_current_book, tname, layout, path_display)
                        out_row = _merge_copy_data_rows_to_target(ts, ss, cols, data_rows, out_row, src if not is_current_book else None, target_doc, row_label, mtime_str, report, fname, tname, file_key=file_key, source_sheet_name=tname, allow_batch_copy=allow_batch, hdr_row=hdr_row)
                        target_info['out_row'] = out_row
                        target_info['sources'].append(fname)
                        ci = 0
                        while ci < len(cols):
                            sc = cols[ci][0]
                            hname = cols[ci][1]
                            report.log_stat(src_label, 'Merge_%d' % idx, '%s (%s)' % (col_label(sc), hname), rows_n, 'скопировано', block_settings_note(blk))
                            ci = ci + 1
                        _merge_undo_clear(target_doc, 'source:%s|Merge_%d' % (src_label, idx), defer_ok=False)
            finally:
                _merge_clear_file_transfer_override()
                if not is_current_book and src is not None:
                    close_source(src)
            if _merge_stop_if_aborted(report):
                break
            merge_ui_yield(force=True)
            fi = fi + 1
        if merge_ui_abort_requested():
            result_sheets = []
            for idx in merge_targets:
                ts = merge_targets[idx]['sheet']
                if ts is not None:
                    result_sheets.append(ts)
            if len(result_sheets) > 0:
                apply_cell_to_column_mappings(result_sheets, files, is_current_book_flags, cell_to_column_plan, cell_to_column_cache, path_display, report)
                _merge_run_split_sheets_deferred_phase(target_doc, 'after_collect', report=report)
                for idx in merge_targets:
                    ts = merge_targets[idx]['sheet']
                    if ts is not None:
                        apply_result_sheet_formatting(target_doc, ts, report)
            report.stats['files_done'] = fi
            refresh_document(target_doc)
            return len(result_sheets) > 0
        result_sheets = []
        for idx in merge_targets:
            ts = merge_targets[idx]['sheet']
            if ts is not None:
                result_sheets.append(ts)
        apply_cell_to_column_mappings(result_sheets, files, is_current_book_flags, cell_to_column_plan, cell_to_column_cache, path_display, report)
        _merge_run_split_sheets_deferred_phase(target_doc, 'after_collect', report=report)
        blk = per_file_blocks[0] if len(per_file_blocks) > 0 else parse_block_from_strings('1', '1', '', '', '')
        sheets_info = _merge_build_sheets_info_from_sheets(target_doc, result_sheets, blk)
        _merge_apply_builtin_then_book_pipeline(target_doc, sheets_info, report)
        report.stats['files_done'] = len(files)
        refresh_document(target_doc)
        return True
    # NAME / INDEX / ALL — общая ветка (target_key из iter_sheet_slots).
    sheet_keys_order = []
    name_to_info = {}
    fi = 0
    while fi < len(files):
        is_current_book = is_current_book_flags[fi] if fi < len(is_current_book_flags) else False
        sheet_specs_fi = per_file_sheet_specs[fi] if fi < len(per_file_sheet_specs) else []
        try:
            file_sheet_kind = classify_sheet_specs(sheet_specs_fi) if sheet_specs_fi else sheet_kind
        except Exception:
            file_sheet_kind = sheet_kind
        if is_current_book:
            src = target_doc
            slots_gen = _iter_sheet_slots_current_book(src, sheet_specs_fi, file_sheet_kind)
            try:
                slot_count = 0
                for slot in slots_gen:
                    sn = slot['source_name']
                    tn = slot.get('target_key') or sn
                    ikey = merge_identity_key(tn)
                    if ikey == '':
                        continue
                    if ikey not in name_to_info:
                        sheet_keys_order.append(ikey)
                        name_to_info[ikey] = {'display_name': str(tn).strip(), 'sources': []}
                    name_to_info[ikey]['sources'].append({'file_idx': fi, 'sheet_name': sn})
                    slot_count = slot_count + 1
                    if slot_count % 100 == 0:
                        merge_ui_yield(counter=slot_count)
            finally:
                pass
        else:
            fpath = os.path.abspath(files[fi])
            sheet_specs = sheet_specs_fi
            if _merge_path_is_csv(fpath):
                sn = _merge_csv_logical_sheet_title(fpath)
                if _merge_csv_included_by_sheet_specs(sn, sheet_specs, file_sheet_kind):
                    tn = _merge_csv_resolve_target_name(sn, sheet_specs)
                    ikey = merge_identity_key(tn)
                    if ikey != '':
                        if ikey not in name_to_info:
                            sheet_keys_order.append(ikey)
                            name_to_info[ikey] = {'display_name': str(tn).strip(), 'sources': []}
                        name_to_info[ikey]['sources'].append({'file_idx': fi, 'sheet_name': sn})
            else:
                src = _merge_open_source_for_file(fpath, fi, sheet_specs=sheet_specs)
                if src is None:
                    fi = fi + 1
                    continue
                slots_gen = iter_sheet_slots(src, sheet_specs, file_sheet_kind)
                try:
                    slot_count = 0
                    for slot in slots_gen:
                        sn = slot['source_name']
                        tn = slot.get('target_key') or sn
                        ikey = merge_identity_key(tn)
                        if ikey == '':
                            continue
                        if ikey not in name_to_info:
                            sheet_keys_order.append(ikey)
                            name_to_info[ikey] = {'display_name': str(tn).strip(), 'sources': []}
                        name_to_info[ikey]['sources'].append({'file_idx': fi, 'sheet_name': sn})
                        slot_count = slot_count + 1
                        if slot_count % 100 == 0:
                            merge_ui_yield(counter=slot_count)
                finally:
                    close_source(src)
        fi = fi + 1
    name_targets = {}
    max_prefix_by_sheet_key = {}
    si = 0
    while si < target_doc.Sheets.getCount():
        try:
            existing_name = target_doc.Sheets.getByIndex(si).Name
            m = re.match('^(\\d+)_(.+)$', str(existing_name).strip())
            if m is not None:
                n = int(m.group(1))
                key = merge_identity_key(m.group(2))
                prev = max_prefix_by_sheet_key.get(key, 0)
                if n > prev:
                    max_prefix_by_sheet_key[key] = n
        except Exception:
            pass
        si = si + 1
    next_prefix_by_sheet_key = {k: int(v) + 1 for k, v in max_prefix_by_sheet_key.items()}
    sheet_idx = 0
    for ikey in sheet_keys_order:
        sheet_idx = sheet_idx + 1
        if sheet_idx % 50 == 0:
            merge_ui_yield(counter=sheet_idx)
        info = name_to_info[ikey]
        display_name = info['display_name']
        ts = find_sheet_by_identity(target_doc, display_name)
        needs_fork = False
        try:
            for src_item in info.get('sources') or []:
                fidx = int(src_item.get('file_idx', -1))
                if 0 <= fidx < len(is_current_book_flags) and bool(is_current_book_flags[fidx]):
                    needs_fork = True
                    break
        except Exception:
            needs_fork = False
        if ts is not None and needs_fork:
            base = str(display_name or '').strip() or 'Лист'
            key = merge_identity_key(base)
            prefix = int(next_prefix_by_sheet_key.get(key, 1))
            next_prefix_by_sheet_key[key] = prefix + 1
            prefix_str = '%d_' % prefix
            max_base = 31 - len(prefix_str)
            if max_base < 1:
                max_base = 1
            target_key = prefix_str + base[:max_base]
            suffix = 2
            while target_key in used_names or find_sheet_by_identity(target_doc, target_key) is not None:
                tail = '_%d' % suffix
                head_len = 31 - len(prefix_str) - len(tail)
                if head_len < 1:
                    head_len = 1
                target_key = prefix_str + base[:head_len] + tail
                suffix = suffix + 1
                if suffix > 999:
                    break
            used_names.add(target_key)
            try:
                target_doc.Sheets.insertNewByName(target_key, target_doc.Sheets.getCount())
            except Exception:
                pass
            ts = get_sheet(target_doc, target_key)
        elif ts is not None:
            target_key = ts.Name
        else:
            target_key = display_name
            if len(target_key) > 31:
                target_key = target_key[:31]
            suffix = 1
            base_name = target_key
            while target_key in used_names or find_sheet_by_identity(target_doc, target_key) is not None:
                suffix = suffix + 1
                suffix_str = '_%d' % suffix
                max_base = 31 - len(suffix_str)
                target_key = base_name[:max_base] + suffix_str
            used_names.add(target_key)
            try:
                target_doc.Sheets.insertNewByName(target_key, target_doc.Sheets.getCount())
            except Exception:
                pass
            ts = get_sheet(target_doc, target_key)
        if ts is None:
            report.problem('Не удалось создать лист «%s»' % display_name)
            continue
        ensure_service_headers(ts)
        start_out = _merge_resolve_out_row(ts)
        name_targets[ikey] = {
            'sheet': ts,
            'out_row': start_out,
            'initial_out_row': start_out,
            'sources': [],
            'header_cols': None,
        }
    ctc_per_file_specs = build_cell_to_column_per_file_specs(cell_to_column_plan, len(files))
    cell_to_column_cache = {}
    fi = 0
    while fi < len(files):
        if _merge_stop_if_aborted(report):
            break
        merge_debug('merge_on_many_sheets.name.file', 'fi=%d/%d' % (fi + 1, len(files)))
        is_current_book = is_current_book_flags[fi] if fi < len(is_current_book_flags) else False
        is_csv_source = False
        csv_shadow_xlsx = False
        is_book_memory = False
        csv_matrix = None
        csv_conv_meta = None
        col_rename_items_loop = []
        if per_file_col_rename_items and fi < len(per_file_col_rename_items):
            col_rename_items_loop = per_file_col_rename_items[fi] or []
        if is_current_book:
            fpath = get_current_book_path()
            fname = short_name(fpath) if fpath else '(текущая книга)'
            src_label = '(текущая книга)'
            src = target_doc
        else:
            fpath = os.path.abspath(files[fi])
            fname = short_name(fpath)
            src_label = format_source_path(fpath, path_display_for_file_key(path_display))
            sheet_specs = per_file_sheet_specs[fi] if fi < len(per_file_sheet_specs) else []
            book_mem_active, book_skip = _merge_book_memory_path_active(
                fpath, fi, _cw_cfg.MERGE_MODE_MANY, is_current_book,
            )
            if book_mem_active:
                is_book_memory = True
                src = None
            elif book_skip:
                _merge_mem_console_log(
                    _merge_mem_log_tag_for_path(fpath),
                    u'prepare_source_in_memory не применимо: %s' % book_skip,
                )
            is_csv_source = _merge_path_is_csv(fpath)
            csv_shadow_xlsx = False
            if is_csv_source:
                try:
                    from libre_macros_csv_source_lib import source_extra_open_as_xlsx
                    csv_shadow_xlsx = bool(source_extra_open_as_xlsx(_merge_source_extra_for_fi(fi)))
                except Exception:
                    csv_shadow_xlsx = False
            if is_csv_source and (not csv_shadow_xlsx):
                src = None
                csv_matrix, csv_conv_meta = _merge_load_csv_source_matrix(
                    target_doc, fpath, fi, col_map_items=col_rename_items_loop
                )
                if not csv_matrix:
                    report.problem('Не удалось прочитать CSV: %s' % fpath)
                    fi = fi + 1
                    continue
            elif not is_book_memory:
                skip_spec_open = ''
                if fi < len(per_file_skip_row_specs):
                    skip_spec_open = per_file_skip_row_specs[fi]
                src = _merge_open_source_for_file(fpath, fi, writable=_merge_skip_spec_needs_writable(skip_spec_open), sheet_specs=sheet_specs)
        if not is_current_book and (not is_csv_source) and (not is_book_memory) and src is None:
            report.problem('Не удалось открыть: %s' % fpath)
            fi = fi + 1
            continue
        if fi < len(per_file_blocks):
            blk = per_file_blocks[fi]
        elif len(per_file_blocks) > 0:
            blk = per_file_blocks[0]
        else:
            blk = parse_block_from_strings('1', '1', '', '', '')
        start_col = blk['start_col']
        row_count = blk['row_count']
        col_count = blk['col_count']
        col_specs = per_file_col_specs[fi] if fi < len(per_file_col_specs) else []
        col_rename_items = list(col_rename_items_loop)
        col_kind = classify_column_specs(col_specs)
        report.step('Файл %d/%d: %s' % (fi + 1, len(files), fname))
        _merge_ui_collect_file_start(report, fi + 1, len(files), fname)
        try:
            if is_csv_source and (not csv_shadow_xlsx):
                sn = _merge_csv_logical_sheet_title(fpath)
                try:
                    _csv_specs = per_file_sheet_specs[fi] if fi < len(per_file_sheet_specs) else []
                except Exception:
                    _csv_specs = []
                tn = _merge_csv_resolve_target_name(sn, _csv_specs)
                ikey = merge_identity_key(tn)
                if ikey not in name_targets:
                    # fallback: слот мог быть зарегистрирован под логическим именем
                    ikey = merge_identity_key(sn)
                if ikey in name_targets:
                    target_info = name_targets[ikey]
                    ts = target_info['sheet']
                    out_row = target_info['out_row']
                    report.status(u'  → %s ← CSV %s' % (target_info.get('display_name') or tn or sn, fname))
                    skip_spec = ''
                    if fi < len(per_file_skip_row_specs):
                        skip_spec = per_file_skip_row_specs[fi]
                    out_row = _merge_append_csv_matrix_to_target(
                        target_doc, ts, csv_matrix, csv_conv_meta, blk, col_specs, col_kind,
                        skip_spec, out_row, report, fname, sn, src_label, fpath, path_display, fi,
                        col_rename_items=col_rename_items,
                    )
                    target_info['out_row'] = out_row
                    target_info['sources'].append(fname)
                    _merge_undo_clear(target_doc, 'source:%s|%s' % (src_label, sn), defer_ok=False)
            elif is_book_memory:
                skip_spec = ''
                if fi < len(per_file_skip_row_specs):
                    skip_spec = per_file_skip_row_specs[fi]
                _ss = per_file_sheet_specs[fi] if fi < len(per_file_sheet_specs) else []
                try:
                    _fk = classify_sheet_specs(_ss) if _ss else sheet_kind
                except Exception:
                    _fk = sheet_kind
                _merge_process_book_file_in_memory(
                    target_doc, name_targets, fpath, fi, blk, col_specs, col_kind, skip_spec,
                    None, report, fname, src_label, path_display,
                    _ss, _fk,
                    many_mode=True,
                    cell_to_column_cache=cell_to_column_cache,
                    ctc_per_file_specs=ctc_per_file_specs,
                    col_rename_items=col_rename_items,
                )
            else:
                _ss = per_file_sheet_specs[fi] if fi < len(per_file_sheet_specs) else []
                try:
                    _fk = classify_sheet_specs(_ss) if _ss else sheet_kind
                except Exception:
                    _fk = sheet_kind
                _merge_maybe_force_api_for_hidden_source(
                    src, _ss, _fk, report=report, src_label=src_label,
                )
                if is_current_book:
                    slots = _iter_sheet_slots_current_book(src, _ss, _fk)
                else:
                    slots = iter_sheet_slots(src, _ss, _fk)
                    if is_csv_source:
                        slots = _merge_csv_name_slots_for_shadow(src, fpath, list(slots))
                for slot in slots:
                    if _merge_stop_if_aborted(report):
                        break
                    sn = slot['source_name']
                    tn = slot.get('target_key') or sn
                    ikey = merge_identity_key(tn)
                    ss = get_sheet(src, sn)
                    if is_csv_source:
                        logical = _merge_csv_logical_sheet_title(fpath)
                        logical_key = merge_identity_key(logical)
                        # Слот уже под target (*→csv / 1→Итог) — не откатывать на логическое имя.
                        if ikey in name_targets:
                            if ss is None:
                                ss = _merge_csv_shadow_source_sheet(src, logical)
                        elif logical_key in name_targets:
                            if ss is None:
                                ss = _merge_csv_shadow_source_sheet(src, logical)
                            ikey = logical_key
                            tn = logical
                            if merge_identity_key(sn) in (
                                merge_identity_key(u'CSV'),
                                logical_key,
                            ):
                                sn = logical
                    if ikey not in name_targets:
                        continue
                    if ss is None:
                        continue
                    hdr_row, start_row_0, no_header, skipped_top_0 = _merge_block_sheet_collect_params(ss, blk)
                    hdr_titles = _merge_header_titles_for_sheet(ss, blk, start_col, col_count)
                    cols = build_column_list(ss, col_specs, col_kind, hdr_row, start_col, col_count, no_header=no_header, probe_row_0=start_row_0, header_titles=hdr_titles)
                    cols = _merge_apply_col_rename_items(cols, col_rename_items)
                    if len(cols) == 0:
                        continue
                    target_info = name_targets[ikey]
                    ts = target_info['sheet']
                    out_row = target_info['out_row']
                    _merge_note_result_skipped_top(ts.Name, skipped_top_0)
                    report.status('  → %s ← %s' % (ts.Name if ts is not None else tn, fname))
                    maybe_prefetch_cell_to_column(cell_to_column_cache, ctc_per_file_specs, fi, fpath if not is_current_book else '', is_current_book, path_display, sn, src)
                    maybe_prefetch_add_to_variables_map(_cw_cfg._MERGE_ADD_TO_VARIABLES_PER_FILE, fi, fpath if not is_current_book else '', is_current_book, path_display, sn, src, report=report)
                    if _merge_uses_header_column_matching():
                        ensure_target_headers(ts, cols)
                        target_info['header_cols'] = cols
                    skip_spec = ''
                    if fi < len(per_file_skip_row_specs):
                        skip_spec = per_file_skip_row_specs[fi]
                    last_row_col_spec = ''
                    try:
                        from libre_macros_source_extra_lib import source_extra_last_row_column

                        last_row_col_spec = source_extra_last_row_column(
                            _merge_source_extra_for_fi(fi)
                        )
                    except Exception:
                        last_row_col_spec = ''
                    t_rows = time.time()
                    data_rows, _skip_n, allow_batch = _merge_prepare_data_rows_with_skip(ss, hdr_row, start_col, row_count, col_count, skip_spec, report, fname, sn, src_doc=src, is_current_book=is_current_book, first_data_row_0=start_row_0, last_row_col_spec=last_row_col_spec)
                    rows_elapsed_ms = (time.time() - t_rows) * 1000.0
                    rows_n = len(data_rows)
                    first_row_0 = data_rows[0] if rows_n > 0 else None
                    last_row_0 = data_rows[-1] if rows_n > 0 else None
                    _merge_log_last_row_column_usage(
                        report, src_label, sn, last_row_col_spec, rows_n,
                        first_row_0=first_row_0, last_row_0=last_row_0, elapsed_ms=rows_elapsed_ms,
                    )
                    layout = merge_active_service_layout()
                    log_fpath = fpath if not is_current_book else get_current_book_path() or ''
                    row_label, mtime_str, file_key = _merge_service_row_context(log_fpath, is_current_book, sn, layout, path_display)
                    out_row = _merge_copy_data_rows_to_target(ts, ss, cols, data_rows, out_row, src if not is_current_book else None, target_doc, row_label, mtime_str, report, fname, sn, file_key=file_key, source_sheet_name=sn, allow_batch_copy=allow_batch, hdr_row=hdr_row)
                    target_info['out_row'] = out_row
                    target_info['sources'].append(fname)
                    ci = 0
                    while ci < len(cols):
                        sc = cols[ci][0]
                        hname = cols[ci][1]
                        report.log_stat(src_label, sn, '%s (%s)' % (col_label(sc), hname), rows_n, 'скопировано', block_settings_note(blk))
                        ci = ci + 1
                    _merge_undo_clear(target_doc, 'source:%s|%s' % (src_label, sn), defer_ok=False)
        finally:
            _merge_clear_file_transfer_override()
            if not is_current_book and src is not None:
                close_source(src)
        if _merge_stop_if_aborted(report):
            break
        merge_ui_yield(force=True)
        fi = fi + 1
    if merge_ui_abort_requested():
        _merge_finalize_empty_many_targets(target_doc, name_targets, report=report)
        result_sheets = []
        for sn in name_targets:
            ts = name_targets[sn]['sheet']
            if ts is not None:
                result_sheets.append(ts)
        if len(result_sheets) > 0:
            apply_cell_to_column_mappings(result_sheets, files, is_current_book_flags, cell_to_column_plan, cell_to_column_cache, path_display, report)
            _merge_run_split_sheets_deferred_phase(target_doc, 'after_collect', report=report)
            for sn in name_targets:
                ts = name_targets[sn]['sheet']
                if ts is not None:
                    apply_result_sheet_formatting(target_doc, ts, report)
        report.stats['files_done'] = fi
        refresh_document(target_doc)
        return len(result_sheets) > 0
    _merge_finalize_empty_many_targets(target_doc, name_targets, report=report)
    result_sheets = []
    for sn in name_targets:
        ts = name_targets[sn]['sheet']
        if ts is not None:
            result_sheets.append(ts)
    apply_cell_to_column_mappings(result_sheets, files, is_current_book_flags, cell_to_column_plan, cell_to_column_cache, path_display, report)
    _merge_run_split_sheets_deferred_phase(target_doc, 'after_collect', report=report)
    blk = per_file_blocks[0] if len(per_file_blocks) > 0 else parse_block_from_strings('1', '1', '', '', '')
    sheets_info = _merge_build_sheets_info_from_sheets(target_doc, result_sheets, blk)
    _merge_apply_builtin_then_book_pipeline(target_doc, sheets_info, report)
    report.stats['files_done'] = len(files)
    refresh_document(target_doc)
    return True

def _merge_has_pre_shell_config(doc):
    """True, если на листе параметров задан «Предварительный_скрипт»."""
    try:
        table = read_param_table(doc)
        raw = merge_pre_shell_param_raw(table)
        return str(raw or '').strip() != ''
    except Exception:
        return False

def merge_pre_shell_param_raw(table):
    """
    Текст JSON «Предварительный_скрипт» из таблицы параметров.

    B = «смотри в С» → берём C (как у пропуска строк / прочих подвизардов).
    Иначе — B (обратная совместимость: JSON раньше писали в B).
    """
    vals = list_value(table, _cw_cfg.P_MERGE_PRE_SHELL, [])
    if not vals:
        return ''
    b = str(vals[0] or '').strip()
    if _merge_param_b_is_col_c_marker(b):
        if len(vals) > 1:
            return str(vals[1] or '').strip()
        return ''
    return b

def merge_run_pre_shell_from_doc(doc):
    """
    Запуск «Предварительный_скрипт» до разбора источников / сбора.

    Пустая ячейка (после разрешения B→C) — пропуск. Гейт: OS env MERGE_ALLOW_PRE_SCRIPT +
    зашифрованная глобальная Merge_Allow_Pre_Scripts (только runtime-карта,
    сегмент «Глобальные_переменные»). Отмена в диалоге / ошибка / таймаут —
    возвращает текст ошибки (сбор прервать). Успех или пропуск — None.
    """
    try:
        from libre_macros_pre_shell_lib import (
            confirm_pre_shell_before_run,
            parse_pre_shell_dict,
            run_pre_shell_from_param_raw,
            verify_pre_shell_allow_gate,
        )
    except Exception as err:
        return 'Не удалось загрузить libre_macros_pre_shell_lib: %s' % err
    try:
        table = read_param_table(doc)
    except Exception as err:
        return 'Не удалось прочитать параметры для предварительного скрипта: %s' % err
    raw = merge_pre_shell_param_raw(table)
    if str(raw or '').strip() == '':
        return None
    spec = parse_pre_shell_dict(raw)
    if spec is None:
        return None
    # Карта ещё не заполнена parse_collect_settings — засеять только глобальные.
    try:
        _merge_seed_globals_into_variables_map()
    except Exception as err:
        return 'Предварительный_скрипт запрещён: не удалось загрузить глобальные переменные: %s' % err
    gate_err = verify_pre_shell_allow_gate(
        getattr(_cw_cfg, '_MERGE_SOURCE_VARIABLES_MAP', None) or {},
    )
    if gate_err:
        merge_debug('pre_shell', 'allow gate denied')
        try:
            append_collect_log(
                doc, '', '', '', '', 'предварительный_скрипт',
                str(gate_err).replace('\n', ' | ')[:800],
            )
        except Exception:
            pass
        return gate_err
    param_sheet = get_run_param_sheet(doc)
    param_sheet_name = u''
    if param_sheet is not None:
        try:
            param_sheet_name = unicode(param_sheet.getName())
        except Exception:
            param_sheet_name = u''
    if not confirm_pre_shell_before_run(
        doc,
        spec,
        table=table,
        param_sheet_name=param_sheet_name,
        macro_version=MACRO_VERSION,
    ):
        merge_debug('pre_shell', 'cancelled by user')
        try:
            append_collect_log(
                doc, '', '', '', '', 'предварительный_скрипт',
                'отмена: пользователь не подтвердил запуск',
            )
        except Exception:
            pass
        return 'Запуск предварительного скрипта отменён пользователем.'
    merge_debug('pre_shell', 'start')
    try:
        append_collect_log(
            doc, '', '', '', '', 'предварительный_скрипт', 'запуск…',
        )
    except Exception:
        pass
    err_text, result = run_pre_shell_from_param_raw(raw)
    if err_text:
        merge_debug('pre_shell', 'fail: %s' % err_text)
        try:
            append_collect_log(
                doc, '', '', '', '', 'предварительный_скрипт',
                str(err_text).replace('\n', ' | ')[:800],
            )
        except Exception:
            pass
        return err_text
    if result is None:
        merge_debug('pre_shell', 'skip (empty argv)')
        return None
    argv_s = ' '.join(result.get('argv') or [])
    merge_debug('pre_shell', 'ok returncode=0 argv=%s' % argv_s)
    try:
        append_collect_log(
            doc, '', '', '', '', 'предварительный_скрипт',
            'ok, argv=%s' % argv_s[:400],
        )
    except Exception:
        pass
    return None

def parse_collect_settings(doc, validate_sources=True, interactive_manual=True):
    """
    Полная сборка настроек сбора из листа «Параметры_Объединения».

    Назначение:
        Прочитать таблицу, развернуть маски файлов, построить per_file_*,
        проверить MIXED в фильтрах, пути, пустые glob, распарсить постобработку.

    Параметры:
        doc — книга результата.
        validate_sources — проверять наличие файлов по маскам.
        interactive_manual — показывать диалоги ручного ввода (False = prevalidate pack).

    Возвращает:
        (err_text, None) — фatalная ошибка до копирования;
        (None, settings) — dict с files, mode, per_file_*, path_display,
        sheets_undelete, postprocess_range, postprocess_row, param_comment.

    Связь:
        collect_workbooks (этап 1), collect_workbooks_run(этап 2), run_collect_merge.
    """
    try:
        from libre_macros_global_settings_lib import apply_runtime_param_sheet_prefix

        apply_runtime_param_sheet_prefix()
    except Exception:
        pass
    # Не тянуть устаревший filter C с прошлого запуска в превалидацию/разбор.
    try:
        _cw_set('_MERGE_SHEETS_INCLUDE_FILTER_FN', None)
    except Exception:
        pass
    param_sheet = get_run_param_sheet(doc)
    if param_sheet is None:
        err_ps, param_sheet = resolve_param_sheet_for_run(doc)
        if err_ps:
            return (err_ps, None)
        set_run_param_sheet(param_sheet)
    ensure_macro_version(doc)
    path_stop, path_stop_msg = _merge_fixup_source_paths_in_param_sheet(doc)
    if path_stop:
        try:
            refresh_document(doc)
        except Exception:
            pass
        return (path_stop_msg, None)
    table = read_param_table(doc)
    flag_applied, flag_warnings, merge_flags = apply_merge_flag_settings_from_table(table)
    advanced_applied, advanced_warnings = apply_merge_advanced_settings_from_table(table)
    raw_files = _merge_param_row_sparse_values(doc, _cw_cfg.P_MERGE_FILES, min_cols=0)
    raw_files, inferred_source_cols = _merge_expand_sparse_source_files(doc, table, raw_files)
    doc_path = _merge_doc_system_path(doc)
    # Карта переменных до разворота масок: globals + ручной ввод «выше файлов»
    # → плейсхолдеры в путях и file_pick_lambda.
    # Кэш диалогов НЕ очищаем здесь: parse вызывается на этапе 1 и 2.
    _merge_seed_globals_into_variables_map()
    manual_before, manual_after = collect_manual_variable_input_specs(doc)
    ok_manual, manual_early = run_manual_variable_input_dialogs(
        manual_before, doc=doc, interactive=bool(interactive_manual),
    )
    if not ok_manual:
        return (
            'Сбор прерван: отменён обязательный ручной ввод в карту переменных.',
            None,
        )
    raw_files = _merge_expand_placeholders_in_source_paths(raw_files)
    # Не жёстко валидировать пути, пока нет интерактивного ввода:
    # prevalidate pack (interactive_manual=False) иначе подставляет default
    # и падает на «Не найдены файлы» до диалога ручного ввода.
    if validate_sources:
        unresolved_paths = []
        ui = 0
        while ui < len(raw_files):
            rp = raw_files[ui]
            ui = ui + 1
            if _merge_path_has_variable_placeholder(rp):
                unresolved_paths.append(str(rp))
        if unresolved_paths:
            return (
                'В «Файлы-Источники» не подставлены переменные из карты:\n'
                + '\n'.join(unresolved_paths)
                + '\n\nСтрока «Ручной_ввод_в_карту_переменных» должна быть выше «Файлы-Источники» '
                '(или переменная — в глобальных настройках).',
                None,
            )
    per_col_source_extra = _merge_source_extra_dicts_by_source_col(doc, max(len(raw_files), 1))
    files, param_col_for_file, empty_globs, is_current_book_flags = expand_source_files(
        raw_files,
        current_book_path=doc_path,
        per_col_source_extra=per_col_source_extra,
    )
    if validate_sources and len(empty_globs) > 0:
        return ('По маске не найдено ни одного файла:\n' + '\n'.join(empty_globs), None)
    ok_manual2, manual_late = run_manual_variable_input_dialogs(
        manual_after, doc=doc, interactive=bool(interactive_manual),
    )
    if not ok_manual2:
        return (
            'Сбор прерван: отменён обязательный ручной ввод в карту переменных.',
            None,
        )
    manual_variables = list(manual_early) + list(manual_late)
    mode = _normalize_collect_merge_mode(first_value(table, _cw_cfg.P_MERGE_MODE, 'На один лист'))
    path_display = parse_path_display_mode(table)
    datetime_display = parse_datetime_display_mode(table)
    try:
        data_transfer_mode = parse_data_transfer_mode(table)
    except ValueError as err:
        return (str(err), None)
    involve_extra_warnings = []
    if mode == _cw_cfg.MERGE_MODE_INVOLVE:
        if data_transfer_mode == _cw_cfg.MERGE_TRANSFER_XML_EXCEL_ODS:
            involve_extra_warnings.append(
                'Способ_переноса «xml_excel_ods» не используется в режиме «Текущие листы» (перенос не выполняется).'
            )
            data_transfer_mode = _cw_cfg.MERGE_TRANSFER_API
        elif data_transfer_mode not in (_cw_cfg.MERGE_TRANSFER_API,):
            involve_extra_warnings.append(
                'Способ_переноса игнорируется в режиме «Текущие листы».'
            )
            data_transfer_mode = _cw_cfg.MERGE_TRANSFER_API
    if data_transfer_mode == _cw_cfg.MERGE_TRANSFER_XML_EXCEL_ODS and mode in (_cw_cfg.MERGE_MODE_ONE, _cw_cfg.MERGE_MODE_MANY, _cw_cfg.MERGE_MODE_COPY):
        err_xml_saved = _merge_xml_excel_ods_require_saved_book(doc)
        if err_xml_saved:
            return (err_xml_saved, None)
    service_layout = _merge_effective_service_layout({'mode': mode, 'path_display': path_display, 'datetime_display': datetime_display, 'data_transfer_mode': data_transfer_mode})
    sheets_undelete = merge_param_sheets_into_undelete(doc, parse_sheets_undelete_list(table))
    sheets_undelete_filter = parse_sheets_undelete_filter(table)
    sheets_force_delete = parse_sheets_force_delete_list(table)
    sheets_force_delete_filter = parse_sheets_force_delete_filter(table)
    n_source_cols = max(len(raw_files), int(inferred_source_cols or 0))
    n = len(files)
    if mode == _cw_cfg.MERGE_MODE_INVOLVE:
        bad_src = []
        fi_inv = 0
        while fi_inv < len(files):
            is_curr = is_current_book_flags[fi_inv] if fi_inv < len(is_current_book_flags) else False
            if not is_curr:
                bad_src.append(str(files[fi_inv]))
            fi_inv = fi_inv + 1
        if len(raw_files) == 0 or n == 0:
            return ('Не задан параметр «Файлы-Источники».', None)
        if bad_src:
            return (
                'Режим «Текущие листы» допускает только источник эта_книга / ThisWorkbook.\n'
                'Недопустимо:\n' + '\n'.join(bad_src),
                None,
            )
        # Несколько маркеров → один логический источник (спеки — с первого столбца).
        files = [_cw_cfg.MERGE_CURRENT_BOOK_MARKER]
        is_current_book_flags = [True]
        if param_col_for_file:
            param_col_for_file = [param_col_for_file[0]]
        else:
            param_col_for_file = [0]
        n_source_cols = 1
        n = 1
    per_file_blocks = build_per_file_block_settings(table, param_col_for_file, n_source_cols)
    per_file_sheet_specs = build_per_file_sheet_specs(table, param_col_for_file, n_source_cols)
    sheets_include_filter = parse_sheets_include_filter(table)
    sheets_include_filter_fn = None
    if sheets_include_filter:
        try:
            from libre_macros_sheet_filter_lib import compile_sheet_name_filter

            sheets_include_filter_fn = compile_sheet_name_filter(sheets_include_filter)
        except Exception as err:
            return (u'Параметр «Листы»: ошибка фильтра (C): %s' % err, None)
    per_file_col_specs = build_per_file_col_specs(table, param_col_for_file, n_source_cols)
    per_file_col_rename_items = build_per_file_col_rename_items(table, param_col_for_file, n_source_cols)
    per_file_skip_row_specs = build_per_file_skip_row_specs(table, param_col_for_file, n_source_cols)
    per_file_source_extra = build_per_file_source_extra(doc, param_col_for_file, n_source_cols)
    if mode != _cw_cfg.MERGE_MODE_INVOLVE and sheets_undelete is not _cw_cfg.MERGE_SHEETS_UNDELETE_KEEP_ALL:
        for sn in merge_current_book_source_sheet_names(
            doc, per_file_sheet_specs, is_current_book_flags, filter_fn=sheets_include_filter_fn
        ):
            if sn not in sheets_undelete:
                sheets_undelete.append(sn)
    try:
        roots_errs = list(getattr(_cw_cfg, '_MERGE_SOURCE_ROOTS_EXPAND_ERRORS', None) or [])
    except Exception:
        roots_errs = []
    if roots_errs:
        return (u'\n\n'.join(unicode(e) for e in roots_errs), None)
    if len(raw_files) == 0 or n == 0:
        return ('Не задан параметр «Файлы-Источники».', None)
    try:
        from libre_macros_source_roots_lib import validate_expanded_sources

        err_roots = validate_expanded_sources(
            files,
            is_current_book_flags,
            book_path=get_current_book_path(),
            variables_map=getattr(_cw_cfg, '_MERGE_SOURCE_VARIABLES_MAP', None) or {},
        )
        if err_roots:
            return (unicode(err_roots), None)
    except Exception as err:
        merge_debug('source_roots', 'validate skip: %s' % err)
    if validate_sources:
        if len(empty_globs) > 0:
            return ('По маске не найдено ни одного файла:\n' + '\n'.join(empty_globs), None)
        missing = []
        fi_chk = 0
        while fi_chk < len(files):
            f = files[fi_chk]
            is_curr = is_current_book_flags[fi_chk] if fi_chk < len(is_current_book_flags) else False
            if not is_curr and (not os.path.isfile(f)):
                missing.append(f)
            fi_chk = fi_chk + 1
        if missing:
            return ('Не найдены файлы:\n' + '\n'.join(missing), None)
    err_open_src = _merge_check_open_sources_unsaved(files, is_current_book_flags)
    if err_open_src:
        return (err_open_src, None)
    si = 0
    while si < n:
        if classify_sheet_specs(per_file_sheet_specs[si]) == 'MIXED':
            return ('Файл %d: в «Листы» один тип в списке (через , или ;): только номера или только имена/шаблоны.' % (si + 1), None)
        if mode != _cw_cfg.MERGE_MODE_INVOLVE and classify_column_specs(per_file_col_specs[si]) == 'MIXED':
            return ('Файл %d: в «Столбцы» один тип в списке (через , или ;): номера, буквы (A) или имена.' % (si + 1), None)
        si = si + 1
    if mode == _cw_cfg.MERGE_MODE_INVOLVE:
        specs0 = per_file_sheet_specs[0] if per_file_sheet_specs else []
        kind0 = classify_sheet_specs(specs0)
        miss_sheets = _merge_involve_missing_sheet_specs(doc, specs0, kind0)
        skip_miss = False
        try:
            from libre_macros_source_extra_lib import source_extra_skip_missing_sheets

            extra0 = None
            if per_file_source_extra and len(per_file_source_extra) > 0:
                extra0 = per_file_source_extra[0]
            skip_miss = bool(source_extra_skip_missing_sheets(extra0))
        except Exception:
            skip_miss = False
        if miss_sheets and not skip_miss:
            return (
                'Режим «Текущие листы»: не найдены листы по фильтру «Листы»:\n' + '\n'.join(miss_sheets),
                None,
            )
        if miss_sheets and skip_miss:
            involve_extra_warnings.append(
                'skip_missing_sheets: пропускаем отсутствующие листы из «Листы»: %s'
                % ', '.join(miss_sheets[:20])
                + ('…' if len(miss_sheets) > 20 else '')
            )
        involve_slots = list(
            _iter_sheet_slots_current_book(
                doc, specs0, kind0, filter_fn=sheets_include_filter_fn
            )
        )
        if not involve_slots:
            # Диагностика: что отсеял filter C / служебные / INDEX→служебный.
            raw_slots = list(
                iter_sheet_slots(doc, specs0, kind0, filter_fn=sheets_include_filter_fn)
            )
            skipped_svc = []
            for slot in raw_slots:
                n = slot.get('source_name') or ''
                if _is_service_sheet(n):
                    skipped_svc.append(n)
            detail = []
            detail.append('«Листы»=%s (тип %s)' % (', '.join(str(s) for s in (specs0 or [])) or '«Все»', kind0))
            if sheets_include_filter:
                detail.append('фильтр C задан — проверьте лямбду (True = вовлечь)')
            if skipped_svc:
                detail.append(
                    'совпали, но служебные (не вовлекаются при «Все»/номере): %s'
                    % ', '.join(skipped_svc[:12])
                )
            if kind0 == 'INDEX':
                detail.append(
                    'номер в «Листы» выбирает лист по позиции слева направо, '
                    'не по имени «N_…»; для имени «1_Merge» укажите текст 1_Merge'
                )
            if not raw_slots and not skipped_svc:
                try:
                    all_names = sheet_names(doc)
                except Exception:
                    all_names = []
                detail.append(
                    'в книге вкладок: %d (%s)'
                    % (
                        len(all_names),
                        ', '.join(all_names[:8]) + ('…' if len(all_names) > 8 else ''),
                    )
                )
            return (
                'Нет листов для вовлечения (проверьте «Листы» и фильтр C; '
                'служебные вкладки не вовлекаются).\n' + '\n'.join(detail),
                None,
            )
    pipeline, pipeline_err = build_processing_pipeline(doc, _cw_cfg.MERGE_RESULT_POSTPROCESS_RANGE_MAP, _cw_cfg.MERGE_RESULT_POSTPROCESS_ROW_MAP)
    if pipeline_err:
        return ('Ошибка в настройках постобработки/ВПР:\n%s' % pipeline_err, None)
    err_plugin_gate = merge_verify_plugin_allow_gates(doc)
    if err_plugin_gate:
        return (err_plugin_gate, None)
    err_split_xml = _validate_split_sheets_xml_run_phase(doc, data_transfer_mode)
    if err_split_xml:
        return (err_split_xml, None)
    pp_range = parse_postprocess_from_sheet(doc, _cw_cfg.P_MERGE_POSTPROCESS_RANGE, _cw_cfg.MERGE_RESULT_POSTPROCESS_RANGE_MAP, row_callback=False)
    pp_row = parse_postprocess_from_sheet(doc, _cw_cfg.P_MERGE_POSTPROCESS_ROW, _cw_cfg.MERGE_RESULT_POSTPROCESS_ROW_MAP, row_callback=True)
    final_pp = parse_final_processing_from_sheet(doc, _cw_cfg.MERGE_FINAL_PROCESSING_MAP)
    cell_to_column_plan = build_cell_to_column_plan(doc, param_col_for_file, n_source_cols)
    add_to_variables_map_plan = build_add_to_variables_map_plan(doc, param_col_for_file, n_source_cols)
    delete_top_rows_map, delete_top_rows_per_file = parse_delete_top_rows_settings(table, n)
    xml_result_dir = first_value(table, _cw_cfg.P_MERGE_XML_RESULT_DIR, '').strip()
    flag_warnings = list(flag_warnings or []) + list(involve_extra_warnings)
    settings = {'files': files, 'is_current_book_flags': is_current_book_flags, 'mode': mode, 'param_comment': _merge_param_comment_from_table(table), 'per_file_sheet_specs': per_file_sheet_specs, 'per_file_col_specs': per_file_col_specs, 'per_file_col_rename_items': per_file_col_rename_items, 'per_file_blocks': per_file_blocks, 'per_file_skip_row_specs': per_file_skip_row_specs, 'per_file_source_extra': per_file_source_extra, 'path_display': path_display, 'datetime_display': datetime_display, 'data_transfer_mode': data_transfer_mode, 'service_layout': service_layout, 'sheets_undelete': sheets_undelete, 'sheets_undelete_filter': sheets_undelete_filter, 'sheets_force_delete': sheets_force_delete, 'sheets_force_delete_filter': sheets_force_delete_filter, 'sheets_include_filter': sheets_include_filter, 'sheets_include_filter_fn': sheets_include_filter_fn, 'postprocess_range': pp_range, 'postprocess_row': pp_row, 'final_processing': final_pp, 'processing_pipeline': pipeline, 'cell_to_column_plan': cell_to_column_plan, 'add_to_variables_map_plan': add_to_variables_map_plan, 'manual_variables': manual_variables, 'delete_top_rows_map': delete_top_rows_map, 'delete_top_rows_per_file': delete_top_rows_per_file, 'xml_postprocess_pipeline': build_xml_postprocess_pipeline(doc), 'xml_result_dir': xml_result_dir, 'param_sheet': param_sheet, 'flag_applied': flag_applied, 'flag_warnings': flag_warnings, 'merge_flags': merge_flags, 'advanced_applied': advanced_applied, 'advanced_warnings': advanced_warnings, 'split_sheets_deferred': collect_split_sheets_deferred_steps(doc)}
    return (None, settings)

def _merge_bind_postprocess_from_settings(doc, settings):
    """
    Подключить цепочки постобработки/ВПР/финала из settings к глобалам этапа 2.
    Вызывается до merge_on_* и после reopen в xml_excel_ods.
    """
    _cw_cfg._MERGE_PP_PIPELINE_STEP_DONE = set()
    _cw_cfg._MERGE_PROCESSING_PIPELINE = (settings or {}).get('processing_pipeline')
    _cw_cfg._MERGE_XML_POSTPROCESS_PIPELINE = (settings or {}).get('xml_postprocess_pipeline') or []
    _cw_cfg._MERGE_SPLIT_SHEETS_DEFERRED = (settings or {}).get('split_sheets_deferred') or []
    _cw_cfg._MERGE_FINAL_PROCESSING = (settings or {}).get('final_processing')
    _cw_cfg._MERGE_DELETE_TOP_ROWS_MAP = (settings or {}).get('delete_top_rows_map') or {}
    _cw_cfg._MERGE_DELETE_TOP_ROWS_PER_FILE = (settings or {}).get('delete_top_rows_per_file') or []
    _cw_cfg._MERGE_DELETE_TOP_ROWS_DONE = set()
    _cw_cfg._MERGE_RESULT_SKIPPED_TOP_ROWS = {}
    _cw_cfg._MERGE_RESULT_POSTPROCESS_RANGE = _merge_build_postprocess_chain((settings or {}).get('postprocess_range'), _cw_cfg._MERGE_CODE_POSTPROCESS_RANGE)
    _cw_cfg._MERGE_RESULT_POSTPROCESS_ROW = _merge_build_postprocess_chain((settings or {}).get('postprocess_row'), _cw_cfg._MERGE_CODE_POSTPROCESS_ROW)
    if doc is not None:
        _merge_log_postprocess_setup(doc, _cw_cfg.P_MERGE_POSTPROCESS_RANGE, _cw_cfg.MERGE_RESULT_POSTPROCESS_RANGE_MAP, 'диапазон')
        _merge_log_postprocess_setup(doc, _cw_cfg.P_MERGE_POSTPROCESS_ROW, _cw_cfg.MERGE_RESULT_POSTPROCESS_ROW_MAP, 'строка')
        _merge_log_postprocess_setup(doc, _cw_cfg.P_MERGE_POSTPROCESS_XML, _cw_cfg.MERGE_RESULT_POSTPROCESS_XML_MAP, 'xml')
        _merge_log_postprocess_setup(doc, _cw_cfg.P_MERGE_FINAL_PROCESSING, _cw_cfg.MERGE_FINAL_PROCESSING_MAP, 'финальная')
        if _cw_cfg._MERGE_RESULT_POSTPROCESS_RANGE is None and _cw_cfg._MERGE_RESULT_POSTPROCESS_ROW is None and (not _cw_cfg._MERGE_PROCESSING_PIPELINE):
            _merge_log_postprocess(doc, '', 'настройка', 'постобработка', 'пропуск', 'цепочка пуста (лист + код)')

def run_collect_merge(doc, settings, report):
    """
    Диспетчер режима сбора: merge_on_one_sheet, merge_on_many_sheets или merge_on_copy_sheets.

    Назначение:
        Собрать цепочки постобработки (_merge_build_postprocess_chain) в глобальные
        _MERGE_RESULT_POSTPROCESS_* и вызвать соответствующую функцию слияния.

    Параметры:
        doc — книга результата.
        settings — dict из parse_collect_settings.
        report — ProgressReport.

    Возвращает:
        bool — результат merge_on_*; False при неизвестном «Режим».

    Связь:
        collect_workbooks_run; apply_result_sheet_formatting внутри merge_on_*.
    """
    merge_debug('run_collect_merge', 'mode=%s' % settings.get('mode'))
    _cw_cfg._MERGE_NUMBER_FORMAT_CACHE.clear()
    _ensure_pp_from_lib()
    _cw_set('_MERGE_COLLECT_MODE', (settings or {}).get('mode'))
    _cw_set('_MERGE_INVOLVED_SHEET_NAMES', frozenset())
    try:
        from libre_macros_param_codec import columns_map_flatten_items
        _cw_set(
            '_MERGE_COL_MAP_ITEMS_FLAT',
            columns_map_flatten_items((settings or {}).get('per_file_col_rename_items')),
        )
    except Exception:
        _cw_set('_MERGE_COL_MAP_ITEMS_FLAT', [])
    _cw_set('_MERGE_SHEETS_WITH_MENU_AUTOFILTER', set())
    _cw_set('_MERGE_KEEP_SMART_TABLE_SHEETS', set())
    _cw_set('_MERGE_NEED_SMART_TABLE_REOPEN', False)
    _cw_set('_MERGE_SMART_TABLE_STYLES', {})
    _cw_set('_MERGE_SHEETS_INCLUDE_FILTER_FN', None)
    # До создания/копирования листов и до ветки xml_excel_ods (deferred UNO
    # читает тот же снимок).
    _merge_snapshot_collect_preexisting_sheets(doc)
    try:
        if (settings or {}).get('mode') != _cw_cfg.MERGE_MODE_INVOLVE and (settings or {}).get('data_transfer_mode') == _cw_cfg.MERGE_TRANSFER_XML_EXCEL_ODS:
            return _merge_run_collect_direct_xml_excel_ods(doc, settings, report)
    except Exception as _direct_err:
        try:
            report.problem('xml_excel_ods: %s' % str(_direct_err))
        except Exception:
            pass
        return False
    clear_pivot = globals().get('merge_pp_pivot_clear_materialized_registry')
    if clear_pivot is not None:
        try:
            clear_pivot()
        except Exception:
            pass
    clear_pending = globals().get('merge_pp_pivot_clear_as_values_pending')
    if clear_pending is not None:
        try:
            clear_pending()
        except Exception:
            pass
    clear_copy_pp = globals().get('merge_pp_copy_sheet_clear_pending')
    if clear_copy_pp is not None:
        try:
            clear_copy_pp()
        except Exception:
            pass
    merge_ui_set_phase('Сбор данных', 'копирование из источников')
    merge_ui_yield(force=True)
    _merge_bind_postprocess_from_settings(doc, settings)
    mode = settings['mode']
    merge_run_context_begin(settings)
    _merge_log_manual_variables_to_report(report)
    _merge_doc_auto_calc(doc, False)
    ui_locked = False
    ctrl_locked = False
    involve_protect = None
    if mode == _cw_cfg.MERGE_MODE_INVOLVE:
        involve_protect = _merge_involve_begin_sheet_protection(doc, report, settings=settings)
        if involve_protect is False:
            return False
    ui_locked = _merge_doc_action_lock(doc)
    ctrl_locked = _merge_doc_controller_lock(doc)
    try:
        if mode == _cw_cfg.MERGE_MODE_INVOLVE:
            merge_debug('run_collect_merge', 'branch merge_involve_sheets')
            merge_ui_set_phase('Вовлечение листов', 'без копирования')
            return merge_involve_sheets(
                doc,
                settings.get('per_file_sheet_specs') or [],
                settings.get('per_file_blocks') or [],
                report,
            )
        if mode == _cw_cfg.MERGE_MODE_ONE:
            merge_debug('run_collect_merge', 'branch merge_on_one_sheet')
            return merge_on_one_sheet(doc, settings['files'], settings.get('is_current_book_flags', []), settings['per_file_sheet_specs'], settings['per_file_col_specs'], settings['per_file_blocks'], settings.get('per_file_skip_row_specs', []), settings['path_display'], settings.get('cell_to_column_plan', []), report, settings.get('per_file_col_rename_items'))
        if mode == _cw_cfg.MERGE_MODE_MANY:
            merge_debug('run_collect_merge', 'branch merge_on_many_sheets')
            return merge_on_many_sheets(doc, settings['files'], settings.get('is_current_book_flags', []), settings['per_file_sheet_specs'], settings['per_file_col_specs'], settings['per_file_blocks'], settings.get('per_file_skip_row_specs', []), settings['path_display'], settings.get('cell_to_column_plan', []), report, settings.get('per_file_col_rename_items'))
        if mode == _cw_cfg.MERGE_MODE_COPY:
            merge_debug('run_collect_merge', 'branch merge_on_copy_sheets')
            return merge_on_copy_sheets(doc, settings['files'], settings.get('is_current_book_flags', []), settings['per_file_sheet_specs'], settings['per_file_col_specs'], settings['per_file_blocks'], settings.get('per_file_skip_row_specs', []), settings['path_display'], settings.get('cell_to_column_plan', []), report, per_file_col_rename_items=settings.get('per_file_col_rename_items'))
        report.problem('Неизвестный «Режим»: %s' % mode)
        return False
    finally:
        _merge_pp_finish_pending_copy_sheets(doc, report)
        doc = _merge_run_pipeline_final_phase(doc, report) or doc
        if involve_protect not in (None, False):
            try:
                involve_protect.finish()
            except Exception:
                pass
        _merge_doc_controller_unlock(doc, ctrl_locked)
        _merge_doc_action_unlock(doc, ui_locked)
        _merge_doc_auto_calc(doc, True)

def _merge_xml_deferred_uno_pending():
    """True, если после xml_excel_ods ожидает UNO-оформление / подмена файла."""
    job = _cw_get('_MERGE_XML_DEFERRED_UNO_JOB')
    if not isinstance(job, dict):
        return False
    if job.get('temp_path'):
        return True
    return job.get('doc') is not None


def _merge_xml_make_work_copy(target_path):
    """OS-копия файла результата во временный каталог (работа direct/UNO — только с копией)."""
    import shutil
    import tempfile

    target_path = os.path.abspath(str(target_path or '').strip())
    if target_path == '' or not os.path.isfile(target_path):
        raise ValueError('xml_excel_ods: нет файла для временной копии')
    ext = os.path.splitext(target_path)[1] or '.ods'
    fd, tmp_path = tempfile.mkstemp(prefix='libre_macros_xml_work_', suffix=ext)
    try:
        os.close(fd)
    except Exception:
        pass
    try:
        os.unlink(tmp_path)
    except Exception:
        pass
    shutil.copy2(target_path, tmp_path)
    merge_debug('xml_excel_ods', 'work_copy: %s -> %s' % (target_path, tmp_path))
    return tmp_path


def _merge_involve_sheet_names_for_protection(doc, settings):
    """Имена листов «Текущие листы», которые затронет сбор (для снятия защиты)."""
    if doc is None or settings is None:
        return None
    try:
        specs = (settings.get('per_file_sheet_specs') or [[]])[0]
    except Exception:
        specs = []
    kind = classify_sheet_specs(specs)
    if kind == 'MIXED':
        return None
    names = []
    seen = set()
    try:
        for slot in _iter_sheet_slots_current_book(doc, specs, kind):
            n = unicode(slot.get('source_name') or u'').strip()
            if n == u'' or n in seen:
                continue
            seen.add(n)
            names.append(n)
    except Exception as exc:
        merge_debug('involve_protect', 'sheet names: %s' % exc)
        return None
    return names if names else None


def _merge_involve_begin_sheet_protection(doc, report, settings=None):
    """
    Режим «Текущие листы»: снять защиту защищённых листов книги.
    Пароль — из «Доп_Параметры_Источника» (sheet_unprotect_password).
    Возвращает MergeSheetProtectSession, None (нет модуля) или False (ошибка).
    """
    try:
        from libre_macros_source_extra_lib import source_extra_sheet_unprotect_password
        from libre_macros_sheet_protect_lib import MergeSheetProtectSession
    except Exception as exc:
        merge_debug('involve_protect', 'import fail: %s' % exc)
        return None
    extra = _merge_source_extra_for_fi(0) or {}
    pwd = source_extra_sheet_unprotect_password(extra)
    merge_debug(
        'involve_protect',
        'password_len=%s extra_keys=%s'
        % (len(pwd or u''), sorted(list(extra.keys())) if isinstance(extra, dict) else []),
    )
    sheet_names = _merge_involve_sheet_names_for_protection(doc, settings)
    if sheet_names:
        merge_debug('involve_protect', 'target_sheets=%s' % sheet_names[:20])
    session = MergeSheetProtectSession(pwd)
    if not session.begin_doc(doc, sheet_names=sheet_names):
        if report is not None:
            report.problem(
                u'Не удалось снять защиту листов. Проверьте пароль '
                u'в «Доп_Параметры_Источника» (sheet_unprotect_password).'
            )
        return False
    return session


def _merge_xml_resolve_result_dir(doc, settings):
    """
    Абсолютный путь «Папка_результата».
    Пусто / не задано — системный temp (tempfile.gettempdir()).
    Относительный путь — от каталога книги.
    """
    import tempfile

    raw = str((settings or {}).get('xml_result_dir') or '').strip()
    if raw == '':
        return os.path.abspath(tempfile.gettempdir())
    if os.path.isabs(raw):
        return os.path.abspath(raw)
    base = ''
    try:
        base = os.path.dirname(_merge_doc_system_path(doc) or '')
    except Exception:
        base = ''
    if base == '':
        return os.path.abspath(raw)
    return os.path.abspath(os.path.join(base, raw))


def _merge_xml_make_outdir_work_copy(target_path, out_dir):
    """
    Копия книги в «Папка_результата» (без OS temp и без подмены открытого файла).
    Имя: «исходное-result.ext».
    """
    import shutil

    target_path = os.path.abspath(str(target_path or '').strip())
    out_dir = os.path.abspath(str(out_dir or '').strip())
    if target_path == '' or not os.path.isfile(target_path):
        raise ValueError('xml_excel_ods: нет файла для копии: %s' % target_path)
    if out_dir == '':
        raise ValueError(
            u'xml_excel_ods: не задана «%s» (папка для файла результата).'
            % _cw_cfg.P_MERGE_XML_RESULT_DIR
        )
    try:
        if not os.path.isdir(out_dir):
            os.makedirs(out_dir)
    except Exception as err:
        raise ValueError(
            u'xml_excel_ods: не удалось создать «%s»: %s\n%s'
            % (_cw_cfg.P_MERGE_XML_RESULT_DIR, out_dir, err)
        )
    base = os.path.basename(target_path)
    stem, ext = os.path.splitext(base)
    if ext == '':
        ext = '.xlsx'
    dest = os.path.join(out_dir, stem + '-result' + ext)
    shutil.copy2(target_path, dest)
    merge_debug('xml_excel_ods', 'outdir_work_copy: %s -> %s' % (target_path, dest))
    return dest


def _merge_xml_open_path(path, hidden=False):
    """Открыть книгу по пути средствами UNO (без принудит. minimize)."""
    path = os.path.abspath(str(path or '').strip())
    if path == '' or not os.path.isfile(path):
        raise ValueError('xml_excel_ods: файл не найден: %s' % path)
    url = uno.systemPathToFileUrl(path)
    props = (make_load_prop('Hidden', bool(hidden)), make_load_prop('ReadOnly', False))
    try:
        opened = _merge_run_with_suppressed_office_info(
            lambda: XSCRIPTCONTEXT.getDesktop().loadComponentFromURL(
                url, '_blank', 0, props
            ),
            primary_doc=get_run_target_doc(),
        )
    except Exception as err:
        raise ValueError('xml_excel_ods: не удалось открыть файл: %s' % err)
    if opened is None:
        raise ValueError('xml_excel_ods: не удалось открыть файл (None): %s' % path)
    return opened


def _merge_xml_save_doc(doc):
    """Сохранить открытую книгу (.uno:Save)."""
    if doc is None:
        return
    try:
        if getattr(doc, 'isModified', None) is not None and (not doc.isModified()):
            return
    except Exception:
        pass
    try:
        _merge_execute_dispatch(doc, '.uno:Save')
    except Exception:
        try:
            _merge_execute_dispatch(doc, '.uno:Save')
        except Exception:
            pass


def _merge_xml_store_filter_for_path(path):
    """FilterName для storeAsURL/storeToURL по расширению."""
    ext = os.path.splitext(str(path or ''))[1].lower()
    if ext in ('.xlsx', '.xlsm'):
        return 'Calc MS Excel 2007 XML'
    if ext == '.xls':
        return 'MS Excel 97'
    if ext == '.ods':
        return 'calc8'
    return 'Calc MS Excel 2007 XML'


def _merge_xml_save_as_doc(doc, dest_path):
    """
    UNO Save As: сохранить открытую книгу в dest_path с Overwrite.

    Только storeAsURL — документ обязан сменить location на dest_path.
    Fallback storeToURL запрещён: иначе OS-копия поверх исходного пути
    при открытой книге крашит AlterOffice (особенно ODS).
    """
    if doc is None:
        raise ValueError('xml_excel_ods: save as — нет документа')
    dest_path = os.path.abspath(str(dest_path or '').strip())
    if dest_path == '':
        raise ValueError('xml_excel_ods: save as — пустой путь')
    dest_url = uno.systemPathToFileUrl(dest_path)
    filter_name = _merge_xml_store_filter_for_path(dest_path)
    store_props = (
        make_load_prop('FilterName', filter_name),
        make_load_prop('Overwrite', True),
    )
    merge_debug(
        'xml_excel_ods',
        'save_as: %s (filter=%s)' % (dest_path, filter_name),
    )
    try:
        doc.storeAsURL(dest_url, store_props)
    except Exception as err:
        raise ValueError(
            u'xml_excel_ods: Save As (storeAsURL) не удался.\n'
            u'Путь: %s\nФильтр: %s\nОшибка: %s'
            % (dest_path, filter_name, err)
        )
    after = str(_merge_doc_system_path(doc) or '').strip()
    if not _merge_paths_same(after, dest_path):
        raise ValueError(
            u'xml_excel_ods: после Save As книга не привязана к временному файлу '
            u'(location не сменился).\n'
            u'Ожидалось: %s\nФактически: %s\n'
            u'Перезапись исходного пути при открытой книге запрещена.'
            % (dest_path, after if after else u'(пусто)')
        )
    if not os.path.isfile(dest_path):
        raise ValueError(
            u'xml_excel_ods: после Save As файл не найден на диске:\n%s' % dest_path
        )
    return dest_path


def _merge_xml_alloc_work_path(original_path):
    """Путь /tmp/libre_macros_xml_*.ext под UNO Save As (файл ещё не создан)."""
    import tempfile

    original_path = os.path.abspath(str(original_path or '').strip())
    ext = os.path.splitext(original_path)[1] or '.ods'
    fd, tmp_path = tempfile.mkstemp(prefix='libre_macros_xml_', suffix=ext)
    try:
        os.close(fd)
    except Exception:
        pass
    try:
        os.unlink(tmp_path)
    except Exception:
        pass
    return os.path.abspath(tmp_path)


def _merge_xml_wipe_and_close_anchor(anchor):
    """
    В якорь — один чистый лист, остальные удалить; закрыть с сохранением.
    """
    if anchor is None:
        return
    try:
        sheets = anchor.Sheets
        blank = u'Лист1'
        n = 1
        while True:
            taken = False
            try:
                i = 0
                while i < sheets.getCount():
                    if str(sheets.getByIndex(i).Name or '') == blank:
                        taken = True
                        break
                    i += 1
            except Exception:
                taken = False
            if not taken:
                break
            n += 1
            blank = u'Лист%d' % n
        sheets.insertNewByName(blank, sheets.getCount())
        try:
            anchor.getCurrentController().setActiveSheet(sheets.getByName(blank))
        except Exception:
            pass
        to_remove = []
        i = 0
        while i < sheets.getCount():
            nm = str(sheets.getByIndex(i).Name or '')
            if nm != blank:
                to_remove.append(nm)
            i += 1
        for nm in to_remove:
            try:
                if nm in sheets:
                    sheets.removeByName(nm)
            except Exception:
                pass
        merge_debug('xml_excel_ods', 'finish wipe anchor: keep=%s removed=%d' % (blank, len(to_remove)))
    except Exception as err:
        merge_debug('xml_excel_ods', 'finish wipe anchor failed: %s' % err)
    try:
        anchor.close(True)
    except Exception:
        try:
            _merge_xml_save_doc(anchor)
        except Exception:
            pass
        _merge_xml_close_doc(anchor, save=False)
    merge_debug('xml_excel_ods', 'finish wipe anchor: closed with save')


def _merge_xml_close_doc(doc, save=False):
    """Закрыть книгу UNO."""
    if doc is None:
        return
    try:
        doc.close(bool(save))
    except Exception:
        try:
            doc.dispose()
        except Exception:
            pass


def _merge_xml_replace_path(src_path, dst_path):
    """Заменить dst содержимым src (OS). После закрытия якоря dst свободен."""
    import shutil

    src_path = os.path.abspath(str(src_path or '').strip())
    dst_path = os.path.abspath(str(dst_path or '').strip())
    if src_path == '' or not os.path.isfile(src_path):
        raise ValueError('xml_excel_ods: нет временного файла: %s' % src_path)
    if dst_path == '':
        raise ValueError('xml_excel_ods: пустой путь результата')
    merge_debug('xml_excel_ods', 'replace: %s -> %s' % (src_path, dst_path))
    try:
        os.replace(src_path, dst_path)
        return dst_path
    except Exception:
        shutil.copy2(src_path, dst_path)
        try:
            os.unlink(src_path)
        except Exception:
            pass
        return dst_path


def _merge_xml_finish_replace_and_open(job):
    """
    Финал xml_excel_ods: закрыть якорь без save → подменить файл → открыть итог.
    """
    if not isinstance(job, dict):
        return None
    anchor = job.get('anchor_doc')
    temp_path = job.get('temp_path')
    final_path = job.get('final_path')
    # Снять якорь и закрыть без сохранения (содержимое устарело).
    try:
        if _cw_cfg._merge_ui_anchor_doc is anchor:
            _merge_ui_anchor_end(activate_doc=None, close_anchor=True)
        elif anchor is not None:
            _merge_xml_close_doc(anchor, save=False)
    except Exception as err:
        merge_debug('xml_excel_ods', 'finish: close anchor failed: %s' % err)
    set_run_target_doc(None)
    _merge_set_debug_log_doc(None)
    if not temp_path or not final_path:
        return None
    try:
        _merge_xml_replace_path(temp_path, final_path)
    except Exception as err:
        merge_debug('xml_excel_ods', 'finish: replace failed: %s' % err)
        raise
    merge_ui_set_phase('Завершение', 'открытие итогового файла', journal=False)
    final_doc = _merge_xml_open_path(final_path, hidden=False)
    set_run_target_doc(final_doc)
    _merge_set_debug_log_doc(final_doc)
    try:
        _merge_activate_document(final_doc)
    except Exception:
        pass
    return final_doc


def _merge_run_collect_direct_xml_excel_ods(doc, settings, report):
    """
    Реализация MERGE_TRANSFER_XML_EXCEL_ODS (two-doc, AlterOffice-safe).

    Алгоритм (AlterOffice early-relocate):
      - сохранить книгу; storeAsURL якоря → системный temp
        (.ods → temp/*.xlsx; иначе тот же формат)
      - direct пишет в work_path
        (.ods: OS-копия temp xlsx → рядом с исходником как .xlsx;
         иначе исходный путь)
      - финал: открыть результат → UNO
        (.ods: storeAsURL в исходный .ods; якорь закрывается;
         sidecar .xlsx не удаляется)
    """
    import shutil

    if doc is None:
        raise ValueError('нет активной книги результата')
    mode = (settings or {}).get('mode') or ''
    if mode not in (_cw_cfg.MERGE_MODE_ONE, _cw_cfg.MERGE_MODE_MANY, _cw_cfg.MERGE_MODE_COPY):
        raise ValueError('xml_excel_ods: поддерживаются только режимы «На один лист», «На разные листы» и «Копирование листов»')
    err_saved = _merge_xml_excel_ods_require_saved_book(doc)
    if err_saved:
        raise ValueError(err_saved)
    copied_result_sheet_names = []
    merge_debug('xml_excel_ods', 'begin: target_doc=%s' % (getattr(doc, 'Title', '') or ''))
    merge_ui_set_phase('Прямой перенос', 'подготовка')
    merge_ui_yield(force=True)
    if _merge_doc_is_unsaved(doc):
        raise ValueError(_merge_xml_excel_ods_require_saved_book(doc) or 'xml_excel_ods: книга результата не сохранена (нужен файл .ods/.xlsx на диске)')
    merge_debug('xml_excel_ods', 'save: start')
    merge_ui_set_phase('Прямой перенос', 'сохранение книги', journal=False)
    _merge_xml_save_doc(doc)
    merge_debug('xml_excel_ods', 'save: done')
    original_target_path = os.path.abspath(str(_merge_doc_system_path(doc) or '').strip())
    merge_debug('xml_excel_ods', 'target_path=%s' % (original_target_path or ''))
    if original_target_path == '':
        raise ValueError('xml_excel_ods: книга результата не сохранена (нужен файл .ods на диске)')
    if not os.path.isfile(original_target_path):
        raise ValueError('xml_excel_ods: не найден файл результата: %s' % original_target_path)
    # До direct-чтения и Постобработка_xml: иначе карта переменных пуста
    # (в run_collect_merge begin вызывается только после early-return xml-ветки).
    try:
        merge_run_context_begin(settings)
        _merge_log_manual_variables_to_report(report)
        merge_debug(
            'xml_excel_ods',
            'merge_run_context_begin: variables=%d'
            % len(getattr(_cw_cfg, '_MERGE_SOURCE_VARIABLES_MAP', {}) or {}),
        )
    except Exception as err:
        merge_debug('xml_excel_ods', 'merge_run_context_begin failed: %s' % err)
    origin_is_ods = _merge_xml_path_is_ods(original_target_path)
    no_replace = bool(getattr(_cw_cfg, 'MERGE_XML_NO_REPLACE', False))
    early_relocate = bool(no_replace)
    # ODS + early-relocate: работаем как xlsx (не odfpy copy в .ods).
    use_direct_copy_ods = (
        mode == _cw_cfg.MERGE_MODE_COPY
        and origin_is_ods
        and (not early_relocate)
    )
    ods_final_via_uno = bool(early_relocate and origin_is_ods)
    anchor_tmp_path = None
    work_path = None
    if early_relocate:
        merge_ui_set_phase(
            'Прямой перенос',
            'якорь → temp (xlsx)' if origin_is_ods else 'якорь → temp',
            journal=False,
        )
        anchor_tmp_path = _merge_xml_relocate_anchor_to_tmp(doc, original_target_path)
        if ods_final_via_uno:
            if not anchor_tmp_path or not os.path.isfile(anchor_tmp_path):
                raise ValueError(
                    'xml_excel_ods: не удалось сохранить якорь ODS как temp XLSX'
                )
            work_path = _merge_xml_ods_sidecar_xlsx_path(original_target_path)
            if work_path == '':
                raise ValueError(
                    'xml_excel_ods: пустой путь sidecar XLSX для ODS'
                )
            _merge_xml_os_copy_file(anchor_tmp_path, work_path)
            merge_debug(
                'xml_excel_ods',
                'ods→xlsx work_path=%s (os_copy from %s, origin=%s)'
                % (work_path, anchor_tmp_path, original_target_path),
            )
        else:
            work_path = original_target_path
    if _cw_cfg._merge_ui_anchor_doc is None:
        _merge_ui_anchor_begin(settings, anchor_doc=doc)
    if mode == _cw_cfg.MERGE_MODE_COPY and (not use_direct_copy_ods):
        before_names = set()
        try:
            bi = 0
            while bi < result_doc.Sheets.getCount():
                sh0 = result_doc.Sheets.getByIndex(bi)
                if sh0 is not None:
                    before_names.add(str(getattr(sh0, 'Name', '') or ''))
                bi += 1
        except Exception:
            before_names = set()
        try:
            copied_ok = merge_on_copy_sheets(
                result_doc,
                (settings or {}).get('files') or [],
                (settings or {}).get('is_current_book_flags', []),
                (settings or {}).get('per_file_sheet_specs', []),
                (settings or {}).get('per_file_col_specs', []),
                (settings or {}).get('per_file_blocks', []),
                (settings or {}).get('per_file_skip_row_specs', []),
                (settings or {}).get('path_display', 'none'),
                (settings or {}).get('cell_to_column_plan', []),
                report,
                skip_phase2=True,
                per_file_col_rename_items=(settings or {}).get('per_file_col_rename_items'),
            )
            if not copied_ok:
                raise ValueError('нет скопированных листов по заданным фильтрам')
        except Exception as err:
            try:
                _merge_xml_close_doc(result_doc, save=False)
            except Exception:
                pass
            raise ValueError('xml_excel_ods: copy_sheets (UNO) ошибка: %s' % err)
        try:
            ai = 0
            while ai < result_doc.Sheets.getCount():
                sh1 = result_doc.Sheets.getByIndex(ai)
                ai += 1
                if sh1 is None:
                    continue
                nm1 = str(getattr(sh1, 'Name', '') or '')
                if nm1 in before_names:
                    continue
                if nm1 and (is_param_sheet_name(nm1) or nm1 in _cw_cfg.MERGE_SHEETS_UNDELETE_DEFAULT):
                    continue
                copied_result_sheet_names.append(nm1)
        except Exception:
            copied_result_sheet_names = []
    if mode == _cw_cfg.MERGE_MODE_COPY and (not use_direct_copy_ods) and copied_result_sheet_names:
        sync_dst = work_path if (ods_final_via_uno and work_path) else original_target_path
        try:
            _merge_xml_store_to_path(doc, sync_dst, overwrite=True)
            merge_debug('xml_excel_ods', 'sync copy_sheets to: %s' % sync_dst)
            merge_ui_yield(force=True)
        except Exception as err:
            merge_debug('xml_excel_ods', 'sync copy_sheets failed: %s' % err)
    _merge_flush_console_log_buffer(doc)
    set_run_target_doc(doc)
    _merge_set_debug_log_doc(doc)
    if early_relocate:
        if work_path is None:
            work_path = original_target_path
        merge_ui_set_phase(
            'Прямой перенос',
            'запись в sidecar xlsx' if ods_final_via_uno else 'запись в исходный путь',
            journal=False,
        )
        merge_debug('xml_excel_ods', 'direct: work on %s' % work_path)
    elif no_replace:
        out_dir = _merge_xml_resolve_result_dir(doc, settings)
        work_path = _merge_xml_make_outdir_work_copy(original_target_path, out_dir)
        merge_ui_set_phase('Прямой перенос', 'файл результата в «%s»' % out_dir, journal=False)
    else:
        merge_ui_set_phase('Прямой перенос', 'временная копия файла', journal=False)
        work_path = _merge_xml_make_work_copy(original_target_path)
    merge_debug('xml_excel_ods', 'direct: start (work=%s)' % work_path)
    import libre_macros_direct_lib as direct

    def _direct_ui_on_source(src_path, sheet_name='', row_hint=None):
        detail = short_name(src_path)
        if str(sheet_name or '').strip() != '':
            detail = '%s — «%s»' % (detail, str(sheet_name).strip())
        if row_hint is not None:
            detail = '%s (%s строк)' % (detail, int(row_hint))
        merge_ui_set_phase('Прямой перенос', detail, journal=False)

    def _direct_ui_journal(source, sheet, column, rows_n, status, note=''):
        # В лист лога не пишем здесь (result закрыт); буфер direct + UI-диалог.
        if report is not None:
            try:
                report.log_stat(source, sheet, column, rows_n, status, note)
            except Exception:
                pass
        if _merge_ui_is_dialog_mode():
            try:
                line = u'%s | %s | %s' % (status, sheet or source, note)
                merge_ui_log_append(line)
            except Exception:
                pass
    direct.direct_bind_ui({'pulse': lambda force=False: merge_ui_yield(force=force), 'source': _direct_ui_on_source, 'journal': _direct_ui_journal})
    xml_flags = (settings or {}).get('merge_flags') or {}
    global_on = bool(xml_flags.get('MERGE_XML_CONVERT_TO_NUMBERS', True))
    col_items = list(_cw_get('_MERGE_COL_MAP_ITEMS_FLAT') or [])
    has_explicit = False
    try:
        from libre_macros_param_codec import columns_map_has_explicit_convert
        has_explicit = columns_map_has_explicit_convert(col_items)
    except Exception:
        has_explicit = False
    convert_nums = global_on or has_explicit
    dt_formats = str(xml_flags.get('MERGE_XML_DATETIME_FORMATS', '') or '').strip()
    locale_opts = _merge_locale_for_direct(doc)
    gs_opts = {}
    try:
        from libre_macros_global_settings_lib import direct_options_from_global_settings
        gs_opts = direct_options_from_global_settings()
    except Exception:
        gs_opts = {}
    direct.direct_bind_options({'convert_to_numbers': convert_nums, 'convert_auto_probe': global_on, 'datetime_formats': dt_formats, 'locale_language': locale_opts.get('locale_language', ''), 'locale_country': locale_opts.get('locale_country', ''), 'default_date_format': gs_opts.get('default_date_format', ''), 'number_format': gs_opts.get('number_format', ''), 'font_name': gs_opts.get('font_name', ''), 'font_size': gs_opts.get('font_size', ''), 'column_map_items': col_items})
    merge_debug('xml_excel_ods', 'MERGE_XML_CONVERT_TO_NUMBERS=%s explicit_cols=%s convert=%s MERGE_XML_DATETIME_FORMATS=%r locale=%s-%s' % (global_on, has_explicit, convert_nums, dt_formats, locale_opts.get('locale_language', ''), locale_opts.get('locale_country', '')))
    merge_ui_set_phase('Прямой перенос', 'чтение источников и запись в файл результата')
    direct_overrides = {}
    tmp_paths = []
    eff_settings = dict(settings or {})
    try:
        try:
            import tempfile
            files = (settings or {}).get('files') or []
            for f in files:
                try:
                    src_path = os.path.abspath(f)
                except Exception:
                    continue
                ext = os.path.splitext(src_path)[1].lower()
                if ext != '.xls':
                    continue
                fd, tmp_xlsx = tempfile.mkstemp(prefix='libre_macros_xls_', suffix='.xlsx')
                try:
                    os.close(fd)
                except Exception:
                    pass
                ok = _merge_convert_xls_to_xlsx_via_uno(src_path, tmp_xlsx)
                if ok:
                    direct_overrides[src_path] = tmp_xlsx
                    tmp_paths.append(tmp_xlsx)
                else:
                    try:
                        os.unlink(tmp_xlsx)
                    except Exception:
                        pass
        except Exception:
            pass
        if direct_overrides:
            eff_settings['direct_source_overrides'] = direct_overrides
        eff_settings['direct_target_path'] = work_path
        if copied_result_sheet_names:
            eff_settings['direct_result_sheet_names'] = list(copied_result_sheet_names)
        target_ext = os.path.splitext(work_path)[1].lower()
        one_sheet = mode == _cw_cfg.MERGE_MODE_ONE
        if mode != _cw_cfg.MERGE_MODE_COPY:
            if target_ext == '.xlsx':
                if one_sheet:
                    direct.direct_merge_on_one_sheet_to_xlsx(work_path, eff_settings)
                else:
                    direct.direct_merge_on_many_sheets_to_xlsx(work_path, eff_settings)
            elif one_sheet:
                direct.direct_merge_on_one_sheet_to_ods(work_path, eff_settings)
            else:
                direct.direct_merge_on_many_sheets_to_ods(work_path, eff_settings)
        if mode == _cw_cfg.MERGE_MODE_COPY:
            trim_map = _merge_build_copy_sheets_auto_trim_map(eff_settings)
            delete_map = _merge_build_copy_sheets_explicit_delete_map(eff_settings)
            eff_settings['copy_sheets_block_by_name'] = dict(_cw_get('_MERGE_COPY_SHEETS_BLOCK_BY_NAME') or {})
            eff_settings['copy_sheets_file_index_by_name'] = dict(_cw_get('_MERGE_COPY_SHEETS_FILE_INDEX') or {})
        else:
            trim_map = {}
            delete_map = (eff_settings or {}).get('delete_top_rows_map') or {}
        copy_prepare = mode == _cw_cfg.MERGE_MODE_COPY and (trim_map or (convert_nums and copied_result_sheet_names))
        if copy_prepare:
            convert_sheets = []
            if convert_nums and copied_result_sheet_names:
                convert_sheets = _merge_csv_filter_sheets_for_number_date_convert(
                    copied_result_sheet_names
                )
                skipped_n = len(copied_result_sheet_names) - len(convert_sheets)
                if skipped_n > 0:
                    merge_debug(
                        'xml_excel_ods',
                        'skip CSV convert (Calc/матрица) sheets=%d remain=%d'
                        % (skipped_n, len(convert_sheets)),
                    )
            detail = 'обрезка и распознавание чисел/дат на скопированных листах' if convert_sheets else 'обрезка скопированных листов (заголовок/данные)'
            merge_ui_set_phase('Прямой перенос', detail, journal=False)
            direct.direct_apply_copy_sheets_row_trim_and_convert(
                work_path, trim_map, convert_sheets, header_row=0, convert=bool(convert_sheets)
            )
        elif trim_map:
            merge_ui_set_phase('Прямой перенос', 'обрезка скопированных листов (заголовок/данные)', journal=False)
            direct.direct_apply_copy_sheets_row_trim(work_path, trim_map)
        if mode == _cw_cfg.MERGE_MODE_COPY and (eff_settings or {}).get('per_file_col_rename_items'):
            merge_ui_set_phase('Прямой перенос', 'переименование столбцов на скопированных листах', journal=False)
            direct.direct_apply_copy_sheets_column_rename(work_path, eff_settings, trim_map=trim_map)
        if delete_map:
            merge_ui_set_phase('Прямой перенос', 'удаление верхних строк в файле', journal=False)
            skipped_top = (eff_settings or {}).get('result_skipped_top_rows') or {}
            direct.direct_apply_delete_top_rows(work_path, delete_map, skipped_top)
        merge_ui_set_phase('Постобработка_xml', 'шаги в файле', journal=True)
        direct.direct_run_xml_postprocess(work_path, eff_settings, one_sheet)
        try:
            refreshed = direct._direct_result_sheet_names_from_file(work_path, one_sheet)
            if refreshed:
                eff_settings['direct_result_sheet_names'] = list(refreshed)
                merge_debug('xml_excel_ods', 'result_sheets_after_xml_pp=%s' % (refreshed,))
        except Exception:
            pass
        merge_debug('xml_excel_ods', 'direct: done')
    except Exception:
        raise
    finally:
        direct.direct_bind_ui(None)
        direct.direct_bind_options(None)
    for p in tmp_paths:
        try:
            os.unlink(p)
        except Exception:
            pass
    _cw_cfg._MERGE_DIRECT_XML_FORMULAS_IN_FILE = direct.direct_xml_pp_applied_formulas()
    merge_debug('xml_excel_ods', 'formulas_in_file=%s' % (sorted(_cw_cfg._MERGE_DIRECT_XML_FORMULAS_IN_FILE),))
    pending_as_values = direct.direct_take_xml_as_values_pending()
    pending_freeze_sheets = direct.direct_take_xml_freeze_pending()
    pending_uno_pp = direct.direct_take_xml_uno_pending()
    _cw_cfg._MERGE_DIRECT_XML_FILE_VISUAL_SHEETS = frozenset(direct.direct_take_xml_file_visual_sheets())
    _cw_cfg._MERGE_FORMAT_HEADER_COLS = direct.direct_take_xml_format_header_cols()
    pending_created_sheets = []
    try:
        pending_created_sheets = list(direct.direct_take_xml_created_sheets() or [])
    except Exception:
        pending_created_sheets = []
    journal_entries = []
    try:
        journal_entries = list(direct.direct_take_journal_buffer() or [])
    except Exception:
        journal_entries = []
    try:
        synced_names = list((eff_settings or {}).get('direct_result_sheet_names') or [])
    except Exception:
        synced_names = []
    if pending_created_sheets:
        seen_keys = set()
        for nm in synced_names:
            try:
                seen_keys.add(merge_identity_key(str(nm or '')))
            except Exception:
                pass
        for entry in pending_created_sheets:
            nm = str((entry or {}).get('name') or '').strip()
            if nm == '':
                continue
            try:
                key = merge_identity_key(nm)
            except Exception:
                key = nm.casefold()
            if key in seen_keys:
                continue
            synced_names.append(nm)
            seen_keys.add(key)
        try:
            eff_settings['direct_result_sheet_names'] = list(synced_names)
        except Exception:
            pass
    if mode == _cw_cfg.MERGE_MODE_COPY and synced_names:
        copied_result_sheet_names = synced_names
        merge_debug('xml_excel_ods', 'result_sheets_after_xml=%s' % (copied_result_sheet_names,))
    elif mode == _cw_cfg.MERGE_MODE_MANY and synced_names:
        merge_debug('xml_excel_ods', 'many_result_sheets_after_xml=%s' % (synced_names,))
    merge_debug('xml_excel_ods', 'file_visual_sheets=%s' % (sorted(_cw_cfg._MERGE_DIRECT_XML_FILE_VISUAL_SHEETS),))
    _merge_ui_anchor_activate()
    _merge_bind_postprocess_from_settings(doc, settings)
    skip_uno = bool(getattr(_cw_cfg, 'MERGE_XML_SKIP_UNO_PHASE', False))
    merge_debug(
        'xml_excel_ods',
        'deferred: queued (two_doc: UNO on result keep-open → Finish activate)'
        if not skip_uno
        else 'deferred: queued (two_doc skip UNO → open result → Finish activate)',
    )
    _cw_cfg._MERGE_XML_DEFERRED_UNO_JOB = {
        'doc': None,
        'anchor_doc': doc,
        'anchor_tmp_path': anchor_tmp_path,
        'early_relocate': bool(early_relocate),
        'ods_final_via_uno': bool(ods_final_via_uno),
        'temp_path': work_path,
        'final_path': original_target_path,
        'result_path': work_path,
        'settings': settings,
        'report': report,
        'eff_settings': eff_settings,
        'mode': mode,
        'copied_result_sheet_names': list(copied_result_sheet_names),
        'pending_uno_pp': pending_uno_pp,
        'pending_freeze_sheets': pending_freeze_sheets,
        'pending_as_values': pending_as_values,
        'pending_created_sheets': pending_created_sheets,
        'journal_entries': journal_entries,
        'uno_done': bool(skip_uno),
        'skip_uno': bool(skip_uno),
        'two_doc_finish': True,
        'no_replace': False,
        'skip_final_message': False,
    }
    return True


def _merge_settings_force_statusbar(settings):
    """Копия settings с принудительным MERGE_PROGRESS_UI_MODE=statusbar."""
    out = dict(settings or {})
    flags = dict(out.get('merge_flags') or {})
    flags['MERGE_PROGRESS_UI_MODE'] = 'statusbar'
    out['merge_flags'] = flags
    return out


def _merge_run_xml_excel_ods_uno_on_temp(job):
    """
    Открыть файл результата → UNO-оформление/ПП → сохранить.
    При two_doc_finish результат НЕ закрывается. Якорь — только для диалога.
    Лог пишется в result, не в якорь.
    """
    if not isinstance(job, dict):
        return
    if job.get('uno_done'):
        return
    temp_path = job.get('temp_path') or job.get('result_path')
    if not temp_path:
        # legacy: doc уже открыт
        _merge_run_xml_excel_ods_uno_phase(job)
        return
    merge_ui_set_phase('Оформление', 'открытие файла результата', journal=False)
    temp_doc = _merge_xml_open_path(temp_path, hidden=False)
    job['doc'] = temp_doc
    report = job.get('report')
    if report is not None:
        report.doc = temp_doc
    try:
        reset_collect_log(temp_doc)
    except Exception:
        pass
    try:
        _st = job.get('settings') or {}
        _mode = str(_st.get('mode') or job.get('mode') or '')
        _nfc = len(_st.get('files') or [])
        append_collect_log(
            temp_doc,
            '',
            '',
            '',
            '',
            'старт',
            'v%s, режим %s, файлов %d (xml_excel_ods)'
            % (MACRO_VERSION, _mode, _nfc),
        )
    except Exception:
        pass
    set_run_target_doc(temp_doc)
    _merge_set_debug_log_doc(temp_doc)
    # journal entries
    for entry in list(job.get('journal_entries') or []):
        try:
            append_collect_log(temp_doc, entry[0], entry[1], entry[2], entry[3], entry[4], entry[5])
        except Exception:
            pass
    pending_created = list(job.get('pending_created_sheets') or [])
    if pending_created:
        try:
            _merge_pp_register_xml_created_sheets(temp_doc, pending_created)
        except Exception:
            pass
    try:
        _merge_bind_postprocess_from_settings(temp_doc, job.get('settings') or {})
    except Exception:
        pass
    # UNO phase consumes _MERGE_XML_DEFERRED_UNO_JOB — передаём копию без сброса temp
    job_run = dict(job)
    job_run['doc'] = temp_doc
    # Не давать фазе обнулить наш job с temp_path: временно спрячем
    saved = _cw_cfg._MERGE_XML_DEFERRED_UNO_JOB
    _cw_cfg._MERGE_XML_DEFERRED_UNO_JOB = None
    try:
        _merge_run_xml_excel_ods_uno_phase(job_run)
    finally:
        _cw_cfg._MERGE_XML_DEFERRED_UNO_JOB = saved
    merge_ui_set_phase('Оформление', 'сохранение результата', journal=False)
    try:
        _merge_xml_save_doc(temp_doc)
    except Exception as err:
        merge_debug('xml_excel_ods', 'result save failed: %s' % err)
    keep_open = bool(job.get('two_doc_finish'))
    if keep_open:
        job['doc'] = temp_doc
        job['uno_done'] = True
        merge_debug('xml_excel_ods', 'uno keep open (result); log on result')
        try:
            _merge_ui_anchor_activate()
        except Exception:
            pass
        # run_target / debug log остаются на result
        return
    _merge_xml_close_doc(temp_doc, save=False)
    job['doc'] = None
    job['uno_done'] = True
    try:
        _merge_ui_anchor_activate()
    except Exception:
        pass
    set_run_target_doc(job.get('anchor_doc'))
    _merge_set_debug_log_doc(job.get('anchor_doc'))
    if job.get('no_replace'):
        merge_debug('xml_excel_ods', 'uno_on_outdir: done, no replace')
    else:
        merge_debug('xml_excel_ods', 'uno_on_temp: done, waiting Finish replace')


def _merge_run_xml_excel_ods_uno_phase(job=None):
    """
    UNO-оформление, Постобработка_Диапазон/Строка, финал — после показа книги.

    Статус — только строка состояния Calc; лог — консоль и «Сбор_книг_лог».
    """
    if job is None:
        job = _cw_cfg._MERGE_XML_DEFERRED_UNO_JOB
    if not isinstance(job, dict):
        return
    _cw_cfg._MERGE_XML_DEFERRED_UNO_JOB = None

    doc = job.get("doc")
    settings = job.get("settings") or {}
    report = job.get("report")
    eff_settings = job.get("eff_settings") or {}
    mode = job.get("mode") or ""
    copied_result_sheet_names = list(job.get("copied_result_sheet_names") or [])
    pending_uno_pp = list(job.get("pending_uno_pp") or [])
    pending_freeze_sheets = list(job.get("pending_freeze_sheets") or [])
    pending_as_values = list(job.get("pending_as_values") or [])

    if doc is None:
        return

    forced_settings = _merge_settings_force_statusbar(settings)
    merge_ui_bind_settings(forced_settings)
    # Диалог прогресса не закрываем здесь: после UNO на temp ждём «Завершить».
    merge_ui_status_start(
        "Оформление…",
        _cw_cfg._merge_ui_progress_scale,
        settings=forced_settings,
    )
    merge_ui_set_phase("Оформление", "постобработка листов результата")

    merge_debug("xml_excel_ods", "deferred_uno: start")
    _cw_cfg._MERGE_DIRECT_XML_ACTIVE = True
    _merge_doc_auto_calc(doc, False)
    try:
        if pending_as_values:
            _merge_materialize_xml_as_values(doc, pending_as_values, report)
        try:
            merge_run_context_begin(settings)
            _merge_log_manual_variables_to_report(report)
        except Exception:
            pass

        formatted_sheet_names = []
        try:
            if mode == _cw_cfg.MERGE_MODE_ONE:
                one_sheet_names = []
                try:
                    one_sheet_names = list(
                        eff_settings.get("direct_result_sheet_names") or []
                    )
                except Exception:
                    one_sheet_names = []
                if not one_sheet_names:
                    one_sheet_names = [_cw_cfg.MERGE_ONE_SHEET_TARGET_NAME]
                elif _cw_cfg.MERGE_ONE_SHEET_TARGET_NAME not in one_sheet_names:
                    one_sheet_names = [_cw_cfg.MERGE_ONE_SHEET_TARGET_NAME] + list(
                        one_sheet_names
                    )
                applied_one_n = 0
                for nm in one_sheet_names:
                    sh = None
                    try:
                        sh = get_sheet(doc, nm)
                    except Exception:
                        sh = None
                    if sh is None:
                        if nm == _cw_cfg.MERGE_ONE_SHEET_TARGET_NAME:
                            raise ValueError(
                                "xml_excel_ods: не найден лист результата «%s»"
                                % _cw_cfg.MERGE_ONE_SHEET_TARGET_NAME
                            )
                        continue
                    try:
                        apply_result_sheet_formatting(doc, sh, report)
                        applied_one_n += 1
                        formatted_sheet_names.append(nm)
                    except Exception as err:
                        try:
                            report.problem(
                                "Оформление/постобработка «%s»: %s" % (nm, err)
                            )
                        except Exception:
                            pass
                merge_debug(
                    "xml_excel_ods",
                    "deferred one_sheet_format_n=%d names=%s"
                    % (applied_one_n, one_sheet_names),
                )
            else:
                try:
                    if mode == _cw_cfg.MERGE_MODE_COPY and copied_result_sheet_names:
                        applied_copy_n = 0
                        for nm in copied_result_sheet_names:
                            sh = None
                            try:
                                sh = get_sheet(doc, nm)
                            except Exception:
                                sh = None
                            if sh is None:
                                try:
                                    _merge_log_postprocess(
                                        doc,
                                        nm,
                                        "Оформление",
                                        "лист",
                                        "пропуск",
                                        "лист не найден после xml (возможно переименован)",
                                    )
                                except Exception:
                                    pass
                                continue
                            try:
                                apply_result_sheet_formatting(doc, sh, report)
                                applied_copy_n += 1
                                formatted_sheet_names.append(nm)
                            except Exception:
                                pass
                        if applied_copy_n == 0:
                            i = 0
                            while i < doc.Sheets.getCount():
                                sh = doc.Sheets.getByIndex(i)
                                if sh is None:
                                    i += 1
                                    continue
                                nm = getattr(sh, "Name", "")
                                if nm and (
                                    is_param_sheet_name(nm)
                                    or nm in _cw_cfg.MERGE_SHEETS_UNDELETE_DEFAULT
                                ):
                                    i += 1
                                    continue
                                try:
                                    apply_result_sheet_formatting(doc, sh, report)
                                    formatted_sheet_names.append(nm)
                                except Exception:
                                    pass
                                i += 1
                    else:
                        many_names = []
                        try:
                            many_names = list(
                                eff_settings.get("direct_result_sheet_names") or []
                            )
                        except Exception:
                            many_names = []
                        if many_names:
                            for nm in many_names:
                                sh = None
                                try:
                                    sh = get_sheet(doc, nm)
                                except Exception:
                                    sh = None
                                if sh is None:
                                    continue
                                try:
                                    apply_result_sheet_formatting(doc, sh, report)
                                    formatted_sheet_names.append(nm)
                                except Exception:
                                    pass
                        else:
                            i = 0
                            while i < doc.Sheets.getCount():
                                sh = doc.Sheets.getByIndex(i)
                                if sh is None:
                                    i += 1
                                    continue
                                nm = getattr(sh, "Name", "")
                                if nm and (
                                    is_param_sheet_name(nm)
                                    or nm in _cw_cfg.MERGE_SHEETS_UNDELETE_DEFAULT
                                ):
                                    i += 1
                                    continue
                                try:
                                    apply_result_sheet_formatting(doc, sh, report)
                                    formatted_sheet_names.append(nm)
                                except Exception:
                                    pass
                                i += 1
                except Exception as err:
                    try:
                        report.problem(
                            "Оформление/постобработка (много листов): %s" % err
                        )
                    except Exception:
                        pass

            try:
                refresh_document(doc)
            except Exception:
                pass
            merge_debug("xml_excel_ods", "deferred_uno: formatting done")
        finally:
            try:
                _merge_pp_finish_xml_created_sheets(
                    doc, report, already_formatted=formatted_sheet_names
                )
            except Exception:
                pass
            _merge_pp_finish_pending_copy_sheets(doc, report)
            doc = _merge_run_pipeline_final_phase(doc, report) or doc
            if pending_uno_pp:
                try:
                    _merge_apply_xml_uno_pending(doc, pending_uno_pp, report)
                except Exception:
                    pass
            if pending_freeze_sheets:
                try:
                    _merge_queue_xml_freeze(doc, pending_freeze_sheets, report)
                except Exception:
                    pass
            try:
                _merge_flush_xml_freeze_pending(doc)
            except Exception:
                pass
            _merge_doc_auto_calc(doc, True)
    finally:
        _cw_cfg._MERGE_DIRECT_XML_ACTIVE = False
        _cw_cfg._MERGE_DIRECT_XML_FORMULAS_IN_FILE = frozenset()
        _cw_cfg._MERGE_DIRECT_XML_FILE_VISUAL_SHEETS = frozenset()
        _cw_cfg._MERGE_FORMAT_HEADER_COLS = {}
        merge_ui_status_finish()
        merge_debug("xml_excel_ods", "deferred_uno: done")




def _merge_convert_xls_to_xlsx_via_uno(src_xls_path, dst_xlsx_path):
    """
    Конвертация .xls -> .xlsx через UNO (скрыто), чтобы потом прочитать openpyxl.
    Возвращает bool.
    """
    try:
        src_abs = os.path.abspath(src_xls_path)
        dst_abs = os.path.abspath(dst_xlsx_path)
        src_url = uno.systemPathToFileUrl(src_abs)
        dst_url = uno.systemPathToFileUrl(dst_abs)
        props = (make_load_prop('Hidden', True), make_load_prop('ReadOnly', True), make_load_prop('FilterName', 'MS Excel 97'))
        doc = XSCRIPTCONTEXT.getDesktop().loadComponentFromURL(src_url, '_blank', 0, props)
        if doc is None:
            return False
        try:
            store_props = (make_load_prop('FilterName', 'Calc MS Excel 2007 XML'), make_load_prop('Overwrite', True))
            doc.storeToURL(dst_url, store_props)
            return os.path.isfile(dst_abs)
        finally:
            try:
                doc.close(True)
            except Exception:
                try:
                    doc.dispose()
                except Exception:
                    pass
    except Exception:
        return False

def merge_xml_deferred_anchor_close():
    """
    Отложенное закрытие якоря xml_excel_ods (отдельный вызов макроса через dispatch).

    Связь:
        _merge_schedule_xml_anchor_close после OK в no_replace / open_result_only.
    """
    anchor = _cw_cfg._MERGE_XML_PENDING_ANCHOR_CLOSE
    _cw_cfg._MERGE_XML_PENDING_ANCHOR_CLOSE = None
    if anchor is None:
        return
    try:
        _merge_close_doc_save(anchor)
        merge_debug('xml_excel_ods', 'deferred: saved and closed anchor')
    except Exception as err:
        merge_debug('xml_excel_ods', 'deferred: close anchor failed: %s' % err)
    merge_ui_yield(force=True)

def collect_workbooks_reopen(event=None):
    """
    Сохранить, закрыть и снова открыть текущую книгу результата.

    Вызывается отдельно после collect_workbooks_run() с небольшой задержкой.
    """
    doc = None
    try:
        doc = get_run_target_doc()
        if doc is None:
            try:
                doc = XSCRIPTCONTEXT.getDocument()
            except Exception:
                doc = None
        if doc is None:
            merge_debug('collect_workbooks_reopen', 'skip: no active doc')
            return False
        path = _merge_open_doc_system_path(doc)
        if path == '':
            merge_debug('collect_workbooks_reopen', 'skip: empty doc path')
            return False
        merge_debug('collect_workbooks_reopen', 'start path=%s' % path)
        _merge_close_doc_save(doc)
        merge_ui_yield(force=True)
        desktop = XSCRIPTCONTEXT.getDesktop()
        reopened = desktop.loadComponentFromURL(
            uno.systemPathToFileUrl(path),
            '_default',
            0,
            (
                make_load_prop('Hidden', False),
                make_load_prop('ReadOnly', False),
            ),
        )
        if reopened is not None:
            set_run_target_doc(reopened)
            _merge_set_debug_log_doc(reopened)
            merge_debug('collect_workbooks_reopen', 'reopened=%s' % reopened.getTitle())
            return True
        merge_debug('collect_workbooks_reopen', 'reopen returned None')
        return False
    except Exception as err:
        merge_debug('collect_workbooks_reopen', 'error: %s' % err)
        return False

def _merge_collect_element_names(collection):
    """Имена элементов UNO-коллекции (getElementNames) → list[str]."""
    if collection is None:
        return []
    try:
        names = collection.getElementNames()
        if names is None:
            return []
        return [str(n) for n in tuple(names) if str(n).strip() != '']
    except Exception:
        return []

def _merge_clear_named_ranges_uno(doc):
    """
    Удалить все именованные диапазоны книги перед сбором данных.

    Снимает DatabaseRanges (таблицы Excel / диапазоны БД / автофильтры)
    и NamedRanges (именованные формульные диапазоны) средствами UNO.
    """
    if doc is None:
        return (0, 0)
    db_removed = 0
    nr_removed = 0
    try:
        db_ranges = doc.DatabaseRanges
        for name in list(_merge_collect_element_names(db_ranges)):
            try:
                if not db_ranges.hasByName(name):
                    continue
                db = db_ranges.getByName(name)
                try:
                    db.AutoFilter = False
                except Exception:
                    try:
                        db.setPropertyValue('AutoFilter', False)
                    except Exception:
                        pass
                db_ranges.removeByName(name)
                db_removed = db_removed + 1
            except Exception as err:
                merge_debug('_merge_clear_named_ranges_uno', 'DatabaseRange %s: %s' % (name, err))
    except Exception as err:
        merge_debug('_merge_clear_named_ranges_uno', 'DatabaseRanges: %s' % err)
    try:
        named = doc.NamedRanges
        for name in list(_merge_collect_element_names(named)):
            try:
                if not named.hasByName(name):
                    continue
                named.removeByName(name)
                nr_removed = nr_removed + 1
            except Exception as err:
                merge_debug('_merge_clear_named_ranges_uno', 'NamedRange %s: %s' % (name, err))
    except Exception as err:
        merge_debug('_merge_clear_named_ranges_uno', 'NamedRanges: %s' % err)
    if db_removed > 0 or nr_removed > 0:
        merge_debug('_merge_clear_named_ranges_uno', 'removed db=%d named=%d' % (db_removed, nr_removed))
        append_collect_log(doc, '', '', '', '', 'настройка', 'удалены именованные диапазоны: DatabaseRange=%d, NamedRange=%d' % (db_removed, nr_removed))
    return (db_removed, nr_removed)

def collect_workbooks(event=None):
    """
    Точка входа из меню LibreOffice — этап 1 (подготовка без открытия источников).

    Возвращает:
        bool — True, если сбор данных начат (dispatch или этап 2); иначе False.

    Назначение:
        1) get_run_target_doc, закрыть зависшие скрытые документы;
        2) parse_collect_settings — валидация параметров;
        3) schedule_collect_run → collect_workbooks_run в новом вызове;
           при сбое планировщика — прямой collect_workbooks_run().
        Очистку листов (maybe_clear_sheets) делает этап 2 после подтверждения запуска.

    Связь:
        g_exportedScripts; collect_workbooks_run; show_message при ошибках.
    """
    doc = None
    try:
        _ensure_pp_from_lib()
        _merge_debug_reset_timer()
        merge_debug('collect_workbooks', 'start')
        set_run_target_doc(None)
        doc = get_run_target_doc()
        if doc is None:
            show_message('Не открыта книга Calc.', None)
            return False
        if len(list_param_sheet_names(doc)) == 0:
            others = _merge_list_param_workbooks()
            if len(others) > 0:
                show_message('Активная книга не содержит лист параметров (collect_params… или Параметры_Объединения…).\nПереключитесь на нужную книгу и запустите макрос снова.', doc)
                return False
        set_run_target_doc(doc)
        active_param = get_active_param_sheet_name(doc)
        set_run_param_sheet(active_param if active_param else None)
        close_orphan_hidden_documents(doc)
        close_all_open_sources()
        _merge_clear_manual_variable_cache()
        defer_src = _merge_has_pre_shell_config(doc)
        err, settings = parse_collect_settings(doc, validate_sources=not defer_src)
        if err:
            show_collect_error(err, doc)
            return False
        _merge_apply_flags_from_settings(settings)
        _merge_set_debug_log_doc(doc)
        if _merge_debug_log_to_worksheet():
            reset_collect_log(doc)
        write_status_log(doc, 'Этап 1 OK, версия макроса %s. Запуск сбора…' % MACRO_VERSION)
        # Этап 1 уже показал ручной ввод — этап 2 не должен спрашивать снова.
        _cw_set('_MERGE_MANUAL_INPUT_DONE', True)
        # AO 2026: executeDispatch(collect_workbooks_run) часто зависает после «Этап 1 OK»
        # (макрос стартует, но дальше не идёт). По умолчанию — прямой вызов этапа 2.
        use_dispatch = bool(_cw_get('MERGE_SCHEDULE_STAGE2_VIA_DISPATCH', False))
        if use_dispatch:
            if schedule_collect_run(doc):
                merge_debug('collect_workbooks', 'stage 2 scheduled via dispatch')
                return True
            write_status_log(doc, 'Планировщик этапа 2 недоступен — прямой запуск.')
        merge_debug('collect_workbooks', 'stage 2 direct call')
        return collect_workbooks_run()

        #time.sleep(2)

        #collect_workbooks_reopen()
        #show_message('Обработка завершена. Нажмите ok и проверьте результат', get_run_target_doc())

    except Exception as err:
        merge_debug('collect_workbooks', 'error: %s' % err)
        show_message('Ошибка: %s' % err, doc)
        print(traceback.format_exc())
        return False

def collect_workbooks_run():
    """
    Точка входа этапа 2 — фактическое копирование данных из источников.

    Назначение:
        Сброс лога, ProgressReport, run_collect_merge, закрытие всех источников,
        итоговый MessageBox (до 25 предупреждений) или запись в «Сбор_книг_лог».

    Связь:
        schedule_collect_run / collect_workbooks (fallback); close_all_open_sources в finally.

    Возвращает:
        bool — True, если сбор данных начат; False при отмене/ошибке до старта.
    """
    doc = None
    report = None
    final_text = ''
    ok = False
    started = False
    mode_for_msg = ''
    file_count = 0
    progress_dialog_active = False
    final_message_shown = False
    try:
        _ensure_pp_from_lib()
        _merge_debug_reset_timer()
        merge_debug('collect_workbooks_run', 'start')
        try:
            import libre_macros_lib as _lm_clr
            clr = getattr(_lm_clr, 'lm_final_activate_sheet_clear', None)
            if callable(clr):
                clr()
        except Exception:
            pass
        _merge_ui_anchor_close(save=False)
        doc = get_run_target_doc()
        set_run_target_doc(doc)
        # Запомнить maximize до диалогов (оркестратор мог уже сохранить).
        if not _cw_get('_MERGE_WINDOW_MAX_CAPTURED', False):
            try:
                from libre_macros_split_lib import _split_document_is_maximized
                _cw_set('_MERGE_WINDOW_WAS_MAXIMIZED', _split_document_is_maximized(doc))
            except Exception:
                _cw_set('_MERGE_WINDOW_WAS_MAXIMIZED', None)
            _cw_set('_MERGE_WINDOW_MAX_CAPTURED', True)
            merge_debug(
                'collect_workbooks_run',
                'window was_maximized=%s' % _cw_get('_MERGE_WINDOW_WAS_MAXIMIZED', None),
            )
        close_orphan_hidden_documents(doc)
        close_all_open_sources()
        merge_debug('collect_workbooks_run', 'before consent')
        if not _cw_get('_MERGE_PACK_SKIP_CONSENT', False):
            if not merge_ensure_consent_before_run(doc):
                append_collect_log(doc, '', '', '', '', 'отмена', 'запуск отменён: условия использования или предупреждение о плагинах')
                return False
        else:
            merge_debug('collect_workbooks_run', 'consent skipped (pack orchestrator)')
        merge_debug('collect_workbooks_run', 'after consent')
        # Лог сбрасываем до pre-shell, чтобы запись о скрипте не стёрлась.
        reset_collect_log(doc)
        # До expand_source_files: скрипт может создать CSV/файлы-источники.
        err_pre = merge_run_pre_shell_from_doc(doc)
        if err_pre:
            show_collect_error(err_pre, doc)
            return False
        # Этап 1 / pack уже спросили ручной ввод → только кэш, без повторных диалогов.
        # Самостоятельный запуск этапа 2: флага нет → очистить кэш и спросить.
        manual_done = bool(_cw_get('_MERGE_MANUAL_INPUT_DONE', False))
        _cw_set('_MERGE_MANUAL_INPUT_DONE', False)
        if not manual_done:
            _merge_clear_manual_variable_cache()
        err, settings = parse_collect_settings(
            doc,
            validate_sources=True,
            interactive_manual=not manual_done,
        )
        if err:
            show_collect_error(err, doc)
            return False
        mode_for_msg = settings['mode']
        file_count = len(settings['files'])
        xml_direct = (settings or {}).get('data_transfer_mode') == _cw_cfg.MERGE_TRANSFER_XML_EXCEL_ODS
        pack_param = get_run_param_sheet(doc)
        if pack_param:
            append_collect_log(doc, '', '', '', '', 'старт', 'v%s, режим %s, файлов %d, лист параметров «%s»' % (MACRO_VERSION, mode_for_msg, file_count, pack_param))
        else:
            append_collect_log(doc, '', '', '', '', 'старт', 'v%s, режим %s, файлов %d' % (MACRO_VERSION, mode_for_msg, file_count))
        flag_applied = settings.get('flag_applied') or {}
        flag_warnings = settings.get('flag_warnings') or []
        if len(flag_applied) > 0:
            parts = []
            for k in sorted(flag_applied.keys()):
                parts.append('%s=%s' % (k, flag_applied[k]))
            append_collect_log(doc, '', '', '', '', 'настройка', 'флаги поведения: ' + ', '.join(parts))
        wi_flag = 0
        while wi_flag < len(flag_warnings):
            append_collect_log(doc, '', '', '', '', 'предупреждение', flag_warnings[wi_flag])
            wi_flag = wi_flag + 1
        adv_applied = settings.get('advanced_applied') or {}
        adv_warnings = settings.get('advanced_warnings') or []
        if len(adv_applied) > 0:
            parts = []
            for k in sorted(adv_applied.keys()):
                parts.append('%s=%s' % (k, adv_applied[k]))
            append_collect_log(doc, '', '', '', '', 'настройка', 'расширенные параметры: ' + ', '.join(parts))
        wi = 0
        while wi < len(adv_warnings):
            append_collect_log(doc, '', '', '', '', 'предупреждение', adv_warnings[wi])
            wi = wi + 1
        report = ProgressReport(estimate_work_steps(file_count, mode_for_msg), doc)
        merge_ui_bind_report(report)
        _merge_apply_flags_from_settings(settings)
        _merge_set_debug_log_doc(doc)
        merge_ui_bind_settings(settings)
        merge_ui_abort_reset()
        _cw_cfg._merge_ui_finish_message_shown = False
        suppress_pre_clear = bool(_cw_get('_MERGE_PACK_SUPPRESS_PRE_CLEAR', False))
        if settings.get('mode') == _cw_cfg.MERGE_MODE_INVOLVE:
            suppress_pre_clear = True
            merge_debug('collect_workbooks_run', 'maybe_clear_sheets suppressed (involve)')
            try:
                append_collect_log(
                    doc,
                    '',
                    '',
                    '',
                    '',
                    'очистка листов',
                    'пропущена (режим «Текущие листы»)',
                )
            except Exception:
                pass
        if _merge_progress_ui_mode(settings) == _cw_cfg.MERGE_PROGRESS_UI_DIALOG:
            skip_pack_confirm = bool(_cw_get('_MERGE_PACK_SKIP_CONFIRM', False))
            if skip_pack_confirm:
                merge_debug('collect_workbooks_run', 'skip confirm dialog (pack auto_continue)')
                confirmed = True
            else:
                merge_debug('collect_workbooks_run', 'before confirm dialog')
                confirmed, settings = merge_ui_dialog_confirm_run(doc, settings)
                merge_debug('collect_workbooks_run', 'after confirm dialog confirmed=%s' % confirmed)
            if not confirmed:
                append_collect_log(doc, '', '', '', '', 'отмена', 'запуск отменён пользователем')
                return False
            mode_for_msg = settings['mode']
            file_count = len(settings['files'])
            # После «Запуск»: очистка лишних листов; при MERGE_CONFIRM_DELETION_OF_SHEETS — отдельный запрос.
            if (not suppress_pre_clear) and len(list_param_sheet_names(doc)) > 0:
                maybe_clear_sheets(
                    doc,
                    settings.get('sheets_undelete'),
                    settings=settings,
                    skip_confirm=not _cw_get('MERGE_CONFIRM_DELETION_OF_SHEETS', False),
                )
            elif suppress_pre_clear:
                merge_debug('collect_workbooks_run', 'maybe_clear_sheets suppressed (pack/involve)')
        elif (not suppress_pre_clear) and len(list_param_sheet_names(doc)) > 0:
            # Без диалога: MERGE_CONFIRM_DELETION_OF_SHEETS и «Листы_не_удалять».
            maybe_clear_sheets(
                doc,
                settings.get('sheets_undelete'),
                settings=settings,
                skip_confirm=False,
            )
        elif suppress_pre_clear:
            merge_debug('collect_workbooks_run', 'maybe_clear_sheets suppressed (pack/involve)')
        # «Листы_удалить» — всегда (любой режим / suppress_pre_clear).
        maybe_force_delete_sheets(doc, settings)
        _merge_clear_named_ranges_uno(doc)
        progress_settings = _merge_settings_force_statusbar(settings) if xml_direct else settings
        merge_ui_bind_settings(progress_settings)
        started = True
        report.start_stage('data_collection')
        # Якорь для xml_excel_ods создаётся внутри _merge_run_collect_direct_xml_excel_ods
        # (после Save As → OS copy → open original).
        merge_ui_status_start('Сбор данных…', _cw_cfg._merge_ui_progress_scale, settings=settings)
        progress_dialog_active = _cw_cfg._merge_ui_progress_dialog is not None
        merge_ui_status_set(0, 'Сбор данных\nПодготовка…', settings=settings)
        report.status('Этап 2: режим %s, файлов %d.' % (mode_for_msg, file_count))
        try:
            ok = _merge_run_with_suppressed_office_info(
                lambda: run_collect_merge(doc, settings, report),
                primary_doc=doc,
            )
            merge_debug('collect_workbooks_run', 'run_collect_merge ok=%s' % ok)
            if merge_ui_abort_requested():
                ok = False
                if len(report.problems) == 0 or not any(('Прервано' in str(p) for p in report.problems)):
                    report.problem('Прервано пользователем.')
            report.end_stage('data_collection')
            if ok:
                report.step('Завершение…')
            report.finalize_timings()
            if progress_dialog_active:
                merge_ui_set_phase('Завершение', 'подготовка итога')
                merge_ui_sync_progress(report, file_frac=1.0)
            final_text = report.build_final_message(mode_for_msg, file_count, ok)
            if not ok and len(report.problems) == 0:
                report.problem('Данные не были собраны (проверьте параметры и пути).')
                final_text = report.build_final_message(mode_for_msg, file_count, False)
        except Exception as err:
            merge_debug('collect_workbooks_run', 'critical: %s' % err)
            report.problem('Критическая ошибка: %s' % str(err))
            final_text = report.build_final_message(mode_for_msg, file_count, False)
            print(traceback.format_exc())
    except Exception as err:
        final_text = 'Ошибка: %s' % err
        merge_debug('collect_workbooks_run', 'error: %s' % err)
        print(traceback.format_exc())
    finally:
        merge_debug('collect_workbooks_run', 'finally')
        close_all_open_sources()
        target_doc = get_run_target_doc()
        if target_doc is not None:
            doc = target_doc
        deferred_xml_uno = _merge_xml_deferred_uno_pending()
        two_doc_pending_finish = False
        two_doc_await_dialog = False
        _finish_two_doc = None
        if deferred_xml_uno:
            job = _cw_cfg._MERGE_XML_DEFERRED_UNO_JOB
            auto_close = _merge_ui_dialog_autoclose_enabled(default=False)
            skip_uno = bool((job or {}).get('skip_uno')) or bool(
                getattr(_cw_cfg, 'MERGE_XML_SKIP_UNO_PHASE', False)
            )
            two_doc = bool((job or {}).get('two_doc_finish'))

            def _run_uno_on_temp():
                nonlocal ok, final_text
                try:
                    _merge_run_xml_excel_ods_uno_on_temp(job)
                    if report is not None:
                        report.finalize_timings()
                        final_text = report.build_final_message(mode_for_msg, file_count, ok)
                except Exception as err:
                    ok = False
                    merge_debug('collect_workbooks_run', 'deferred_uno: %s' % err)
                    if report is not None:
                        report.problem('Оформление/постобработка (временная копия): %s' % err)
                        final_text = report.build_final_message(mode_for_msg, file_count, False)
                    print(traceback.format_exc())

            def _finish_two_doc():
                """Активировать result; закрыть якорь с сохранением; итоговое сообщение."""
                nonlocal doc, final_message_shown
                try:
                    _merge_ui_dialog_finish()
                except Exception:
                    pass
                try:
                    merge_ui_status_finish()
                except Exception:
                    pass
                result_doc = (job or {}).get('doc')
                anchor = (job or {}).get('anchor_doc')
                result_path = str(
                    (job or {}).get('result_path')
                    or (job or {}).get('temp_path')
                    or ''
                ).strip()
                saved_job = job or {}
                early_relocate = bool(saved_job.get('early_relocate'))
                open_result_only = bool(saved_job.get('open_result_only'))
                final_path = str(
                    saved_job.get('final_path') or result_path or ''
                ).strip()
                _cw_cfg._MERGE_XML_DEFERRED_UNO_JOB = None
                if early_relocate:
                    if bool((saved_job or {}).get('ods_final_via_uno')):
                        msg = (
                            u'Сбор xml_excel_ods завершён.\n\n'
                            u'Исходный файл ODS:\n%s\n\n'
                            u'После OK: откроется sidecar XLSX, оформление UNO; '
                            u'затем результат сохранится как ODS (UNO storeAsURL); '
                            u'якорь (temp) закроется. Sidecar XLSX не удаляется.'
                            % (final_path or u'(путь неизвестен)')
                        )
                    else:
                        msg = (
                            u'Сбор xml_excel_ods завершён.\n\n'
                            u'Файл результата:\n%s\n\n'
                            u'После OK: откроется результат по исходному пути, '
                            u'оформление UNO; окно якоря (temp) будет очищено.'
                            % (final_path or u'(путь неизвестен)')
                        )
                elif open_result_only:
                    msg = (
                        u'Сбор xml_excel_ods завершён.\n\n'
                        u'Файл результата:\n%s\n\n'
                        u'После OK: откроется файл результата.'
                        % (final_path or u'(путь неизвестен)')
                    )
                else:
                    msg = (
                        u'Сбор xml_excel_ods завершён.\n\n'
                        u'Файл результата:\n%s'
                        % (final_path or u'(путь неизвестен)')
                    )
                if not ok and final_text:
                    msg = u'Сбор завершён с ошибками.\n\n' + final_text + u'\n\n' + msg
                elif final_text:
                    msg = final_text + u'\n\n' + msg
                try:
                    _merge_ui_anchor_end(activate_doc=None, close_anchor=False)
                except Exception:
                    pass
                if result_doc is None and result_path and os.path.isfile(result_path):
                    try:
                        result_doc = _merge_xml_open_path(result_path, hidden=False)
                        if job is not None:
                            job['doc'] = result_doc
                        merge_debug('xml_excel_ods', 'finish two_doc: opened result')
                    except Exception as err:
                        merge_debug(
                            'xml_excel_ods',
                            'finish two_doc: open result failed: %s' % err,
                        )
                        print(traceback.format_exc())
                if result_doc is not None:
                    set_run_target_doc(result_doc)
                    _merge_set_debug_log_doc(result_doc)
                    try:
                        _merge_activate_document(result_doc)
                    except Exception:
                        pass
                    final_message_shown = True
                    _cw_cfg._merge_ui_finish_message_shown = True
                if not open_result_only:
                    if result_doc is not None:
                        doc = result_doc
                    try:
                        if anchor is not None:
                            _merge_xml_close_doc(anchor, save=True)
                            merge_debug(
                                'xml_excel_ods',
                                'finish two_doc: closed anchor with save (keep-open result)',
                            )
                    except Exception as err:
                        merge_debug(
                            'xml_excel_ods',
                            'finish two_doc: close anchor failed (keep-open result): %s'
                            % err,
                        )
                        print(traceback.format_exc())
                    try:
                        if result_doc is not None:
                            _merge_force_result_interactive(result_doc)
                    except Exception:
                        pass
                    merge_debug(
                        'xml_excel_ods',
                        'two_doc: keep already-open result, skip reopen by flag',
                    )
                    return
                need_path = final_path
                if early_relocate and bool((saved_job or {}).get('ods_final_via_uno')):
                    need_path = str(
                        (saved_job or {}).get('temp_path')
                        or (saved_job or {}).get('result_path')
                        or ''
                    ).strip()
                if need_path == '' or not os.path.isfile(need_path):
                    merge_debug(
                        'xml_excel_ods',
                        'no replace: result file missing, skip open (%s)' % need_path,
                    )
                    return
                try:
                    if early_relocate:
                        run_uno = not bool((saved_job or {}).get('skip_uno'))
                        final_doc = _merge_xml_finish_open_result(saved_job, report, run_uno=run_uno)
                    else:
                        final_doc = _merge_xml_open_path(final_path, hidden=False)
                        try:
                            _merge_activate_document(final_doc)
                        except Exception:
                            pass
                        merge_ui_yield(force=True)
                        _merge_xml_apply_job_journal(final_doc, saved_job, anchor=(saved_job or {}).get('anchor_doc'))
                        set_run_target_doc(final_doc)
                        _merge_set_debug_log_doc(final_doc)
                    if final_doc is None:
                        merge_debug('xml_excel_ods', 'no replace: finish open failed')
                        return
                    doc = final_doc
                    try:
                        _merge_xml_close_doc(anchor, save=True)
                        merge_debug(
                            'xml_excel_ods',
                            'finish two_doc: closed anchor with save',
                        )
                    except Exception as err:
                        merge_debug(
                            'xml_excel_ods',
                            'finish two_doc: close anchor failed: %s' % err,
                        )
                        print(traceback.format_exc())
                except Exception:
                    pass
                if final_text != '' and (not final_message_shown):
                    tail = '\n\n(журнал: лист «%s»)' % _cw_cfg.MERGE_LOG_SHEET_NAME
                    try:
                        if ok:
                            show_message(final_text + tail, doc)
                        else:
                            show_message(
                                'Сбор не выполнен.\n\n' + final_text + tail, doc
                            )
                        final_message_shown = True
                    except Exception:
                        pass

            def _finish_replace_open():
                nonlocal doc, final_message_shown, final_text, ok
                try:
                    final_doc = _merge_xml_finish_replace_and_open(job)
                    _cw_cfg._MERGE_XML_DEFERRED_UNO_JOB = None
                    if final_doc is not None:
                        doc = final_doc
                        if skip_uno:
                            for entry in list((job or {}).get('journal_entries') or []):
                                try:
                                    append_collect_log(
                                        final_doc,
                                        entry[0],
                                        entry[1],
                                        entry[2],
                                        entry[3],
                                        entry[4],
                                        entry[5],
                                    )
                                except Exception:
                                    pass
                            pending_created = list((job or {}).get('pending_created_sheets') or [])
                            if pending_created:
                                try:
                                    _merge_pp_register_xml_created_sheets(final_doc, pending_created)
                                except Exception:
                                    pass
                except Exception as err:
                    ok = False
                    merge_debug('collect_workbooks_run', 'finish_replace: %s' % err)
                    if report is not None:
                        report.problem('Подмена итогового файла: %s' % err)
                        final_text = report.build_final_message(mode_for_msg, file_count, False)
                    print(traceback.format_exc())
                    return
                if (job or {}).get('skip_final_message') or skip_uno:
                    final_message_shown = True
                    merge_debug('xml_excel_ods', 'skip final MessageBox (file-only mode)')
                    return
                if final_text != '':
                    tail = '\n\n(журнал: лист «%s»)' % _cw_cfg.MERGE_LOG_SHEET_NAME
                    try:
                        if ok:
                            show_message(final_text + tail, doc)
                        else:
                            show_message('Сбор не выполнен.\n\n' + final_text + tail, doc)
                        final_message_shown = True
                    except Exception:
                        pass

            two_doc_pending_finish = False
            two_doc_await_dialog = False

            if two_doc:
                if not skip_uno:
                    _run_uno_on_temp()
                if (job or {}).get('doc') is None:
                    _rp = str(
                        (job or {}).get('result_path')
                        or (job or {}).get('temp_path')
                        or ''
                    ).strip()
                    if _rp and os.path.isfile(_rp):
                        try:
                            _rd = _merge_xml_open_path(_rp, hidden=False)
                            if job is not None:
                                job['doc'] = _rd
                            merge_debug('xml_excel_ods', 'two_doc: opened result for finish')
                        except Exception as err:
                            merge_debug(
                                'xml_excel_ods',
                                'two_doc: open result failed: %s' % err,
                            )
                if (job or {}).get('doc') is not None:
                    doc = job['doc']
                    set_run_target_doc(doc)
                    _merge_set_debug_log_doc(doc)
                two_doc_pending_finish = True
                two_doc_await_dialog = bool(
                    (not auto_close)
                    and progress_dialog_active
                    and _cw_cfg._merge_ui_progress_dialog is not None
                )
                if two_doc_await_dialog:
                    merge_ui_set_phase('Готово', 'ожидание «Завершить»')
                    merge_ui_sync_progress(report, file_frac=1.0)
            elif skip_uno:
                progress_dialog_active = False
                try:
                    _merge_ui_dialog_finish()
                except Exception:
                    pass
                try:
                    merge_ui_status_finish()
                except Exception:
                    pass
                _finish_replace_open()
            else:
                _run_uno_on_temp()
                if auto_close:
                    _merge_ui_dialog_finish()
                    progress_dialog_active = False
                    _finish_replace_open()
                elif progress_dialog_active and _cw_cfg._merge_ui_progress_dialog is not None:
                    merge_ui_set_phase('Готово', 'ожидание «Завершить»')
                    merge_ui_sync_progress(report, file_frac=1.0)
                    interim = 'Сбор и оформление во временной копии завершены.'
                    if ok:
                        interim += '\n\nНажмите «Завершить»: закрыть текущую книгу без сохранения и открыть итоговый файл.'
                    else:
                        interim += '\n\nСбор завершён с ошибками — см. журнал.\nНажмите «Завершить» для подмены файла.'
                    _merge_ui_anchor_activate()
                    merge_ui_dialog_await_finish(interim, on_finish=_finish_replace_open)
                    progress_dialog_active = False
                else:
                    _finish_replace_open()
        if report is not None and doc is not None:
            append_collect_log(doc, '', '', '', report.stats['rows_copied'], 'итог', 'файлов %d, листов %d, пропусков %d' % (report.stats['files_done'], report.stats['sheets_done'], report.stats['sheets_skipped']))

            def _fmt(sec):
                if sec < 0.01:
                    return '<0.01с'
                if sec < 1:
                    return '%.2fс' % sec
                if sec < 60:
                    return '%.1fс' % sec
                m = int(sec // 60)
                s = sec % 60
                return '%dм%.1fс' % (m, s)
            append_collect_log(doc, '', '', '', '', 'время', 'Сбор данных: %s' % _fmt(report.timings['data_collection']))
            append_collect_log(doc, '', '', '', '', 'время', 'Форматирование: %s' % _fmt(report.timings['formatting']))
            append_collect_log(doc, '', '', '', '', 'время', 'Постобработка (диапазон): %s' % _fmt(report.timings['postprocess_range']))
            append_collect_log(doc, '', '', '', '', 'время', 'Постобработка (строки): %s' % _fmt(report.timings['postprocess_row']))
            append_collect_log(doc, '', '', '', '', 'время', 'Финальная обработка: %s' % _fmt(report.timings['final_processing']))
            append_collect_log(doc, '', '', '', '', 'время', 'Общее: %s' % _fmt(report.timings['total']))
            report.close()
        if doc is not None:
            format_collect_log_sheet(doc)
            # Оформление лога активирует «Сбор_книг_лог» — вернуть лист из финального
            # «активировать_лист», если он был.
            try:
                import libre_macros_lib as _lm_act
                want = ""
                getter = getattr(_lm_act, "lm_final_activate_sheet_name", None)
                if callable(getter):
                    want = str(getter() or "").strip()
                if want != "":
                    focus = getattr(_lm_act, "_lm_pp_activate_sheet_focus_a1", None)
                    if callable(focus):
                        focus(doc, want)
                        merge_debug(
                            "collect_workbooks_run",
                            "restore final activate sheet «%s»" % want,
                        )
            except Exception as err:
                merge_debug(
                    "collect_workbooks_run",
                    "restore final activate sheet: %s" % err,
                )
            refresh_document(doc)
            try:
                _merge_force_result_interactive(get_run_target_doc() or doc)
            except Exception as err:
                merge_debug(
                    'collect_workbooks_run',
                    'final interactive restore: %s' % err,
                )
        if report is not None and final_text == '':
            final_text = report.build_final_message(mode_for_msg, file_count, ok)
        if two_doc_pending_finish and _finish_two_doc is not None:
            if two_doc_await_dialog:
                interim = 'Сбор и оформление завершены.'
                if ok:
                    interim += (
                        '\n\nНажмите «Завершить»: активировать файл результата '
                        'и закрыть исходную книгу с сохранением.'
                    )
                else:
                    interim += (
                        '\n\nСбор завершён с ошибками — см. журнал.\n'
                        'Нажмите «Завершить».'
                    )
                _merge_ui_anchor_activate()
                merge_ui_dialog_await_finish(interim, on_finish=_finish_two_doc)
                progress_dialog_active = False
            else:
                progress_dialog_active = False
                _finish_two_doc()
        anchor_finish = _cw_cfg._merge_ui_anchor_doc is not None
        quiet_pack_finish = bool(_cw_get('_MERGE_PACK_QUIET_FINISH', False)) and (
            bool(ok) or bool(_cw_get('_MERGE_QA_HEADLESS', False))
        )
        if quiet_pack_finish:
            merge_debug('collect_workbooks_run', 'quiet finish (pack auto_continue intermediate)')
            try:
                append_collect_log(
                    doc,
                    '',
                    '',
                    '',
                    '',
                    'оркестратор',
                    'шаг завершён успешно — автопродолжение без MessageBox',
                )
            except Exception:
                pass
            try:
                _merge_ui_dialog_finish()
            except Exception:
                pass
            try:
                merge_ui_status_finish()
            except Exception:
                pass
            try:
                _merge_ui_anchor_end(activate_doc=doc)
            except Exception:
                pass
            final_message_shown = True
            progress_dialog_active = False
            _cw_cfg._merge_ui_finish_message_shown = True
        elif progress_dialog_active and _cw_cfg._merge_ui_progress_dialog is not None:
            hint = '\n\nНажмите «Завершить» для просмотра итогового отчёта.'
            finish_text = final_text + hint if ok else 'Сбор не выполнен.\n\n' + final_text + hint
            if anchor_finish:
                _merge_ui_anchor_activate()

                def _anchor_on_finish():
                    _merge_ui_anchor_end(activate_doc=doc)
                merge_ui_dialog_await_finish(finish_text, on_finish=_anchor_on_finish)
            else:
                merge_ui_dialog_await_finish(finish_text)
        elif not deferred_xml_uno:
            merge_ui_status_finish()
            _merge_ui_anchor_end(activate_doc=doc)
        if (
            final_text != ''
            and (not quiet_pack_finish)
            and (not _merge_ui_is_dialog_mode())
            and (not anchor_finish or deferred_xml_uno)
            and (not final_message_shown)
            and (not getattr(_cw_cfg, '_merge_ui_finish_message_shown', False))
        ):
            tail = '\n\n(журнал: лист «%s»)' % _cw_cfg.MERGE_LOG_SHEET_NAME
            if ok:
                show_message(final_text + tail, doc)
            else:
                show_message('Сбор не выполнен.\n\n' + final_text + tail, doc)
        try:
            # Диалоги прогресса / activate часто сбивают вид; .uno:Maximize — toggle.
            # Восстановить maximize только если окно было развёрнуто (или состояние неизвестно).
            import libre_macros_split_lib as _split
            d = get_run_target_doc() or doc
            was_max = _cw_get('_MERGE_WINDOW_WAS_MAXIMIZED', None)
            if d is not None:
                if _split._split_restore_document_maximized(d, was_max):
                    merge_debug('collect_workbooks_run', 'maximize restored was=%s' % was_max)
                try:
                    _split._split_flush_maximize_pending()
                except Exception:
                    pass
        except Exception as err:
            merge_debug('collect_workbooks_run', 'flush maximize: %s' % err)
        try:
            _merge_clear_collect_preexisting_sheets()
        except Exception:
            pass
        try:
            _cw_set('_MERGE_LAST_COLLECT_OK', bool(ok))
        except Exception:
            pass
    return started
'\nСекция постобработки листа результата (merge_pp_*, _merge_pp_*).\n\nФункции вызываются из apply_result_sheet_postprocessing после стандартного форматирования.\nНастройка: лист «Параметры_Объединения» (A/B/C), карты MERGE_RESULT_POSTPROCESS_*_MAP,\nцепочки _MERGE_CODE_POSTPROCESS_* — см. # region ниже и POSTPROCESS_GUIDE.md.\n'

