def _load_macros_lib():
    if _cw_cfg.macros_lib.get('_loaded'):
        return bool(_cw_cfg.macros_lib.get('_ok', False))
    _cw_cfg.macros_lib['_loaded'] = True
    _cw_cfg.macros_lib['_ok'] = False
    lm = None
    try:
        import libre_macros_lib as lm
    except ImportError:
        try:
            user_lib = get_user_scripts_path()
            pp_dir = os.path.join(user_lib, 'pythonpath')
            if os.path.isdir(pp_dir) and pp_dir not in sys.path:
                sys.path.insert(0, pp_dir)
            import libre_macros_lib as lm
        except ImportError:
            return False
    try:
        for lm_name in lm.LM_PP_PUBLIC_NAMES:
            fn = getattr(lm, lm_name, None)
            if fn is None or not callable(fn):
                continue
            merge_name = 'merge_' + lm_name[3:]
            _cw_cfg.macros_lib[merge_name] = fn
        for lm_name in getattr(lm, 'LM_FINAL_PUBLIC_NAMES', ()):
            fn = getattr(lm, lm_name, None)
            if fn is None or not callable(fn):
                continue
            merge_name = 'merge_' + lm_name[3:]
            _cw_cfg.macros_lib[merge_name] = fn
        if hasattr(lm, 'lo_color_rgb'):
            _cw_cfg.macros_lib['lo_color_rgb'] = lm.lo_color_rgb
        if hasattr(lm, 'lm_pp_set_log_hook'):
            lm.lm_pp_set_log_hook(_merge_log_postprocess)
        if hasattr(lm, 'lm_set_freeze_defer_hook'):
            lm.lm_set_freeze_defer_hook(_merge_freeze_defer_hook)
        _cw_cfg.macros_lib['_ok'] = True
        return True
    except Exception as err:
        print('libre_macros_lib: %s' % err)
        return False

def _install_pp_shims():
    if not _load_macros_lib():
        raise ImportError('collect_workbooks: не найден libre_macros_lib.py (установите macro-lib/pythonpath/ через install.sh)')
    import libre_macros_lib as lm
    mod = globals()
    _LM_SHIM_SKIP = ('_lm_pp_', '_lm_log_', '_lm_ui_')
    for name, obj in vars(lm).items():
        if name.startswith('lm_pp_') and callable(obj):
            mod['merge_' + name[3:]] = obj
        elif name.startswith('lm_final_') and callable(obj):
            mod['merge_' + name[3:]] = obj
        elif name.startswith('_lm_pp_') and callable(obj):
            mod['_merge_pp_' + name[7:]] = obj
        elif name.startswith('_lm_') and callable(obj):
            if any((name.startswith(prefix) for prefix in _LM_SHIM_SKIP)):
                continue
            merge_name = '_merge_' + name[4:]
            if merge_name not in mod:
                mod[merge_name] = obj
            if name == '_lm_set_char_color_safe' and '_set_char_color_safe' not in mod:
                mod['_set_char_color_safe'] = obj
            elif name == '_lm_set_char_color_cell' and '_set_char_color_cell' not in mod:
                mod['_set_char_color_cell'] = obj
        elif name.startswith('_LM_PP_') and (not name.endswith('_')):
            merge_const = '_MERGE_PP_' + name[6:]
            if merge_const not in mod:
                mod[merge_const] = obj
    _cw_cfg._PP_SHIMS_INSTALLED = True

def _merge_pp_bind_required_from_lib():
    """Привязать новые merge_pp_* / merge_final_* из lib, если шим ещё не подхватил."""
    try:
        import libre_macros_lib as lm
    except ImportError:
        return
    mod = globals()
    i = 0
    while i < len(_cw_cfg._LM_PP_REQUIRED_BINDINGS):
        merge_name, lm_name = _cw_cfg._LM_PP_REQUIRED_BINDINGS[i]
        i = i + 1
        if _resolve_merge_pp_function(merge_name) is not None:
            continue
        fn = getattr(lm, lm_name, None)
        if fn is not None and callable(fn):
            mod[merge_name] = fn
            _cw_cfg.macros_lib[merge_name] = fn

def _resolve_merge_pp_function(merge_name):
    """Найти merge_pp_* после загрузки lib и shims."""
    fn = _cw_cfg.macros_lib.get(merge_name)
    if fn is not None and callable(fn):
        return fn
    fn = globals().get(merge_name)
    if fn is not None and callable(fn):
        return fn
    return None

def _fill_postprocess_maps():
    _install_pp_shims()
    _merge_pp_bind_required_from_lib()
    missing = []
    for key, merge_name in _cw_cfg._PP_RANGE_MAP_SPEC:
        fn = _resolve_merge_pp_function(merge_name)
        if fn is None:
            missing.append(merge_name)
            continue
        _cw_cfg.MERGE_RESULT_POSTPROCESS_RANGE_MAP[key] = fn
    for key, merge_name in _cw_cfg._PP_XML_MAP_SPEC:
        fn = _resolve_merge_pp_function(merge_name)
        if fn is None:
            missing.append(merge_name)
            continue
        _cw_cfg.MERGE_RESULT_POSTPROCESS_XML_MAP[key] = fn
    for key, merge_name in _cw_cfg._PP_ROW_MAP_SPEC:
        fn = _resolve_merge_pp_function(merge_name)
        if fn is None:
            missing.append(merge_name)
            continue
        _cw_cfg.MERGE_RESULT_POSTPROCESS_ROW_MAP[key] = fn
    for key, merge_name in _cw_cfg._FINAL_MAP_SPEC:
        fn = _resolve_merge_pp_function(merge_name)
        if fn is None:
            missing.append(merge_name)
            continue
        _cw_cfg.MERGE_FINAL_PROCESSING_MAP[key] = fn
    if len(missing) > 0:
        uniq = sorted(set(missing))
        _merge_console_print('collect_workbooks: не загружены функции постобработки: %s (установите pythonpath/libre_macros_lib.py и перезапустите Calc)' % ', '.join(uniq))
    _cw_cfg._PP_MAPS_READY = True

def _ensure_pp_from_lib():
    _fill_postprocess_maps()
    _merge_sync_pivot_lib_flags()
    _merge_install_lib_hooks()

