def _merge_reset_db_skip_sheet_name(name):
    """Служебные листы — без сброса/простого автофильтра."""
    sn = str(name or '').strip()
    if sn == '':
        return True
    if is_param_sheet_name(sn):
        return True
    if is_collect_log_sheet_name(sn):
        return True
    for keep in (
        _cw_cfg.MERGE_HELP_SHEET_NAME,
        _cw_cfg.MERGE_WIZARD_LISTS_SHEET_NAME,
        _cw_cfg.MERGE_SERVICE_SHEET_NAME,
    ):
        if sn == keep:
            return True
    return False


def collect_reset_db_ranges(event=None):
    """
    Сброс именованных DatabaseRange и установка простого автофильтра.

    Как в разделить_листы: снять все DatabaseRanges книги, затем простой
    автофильтр через меню (.uno:DataFilterAutoFilter).

    В режиме «Текущие листы» — автофильтр только на вовлечённых листах
    (_MERGE_INVOLVED_SHEET_NAMES); иначе — на всех неслужебных.

    Вызывается из collect_pack при галочке сброса именованных диапазонов.
    """
    doc = None
    try:
        doc = get_run_target_doc()
        if doc is None:
            try:
                doc = XSCRIPTCONTEXT.getDocument()
            except Exception:
                doc = None
        if doc is None:
            merge_debug('collect_reset_db_ranges', 'нет активной книги Calc')
            return False
        set_run_target_doc(doc)
        from libre_macros_split_lib import _split_activate_document
        from libre_macros_split_lib import _split_clear_database_ranges
        from libre_macros_split_lib import _split_restore_sheet_menu_autofilter
        try:
            _split_activate_document(doc)
        except Exception:
            pass
        dropped = []
        try:
            dropped = list(_split_clear_database_ranges(doc, keep_anonymous=False) or [])
        except Exception as err:
            merge_debug('collect_reset_db_ranges', 'clear DatabaseRanges: %s' % err)
            dropped = []
        merge_debug(
            'collect_reset_db_ranges',
            'снято DatabaseRanges=%d names=%s'
            % (len(dropped), dropped[:40]),
        )
        # «Текущие листы»: простой автофильтр только на вовлечённых листах.
        involve_only = None
        try:
            if _cw_get('_MERGE_COLLECT_MODE') == _cw_cfg.MERGE_MODE_INVOLVE:
                involve_only = frozenset(_cw_get('_MERGE_INVOLVED_SHEET_NAMES') or ())
                merge_debug(
                    'collect_reset_db_ranges',
                    'involve filters only n=%d names=%s'
                    % (len(involve_only), sorted(involve_only)[:40]),
                )
        except Exception:
            involve_only = None
        filtered_n = 0
        empty_n = 0
        fail_n = 0
        skip_n = 0
        i = 0
        while i < doc.Sheets.getCount():
            sh = None
            try:
                sh = doc.Sheets.getByIndex(i)
            except Exception:
                sh = None
            i = i + 1
            if sh is None:
                continue
            try:
                nm = str(getattr(sh, 'Name', '') or '').strip()
            except Exception:
                nm = ''
            if _merge_reset_db_skip_sheet_name(nm):
                skip_n = skip_n + 1
                continue
            if involve_only is not None and nm not in involve_only:
                skip_n = skip_n + 1
                continue
            try:
                note = _split_restore_sheet_menu_autofilter(doc, sh, 0, True)
            except Exception as err:
                note = u'ошибка: %s' % err
            note_s = str(note or '')
            merge_debug('collect_reset_db_ranges', 'лист «%s»: %s' % (nm, note_s))
            if u'автофильтр(меню)' in note_s:
                filtered_n = filtered_n + 1
            elif note_s == u'пусто' or note_s.startswith(u'пусто'):
                empty_n = empty_n + 1
            else:
                fail_n = fail_n + 1
        merge_debug(
            'collect_reset_db_ranges',
            'done filters=%d empty=%d fail=%d skip_svc=%d'
            % (filtered_n, empty_n, fail_n, skip_n),
        )
        # activate/dispatch автофильтра часто сбрасывает maximize → вернуть.
        try:
            from libre_macros_split_lib import _split_maximize_document
            if _split_maximize_document(doc):
                merge_debug('collect_reset_db_ranges', 'окно максимизировано')
            else:
                merge_debug('collect_reset_db_ranges', 'максимизация: не удалось')
        except Exception as err:
            merge_debug('collect_reset_db_ranges', 'максимизация: %s' % err)
        return fail_n == 0
    except Exception as err:
        merge_debug('collect_reset_db_ranges', 'error: %s' % err)
        return False


def collect_workbooks_for_param_sheet(sheet_name, suppress_pre_clear=False, skip_consent=False, skip_confirm=False, quiet_finish=False):
    """
    Один прогон сбора для указанного листа параметров (оркестратор collect_pack).

    Активирует лист, set_run_param_sheet, затем collect_workbooks_run.
    Возвращает True только при успешном сборе (не при одной лишь отмене/старте).
    """
    doc = None
    try:
        _ensure_pp_from_lib()
        name = str(sheet_name or '').strip()
        if name == '':
            show_message('Не задан лист параметров.', None)
            return False
        doc = get_run_target_doc()
        if doc is None:
            try:
                doc = XSCRIPTCONTEXT.getDocument()
            except Exception:
                doc = None
        if doc is None:
            show_message('Не открыта книга Calc.', None)
            return False
        set_run_target_doc(doc)
        sh = get_sheet(doc, name)
        if sh is None:
            show_message('Лист параметров «%s» не найден.' % name, doc)
            return False
        try:
            activate_sheet(doc, sh)
        except Exception:
            try:
                doc.getCurrentController().setActiveSheet(sh)
            except Exception:
                pass
        set_run_param_sheet(name)
        close_orphan_hidden_documents(doc)
        close_all_open_sources()
        _merge_clear_manual_variable_cache()
        defer_src = _merge_has_pre_shell_config(doc)
        err, settings = parse_collect_settings(doc, validate_sources=not defer_src)
        if err:
            show_collect_error(err, doc)
            return False
        _merge_apply_flags_from_settings(settings)
        _merge_set_debug_log_doc(doc)
        _cw_set('_MERGE_PACK_SUPPRESS_PRE_CLEAR', bool(suppress_pre_clear))
        _cw_set('_MERGE_PACK_SKIP_CONSENT', bool(skip_consent))
        _cw_set('_MERGE_PACK_SKIP_CONFIRM', bool(skip_confirm))
        _cw_set('_MERGE_PACK_QUIET_FINISH', bool(quiet_finish))
        _cw_set('_MERGE_LAST_COLLECT_OK', False)
        # Ручной ввод уже в кэше — collect_workbooks_run не спрашивает повторно.
        _cw_set('_MERGE_MANUAL_INPUT_DONE', True)
        try:
            merge_debug(
                'collect_workbooks_for_param_sheet',
                'run sheet=%s suppress_clear=%s skip_consent=%s skip_confirm=%s quiet=%s log=%s'
                % (
                    name,
                    suppress_pre_clear,
                    skip_consent,
                    skip_confirm,
                    quiet_finish,
                    _cw_cfg.MERGE_LOG_SHEET_NAME,
                ),
            )
            started = collect_workbooks_run()
            ok = bool(_cw_get('_MERGE_LAST_COLLECT_OK', False))
            return bool(started and ok)
        finally:
            _cw_set('_MERGE_PACK_SUPPRESS_PRE_CLEAR', False)
            _cw_set('_MERGE_PACK_SKIP_CONSENT', False)
            _cw_set('_MERGE_PACK_SKIP_CONFIRM', False)
            _cw_set('_MERGE_PACK_QUIET_FINISH', False)
    except Exception as err:
        merge_debug('collect_workbooks_for_param_sheet', 'error: %s' % err)
        show_message('Ошибка: %s' % err, doc)
        print(traceback.format_exc())
        return False

def _collect_pack_prevalidate(doc, plan):
    """
    Превалидация parse_collect_settings по каждому листу плана. None = ok.

    Без UI (interactive_manual=False). Если на листе есть ручной ввод
    «выше Файлы-Источники» или плейсхолдеры в путях — не проверяем наличие
    файлов (иначе default/пустая подстановка даёт ложное «Не найдены файлы»
    до реального диалога при сборе).
    """
    from libre_macros_pack_orchestrator_cfg import PACK_ORCH_ERR_PREVALIDATE
    prev = get_run_param_sheet(doc)
    try:
        for name in plan or []:
            set_run_param_sheet(name)
            defer_src = _merge_has_pre_shell_config(doc)
            manual_before, _manual_after = collect_manual_variable_input_specs(doc)
            raw_files = _merge_param_row_sparse_values(doc, _cw_cfg.P_MERGE_FILES, min_cols=0)
            has_path_ph = False
            ri = 0
            while ri < len(raw_files):
                if _merge_path_has_variable_placeholder(raw_files[ri]):
                    has_path_ph = True
                    break
                ri = ri + 1
            # Пути зависят от ввода пользователя / отложенного expand — не валидировать файлы.
            skip_src = bool(defer_src) or bool(manual_before) or has_path_ph
            err, _settings = parse_collect_settings(
                doc,
                validate_sources=not skip_src,
                interactive_manual=False,
            )
            if err:
                return PACK_ORCH_ERR_PREVALIDATE % (name, err)
        return None
    finally:
        try:
            set_run_param_sheet(prev)
        except Exception:
            pass
        # Не оставлять default’ы prevalidate в кэше диалогов.
        try:
            _merge_clear_manual_variable_cache()
        except Exception:
            pass

def collect_pack(event=None):
    """
    Оркестратор: диалог выбора листов Параметры_Объединения* → последовательный сбор.

    Имя экспорта без изменений. См. todo/оркестратор.md.
    """
    doc = None
    log_prev = None
    try:
        _ensure_pp_from_lib()
        from libre_macros_pack_orchestrator_lib import lm_pack_show_dialog
        from libre_macros_pack_orchestrator_cfg import PACK_ORCH_ERR_NO_SHEETS
        merge_debug('collect_pack', 'start')
        set_run_target_doc(None)
        doc = get_run_target_doc()
        if doc is None:
            show_message('Не открыта книга Calc.', None)
            return False
        _merge_clear_manual_variable_cache()
        # До диалога оркестратора: было ли окно развёрнуто.
        try:
            from libre_macros_split_lib import _split_document_is_maximized
            _cw_set('_MERGE_WINDOW_WAS_MAXIMIZED', _split_document_is_maximized(doc))
            _cw_set('_MERGE_WINDOW_MAX_CAPTURED', True)
            merge_debug(
                'collect_pack',
                'window was_maximized=%s' % _cw_get('_MERGE_WINDOW_WAS_MAXIMIZED', None),
            )
        except Exception:
            _cw_set('_MERGE_WINDOW_WAS_MAXIMIZED', None)
            _cw_set('_MERGE_WINDOW_MAX_CAPTURED', True)
        try:
            from libre_macros_global_settings_lib import apply_runtime_param_sheet_prefix

            apply_runtime_param_sheet_prefix()
        except Exception:
            pass
        try:
            _cw_set('_MERGE_SHEETS_INCLUDE_FILTER_FN', None)
        except Exception:
            pass
        names = list_param_sheet_names(doc, tab_order=True)
        if len(names) == 0:
            others = _merge_list_param_workbooks()
            if len(others) > 0:
                show_message(PACK_ORCH_ERR_NO_SHEETS, doc)
            else:
                show_message(PACK_ORCH_ERR_NO_SHEETS, doc)
            return False
        set_run_target_doc(doc)
        book_path = ''
        try:
            if not _merge_doc_is_unsaved(doc):
                book_path = str(_merge_doc_system_path(doc) or '').strip()
        except Exception:
            book_path = ''
        try:
            ctx = XSCRIPTCONTEXT.getComponentContext()
        except Exception:
            ctx = None
        result = lm_pack_show_dialog(
            doc,
            names,
            book_path=book_path,
            toolkit=get_awt_toolkit(),
            parent_window=message_parent_window(doc),
            show_message=show_message,
            ctx=ctx,
            sheet_comments=_merge_param_comments_for_sheets(doc, names),
        )
        if not result or not result.get('ok'):
            merge_debug('collect_pack', 'cancelled')
            return False
        plan = list(result.get('plan') or [])
        reset_db = bool(result.get('reset_db', False))
        auto_continue = bool(result.get('auto_continue', False))
        if not plan:
            show_message(PACK_ORCH_ERR_NO_SHEETS, doc)
            return False
        pre_err = _collect_pack_prevalidate(doc, plan)
        if pre_err:
            show_collect_error(pre_err, doc)
            return False
        if not merge_ensure_consent_before_run(doc):
            return False
        log_prev = str(_cw_cfg.MERGE_LOG_SHEET_NAME)
        any_ok = False
        all_ok = True
        plan_len = len(plan)
        _cw_set('_MERGE_PACK_PLAN_LEN', plan_len)
        skip_confirm = bool(auto_continue) and plan_len > 1
        i = 0
        while i < plan_len:
            name = plan[i]
            i = i + 1
            doc = get_run_target_doc() or doc
            set_run_target_doc(doc)
            log_name = merge_pack_iteration_log_name(plan_len, i)
            _cw_set('MERGE_LOG_SHEET_NAME', log_name)
            suppress_clear = plan_len > 1 and i > 1
            quiet_finish = skip_confirm and i < plan_len
            merge_debug(
                'collect_pack',
                'iteration %d/%d sheet=%s log=%s suppress_clear=%s skip_confirm=%s quiet=%s'
                % (i, plan_len, name, log_name, suppress_clear, skip_confirm, quiet_finish),
            )
            ok = collect_workbooks_for_param_sheet(
                name,
                suppress_pre_clear=suppress_clear,
                skip_consent=True,
                skip_confirm=skip_confirm,
                quiet_finish=quiet_finish,
            )
            if ok:
                any_ok = True
            else:
                all_ok = False
                break
        if reset_db and any_ok:
            merge_debug('collect_pack', 'collect_reset_db_ranges')
            collect_reset_db_ranges(event)
        merge_debug('collect_pack', 'done all_ok=%s any_ok=%s' % (all_ok, any_ok))
        # Вернуть maximize, если окно было развёрнуто до оркестратора.
        try:
            from libre_macros_split_lib import (
                _split_flush_maximize_pending,
                _split_restore_document_maximized,
            )
            d = get_run_target_doc() or doc
            was_max = _cw_get('_MERGE_WINDOW_WAS_MAXIMIZED', None)
            if d is not None:
                if _split_restore_document_maximized(d, was_max):
                    merge_debug('collect_pack', 'maximize restored was=%s' % was_max)
                try:
                    _split_flush_maximize_pending()
                except Exception:
                    pass
        except Exception as err:
            merge_debug('collect_pack', 'максимизация: %s' % err)
        return bool(all_ok)
    except Exception as err:
        merge_debug('collect_pack', 'error: %s' % err)
        show_message('Ошибка оркестратора: %s' % err, doc)
        print(traceback.format_exc())
        return False
    finally:
        try:
            if log_prev is not None:
                _cw_set('MERGE_LOG_SHEET_NAME', log_prev)
            else:
                base = str(getattr(_cw_cfg, 'MERGE_LOG_SHEET_BASE', None) or 'Сбор_книг_лог')
                _cw_set('MERGE_LOG_SHEET_NAME', base)
        except Exception:
            pass
        try:
            _cw_set('_MERGE_PACK_SUPPRESS_PRE_CLEAR', False)
            _cw_set('_MERGE_PACK_SKIP_CONSENT', False)
            _cw_set('_MERGE_PACK_SKIP_CONFIRM', False)
            _cw_set('_MERGE_PACK_QUIET_FINISH', False)
            _cw_set('_MERGE_PACK_PLAN_LEN', 1)
            _cw_set('_MERGE_COLLECT_MODE', None)
            _cw_set('_MERGE_INVOLVED_SHEET_NAMES', frozenset())
            _cw_set('_MERGE_LAST_COLLECT_OK', False)
            _cw_set('_MERGE_WINDOW_MAX_CAPTURED', False)
            _cw_set('_MERGE_WINDOW_WAS_MAXIMIZED', None)
        except Exception:
            pass

g_exportedScripts = (collect_pack, collect_workbooks, collect_workbooks_reopen, collect_reset_db_ranges, merge_xml_deferred_anchor_close)
